import {AdventuresBooksList} from "./bookslist.js";

class AdventuresList extends AdventuresBooksList {
	static _getLevelsStr (adv) {
		if (adv.level.custom) return adv.level.custom;
		return `${adv.level.start}\u2013${adv.level.end}`;
	}

	constructor () {
		super({
			contentsUrl: "data/adventures.json",
			fnSort: AdventuresBooksList._sortAdventuresBooks.bind(AdventuresBooksList),
			sortByInitial: "group",
			sortDirInitial: "asc",
			dataProp: "adventure",
			enhanceRowDataFn: (adv) => {
				adv._startLevel = adv.level.start || 20;
				adv._pubDate = new Date(adv.published);
			},
			rootPage: "adventure.html",
			rowBuilderFn: (adv) => {
				return `
					<span class="ve-col-1-3 ve-text-center ve-mobile-sm__text-clip-ellipsis">${AdventuresBooksList._getGroupHtml(adv)}</span>
					<span class="ve-col-5-5 ve-bold ve-mobile-sm__text-clip-ellipsis">${adv.name}</span>
					<span class="ve-col-2-5 ve-mobile-sm__text-clip-ellipsis">${adv.storyline || "\u2014"}</span>
					<span class="ve-col-1 ve-text-center ve-mobile-sm__text-clip-ellipsis">${AdventuresList._getLevelsStr(adv)}</span>
					<span class="ve-col-1 ve-text-center ve-mobile-sm__text-clip-ellipsis">${adv.translator || "机翻"}</span>
					<span class="ve-col-1-7 ve-text-center ve-mobile-sm__text-clip-ellipsis ve-code">${AdventuresBooksList._getDateStr(adv)}</span>
				`;
			},
		});
	}
}

const adventuresList = new AdventuresList();

function handleBrew (homebrew) {
	adventuresList.addData(homebrew);
	return Promise.resolve();
}

window.addEventListener("load", () => adventuresList.pOnPageLoad({handleBrew}));

