;(() => {
	const ORDER = [["野蛮人", ["XPHB", "PHB"]], ["吟游诗人", ["XPHB", "PHB"]], ["牧师", ["XPHB", "PHB"]], ["德鲁伊", ["XPHB", "PHB"]], ["战士", ["XPHB", "PHB"]], ["武僧", ["XPHB", "PHB"]], ["圣武士", ["XPHB", "PHB"]], ["游侠", ["XPHB", "PHB"]], ["游荡者", ["XPHB", "PHB"]], ["术士", ["XPHB", "PHB"]], ["魔契师", ["XPHB", "PHB"]], ["法师", ["XPHB", "PHB"]], ["奇械师", ["EFA", "TCE"]], ["血猎手", ["BH2022"]], ["邪狱使", ["IllriggerRevised"]], ["铳士", ["ValdaGunslinger"]], ["怪物猎人", ["GrimHollowPG24"]], ["拳斗士", ["Pugilist2024"]], ["吸血鬼", ["FoxfireVamp"]], ["魔战士", ["BHMagus"]]];
	const rank = cls => {
		for (let i = 0; i < ORDER.length; ++i) {
			const [nm, srcs] = ORDER[i];
			if (cls.name !== nm) continue;
			const ix = srcs.indexOf(cls.source);
			if (ix >= 0) return i * 10 + ix;
		}
		return 100000;
	};
	globalThis.__veOursClassTier = cls => {
		const r = rank(cls);
		return r < 130 ? "ve-ours-cls-off" : r < 100000 ? "ve-ours-cls-feat" : "ve-ours-cls-rest";
	};
	globalThis.__veOursClassSort = (a, b, o) => {
		if (o?.sortBy && o.sortBy !== "name") return SortUtil.listSort(a, b, o);
		const ea = a.data?.entity, eb = b.data?.entity;
		const d = (ea && eb) ? rank(ea) - rank(eb) : 0;
		return d || SortUtil.listSort(a, b, o);
	};
})();

