		a = a.item;
		b = b.item;
		const ixA = PageFilterBestiary._DRAGON_AGES.indexOf(a);
		const ixB = PageFilterBestiary._DRAGON_AGES.indexOf(b);
		if (~ixA && ~ixB) return SortUtil.ascSort(ixA, ixB);
