			header: "Hook",
			cnHeader: "钩针型号",
			displayFn: sizeMm => {
				const asMm = `${sizeMm.toFixed(2)} mm`;

				const usSize = Parser.crochetHookMmToUs(sizeMm);
				if (!usSize) return asMm;

				return `${usSize} (${asMm})`;
