"use strict";

class LanguagesSublistManager extends SublistManager {
	static _getRowTemplate () {
		return [
			new SublistCellTemplate({
				name: "Name",
				css: "ve-bold ve-col-8 ve-pl-1 ve-pr-0",
				colStyle: "",
			}),
			new SublistCellTemplate({
				name: "Type",
				css: "ve-col-2 ve-px-1 ve-text-center",
				colStyle: "text-center",
			}),
			new SublistCellTemplate({
				name: "Script",
				css: "ve-col-2 ve-text-center ve-pl-1 ve-pr-0",
				colStyle: "text-center",
			}),
		];
	}

	pGetSublistItem (it, hash) {
		const cellsText = [
			it.name,
			(it.type || "\u2014").uppercaseFirst(),
			(it.script || "\u2014").toTitleCase(),
		];

		const ele = veT`<div class="ve-lst__row ve-lst__row--sublist ve-flex-col">
			<a href="#${hash}" class="ve-lst__row-border ve-lst__row-inner">
				${this.constructor._getRowCellsHtml({values: cellsText})}
			</a>
		</div>`
			.vee.onn("contextmenu", evt => this._handleSublistItemContextMenu(evt, listItem))
			.vee.onn("click", evt => this._listSub.doSelect(listItem, evt));

		const listItem = new ListItem({
			id: hash,
			ele,
			name: it.name,
			values: {
				...ListItem.getCommonValues(it),
				type: it.type || "",
				script: it.script || "",
				ENG_name: it.ENG_name,
				ENG_hash: UrlUtil.autoEncodeEngHash(it),
			},
			data: {
				hash,
				page: it.page,
				entity: it,
				mdRow: [...cellsText],
			},
		});
		return listItem;
	}
}

class LanguagesPage extends ListPage {
	constructor () {
		const pageFilter = new PageFilterLanguages();
		super({
			dataSource: DataUtil.language.loadJSON.bind(DataUtil.language),

			pFnGetFluff: Renderer.language.pGetFluff.bind(Renderer.language),

			pageFilter,

			dataProps: ["language"],

			bookViewOptions: {
				nameSingular: "language",
				namePlural: "languages",
				pageTitle: "Languages Book View",
			},
		});
	}

	getListItem (it, anI, isExcluded) {
		this._pageFilter.mutateAndAddToFilters(it, isExcluded);

		const eleLi = document.createElement("div");
		eleLi.className = `ve-lst__row ve-flex-col ${isExcluded ? "ve-lst__row--blocklisted" : ""}`;

		const source = Parser.sourceJsonToAbv(it.source);
		const hash = UrlUtil.autoEncodeHash(it);

		eleLi.innerHTML = `<a href="#${hash}" class="ve-lst__row-border ve-lst__row-inner">
			<span class="ve-col-6 ve-bold ve-pl-0 ve-pr-1">${it.name}</span>
			<span class="ve-col-2 ve-px-1 ve-text-center">${(Parser.languageToCn(it.type || "\u2014")).uppercaseFirst()}</span>
			<span class="ve-col-2 ve-px-1 ve-text-center">${(it.script || "\u2014").toTitleCase()}</span>
			<span class="ve-col-2 ve-text-center ${Parser.sourceJsonToSourceClassname(it.source)} ve-pl-1 ve-pr-0" title="${Parser.sourceJsonToFull(it.source)}">${source}</span>
		</a>`;

		const listItem = new ListItem({
			id: anI,
			ele: eleLi,
			name: it.name,
			values: {
				source,
				...ListItem.getCommonValues(it),
				dialects: it.dialects || [],
				type: it.type || "",
				script: it.script || "",
				ENG_name: it.ENG_name,
				ENG_hash: UrlUtil.autoEncodeEngHash(it),
			},
			data: {
				hash,
				page: it.page,
				isExcluded,
			},
		});

		eleLi.addEventListener("click", (evt) => this._list.doSelect(listItem, evt));
		eleLi.addEventListener("contextmenu", (evt) => this._openContextMenu(evt, this._list, listItem));

		return listItem;
	}

	_renderStats_doBuildStatsTab ({ent}) {
		this._pgContent.vee.empty().vee.appends(RenderLanguages.getRenderedLanguage(ent));
	}

	_renderStats_getTabMetasAdditional ({ent}) {
		return [
			new Renderer.utils.TabButton({
				label: "字体",
				fnPopulate: () => {
					this._pgContent.vee.empty().vee.appends(Renderer.utils.getBorderTr());
					this._pgContent.vee.appends(Renderer.utils.getNameTr(ent));
					const td = veT`<td colspan="6" class="ve-pb-3"></td>`;
					veT`<tr>${td}</tr>`.vee.appendTo(this._pgContent);
					this._pgContent.vee.appends(Renderer.utils.getBorderTr());

					const allFonts = [...ent.fonts || [], ...ent._fonts || []];

					if (!allFonts || !allFonts.length) {
						td.vee.appends("<i>No fonts available.</i>");
						return;
					}

					const styleFont = veT`<style></style>`;

					let lastStyleIndex = null;
					let lastStyleClass = null;
					const renderStyle = (ix) => {
						if (ix === lastStyleIndex) return;

						const font = allFonts[ix];
						const slugName = Parser.stringToSlug(font.split("/").last().split(".")[0]);

						const styleClass = `languages__sample--${slugName}`;

						styleFont.vee.html(`
							@font-face { font-family: ${slugName}; src: url('${font}'); }
							.${styleClass} { font-family: ${slugName}, sans-serif; }
						`);

						if (lastStyleClass) ptOutput.vee.removeClass(lastStyleClass);
						lastStyleClass = styleClass;
						ptOutput.vee.addClass(styleClass);
						lastStyleIndex = ix;
					};

					const saveTextDebounced = MiscUtil.debounce((text) => StorageUtil.pSetForPage("sampleText", text), VeCt.DUR_DEBOUNCE_SAVE);
					const updateText = (val) => {
						if (val === undefined) val = iptSample.vee.val();
						else iptSample.vee.val(val);
						ptOutput.vee.txt(val);
						saveTextDebounced(val);
					};

					const DEFAULT_TEXT = "The big quick brown flumph jumped over the lazy dire xorn";

					const iptSample = veT`<textarea class="ve-form-control ve-w-100 ve-mr-2 ve-resize-vertical font-ui ve-mb-2" style="height: 110px">${DEFAULT_TEXT}</textarea>`
						.vee.onn("keyup", () => updateText())
						.vee.onn("change", () => updateText());

					const selFont = allFonts.length === 1
						? null
						: veT`<select class="ve-form-control font-ui languages__sel-sample ve-input-xs">${allFonts.map((f, i) => `<option value="${i}">${f.split("/").last().split(".")[0]}</option>`).join("")}</select>`
							.vee.onn("change", () => {
								const ix = Number(selFont.vee.val());
								renderStyle(ix);
							});

					const ptOutput = veT`<pre class="languages__sample ve-p-2 ve-mb-0">${DEFAULT_TEXT}</pre>`;

					renderStyle(0);

					StorageUtil.pGetForPage("sampleText")
						.then(val => {
							if (val != null) updateText(val);
						});

					veT`<div class="ve-flex-col ve-w-100">
						${styleFont}
						${selFont ? veT`<label class="ve-flex-v-center ve-mb-2"><div class="ve-mr-2">字体:</div>${selFont}</div>` : ""}
						${iptSample}
						${ptOutput}
						<hr class="ve-hr-4">
						<h5 class="ve-mb-2 ve-mt-0">下载</h5>
						<ul class="ve-pl-5 ve-mb-0">
							${allFonts.map(f => `<li><a href="${f}" target="_blank">${f.split("/").last()}</a></li>`).join("")}
						</ul>
					</div>`.vee.appendTo(td);
				},
				isVisible: [...ent.fonts || [], ...ent._fonts || []].length > 0,
			}),
		];
	}
}

const languagesPage = new LanguagesPage();
languagesPage.sublistManager = new LanguagesSublistManager();
window.addEventListener("load", () => languagesPage.pOnLoad());

globalThis.dbg_page = languagesPage;

