function onJsonLoad (lifeData, nameData) {
	bgList = lifeData.lifeBackground.sort((a, b) => SortUtil.ascSort(a.name, b.name));
	classList = lifeData.lifeClass.sort((a, b) => SortUtil.ascSort(a.name, b.name));
