		page: UrlUtil.PG_RACES,
		colorDefault: "#a7894b",
		iconDefault: "family-tree",
		pFnSearch: SearchWidget.pGetUserRaceSearch,
		fnGetContents: MakeCards._getCardContents_race.bind(MakeCards),
