"use strict";

class NavBar {
	static _DROP_TIME = 250;
	static _MIN_MOVE_PX = 3;
	static _CAT_RULES = "规则";
	static _CAT_BOOKS = "书籍";
	static _CAT_PLAYER = "玩家选项";
