				ability: race._slAbility,
				size: sizeText,
				ENG_name: race.ENG_name,
				ENG_hash: UrlUtil.autoEncodeEngHash(race),
			},
			data: {
				hash,
				page: race.page,
				ability: race._srtAbility,
				entity: race,
				mdRow: [...cellsText],
			},
		});
		return listItem;
	}
