/** @abstract */
class _RenderClassesSidebarImplBase {
	_style;

	getRenderedClassSidebar (comp, cls) {
		const renderer = Renderer.get().setFirstSection(true);

		return this._getRenderedClassSidebar({comp, cls, renderer});
	}

