					return vals.filter(it => !it.isDropped).map(it => it.val).sum();
				}
			} else {
				this.addToMeta(
					meta,
					["html", "text", "md"].mergeMap(prop => ({
						[prop]: `${vals.map(it => `(${it.meta[prop].join("")})`).join("+")}`,
