				keyOptions = null,
				isSkipPrefix = false,
				styleHint = null,
			} = {},
		) {
			const entry = this.getEntry(prerequisites, {isListMode, blocklistKeys, keyOptions, isSkipPrefix, styleHint});
			if (!entry) return "";
			return Renderer.get().render(entry);
		}

		/**
		 * @param prerequisites
		 * @param isListMode
		 * @param {?Set} blocklistKeys
		 * @param {?object} keyOptions
		 * @param isSkipPrefix
		 * @param {"classic" | null} styleHint
		 * @return {string}
		 */
		static getText (
			prerequisites,
			{
				isListMode = false,
				blocklistKeys = null,
				keyOptions = null,
				isSkipPrefix = false,
				styleHint = null,
			} = {},
		) {
			return Renderer.stripTags(this.getEntry(prerequisites, {isListMode, blocklistKeys, keyOptions, isSkipPrefix, styleHint}));
		}

		/**
		 * @param prerequisites
		 * @param isListMode
		 * @param {?Set} blocklistKeys
		 * @param {?object} keyOptions
		 * @param isSkipPrefix
		 * @param {"classic" | null} styleHint
		 * @return {string}
		 */
		static getEntry (
			prerequisites,
			{
				isListMode = false,
				blocklistKeys = null,
				keyOptions = null,
				isSkipPrefix = false,
				styleHint = null,
			} = {},
		) {
			if (!prerequisites?.length) return isListMode ? "\u2014" : "";

			styleHint ||= VetoolsConfig.get("styleSwitcher", "style");

			const prereqsShared = prerequisites.length === 1
				? {}
				: Object.entries(
					prerequisites
						.slice(1)
						.reduce((a, b) => CollectionUtil.objectIntersect(a, b), prerequisites[0]),
				)
					.filter(([k, v]) => prerequisites.every(pre => CollectionUtil.deepEquals(pre[k], v)))
					.mergeMap(([k, v]) => ({[k]: v}));

			const shared = Object.keys(prereqsShared).length
				? this.getEntry([prereqsShared], {isListMode, blocklistKeys, keyOptions, isSkipPrefix: true, styleHint})
				: null;

			let cntPrerequisites = 0;
			let hasNote = false;
			const listOfChoices = prerequisites
				.map(pr => {
					// Never include notes in list mode
					const ptNote = !isListMode && pr.note ? pr.note : null;
					if (ptNote) {
						hasNote = true;
					}

					const prereqsToJoin = Object.entries(pr)
						.filter(([k]) => !prereqsShared[k])
						.sort(([kA], [kB]) => this._WEIGHTS[kA] - this._WEIGHTS[kB])
						.map(([k, v]) => {
							if (k === "note" || blocklistKeys?.has(k)) return false;

							cntPrerequisites += 1;

							switch (k) {
								case "level": return this._getEntry_level({v, isListMode, keyOptions, styleHint});
								case "pact": return this._getEntry_pact({v, isListMode, keyOptions, styleHint});
								case "patron": return this._getEntry_patron({v, isListMode, keyOptions, styleHint});
								case "spell": return this._getEntry_spell({v, isListMode, keyOptions, styleHint});
								case "feat": return this._getEntry_feat({v, isListMode, keyOptions, styleHint});
								case "featCategory": return this._getEntry_featCategory({v, isListMode, keyOptions, styleHint});
								case "exclusiveFeatCategory": return this._getEntry_exclusiveFeatCategory({v, isListMode, keyOptions, styleHint});
								case "optionalfeature": return this._getEntry_optionalfeature({v, isListMode, keyOptions, styleHint});
								case "feature": return this._getEntry_feature({v, isListMode, keyOptions, styleHint});
								case "item": return this._getEntry_item({v, isListMode, keyOptions, styleHint});
								case "itemType": return this._getEntry_itemType({v, isListMode, keyOptions, styleHint});
								case "itemProperty": return this._getEntry_itemProperty({v, isListMode, keyOptions, styleHint});
								case "otherSummary": return this._getEntry_otherSummary({v, isListMode, keyOptions, styleHint});
								case "other": return this._getEntry_other({v, isListMode, keyOptions, styleHint});
								case "race": return this._getEntry_race({v, isListMode, keyOptions, styleHint});
								case "background": return this._getEntry_background({v, isListMode, keyOptions, styleHint});
								case "ability": return this._getEntry_ability({v, isListMode, keyOptions, styleHint});
								case "proficiency": return this._getEntry_proficiency({v, isListMode, keyOptions, styleHint});
								case "expertise": return this._getEntry_expertise({v, isListMode, keyOptions, styleHint});
								case "spellcasting": return this._getEntry_spellcasting({v, isListMode, keyOptions, styleHint});
								case "spellcasting2020": return this._getEntry_spellcasting2020({v, isListMode, keyOptions, styleHint});
								case "spellcastingFeature": return this._getEntry_spellcastingFeature({v, isListMode, keyOptions, styleHint});
								case "spellcastingPrepared": return this._getEntry_spellcastingPrepared({v, isListMode, keyOptions, styleHint});
								case "spellcastingFocus": return this._getEntry_spellcastingFocus({v, isListMode, keyOptions, styleHint});
								case "psionics": return this._getEntry_psionics({v, isListMode, keyOptions, styleHint});
								case "alignment": return this._getEntry_alignment({v, isListMode, keyOptions, styleHint});
								case "campaign": return this._getEntry_campaign({v, isListMode, keyOptions, styleHint});
								case "culture": return this._getEntry_culture({v, isListMode, keyOptions, styleHint});
								case "membership": return this._getEntry_membership({v, isListMode, keyOptions, styleHint});
								case "group": return this._getEntry_group({v, isListMode, keyOptions, styleHint});
								default: throw new Error(`Unhandled key: ${k}`);
							}
						})
						.filter(Boolean);

					const ptPrereqs = prereqsToJoin
						.join(prereqsToJoin.some(it => / 或 /.test(it)) ? "; " : ", ");

					return [ptPrereqs, ptNote]
						.filter(Boolean)
						.join(". ");
				})
				.filter(Boolean);

			if (!listOfChoices.length && !shared) return isListMode ? "\u2014" : "";
			if (isListMode) return [shared, listOfChoices.join("/")].filter(Boolean).join(" + ");

			const sharedSuffix = MiscUtil.findCommonSuffix(listOfChoices, {isRespectWordBoundaries: true});
			const listOfChoicesTrimmed = sharedSuffix
				? listOfChoices.map(it => it.slice(0, -sharedSuffix.length))
				: listOfChoices;

			const joinedChoices = (
				hasNote
					? listOfChoicesTrimmed.join(" 或, ")
					: listOfChoicesTrimmed.joinConjunct(listOfChoicesTrimmed.some(it => / or /.test(it)) ? "; " : ", ", " 或 ")
			) + sharedSuffix;

			const ptPrefix = isSkipPrefix ? "" : `先决条件: `;
			const ptsSharedOther = [shared, joinedChoices].filter(Boolean);
			if (ptsSharedOther.length < 2) return `${ptPrefix}${ptsSharedOther.join(", ")}`;

			const ptsSharedOtherJoiner = ptsSharedOther.some(pt => pt.includes(","))
				? ptsSharedOther.some(pt => pt.includes(";")) ? "; plus " : "; "
				: ", ";
			return `${ptPrefix}${[shared, joinedChoices].filter(Boolean).join(ptsSharedOtherJoiner)}`;
		}

		static _getEntry_level ({v, isListMode, keyOptions, styleHint}) {
			// a generic level requirement
			if (typeof v === "number") {
				if (keyOptions?.level?.isNameOnly) return "";

				if (isListMode) return `Lvl ${v}`;

				if (styleHint === "classic") return `${Parser.getOrdinalForm(v)}级`;
				return `等级 ${v}+`;
			}

			if (!v.class && !v.subclass) {
				if (keyOptions?.level?.isNameOnly) return "";

				if (isListMode) return `Lvl ${v.level}`;

				if (styleHint === "classic") return `${Parser.getOrdinalForm(v.level)}级`;
				return `${v.level}级+`;
			}

			const isLevelVisible = v.level !== 1 // Hide the "implicit" 1st level.
				&& !keyOptions?.level?.isNameOnly;
			const isSubclassVisible = v.subclass?.visible
				|| (!isListMode && v.subclass?.visibleStats)
				|| (isListMode && v.subclass?.visibleList);
			const isClassVisible = v.class
				&& (
					v.class.visible
					|| isSubclassVisible // force the class name to be displayed if there's a subclass being displayed
					|| (!isListMode && v.class?.visibleStats)
					|| (isListMode && v.class?.visibleList)
				);
			if (isListMode) {
				const shortNameRaw = isClassVisible ? this._getShortClassName(v.class.name) : null;
				return `${isClassVisible ? `${shortNameRaw.slice(0, 4)}${isSubclassVisible ? "*" : "."}` : ""}${isLevelVisible ? ` Lvl ${v.level}` : ""}`;
			}

			let classPart = "";
			if (isClassVisible && isSubclassVisible) classPart = ` ${v.class.name} (${v.subclass.name})`;
			else if (isClassVisible) classPart = ` ${v.class.name}`;
			else if (isSubclassVisible) classPart = ` &lt;remember to insert class name here&gt; (${v.subclass.name})`; // :^)

			const ptLevel = !isLevelVisible
				? ""
				: styleHint === "classic"
					? `${Parser.getOrdinalForm(v.level)} 级`
					: `Level ${v.level}+`;

			return [ptLevel, classPart].filter(Boolean).join(" ");
		}

		static _getEntry_pact ({v, isListMode}) {
			return Parser.prereqPactToFull(v);
		}

		static _getEntry_patron ({v, isListMode}) {
			return isListMode ? `${Parser.prereqPatronToShort(v)}宗主` : `${v}宗主`;
		}

		static _getEntry_spell ({v, isListMode, keyOptions}) {
			return isListMode
				? v.map(sp => {
					if (typeof sp === "string") return sp.split("#")[0].split("|")[0].toTitleCase();
					return sp.entrySummary || sp.entry;
				})
					.join("/")
				: v.map(sp => {
					if (typeof sp !== "string") return `{@filter ${sp.entry}|spells|${sp.choose}}`;

					const [text, suffix] = sp.split("#");
					if (!suffix) return `{@spell ${sp}}`;
					if (suffix === "c") return `{@spell ${text}} cantrip`;
					if (suffix === "x") return "{@spell hex} spell or a warlock feature that curses";
					return sp;
				})
					.joinConjunct(", ", " 或 ");
		}

		static _getEntry_feat ({v, isListMode, keyOptions, styleHint}) {
			return this._getEntry_uidTag({v, isListMode, keyOptions, styleHint, tag: "feat"});
		}

		static _getEntry_featCategory ({v, isListMode, keyOptions, styleHint}) {
			if (isListMode) {
				const ptTypes = v
					.map(featCategoryMeta => {
						if (typeof featCategoryMeta === "string") return Parser.featCategoryToFull(featCategoryMeta);
						return `${featCategoryMeta.count}× ${Parser.featCategoryToFull(featCategoryMeta.category)}`;
					})
					.join("/");
				return `任意 ${ptTypes}`;
			}

			const ptTypes = v
				.map(featCategoryMeta => {
					if (typeof featCategoryMeta === "string") return Parser.featCategoryToFull(featCategoryMeta);
					return `${Parser.numberToText(featCategoryMeta.count)} ${Parser.featCategoryToFull(featCategoryMeta.category)}`;
				})
				.joinConjunct(", ", " 或 ");
			return `任意 ${ptTypes} 专长`;
		}

		static _getEntry_exclusiveFeatCategory ({v, isListMode, keyOptions, styleHint}) {
			if (isListMode) {
				const ptTypes = v.map(featCategory => Parser.featCategoryToFull(featCategory))
					.join("/");
				return `只有 ${ptTypes}`;
			}

			const ptTypes = v.map(featCategory => Parser.featCategoryToFull(featCategory))
				.joinConjunct(", ", " 或 ");
			return `不具有其他 ${ptTypes} 专长`;
		}

		static _getEntry_optionalfeature ({v, isListMode, keyOptions, styleHint}) {
			return this._getEntry_uidTag({v, isListMode, keyOptions, styleHint, tag: "optfeature"});
		}

		static _getEntry_uidTag ({v, isListMode, keyOptions, styleHint, tag}) {
			if (isListMode) return v.map(x => x.split("|")[0].toTitleCase()).join("/");

			return v
				.map(uid => {
					uid = styleHint === "classic" ? uid : uid.split("|").map((pt, i) => i === 0 ? pt.toTitleCase() : pt).join("|");
					return `{@${tag} ${uid}}`;
				})
				.joinConjunct(", ", " 或 ");
		}

		static _getEntry_feature ({v, isListMode, keyOptions, styleHint}) {
			if (isListMode) return v.map(x => Renderer.stripTags(x).toTitleCase()).join("/");

			const ptNames = v.joinConjunct(", ", " 或 ");

			if (styleHint === "classic") return ptNames;
			return `${ptNames} 特性`;
		}

		static _getEntry_item ({v, isListMode}) {
			return isListMode ? v.map(x => x.toTitleCase()).join("/") : v.joinConjunct(", ", " 或 ");
		}

		static _getEntry_itemType ({v, isListMode}) {
			return isListMode
				? v
					.map(it => Renderer.item.getType(it, {isIgnoreMissing: true}))
					.filter(Boolean)
					.map(it => it.abbreviation)
					.join("+")
				: v
					.map(it => Renderer.item.getType(it, {isIgnoreMissing: true}))
					.filter(Boolean)
					.map(it => it.name?.toTitleCase())
					.joinConjunct(", ", " 和 ");
		}

		static _getEntry_itemProperty ({v, isListMode}) {
			if (v == null) return isListMode ? "No Prop." : "No Other Properties";

			return isListMode
				? v
					.map(it => Renderer.item.getProperty(it, {isIgnoreMissing: true}))
					.filter(Boolean)
					.map(it => it.abbreviation)
					.join("+")
				: (
					`${v
						.map(it => Renderer.item.getProperty(it, {isIgnoreMissing: true}))
						.filter(Boolean)
						.map(it => it.name?.toTitleCase())
						.joinConjunct(", ", " 和 ")
					} Property`
				);
		}

		static _getEntry_otherSummary ({v, isListMode, keyOptions}) {
			return isListMode
				? (v.entrySummary || Renderer.stripTags(v.entry))
				: v.entry;
		}

		static _getEntry_other ({v, isListMode, keyOptions}) {
			return isListMode ? "特殊" : v;
		}

		static _getEntry_race ({v, isListMode, keyOptions, styleHint}) {
			const parts = v.map((it, i) => {
				if (isListMode) {
					return `${it.name.toTitleCase()}${it.subrace != null ? ` (${it.subrace})` : ""}`;
				} else {
					const raceName = it.displayEntry
						? it.displayEntry
						: (i === 0 || styleHint !== "classic")
							? it.name.toTitleCase()
							: it.name;
					return `${raceName}${it.subrace != null ? ` (${it.subrace})` : ""}`;
				}
			});
			return isListMode ? parts.join("/") : parts.joinConjunct(", ", " 或 ");
		}

		static _getEntry_background ({v, isListMode, keyOptions, styleHint}) {
			const parts = v.map((it, i) => {
				if (isListMode) {
					return `${it.name.toTitleCase()}`;
				} else {
					return it.displayEntry
						? it.displayEntry
						: (i === 0 || styleHint !== "classic")
							? it.name.toTitleCase()
							: it.name;
				}
			});
			return isListMode ? parts.join("/") : parts.joinConjunct(", ", " 或 ");
		}

		static _getEntry_ability ({v, isListMode, keyOptions, styleHint}) {
			// `v` is an array or objects with str/dex/... properties; array is "OR"'d together, object is "AND"'d together

			let hadMultipleInner = false;
			let hadMultiMultipleInner = false;
			let allValuesEqual = null;

			outer: for (const abMeta of v) {
				for (const req of Object.values(abMeta)) {
					if (allValuesEqual == null) allValuesEqual = req;
					else {
						if (req !== allValuesEqual) {
							allValuesEqual = null;
							break outer;
						}
					}
				}
			}

			const abilityOptions = v.map(abMeta => {
				if (allValuesEqual) {
					const abList = Object.keys(abMeta);
					hadMultipleInner = hadMultipleInner || abList.length > 1;
					return isListMode ? abList.map(ab => Parser.attAbvToFull(ab)).join(", ") : abList.map(ab => Parser.attAbvToFull(ab)).joinConjunct(", ", " 和 ");
				} else {
					const groups = {};

					Object.entries(abMeta).forEach(([ab, req]) => {
						(groups[req] = groups[req] || []).push(ab);
					});

					let isMulti = false;
					const byScore = Object.entries(groups)
						.sort(([reqA], [reqB]) => SortUtil.ascSort(Number(reqB), Number(reqA)))
						.map(([req, abs]) => {
							hadMultipleInner = hadMultipleInner || abs.length > 1;
							if (abs.length > 1) hadMultiMultipleInner = isMulti = true;

							abs = abs.sort(SortUtil.ascSortAtts);

							if (isListMode) return `${abs.map(ab => ab.uppercaseFirst()).join(", ")} ${req}+`;

							const ptHigher = styleHint === "classic" ? " or higher" : "+";
							return `${abs.map(ab => Parser.attAbvToFull(ab)).joinConjunct(", ", " 和 ")} ${req}${ptHigher}`;
						});

					return isListMode
						? `${isMulti || byScore.length > 1 ? "(" : ""}${byScore.join(" & ")}${isMulti || byScore.length > 1 ? ")" : ""}`
						: isMulti ? byScore.joinConjunct("; ", " 和 ") : byScore.joinConjunct(", ", " 和 ");
				}
			});

			// if all values were equal, add the "X+" text at the end, as the options render doesn't include it
			if (isListMode) {
				return `${abilityOptions.join("/")}${allValuesEqual != null ? ` ${allValuesEqual}+` : ""}`;
			}

			const isComplex = hadMultiMultipleInner || hadMultipleInner || allValuesEqual == null;
			const joined = abilityOptions.joinConjunct(
				hadMultiMultipleInner ? " - " : hadMultipleInner ? "; " : ", ",
				// FIXME(Future) text-only version previously did " /or/ " as joiner; stripped-italics now results in plain " or "
				isComplex ? ` {@i 或} ` : " 或 ",
			);
			const ptHigher = styleHint === "classic" ? " 或更高" : "+";
			return `${joined}${allValuesEqual != null ? ` ${allValuesEqual}${ptHigher}` : ""}`;
		}

		static _getEntry_proficiency ({v, isListMode, keyOptions, styleHint}) {
			const parts = v.map(obj => {
				return Object.entries(obj).map(([profType, prof]) => {
					switch (profType) {
						case "armor": {
							if (prof === "shield") {
								if (isListMode) return styleHint === "classic" ? `Prof ${prof}` : `${prof.toTitleCase()} Trai.`;
								return styleHint === "classic" ? `Proficiency with ${prof}s` : `${prof.toTitleCase()} Training`;
							}

							if (isListMode) return styleHint === "classic" ? `${Parser.ARMOR_FULL_TO_CN[prof] || prof.toTitleCase()}甲熟练项` : `${Parser.ARMOR_FULL_TO_CN[prof] || prof.toTitleCase()}甲受训`;
							return styleHint === "classic" ? `${Parser.ARMOR_FULL_TO_CN[prof] || prof.toTitleCase()}甲熟练项` : `${Parser.ARMOR_FULL_TO_CN[prof] || prof.toTitleCase()}甲受训`;
						}
						case "weapon": {
							return isListMode ? `熟练于${prof}武器` : `具有${prof}武器熟练项`;
						}
						case "weaponGroup": {
							return isListMode ? `熟练于${prof}武器` : `${prof.toTitleCase()}武器熟练项`;
						}
						case "skill": {
							if (prof === true) return isListMode ? `Skill Proficiency` : `Proficiency in a skill`;
							return isListMode
								? prof.map(skill => skill.toTitleCase()).join("+")
								: `Proficiency in the ${prof.map(skill => `{@skill ${skill.toTitleCase()}}`).joinConjunct(", ", " and ")} skill${prof.length === 1 ? "" : "s"}`;
						}
						default: throw new Error(`Unhandled proficiency type: "${profType}"`);
					}
				});
			});
			return isListMode ? parts.join("/") : parts.joinConjunct(", ", " 或 ");
		}

		static _getEntry_expertise ({v, isListMode, keyOptions, styleHint}) {
			const parts = v.map(obj => {
				return Object.entries(obj).map(([profType, prof]) => {
					switch (profType) {
						case "skill": {
							if (prof === true) return isListMode ? `技能专精` : `专精于一项技能`;
							// TODO(Future) speculative; consider revising
							return isListMode ? `${prof.toTitleCase()}专精` : `专精于${prof.toTitleCase()}`;
						}
						default: throw new Error(`Unhandled expertise type: "${profType}"`);
					}
				});
			});
			return isListMode ? parts.join("/") : parts.joinConjunct(", ", " or ");
		}

		static _getEntry_spellcasting ({v, isListMode}) {
			return isListMode ? "施法能力" : "至少能施放一个法术的能力";
		}

		static _getEntry_spellcasting2020 ({v, isListMode, keyOptions, styleHint}) {
			if (isListMode) return "施法能力";
			return styleHint === "classic" ? "施法能力或契约魔法特性" : "施法能力或契约魔法特性";
		}

		static _getEntry_spellcastingFeature ({v, isListMode}) {
			return isListMode ? "施法能力" : "施法能力";
		}

		static _getEntry_spellcastingPrepared ({v, isListMode}) {
			return isListMode ? "施法能力" : "来自职业或者准备法术的施法能力";
		}

		static _SCF_TYPE_TO_NAME = {
			"arcane": "奥术法器",
			"druid": "德鲁伊法器",
			"holy": "圣徽",
			"artisansTool": "工匠工具",
		};
		static _getEntry_spellcastingFocus ({v, isListMode, styleHint}) {
			if (isListMode) {
				if (v === true) return `法器`;
				return v.map(n => this._SCF_TYPE_TO_NAME[n] || `施法${n.toTitleCase()}`).join("/");
			}

			const ptScfSuffix = styleHint === "classic" ? "法器" : "{@variantrule 法器|XPHB}";
			if (v === true) {
				return `可以使用${ptScfSuffix}`;
			}

			const ptScf = v
				.map((scf, i) => {
					if (!i) {
						const a = Parser.getArticle(this._SCF_TYPE_TO_NAME[scf] || scf);
						if (!this._SCF_TYPE_TO_NAME[scf]) return `${a} ${scf}`;
						return `${a} {@item ${this._SCF_TYPE_TO_NAME[scf]}${styleHint === "classic" ? "" : "|XPHB"}}`;
					}

					if (!this._SCF_TYPE_TO_NAME[scf]) return scf;
					return `{@item ${this._SCF_TYPE_TO_NAME[scf]}${styleHint === "classic" ? "" : "|XPHB"}}`;
				})
				.joinConjunct(", ", "或");

			return `可以使用${ptScf}${ptScfSuffix}`;
		}

		static _getEntry_psionics ({v, isListMode, keyOptions}) {
			return isListMode
				? "Psionics"
				: "Psionic Talent feature or Wild Talent feat";
		}

		static _getEntry_alignment ({v, isListMode}) {
			return isListMode
				? Parser.alignmentListToFull(v)
					.replace(/\bany\b/gi, "").trim()
					.replace(/\balignment\b/gi, "align").trim()
					.toTitleCase()
				: Parser.alignmentListToFull(v);
		}

