		static getFontInfo (fontDecl) {
			if (!fontDecl) {
				return {
					fontId: null,
					fontUrl: null,
				};
			}

			const spl = fontDecl.split("/");

			if (spl.length === 1) {
				return {
					fontId: spl[0],
					fontUrl: null,
				};
			}

			const ptName = spl.at(-1);
			const fontIdFaux = ptName.split(".")[0];

			const fontUrl = /^https?:\/\//.test(fontDecl)
				? fontDecl
				: Renderer.get().getMediaUrl("fonts", fontDecl);

			return {
				fontId: fontIdFaux,
				fontUrl,
			};
		}
