	static getSafeAbilityScore (mon, abil, {defaultScore = 0} = {}) {
		if (!mon || abil == null) return defaultScore;
		if (mon[abil] == null) return defaultScore;
		return typeof mon[abil] === "number" ? mon[abil] : (defaultScore);
