});

Renderer.monsterAction.getWeaponLookupName = act => {
	return (act.name || "")
		.replace(/[(（].*[)）]$/, "") // remove parenthetical text (e.g. "(Humanoid or Hybrid Form Only)" off the end
		.trim()
