;globalThis.__veOursCustomPropFns = (item, pFull) => {
	// template asks for item.customProperties.<translated key>; the item may still use the English key
	const out = {};
	const cp = item?.customProperties;
	if (!cp || !pFull?.template) return out;
	for (const m of String(pFull.template).matchAll(/\{\{(item\.customProperties\.([^}]+))\}\}/g)) {
		const [, path, key] = m;
		if (cp[key] != null) continue;
		const alt = [pFull.ENG_name, pFull.name, ...Object.keys(cp).length === 1 ? Object.keys(cp) : []].find(k => k != null && cp[k] != null);
		if (alt != null) out[path] = () => cp[alt];
	}
	return out;
};

