			<div class="ve-vr-0 ve-absolute ve-accordion__vr-preview"></div>
			<div class="ve-flex-col ve-py-3 ve-ml-4 ve-accordion__wrp-preview-inner"></div>
		</div>`;

		const listItem = new ListItem({
			id: rwI,
			ele: eleLi,
			name: reward.name,
			values: {
				source,
				...ListItem.getCommonValues(reward),
				type: reward.type,
				ENG_name: reward.ENG_name,
				ENG_hash: UrlUtil.autoEncodeEngHash(reward),
			},
			data: {
				hash,
				page: reward.page,
				isExcluded,
			},
