import {UtilsOmnisearch} from "./utils-omnisearch.js";
import {OmnisearchConsts} from "./omnisearch/omnisearch-consts.js";
import {OmnisearchState} from "./omnisearch/omnisearch-state.js";
import {OmnisearchBacking} from "./omnisearch/omnisearch-backing.js";
import {OmnisearchUtilsUi} from "./omnisearch/omnisearch-utils-ui.js";

class SearchPage {
	static _STORAGE_KEY_IS_EXPANDED = "isExpanded";

	static _wrp = null;
	static _wrpResults = null;
	static _rowMetas = null;
	static _observer = null;
	static _observed = new Map();
	static _isAllExpanded = false;

	static async pInit () {
		await Promise.all([
			PrereleaseUtil.pInit(),
			BrewUtil2.pInit(),
		]);
		ExcludeUtil.pInitialise().then(null); // don't await, as this is only used for search

		SearchPage._isAllExpanded = (await StorageUtil.pGetForPage(SearchPage._STORAGE_KEY_IS_EXPANDED)) || false;
		SearchPage._wrp = veEs(`#main_content`).vee.empty();
		this._render();
		window.dispatchEvent(new Event("toolsLoaded"));
	}

	/* -------------------------------------------- */

	static _PARAM_QUERY = "q";
	static _PARAM_LUCKY = "lucky";

	static _getSearchParams () {
		const params = new URLSearchParams(location.search);
		return Object.fromEntries(params);
	}

	static _setSearchParams (obj) {
		const params = new URLSearchParams(obj);
		const url = new URL(location.href);
		url.search = params.toString();
		if (!window.__oursSearch?.navigate(url)) location.search = url.search;
	}

	/* -------------------------------------------- */

	static _render_getBtnToggleFilter ({btnMeta}) {
		const btn = veT`<button class="ve-btn ve-btn-default" title="${btnMeta.title.qq()}">${btnMeta.text.qq()}</button>`
			.vee.onn("click", () => OmnisearchState[btnMeta.fnDoToggleOmnisearch]());
		const hkBrew = (val) => {
			btn.vee.toggleClass("ve-active", OmnisearchState[btnMeta.propOmnisearch]);
			if (val == null) return;
			this._pDoSearch().then(null);
		};
		OmnisearchState[btnMeta.fnAddHookOmnisearch](hkBrew);
		hkBrew();

		return btn;
	}

	static _render () {
		const iptSearch = veT`<input class="ve-form-control pg-search__ipt" placeholder="全局搜索.." title="免责声明：不一定真的达到全域搜索，请谨慎使用。">`
			.vee.onn("keydown", evt => {
				if (evt.key !== "Enter") return;
				btnSearch.vee.trigger("click");
			})
			.vee.val(this._getSearchParams()[this._PARAM_QUERY]);

		const btnSearch = veT`<button class="ve-btn ve-btn-default"><span class="glyphicon glyphicon-search"></span></button>`
			.vee.onn("click", () => {
				this._setSearchParams({
					[this._PARAM_QUERY]: iptSearch.vee.val().trim().toLowerCase(),
				});
			});

		const btnHelp = veT`<button class="ve-btn ve-btn-default ve-mr-2 ve-mobile-sm__hidden" title="帮助"><span class="glyphicon glyphicon-info-sign"></span></button>`
			.vee.onn("click", () => OmnisearchUtilsUi.doShowHelp());

		const btnCyclePartneredMode = veT`<button class="ve-btn ve-btn-default pg-search__btn-partnered-mode"></button>`;
		OmnisearchUtilsUi.bindBtnCyclePartneredMode({
			btn: btnCyclePartneredMode,
			omnisearchState: OmnisearchState,
			fnDoSearch: this._pDoSearch.bind(this),
		});

		const [
			btnToggleBrew,
			btnToggleUa,
			btnToggleBlocklisted,
			btnToggleLegacy,
			btnToggleSrd,
		] = OmnisearchConsts.BTN_METAS
			.map(btnMeta => this._render_getBtnToggleFilter({btnMeta}));

		const handleMassExpandCollapse = mode => {
			SearchPage._isAllExpanded = mode;
			StorageUtil.pSetForPage("isExpanded", SearchPage._isAllExpanded);

			if (!SearchPage._rowMetas) return;
			SearchPage._rowMetas
				.filter(meta => meta.setIsExpanded)
				.forEach(meta => meta.setIsExpanded(mode));
		};

		const btnCollapseAll = veT`<button class="ve-btn ve-btn-default" title="折叠所有结果"><span class="glyphicon glyphicon-minus"></span></button>`
			.vee.onn("click", () => handleMassExpandCollapse(false));

		const btnExpandAll = veT`<button class="ve-btn ve-btn-default" title="展开所有结果"><span class="glyphicon glyphicon-plus"></span></button>`
			.vee.onn("click", () => handleMassExpandCollapse(true));

		SearchPage._wrpResults = veT`<div class="ve-flex-col ve-w-100">${this._getWrpResult_message("加载中...")}</div>`;

		veT(SearchPage._wrp)`<div class="ve-flex-col ve-w-100 pg-search__wrp">
			<div class="ve-flex-v-center ve-mb-2 ve-mobile-lg__flex-col">
				<div class="ve-flex-v-center ve-input-group ve-btn-group ve-mr-2 ve-w-100 ve-mobile-lg__mb-2">${iptSearch}${btnSearch}</div>

				<div class="ve-flex-v-center ve-mobile-sm__flex-col ve-mobile-lg__flex-ai-start ve-mobile-lg__w-100">
					${btnHelp}
					<div class="ve-mr-2 ve-ml-1 ve-mobile-sm__ml-0 ve-mobile-sm__mb-2 ve-italic">包括</div>
					<div class="ve-flex-v-center ve-btn-group ve-mr-2 ve-mobile-sm__mb-2 ve-mobile-sm__mr-0">
						${btnCyclePartneredMode}
						${btnToggleBrew}
						${btnToggleUa}
					</div>
					<div class="ve-flex-v-center ve-btn-group ve-mr-2 ve-mobile-sm__mb-2 ve-mobile-sm__mr-0">
						${btnToggleBlocklisted}
						${btnToggleLegacy}
					</div>
					<div class="ve-flex-v-center ve-mr-2 ve-mobile-sm__mb-2 ve-mobile-sm__mr-0">
						${btnToggleSrd}
					</div>
					<div class="ve-btn-group ve-flex-v-center">
						${btnCollapseAll}
						${btnExpandAll}
					</div>
				</div>
			</div>
			${SearchPage._wrpResults}
		</div>`;

		this._pDoSearch().then(null);
	}

	static async _pDoSearch () {
		const token = this._oursSearch = Symbol();
		if (SearchPage._observer) {
			for (const ele of SearchPage._observed.keys()) SearchPage._observer.unobserve(ele);
		} else {
			SearchPage._observer = new IntersectionObserver(
				(obsEntries) => {
					obsEntries.forEach(entry => {
						if (entry.intersectionRatio > 0) { // filter observed entries for those that intersect
							SearchPage._observer.unobserve(entry.target);
							const meta = SearchPage._observed.get(entry.target);
							meta.onObserve();
						}
					});
				},
				{rootMargin: "150px 0px", threshold: 0.01},
			);
		}
		SearchPage._rowMetas = [];

		const params = this._getSearchParams();

		if (!params[this._PARAM_QUERY]) {
			SearchPage._wrpResults.vee.empty().vee.appends(this._getWrpResult_message("输入搜索内容以查看结果"));
			return;
		}

		const size = 20;
		const results = await OmnisearchBacking.pGetResults(params[this._PARAM_QUERY], size);
		const pages = Math.ceil(results.length / size);
		const page = Math.max(0, Math.min(pages - 1, parseInt(params.p, 10) - 1 || 0));
		if (results._oursLoadPage && page) await results._oursLoadPage(page * size);
		if (this._oursSearch !== token) return;
		const current = results._oursLoadPage ? results.slice(page * size, (page + 1) * size) : results;

		SearchPage._wrpResults.vee.empty();

		if (!results.length) {
			SearchPage._wrpResults.vee.appends(this._getWrpResult_message("未搜索到结果。"));
			return;
		}

		if (this._PARAM_LUCKY in params) {
			const [href] = results
				.map(res => OmnisearchUtilsUi.getResultHref(res.doc))
				.filter(Boolean);

			if (href) {
				window.location = `${Renderer.get().baseUrl}${href}`;
				return;
			}
		}

		SearchPage._rowMetas = current.map((result, index) => {
			if (result.doc._oursFuzzy && !current[index - 1]?.doc._oursFuzzy) {
				SearchPage._wrpResults.vee.appends('<div class="ours-search-section">近似结果</div>');
			}
			const r = result.doc;

			const lnk = OmnisearchUtilsUi.getResultLink(r);

			const {
				source,
				page,
				isHoverable,
				category,
				hash,
				isSrd,
				isSrd52,

				sourceAbv,
				sourceFull,
			} = UtilsOmnisearch.getUnpackedSearchResult(r);

			const ptPageInner = page ? `${page}页` : "";
			const adventureBookSourceHref = SourceUtil.getAdventureBookSourceHref(source, page);
			const ptPage = ptPageInner && adventureBookSourceHref
				? `<a href="${adventureBookSourceHref}">${ptPageInner}</a>`
				: ptPageInner;

			const ptSrd = isSrd ? `<span class="ve-muted ve-relative ve-help-subtle pg-search__disp-srd" title="可用于系统参考文档(5.1)">[SRD]</span>` : "";
			const ptSrd52 = isSrd52 ? `<span class="ve-muted ve-relative ve-help-subtle pg-search__disp-srd" title="可用于系统参考文档(5.2)">[SRD]</span>` : "";

			const ptSourceInner = source
				? `<i>${sourceFull}</i> (<span class="${Parser.sourceJsonToSourceClassname(source)}">${sourceAbv}</span>)${ptSrd}${ptSrd52}${Parser.sourceJsonToMarkerHtml(source, {isAddBrackets: true, additionalStyles: "pg-search__disp-source-marker"})}`
				: `<span></span>`;
			const ptSource = ptPage || !adventureBookSourceHref
				? ptSourceInner
				: `<a href="${adventureBookSourceHref}">${ptSourceInner}</a>`;

			const dispImage = veT`<div class="ve-flex-col pg-search__disp-token ve-mr-3 ve-no-shrink"></div>`;
			const dispPreview = veT`<div class="ve-flex-col ve-mobile-sm__w-100"></div>`;
			const wrpPreviewControls = veT`<div class="ve-flex-col ve-mobile-sm__mb-2 ve-mobile-sm__w-100 ve-h-100"></div>`;

			const out = {};

			const row = veT`<div class="ve-my-2 ve-py-2 ve-pl-3 ve-pr-2 pg-search__wrp-result ve-flex ve-relative ve-mobile-sm__flex-col">
				<div class="ve-flex-v-center ve-mobile-sm__mb-2 ve-w-100">
					${dispImage}
					<div class="ve-flex-col ve-flex-h-center ve-mr-auto">
						<div class="ve-mb-2">${lnk}</div>
						<div>${ptSource}${ptPage ? `, ${ptPage}` : ""}</div>
					</div>
				</div>
				<div class="ve-flex-v-center ve-mobile-sm__flex-col-reverse ve-mobile-sm__flex-ai-start">
					${dispPreview}
					${wrpPreviewControls}
				</div>
			</div>`.vee.appendTo(SearchPage._wrpResults);

			if (isHoverable) {
				out.isExpanded = !!SearchPage._isAllExpanded;

				const handleIsExpanded = () => {
					dispPreview.vee.toggle(out.isExpanded);
					btnTogglePreview
						.vee.html(out.isExpanded ? `<span class="glyphicon glyphicon-minus"></span>` : `<span class="glyphicon glyphicon-plus"></span>`)
						.vee.toggleClass("pg-search__btn-toggle-preview--expanded", out.isExpanded);
				};

				out.setIsExpanded = val => {
					out.isExpanded = !!val;
					handleIsExpanded();
				};

				const btnTogglePreview = veT`<button class="ve-btn ve-btn-default ve-btn-xs ve-h-100" title="切换预览"></button>`
					.vee.onn("click", () => {
						out.isExpanded = !out.isExpanded;
						handleIsExpanded();
					})
					.vee.appendTo(wrpPreviewControls);

				handleIsExpanded();
			}

			SearchPage._observed.set(
				row,
				{
					onObserve: () => {
						const page = UrlUtil.categoryToHoverPage(category);
						if (!page) {
							dispImage.vee.addClass(`ve-mobile-sm__hidden`);
							return;
						}

						DataLoader.pCacheAndGet(
							page,
							source,
							hash,
						).then(ent => {
							// region Render tokens, where available
							let isImagePopulated = false;

							const displayTokenImage = (
								{
									fnHasToken,
									fnGetTokenUrl,
								},
								ent,
							) => {
								if (!fnHasToken(ent)) return;

								isImagePopulated = true;
								const tokenUrl = fnGetTokenUrl(ent);
								dispImage.vee.html(`<img src="${tokenUrl}" class="ve-w-100 ve-h-100" ${Renderer.utils.getTokenMetadataAttributes(ent)} loading="lazy">`);
							};

							switch (category) {
								case Parser.CAT_ID_CREATURE: {
									displayTokenImage(
										{
											fnHasToken: Renderer.monster.hasToken,
											fnGetTokenUrl: Renderer.monster.getTokenUrl,
										},
										ent,
									);
									break;
								}
								case Parser.CAT_ID_VEHICLE: {
									displayTokenImage(
										{
											fnHasToken: Renderer.vehicle.hasToken,
											fnGetTokenUrl: Renderer.vehicle.getTokenUrl,
										},
										ent,
									);
									break;
								}
								case Parser.CAT_ID_OBJECT: {
									displayTokenImage(
										{
											fnHasToken: Renderer.object.hasToken,
											fnGetTokenUrl: Renderer.object.getTokenUrl,
										},
										ent,
									);
									break;
								}

								case Parser.CAT_ID_BOOK:
								case Parser.CAT_ID_ADVENTURE: {
									const prop = category === Parser.CAT_ID_BOOK ? "book" : "adventure";
									isImagePopulated = true;
									dispImage.vee.html(`<img src="${Renderer.adventureBook.getCoverUrl(ent[prop])}" class="ve-w-100 ve-h-100" alt="封面图: ${(ent[prop].name || "").qq()}" loading="lazy">`);
								}
							}

							if (!isImagePopulated) dispImage.vee.addClass(`ve-mobile-sm__hidden`);
							// endregion

							if (isHoverable) {
								// region Render preview

								Renderer.hover.getHoverContent_stats(page, ent)
									.vee.removeClass("ve-w-100")
									.vee.addClass("pg-search__wrp-preview")
									.vee.addClass("ve-mobile-sm__w-100")
									.vee.addClass("ve-br-0")
									.vee.appendTo(dispPreview);
								// endregion
							}
						});
					},
				},
			);
			SearchPage._observer.observe(row);

			return out;
		});
		if (results._oursLoadPage && pages > 1) {
			const pager = veT`<div class="ve-flex-vh-center ve-p-2"></div>`.vee.appendTo(SearchPage._wrpResults);
			for (const [label, ix] of [["上一页", page - 1], ["下一页", page + 1]]) {
				const button = veT`<button class="ve-btn ve-btn-default ve-mx-2">${label}</button>`;
				button.disabled = ix < 0 || ix >= pages;
				button.addEventListener("click", () => this._setSearchParams({...params, p: ix + 1}));
				pager.append(button);
			}
			const count = veT`<span>${page + 1} / ${pages}</span>`;
			pager.insertBefore(count, pager.lastChild);
		}
	}

	static _getWrpResult_message (message) {
		return `<div class="ve-my-2 ve-py-2 ve-px-3 pg-search__wrp-result ve-flex-vh-center"><i>${message.qq()}</i></div>`;
	}
}

window.addEventListener("load", () => SearchPage.pInit());

