				(it.source || "").toLowerCase() === sourceDefault.toLowerCase() ? "" : it.source,
				displayName || "",
			].join("|").replace(/\|+$/, ""); // Trim trailing pipes
			if (isMaintainCase) return out;
			return out.toLowerCase();
		}
	};

