import {ConverterBase} from "./converter-base.js";
import {TagJsons} from "./converterutils-entries.js";

export class ConverterEntries extends ConverterBase {
	/**
	 * Parses feats from raw text pastes
	 * @param inText Input text.
	 * @param options Options object.
	 * @param options.cbWarning Warning callback.
	 * @param options.cbOutput Output callback.
	 * @param options.isAppend Default output append mode.
	 * @param options.source Entity source.
	 * @param options.page Entity page.
	 * @param options.titleCaseFields Array of fields to be title-cased in this entity (if enabled).
	 * @param options.isTitleCase Whether title-case fields should be title-cased in this entity.
	 * @param options.styleHint
	 */
	static doParseMarkdown (inText, options) {
		options = this._getValidOptions(options);

		const toConvert = this._getCleanInput(inText, options);

		const entries = MarkdownConverter.getEntries(toConvert);

		TagJsons.mutTagObjectStrictCapsWords(entries, {styleHint: options.styleHint});
		TagJsons.mutTagObject(entries, {styleHint: options.styleHint});

		options.cbOutput(entries, options.isAppend);

		return entries;
	}
}

/js/converter/converter-feat.js:
import {ConversionStateTextBase} from "./converterutils-models.js";
import {ConverterFeatureBase} from "./converter-feature.js";
import {TagCondition} from "./converterutils-tags.js";
import {EntryCoalesceEntryLists, EntryCoalesceRawLines} from "./converterutils-entrycoalesce.js";
import {TagJsons} from "./converterutils-entries.js";
import {ConverterUtils} from "./converterutils-utils.js";
import {PropOrder} from "../utils-proporder.js";

class _ConversionStateTextFeat extends ConversionStateTextBase {

}

export class ConverterFeat extends ConverterFeatureBase {
	/**
	 * Parses feats from raw text pastes
	 * @param inText Input text.
	 * @param options Options object.
	 * @param options.cbWarning Warning callback.
	 * @param options.cbOutput Output callback.
	 * @param options.isAppend Default output append mode.
	 * @param options.source Entity source.
	 * @param options.page Entity page.
	 * @param [options.isAddPageNumber] Whether to include the page in the output. Defaults to true if a page is provided.
	 * @param options.titleCaseFields Array of fields to be title-cased in this entity (if enabled).
	 * @param options.isTitleCase Whether title-case fields should be title-cased in this entity.
	 * @param options.styleHint
	 */
	static doParseText (inText, options) {
		options = this._getValidOptions(options);

		const {toConvert, entity: feat} = this._doParse_getInitialState(inText, options);
		if (!toConvert) return;

		const state = new _ConversionStateTextFeat({toConvert, options, entity: feat});

		state.doPreLoop();
		for (; state.ixToConvert < toConvert.length; ++state.ixToConvert) {
			state.initCurLine();
			if (state.isSkippableCurLine()) continue;

			switch (state.stage) {
				case "name": this._doParseText_stepName(state); state.stage = "category"; break;
				case "category": this._doParseText_stepCategory(state, options); state.stage = "prerequisites"; break;
				case "prerequisites": this._doParseText_stepPrerequisites(state, options); state.stage = "entries"; break;
				case "entries": this._doParseText_stepEntries(state, options); break;
				default: throw new Error(`无法转换的部分："${state.stage}"`);
			}
		}
		state.doPostLoop();

		if (!feat.entries.length) delete feat.entries;
		else {
			this._mutMergeHangingListItems(feat, options);
			this._setAbility(feat, options);
			this._setRepeatable(feat, options);
		}

		const statsOut = this._getFinalState(state, options);

		options.cbOutput(statsOut, options.isAppend);

		return statsOut;
	}

	/* -------------------------------------------- */

	static _doParseText_stepName (state) {
		[state.entity.name, state.entity.ENG_name] = ConverterUtils.splitNameToChineseAndEnglish(this._getAsTitle("name", state.curLine, state.options.titleCaseFields, state.options.isTitleCase));
	}

	/* -------------------------------------------- */

	static _getCategoryMeta ({str}) {
		const mFeatCategory = new RegExp(`^${this._RE_FEAT_TYPE.source}(?: Feat|专长)?`).exec(str);
		if (mFeatCategory) {
			return {
				category: Parser.featCategoryFromFull(mFeatCategory.groups.category),
				remaining: str.slice(mFeatCategory[0].length).trim(),
			};
		}

		const mFeatCategoryUnknown = /(?<ptCategory>.*) Feat (?=\(Prerequisite\b)/i.exec(str);
		if (mFeatCategoryUnknown) {
			const categoryRaw = mFeatCategoryUnknown.groups.ptCategory.trim();
			return {
				category: categoryRaw,
				categoryWarning: `Unknown feat category "${categoryRaw}"`,
				remaining: str.slice(mFeatCategoryUnknown[0].length).trim(),
			};
		}

		return null;
	}

	/* -------------------------------------------- */

	static _getCategoryMeta ({str}) {
		const mFeatCategory = new RegExp(`^${this._RE_FEAT_TYPE.source}(?: Feat)?`).exec(str);
		if (mFeatCategory) {
			return {
				category: Parser.featCategoryFromFull(mFeatCategory.groups.category),
				remaining: str.slice(mFeatCategory[0].length).trim(),
			};
		}

		const mFeatCategoryUnknown = /(?<ptCategory>.*) Feat (?=\(Prerequisite\b)/i.exec(str);
		if (mFeatCategoryUnknown) {
			const categoryRaw = mFeatCategoryUnknown.groups.ptCategory.trim();
			return {
				category: categoryRaw,
				categoryWarning: `Unknown feat category "${categoryRaw}"`,
				remaining: str.slice(mFeatCategoryUnknown[0].length).trim(),
			};
		}

		return null;
	}

	static _doParseText_stepCategory (state, options) {
		const categoryMeta = this._getCategoryMeta({str: state.curLine});
		if (!categoryMeta) {
			state.ixToConvert--;
			return;
		}

		state.entity.category = categoryMeta.category;
		if (categoryMeta.categoryWarning) options.cbWarning(`(${state.entity.name}) Category requires manual conversion`);

		let remaining = categoryMeta.remaining;
		if (!remaining) return;

		remaining = remaining.replace(/^[(（](.*)[)）]$/, "$1");

		if (!/^(?:prerequisite|先决条件)[:：]/gi.test(remaining)) {
			options.cbWarning(`(${state.entity.name})的先决条件"${remaining}"需要手动转换`);
			return;
		}

		(state.entity.entries ||= [])
			.push({
				name: "先决条件:",
				entries: [
					remaining
						.replace(/^(?:prerequisite|先决条件)[:：]/gi, "")
						.trim(),
				],
			});
	}

	/* -------------------------------------------- */

	static _doParseText_stepPrerequisites (state, options) {
		if (!/^(?:prerequisite|先决条件)[:：]/i.test(state.curLine)) {
			state.ixToConvert--;
			return;
		}

		(state.entity.entries ||= [])
			.push({
				name: "先决条件:",
				entries: [
					state.curLine
						.replace(/^(?:prerequisite|先决条件)[:：]/i, "")
						.trim(),
				],
			});
	}

	/* -------------------------------------------- */

	static _doParseText_stepEntries (state, options) {
		const ptrI = {_: state.ixToConvert};
		const entries = EntryCoalesceRawLines.mutGetCoalesced(
			ptrI,
			state.toConvert,
		);
		state.ixToConvert = ptrI._;

		state.entity.entries = [
			...(state.entity.entries || []),
			...entries,
		];
	}

	static _getFinalState (state, options) {
		this._doPostProcess_removePage(state.entity, options);

		this._doFeatPostProcess(state, options);
		return PropOrder.getOrdered(state.entity, state.entity.__prop || "feat");
	}

	// SHARED UTILITY FUNCTIONS ////////////////////////////////////////////////////////////////////////////////////////
	static _doFeatPostProcess (state, options) {
		TagCondition.tryTagConditions(state.entity, {styleHint: options.styleHint});

		if (!state.entity.entries) return;

		EntryCoalesceEntryLists.mutCoalesce(state, "entries", {styleHint: options.styleHint});
		this._doPostProcess_setPrerequisites(state, options);
		if (state.entity.category === "G" && state.entity.name.startsWith("Boon") && state.entity.prerequisite?.some(it => it.level === 19)) state.entity.category = "EB";
		TagJsons.mutTagObjectStrictCapsWords(state.entity, {keySet: new Set(["entries"]), styleHint: options.styleHint});
		TagJsons.mutTagObject(state.entity, {keySet: new Set(["entries"]), isOptimistic: false, styleHint: options.styleHint});
	}

	// SHARED PARSING FUNCTIONS ////////////////////////////////////////////////////////////////////////////////////////
	static _mutMergeHangingListItems (feat, options) {
		const ixStart = feat.entries.findIndex(ent => typeof ent === "string" && /(?:following|these|以下|这些)(?: benefits|增益(?:效[果应])?)[:：。]$/.test(ent));
		if (!~ixStart) return;

		let list;
		for (let i = ixStart + 1; i < feat.entries.length; ++i) {
			const ent = feat.entries[i];
			if (ent.type !== "entries" || !ent.name || !ent.entries?.length) break;

			if (!list) list = {type: "list", style: "list-hang-notitle", items: []};

			list.items.push({
				...ent,
				type: "item",
			});
			feat.entries.splice(i, 1);
			--i;
		}

		if (!list?.items?.length) return;

		feat.entries.splice(ixStart + 1, 0, list);
	}

	static _setAbility (feat, options) {
		const isAbilitySet = this._doPostProcess_setAbility(feat, options);
		if (isAbilitySet) return;

		const walker = MiscUtil.getWalker({
			keyBlocklist: MiscUtil.GENERIC_WALKER_ENTRIES_KEY_BLOCKLIST,
			isNoModification: true,
		});

		walker.walk(
			feat.entries,
			{
				object: (obj) => {
					if (obj.type !== "list") return obj;

					const str = typeof obj.items[0] === "string" ? obj.items[0] : obj.items[0].entries?.[0];
					if (typeof str !== "string") return obj;

					if (/^increase your/i.test(str)) {
						const abils = [];
						str.replace(/(Strength|Dexterity|Constitution|Intelligence|Wisdom|Charisma)/g, (...m) => {
							abils.push(m[1].toLowerCase().slice(0, 3));
						});

						if (abils.length === 1) {
							feat.ability = [{[abils[0]]: 1}];
						} else {
							feat.ability = [
								{
									choose: {
										from: abils,
										amount: 1,
									},
								},
							];
						}

						obj.items.shift();
						return obj;
					}

					if (/^increase (?:one|an) ability score of your choice by 1/i.test(str)) {
						feat.ability = [
							{
								choose: {
									from: [...Parser.ABIL_ABVS],
									amount: 1,
								},
							},
						];

						obj.items.shift();
						return obj;
					}
				},
			},
		);

		if (
			feat.entries.some(ent => typeof ent === "string" && /\bIncrease one ability score of your choice by 2, or increase two ability scores of your choice by 1\b/i.test(ent))
		) {
			feat.ability = [
				{
					"choose": {
						"from": [
							"str",
							"dex",
							"con",
							"int",
							"wis",
							"cha",
						],
						"amount": 2,
					},
					"hidden": true,
				},
				{
					"choose": {
						"from": [
							"str",
							"dex",
							"con",
							"int",
							"wis",
							"cha",
						],
						"count": 2,
					},
					"hidden": true,
				},
			];
		}
	}

	static _setRepeatable (feat, options) {
		const walker = MiscUtil.getWalker({
			keyBlocklist: MiscUtil.GENERIC_WALKER_ENTRIES_KEY_BLOCKLIST,
			isNoModification: true,
		});

		walker.walk(
			feat.entries,
			{
				object: (obj) => {
					if (obj.name !== "Repeatable") return;
					feat.repeatable = true;
				},
			},
		);
	}
}

/js/converter/converter-feature.js:
import {ConverterBase} from "./converter-base.js";
import {ConverterConst} from "./converterutils-const.js";
import {AlignmentUtil} from "./converterutils-utils-alignment.js";
import {ConverterUtils} from "./converterutils-utils.js";

export class ConverterFeatureBase extends ConverterBase {
	static _RE_FEAT_TYPE = new RegExp(`\\b(?<category>${Object.values(Parser.FEAT_CATEGORY_TO_FULL).join("|")})\\b`);

	/* -------------------------------------------- */

	static _doParse_getInitialState (inText, options) {
		if (!inText || !inText.trim()) {
			options.cbWarning("没有输入！");
			return {};
		}

		const toConvert = this._getCleanInput(inText, options)
			.split("\n")
			.filter(it => it && it.trim());

		const entity = {};
		entity.source = options.source;
		// for the user to fill out
		entity.page = options.page;

		return {toConvert, entity};
	}

	/* -------------------------------------------- */

	static _doPostProcess_setPrerequisites (state, options) {
		const [entsPrereq, entsRest] = state.entity.entries.segregate(ent => /(:?Prerequisite|先决条件|先决)[:：]/i.test(ent.name));
		if (!entsPrereq.length) return;

		if (entsPrereq.length > 1) {
			options.cbWarning(`(${state.entity.name}) 先决条件无法自动转换`);
			return;
		}

		const [entPrereq] = entsPrereq;
		if (entPrereq.entries.length > 1 || (typeof entPrereq.entries[0] !== "string")) {
			options.cbWarning(`(${state.entity.name}) 先决条件无法自动转换`);
			return;
		}
		const [entPrereqString] = entPrereq.entries;

		state.entity.entries = entsRest;

		const pres = [];
		const tokens = this._getPrerequisiteTokens(entPrereqString);

		// Collect ability score requirements and cross-product them with other prerequisites later
		const preAbilsMeta = {abils: [], score: null};

		let tkStack = [];

		const handleStack = () => {
			const meta = this._doPostProcess_setPrerequisites_handleStack({state, options, tkStack, preAbilsMeta});

			if (meta != null) {
				pres.push(meta.pre);
			}

			tkStack = [];
		};

		const reAbils = /^(?:Strength|Dexterity|Constitution|Intelligence|Wisdom|Charisma),?/;

		for (let i = 0; i < tokens.length; ++i) {
			const tk = tokens[i];
			const tkNxt = tokens[i + 1];

			// If we're in a list of abilities, greedily take tokens
			if (reAbils.test(tk)) {
				tkStack.push(tk);

				let j = i + 1;
				for (; j < tokens.length; ++j) {
					const tkNxt = tokens[j];
					if (!reAbils.test(tk) && tkNxt !== "or") break;
					tkStack.push(tkNxt);
				}
				if (j > i + 1) i = j;
				continue;
			}

			if (tk !== "or") {
				tkStack.push(tk);
				continue;
			}

			handleStack();
		}
		handleStack();

		if (
			(preAbilsMeta.score && !preAbilsMeta.abils.length)
			|| (!preAbilsMeta.score && preAbilsMeta.abils.length)
		) {
			return options.cbWarning(`(${state.entity.name}) Prerequisite require manual conversion`);
		}

		const presDeduped = [];
		pres.forEach(pre => {
			if (presDeduped.some(it => CollectionUtil.deepEquals(pre, it))) return;
			presDeduped.push(pre);
		});

		const presOut = [];
		if (!preAbilsMeta.abils.length) presOut.push(...presDeduped);
		else if (!presDeduped.length) {
			presOut.push(
				...preAbilsMeta.abils
					.map(abv => ({
						"ability": [{[abv]: preAbilsMeta.score}],
					})),
			);
		} else {
			preAbilsMeta.abils
				.forEach(abv => {
					MiscUtil.copyFast(presDeduped)
						.forEach(cpy => {
							cpy.ability = [{[abv]: preAbilsMeta.score}];
							presOut.push(cpy);
						});
				});
		}

		if (!presOut.length) return;

		state.entity.prerequisite = presOut;
	}

	static _doPostProcess_setPrerequisites_handleStack ({state, options, tkStack, preAbilsMeta}) {
		if (!tkStack.length) return;

		while ([",", ";", "，", "；"].includes(tkStack.at(-1))) tkStack.pop();
		const joinedStack = tkStack.join(" ").trim();

		const parts = joinedStack.split(
			(joinedStack.includes(";") || joinedStack.includes("；"))
				? StrUtil.SEMICOLON_SPACE_NOT_IN_PARENTHESES_REGEX
				: StrUtil.COMMA_SPACE_NOT_IN_PARENTHESES_REGEX,
		);

		const pre = {};

		parts.forEach(pt => {
			pt = pt.trim().replace(/[,;，；]\s*$/, "");

			if (/^the ability to cast at least one spell$/i.test(pt)) return pre.spellcasting = true;

			if (/^(?:spellcasting|施法能力|施法)$/i.test(pt)) return pre.spellcasting2020 = true;
			if (/^(?:pact magic feature|契约魔法|契约魔法特性)$/i.test(pt)) return pre.spellcasting2020 = true;
			if (/^(?:Spellcasting (?:Feature )?or Pact Magic Feature|施法(?:特性)或契约魔法特性)$/i.test(pt)) return pre.spellcasting2020 = true;

			if (/^(?:spellcasting feature|施法特性)$/i.test(pt)) return pre.spellcastingFeature = true;
			if (/^(?:spellcasting feature from a class that prepares spells|需要准备法术的施法职业特性)$/i.test(pt)) return pre.spellcastingPrepared = true;

			if (/^(?:proficiency with a martial weapon|熟练于军用武器)$/i.test(pt)) {
				pre.proficiency ||= [{}];
				pre.proficiency[0].weapon = "martial";
				return;
			}

			if (/^(?:Martial Weapon Proficiency|军用武器熟练项)$/i.test(pt)) {
				pre.proficiency ||= [{}];
				pre.proficiency[0].weaponGroup = "martial";
				return;
			}

			const mArmor = /^(?<armorType>Light|Medium|Heavy) Armor (?:Training|Proficiency)$/i.exec(pt)
				|| /^(?<armorType>Shield) (?:Training|Proficiency)$/i.exec(pt)
				|| /^(?<armorType>轻|中|重)甲(?:受训|熟练|熟练项)$/i.exec(pt)
				|| /^(?<armorType>盾牌)(?:受训|熟练|熟练项)$/i.exec(pt);
			if (mArmor) {
				pre.proficiency ||= [{}];
				switch (mArmor.groups.armorType) {
					case "Light":
					case "轻":
						pre.proficiency[0].armor = "light";
						break;
					case "Medium":
					case "中":
						pre.proficiency[0].armor = "medium";
						break;
					case "Heavy":
					case "重":
						pre.proficiency[0].armor = "heavy";
						break;
					case "Shield":
					case "盾牌":
						pre.proficiency[0].armor = "shield";
						break;
				}
				return;
			}

			const mLevel = /^(?<level>\d+)..(?: level|级)$/i.exec(pt);
			if (mLevel) return pre.level = Number(mLevel.groups.level);

			const mLevelAlt = /^(?:Level |等级\s?)(?<level>\d+)\+?$/i.exec(pt);
			if (mLevelAlt) return pre.level = Number(mLevelAlt.groups.level);

			const mAbilityPlain = new RegExp(`^(${Object.values(Parser.ATB_ABV_TO_FULL).join("|")})$`).exec(pt);
			if (mAbilityPlain) {
				preAbilsMeta.abils.push(mAbilityPlain[0].slice(0, 3).toLowerCase());
				return;
			}

			const mAbility = new RegExp(`^${Object.entries(Parser.ATB_ABV_TO_FULL).map(([abv, full]) => `(?:or |或)?(?<${abv}>${full})?(?:,? )?`).join("")} (?:score of )?(?<score>\\d+)(?:\\+| or higher)$`).exec(pt);
			if (mAbility) {
				// Expect only one ability score threshold (i.e. no "str 15 OR dex 13")
				if (preAbilsMeta.score) {
					options.cbWarning(`(${state.entity.name}) 属性值先决条件 "${pt}" 无法自动转换`);
					return;
				}

				preAbilsMeta.score = Number(mAbility.groups.score);
				Parser.ABIL_ABVS
					.filter(abv => mAbility.groups[abv])
					.forEach(abv => {
						if (preAbilsMeta.abils.includes(abv)) return options.cbWarning(`(${state.entity.name})属性值先决条件 (${abv}) 无法自动转换`);
						preAbilsMeta.abils.push(abv);
					});

				return;
			}

			const mExclusiveCategory = /^Can't Have Another (?<exclusiveType>.*?) Feat$/i.exec(pt);
			if (mExclusiveCategory) {
				const {exclusiveType} = mExclusiveCategory.groups;
				switch (exclusiveType.toLowerCase().trim()) {
					case "dragonmark": return pre.exclusiveFeatCategory = ["D"];
					default: return pre.exclusiveFeatCategory = [exclusiveType];
				}
			}

			const mFeatCategory = new RegExp(`^Any ${this._RE_FEAT_TYPE.source}(?: Feat|专长)?`, "i").exec(pt);
			if (mFeatCategory) {
				return pre.featCategory = [Parser.featCategoryFromFull(mFeatCategory.groups.category)];
			}

			const mFeat = /^(?<name>.*?)(?: feat|专长)$/i.exec(pt);
			if (mFeat) {
				pre.feat ||= [];
				const rawFeat = mFeat.groups.name.toLowerCase().trim();

				const [ptName, ptSpecifier] = rawFeat.split(/ [(（]([^)）]+)[)）]$/);
				if (!ptSpecifier) return pre.feat.push(`${rawFeat}|${state.entity.source.toLowerCase()}`);

				return pre.feat.push(`${ptName}|${state.entity.source.toLowerCase()}|${rawFeat}`);
			}

			const mBackground = /^(?<name>.*?) (?:background|背景)$/i.exec(pt);
			if (mBackground) {
				const name = mBackground.groups.name.trim();
				return (pre.background = pre.background || []).push({
					name,
					displayEntry: `{@background ${name}}`,
				});
			}

			const mAlignment = /^(?<align>.*?)(?: alignment|阵营)/i.exec(pt);
			if (mAlignment) {
				const {alignment} = AlignmentUtil.tryGetConvertedAlignment(mAlignment.groups.align);
				if (alignment) {
					pre.alignment = alignment;
					return;
				}
			}

			const mCampaign = /^(?<name>.*)?(?: campaign|战役)$/i.exec(pt);
			if (mCampaign) {
				return (pre.campaign = pre.campaign || []).push(mCampaign.groups.name);
			}

			const mClass = new RegExp(`^${ConverterConst.STR_RE_CLASS}(?: class)?$`, "i").exec(pt)
			|| new RegExp(`^${ConverterConst.STR_RE_CLASS_CN}(?:职业)?$`, "i").exec(pt);
			if (mClass) {
				return pre.level = {
					level: 1,
					class: {
						name: mClass.groups.name,
						visible: true,
					},
				};
			}

			const mFeature = /^(?<name>.*)(?: Feature|特性)$/.exec(pt);
			if (mFeature) {
				pre.feature = [mFeature.groups.name];
				return;
			}

			const mCulture = /^(?<name>.*)(?: Culture|文化)$/.exec(pt);
			if (mCulture) {
				pre.culture = [mCulture.groups.name];
				return;
			}

			pre.other = pt;
			options.cbWarning(`(${state.entity.name}) 先决条件 "${pt}" 无法自动转换`);
		});

		if (!Object.keys(pre).length) return null;
		return {pre};
	}

	static _PREREQUISITE_TRIE = null;

	static _getPrerequisiteTokens (entPrereqString) {
		// Pre-clean "Level" formatting
		entPrereqString = entPrereqString
			.replace(/(?<=\bLevel \d+\+?)( and )/g, "; ");

		if (this._PREREQUISITE_TRIE == null) {
			this._PREREQUISITE_TRIE = new Trie();
			[
				"Spellcasting or Pact Magic Feature",
				"Spellcasting Feature or Pact Magic Feature",
				"施法或契约魔法特性",
				"施法特性或契约魔法特性",
			]
				.forEach(str => this._PREREQUISITE_TRIE.add(str));
		}

		const toSplitRanges = [];
		for (let i = 0; i < entPrereqString.length; ++i) {
			const char = entPrereqString[i];
			if (char === " ") {
				continue;
			}

			const slice = entPrereqString.slice(i);
			const fromTrie = this._PREREQUISITE_TRIE.findLongestComplete(slice);
			if (!fromTrie) {
				continue;
			}

			toSplitRanges.push({start: i, end: i + fromTrie.length});
			i += fromTrie.length;
		}

		if (!toSplitRanges.length) return ConverterUtils.getTokens(entPrereqString);

		const out = [];

		let startPrev = 0;
		toSplitRanges
			.forEach(({start, end}) => {
				const prev = ConverterUtils.getTokens(entPrereqString.slice(startPrev, start));
				if (prev.length) out.push(...prev);
				startPrev = end;
				out.push(entPrereqString.slice(start, end));
			});

		const remaining = ConverterUtils.getTokens(entPrereqString.slice(startPrev));
		if (remaining.length) out.push(...remaining);

		return out;
	}

	/* -------------------------------------------- */

	static _doPostProcess_setAbility (entity, options) {
		const asiEntries = entity.entries.filter(it => (it.name || "").toLowerCase() === "ability score increase" || (it.name || "").toLowerCase() === "属性值提升");
		if (!asiEntries.length) return false;

		if (asiEntries.length > 1) {
			options.cbWarning(`发现多个属性值增加项！`);
			return false;
		}

		const [entry] = asiEntries;

		if (entry.entries.length !== 1 || typeof entry.entries[0] !== "string") {
			options.cbWarning(`属性值增加项无法自动转换！`);
			return false;
		}

		const ent = entry.entries[0].trim();

		// "Your Strength score increases by 2."
		const mSimple = new RegExp(`^Your (?<ability>${Object.values(Parser.ATB_ABV_TO_FULL).join("|")}) score increases by (?<amount>\\d+)\\.?$`, "i").exec(ent)
			// "Increase your Charisma score by 1, to a maximum of 20."
			|| new RegExp(`^Increase your (?<ability>${Object.values(Parser.ATB_ABV_TO_FULL).join("|")}) score by (?<amount>\\d+)(?:, to a maximum of (?<max>20|30))?\\.?$`, "i").exec(ent)
			// "你的魅力属性值提升1，至多提升至20。"
			|| new RegExp(`^你的(?<ability>${Object.values(Parser.ATB_ABV_TO_FULL).join("|")})(?:属性值?|值)(?:提升|增?加)(?<amount>\\d+)点?(?:[,，](?:上限为|至多提升至)(?<max>20|30))?[.。]?$`, "i").exec(ent);
		if (mSimple) {
			const asi = {
				[this._doRacePostProcess_ability_getAbilityName(mSimple.groups.ability)]: Number(mSimple.groups.amount),
			};
			if (mSimple.groups.max && mSimple.groups.max !== "20") asi.max = Number(mSimple.groups.max);
			entity.ability = [asi];
			entity.entries = entity.entries.filter(ent => ent !== entry);
			return true;
		}

		// "Your Wisdom and Charisma scores each increase by 1."
		const mSimpleTwoSameAmount = new RegExp(`^Your (?<ability1>${Object.values(Parser.ATB_ABV_TO_FULL).join("|")}) and (?<ability2>${Object.values(Parser.ATB_ABV_TO_FULL).join("|")}) scores each increase by (?<amount>\\d+)\\.?$`, "i").exec(ent);
		if (mSimpleTwoSameAmount) {
			entity.ability = [
				{
					[this._doRacePostProcess_ability_getAbilityName(mSimpleTwoSameAmount.groups.ability1)]: Number(mSimpleTwoSameAmount.groups.amount),
					[this._doRacePostProcess_ability_getAbilityName(mSimpleTwoSameAmount.groups.ability2)]: Number(mSimpleTwoSameAmount.groups.amount),
				},
			];
			entity.entries = entity.entries.filter(ent => ent !== entry);
			return true;
		}

		// "Your Dexterity score increases by 2, and your Charisma score increases by 1."
		const mSimpleTwo = new RegExp(`^Your (?<ability1>${Object.values(Parser.ATB_ABV_TO_FULL).join("|")}) score increases by (?<amount1>\\d+),? and your (?<ability2>${Object.values(Parser.ATB_ABV_TO_FULL).join("|")}) score increases by (?<amount2>\\d+)\\.?$`, "i").exec(ent);
		if (mSimpleTwo) {
			entity.ability = [
				{
					[this._doRacePostProcess_ability_getAbilityName(mSimpleTwo.groups.ability1)]: Number(mSimpleTwo.groups.amount1),
					[this._doRacePostProcess_ability_getAbilityName(mSimpleTwo.groups.ability2)]: Number(mSimpleTwo.groups.amount2),
				},
			];
			entity.entries = entity.entries.filter(ent => ent !== entry);
			return true;
		}

		// "Your Dexterity score increases by 2, but your Strength score decreases by 2."
		const mSimpleIncDec = new RegExp(`^Your (?<ability1>${Object.values(Parser.ATB_ABV_TO_FULL).join("|")}) score increases by (?<amount1>\\d+),? (?:and|but) your (?<ability2>${Object.values(Parser.ATB_ABV_TO_FULL).join("|")}) score decreases by (?<amount2>\\d+)\\.?$`, "i").exec(ent);
		if (mSimpleIncDec) {
			entity.ability = [
				{
					[this._doRacePostProcess_ability_getAbilityName(mSimpleIncDec.groups.ability1)]: Number(mSimpleIncDec.groups.amount1),
					[this._doRacePostProcess_ability_getAbilityName(mSimpleIncDec.groups.ability2)]: -Number(mSimpleIncDec.groups.amount2),
				},
			];
			entity.entries = entity.entries.filter(ent => ent !== entry);
			return true;
		}

		const mEitherSingle = new RegExp(`^Either your (?<ability1>${Object.values(Parser.ATB_ABV_TO_FULL).join("|")}) or (?<ability2>${Object.values(Parser.ATB_ABV_TO_FULL).join("|")}) score increases by (?<amount>\\d+)\\.?$`, "i").exec(ent)
			// "Increase your Strength or Dexterity score by 1, to a maximum of 20."
			|| new RegExp(`^Increase your (?<ability1>${Object.values(Parser.ATB_ABV_TO_FULL).join("|")}) or (?<ability2>${Object.values(Parser.ATB_ABV_TO_FULL).join("|")}) (?:score )?by (?<amount>\\d+)(?:, to a maximum of (?<max>20|30))?\\.?$`, "i").exec(ent);
		if (mEitherSingle) {
			const amount = Number(mEitherSingle.groups.amount);
			const asi = {
				"choose": {
					"from": [
						this._doRacePostProcess_ability_getAbilityName(mEitherSingle.groups.ability1),
						this._doRacePostProcess_ability_getAbilityName(mEitherSingle.groups.ability2),
					],
					...(amount === 1 ? {} : {amount}),
				},
			};
			if (mEitherSingle.groups.max !== "20") asi.max = Number(mEitherSingle.groups.max);
			entity.ability = [asi];
			entity.entries = entity.entries.filter(ent => ent !== entry);
			return true;
		}

		const mSimplePlusEitherSingle = new RegExp(`^Your (?<abilityS>${Object.values(Parser.ATB_ABV_TO_FULL).join("|")}) score increases by (?<amount1S>\\d+), and you can choose to increase either your (?<abilityC1>${Object.values(Parser.ATB_ABV_TO_FULL).join("|")}) or (?<abilityC2>${Object.values(Parser.ATB_ABV_TO_FULL).join("|")}) score by (?<amountC>\\d+)\\.?$`, "i").exec(ent);
		if (mSimplePlusEitherSingle) {
			const amountC = Number(mSimplePlusEitherSingle.groups.amountC);
			entity.ability = [
				{
					[this._doRacePostProcess_ability_getAbilityName(mSimplePlusEitherSingle.groups.abilityS)]: Number(mSimplePlusEitherSingle.groups.amount1S),
					"choose": {
						"from": [
							this._doRacePostProcess_ability_getAbilityName(mSimplePlusEitherSingle.groups.abilityC1),
							this._doRacePostProcess_ability_getAbilityName(mSimplePlusEitherSingle.groups.abilityC2),
						],
						...(amountC === 1 ? {} : {amount: amountC}),
					},
				},
			];
			entity.entries = entity.entries.filter(ent => ent !== entry);
			return true;
		}

		// "Your Strength, Constitution, and Wisdom scores each increase by 1. Then, increase one ability score of your choice by 1."
		const mThreePlusOne = new RegExp(`^Your (?<ability1>${Object.values(Parser.ATB_ABV_TO_FULL).join("|")}), (?<ability2>${Object.values(Parser.ATB_ABV_TO_FULL).join("|")}), and (?<ability3>${Object.values(Parser.ATB_ABV_TO_FULL).join("|")}) scores each increase by (?<amount1>\\d+)\\. Then, increase one ability score of your choice by (?<amount2>\\d+)\\.$`, "i").exec(ent);
		if (mThreePlusOne) {
			const abils = [
				this._doRacePostProcess_ability_getAbilityName(mThreePlusOne.groups.ability1),
				this._doRacePostProcess_ability_getAbilityName(mThreePlusOne.groups.ability2),
				this._doRacePostProcess_ability_getAbilityName(mThreePlusOne.groups.ability3),
			];
			const amount1 = Number(mThreePlusOne.groups.amount1);
			const amount2 = Number(mThreePlusOne.groups.amount2);
			entity.ability = [
				{
					"choose": {
						"weighted": {
							"weights": [
								amount1 + amount2,
								amount2,
								amount2,
							],
							"from": [...abils],
						},
					},
				},
				{
					[this._doRacePostProcess_ability_getAbilityName(mThreePlusOne.groups.ability1)]: amount1,
					[this._doRacePostProcess_ability_getAbilityName(mThreePlusOne.groups.ability2)]: amount1,
					[this._doRacePostProcess_ability_getAbilityName(mThreePlusOne.groups.ability3)]: amount1,
					"choose": {
						"from": Parser.ABIL_ABVS.filter(abv => !abils.includes(abv)),
						...(amount2 === 1 ? {} : {amount: amount2}),
					},
				},
			];

			entity.entries = entity.entries.filter(ent => ent !== entry);
			return true;
		}

		// "Increase one ability score of your choice by 1, to a maximum of 30."
		const mChooseOne = new RegExp(`^Increase one ability score of your choice by 1, to a maximum of (?<max>20|30)\\.?$`, "i").exec(ent);
		if (mChooseOne) {
			const asi = {
				"choose": {
					"from": [...Parser.ABIL_ABVS],
				},
			};
			if (mChooseOne.groups.max !== "20") asi.max = Number(mChooseOne.groups.max);
			entity.ability = [asi];
			entity.entries = entity.entries.filter(ent => ent !== entry);
			return true;
		}

		// "Increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 30."
		const mChooseOneFrom = new RegExp(`^Increase your ${Object.entries(Parser.ATB_ABV_TO_FULL).map(([abv, full]) => `(?:or )?(?<${abv}>${full})?(?:, )?`).join("")} score by 1, to a maximum of (?<max>20|30)\\.?$`, "i").exec(ent);
		if (mChooseOneFrom) {
			const asi = {
				"choose": {
					"from": Parser.ABIL_ABVS.filter(abv => mChooseOneFrom.groups[abv]),
				},
			};
			if (mChooseOneFrom.groups.max !== "20") asi.max = Number(mChooseOneFrom.groups.max);
			entity.ability = [asi];
			entity.entries = entity.entries.filter(ent => ent !== entry);
			return true;
		}

		const mChooseTwoOne = new RegExp(`^You may choose one score to increase by 2 and a different score to increase by 1\\.?$`, "i").exec(ent);
		if (mChooseTwoOne) {
			entity.ability = [
				{
					"choose": {
						"weighted": {
							"from": [...Parser.ABIL_ABVS],
							"weights": [
								2,
								1,
							],
						},
					},
				},
			];
			entity.entries = entity.entries.filter(ent => ent !== entry);
			return true;
		}

		options.cbWarning(`Ability Score Increase "${ent}" requires manual conversion!`);
		return false;
	}

	static _doRacePostProcess_ability_getAbilityName (str) {
		return str.toLowerCase().slice(0, 3);
	}
}

