		strEntries.replace(/重量?为?\s?([\u4e00-\u9fa50-9,]+)\s?(英?磅|吨)/, (...m) => {
			if (m[2].toLowerCase().trim().startsWith("吨")) throw new Error(`不支持自动处理单位“吨”！`);

