import {ConversionStateMarkdownBase, ConversionStateTextBase} from "./converterutils-models.js";
import {ConverterUtilsMarkdown} from "./converterutils-markdown.js";
import {TagJsons} from "./converterutils-entries.js";
import {RaceImmResVulnTag, RaceLanguageTag, RaceTraitTag} from "./converterutils-race.js";
import {EntryCoalesceEntryLists, EntryCoalesceRawLines} from "./converterutils-entrycoalesce.js";
import {ConverterUtils} from "./converterutils-utils.js";
import {ConverterFeatureBase} from "./converter-feature.js";
import {SITE_STYLE__CLASSIC, SITE_STYLE__ONE} from "../consts.js";
import {PropOrder} from "../utils-proporder.js";
import {SkillTag} from "./converterutils-tags.js";

class _ConversionStateTextRace extends ConversionStateTextBase {

}

class _ConversionStateMarkdownRace extends ConversionStateMarkdownBase {
	constructor (...rest) {
		super(...rest);
		this.stack = [];
	}
}

export class ConverterRace extends ConverterFeatureBase {
	static _doParse_getInitialState (inText, options) {
		const out = super._doParse_getInitialState(inText, options);

		out.toConvert = out.toConvert
			.filter(line => {
				if (/[yY]ou have the following traits[.:]$/.test(line)) return false;
				if (/As [^.]+, you have (?:these|the following) special traits[.:]$/.test(line)) return false;
				if (/你获得[以如]下特[质性][.:。：]$/.test(line)) return false;
				if (/作为[^.]+[,，] ?你(?:获得|拥有|有)[以如]下[^.]*特[质性][.:。：]$/.test(line)) return false;
				return true;
			});

		return out;
	}

	/* -------------------------------------------- */

	/**
	 * Parses races from raw text pastes
	 * @param inText Input text.
	 * @param options Options object.
	 * @param options.cbWarning Warning callback.
	 * @param options.cbOutput Output callback.
	 * @param options.isAppend Default output append mode.
	 * @param options.source Entity source.
	 * @param options.page Entity page.
	 * @param [options.isAddPageNumber] Whether to include the page in the output. Defaults to true if a page is provided.
	 * @param options.titleCaseFields Array of fields to be title-cased in this entity (if enabled).
	 * @param options.isTitleCase Whether title-case fields should be title-cased in this entity.
	 * @param options.styleHint
	 */
	static doParseText (inText, options) {
		options = this._getValidOptions(options);

		const {toConvert, entity} = this._doParse_getInitialState(inText, options);
		if (!toConvert) return;

		const state = new _ConversionStateTextRace({toConvert, options, entity});

		state.doPreLoop();
		for (; state.ixToConvert < toConvert.length; ++state.ixToConvert) {
			state.initCurLine();
			if (state.isSkippableCurLine()) continue;

			switch (state.stage) {
				case "name": this._doParseText_stepName(state); state.stage = "entries"; break;
				case "entries": this._doParseText_stepEntries(state); break;
				default: throw new Error(`Unknown stage "${state.stage}"`);
			}
		}
		state.doPostLoop();

		if (!entity.entries?.length) delete entity.entries;

		const raceOut = this._getFinalEntity(entity, options);

		options.cbOutput(raceOut, options.isAppend);

		return raceOut;
	}

	static _doParseText_stepName (state) {
		const name = state.curLine.replace(/( Traits|特[质性])$/i, "");
		[state.entity.name, state.entity.ENG_name] = ConverterUtils.splitNameToChineseAndEnglish(this._getAsTitle("name", state.curLine, state.options.titleCaseFields, state.options.isTitleCase));
		state.entity.name = state.entity.name.replace(/( Traits|特[质性])$/i, "");
		state.entity.ENG_name = state.entity.ENG_name.replace(/( Traits|特[质性])$/i, "");
		// region Skip repeated name line
		const nextLineMeta = state.getNextLineMeta();

		if (
			new RegExp(`^${name.escapeRegexp()} (?:Traits|特[质性])$`).test(nextLineMeta.nxtLine.trim())
		) {
			state.ixToConvert = nextLineMeta.ixToConvertNext;
		}
		// endregion
	}

	static _doParseText_stepEntries (state) {
		const ptrI = {_: state.ixToConvert};
		state.entity.entries = EntryCoalesceRawLines.mutGetCoalesced(
			ptrI,
			state.toConvert,
		);
		state.ixToConvert = ptrI._;
	}

	/* -------------------------------------------- */

	/**
	 * Parses races from raw markdown pastes
	 * @param inText Input text.
	 * @param options Options object.
	 * @param options.cbWarning Warning callback.
	 * @param options.cbOutput Output callback.
	 * @param options.isAppend Default output append mode.
	 * @param options.source Entity source.
	 * @param options.page Entity page.
	 * @param [options.isAddPageNumber] Whether to include the page in the output. Defaults to true if a page is provided.
	 * @param options.titleCaseFields Array of fields to be title-cased in this entity (if enabled).
	 * @param options.isTitleCase Whether title-case fields should be title-cased in this entity.
	 */
	static doParseMarkdown (inText, options) {
		options = this._getValidOptions(options);

		const {toConvert, entity} = this._doParse_getInitialState(inText, options);
		if (!toConvert) return;

		const state = new _ConversionStateMarkdownRace({toConvert, options, entity});

		for (; state.ixToConvert < toConvert.length; ++state.ixToConvert) {
			state.initCurLine();
			if (state.isSkippableCurLine()) continue;

			switch (state.stage) {
				case "name": this._doParseMarkdown_stepName(state); state.stage = "entries"; break;
				case "entries": this._doParseMarkdown_stepEntries(state); break;
				default: throw new Error(`Unknown stage "${state.stage}"`);
			}
		}

		if (!entity.entries?.length) delete entity.entries;

		const raceOut = this._getFinalEntity(entity, options);

		options.cbOutput(raceOut, options.isAppend);

		return raceOut;
	}

	static _doParseMarkdown_stepName (state) {
		state.curLine = ConverterUtilsMarkdown.getNoHashes(state.curLine);
		state.entity.name = this._getAsTitle("name", state.curLine, state.options.titleCaseFields, state.options.isTitleCase);
	}

	static _doParseMarkdown_stepEntries (state) {
		state.entity.entries = state.entity.entries || [];

		if (ConverterUtilsMarkdown.isInlineHeader(state.curLine)) {
			while (state.stack.length) state.stack.pop();

			const nxt = {type: "entries", name: "", entries: []};
			if (state.stack.length) delete nxt.type;
			state.stack.push(nxt);

			state.entity.entries.push(nxt);

			const [name, text] = ConverterUtilsMarkdown.getCleanTraitText(state.curLine);
			nxt.name = name;
			nxt.entries.push(ConverterUtilsMarkdown.getNoLeadingSymbols(text));

			return;
		}

		if (ConverterUtilsMarkdown.isListItem(state.curLine)) {
			if (state.stack.last()?.type !== "list") {
				const lst = {type: "list", items: []};

				if (state.stack.length) {
					state.stack.last().entries.push(lst);
					state.stack.push(lst);
				} else {
					state.entity.entries.push(lst);
					state.stack.push(lst);
				}
			}

			state.curLine = ConverterUtilsMarkdown.getNoLeadingListSymbol(state.curLine);

			if (ConverterUtilsMarkdown.isInlineHeader(state.curLine)) {
				state.stack.last().style = "list-hang-notitle";

				const nxt = {type: "item", name: "", entry: ""};

				state.stack.last().items.push(nxt);

				const [name, text] = ConverterUtilsMarkdown.getCleanTraitText(state.curLine);
				nxt.name = name;
				nxt.entry = ConverterUtilsMarkdown.getNoLeadingSymbols(text);
			} else {
				state.stack.last().items.push(ConverterUtilsMarkdown.getNoLeadingSymbols(state.curLine));
			}

			return;
		}

		while (state.stack.length && state.stack.last().type === "list") state.stack.pop();

		if (state.stack.length) {
			state.stack.last().entries.push(ConverterUtilsMarkdown.getNoLeadingSymbols(state.curLine));
			return;
		}

		state.entity.entries.push(ConverterUtilsMarkdown.getNoLeadingSymbols(state.curLine));
	}

	// SHARED UTILITY FUNCTIONS ////////////////////////////////////////////////////////////////////////////////////////
	static _getFinalEntity (race, options) {
		if (options.styleHint === SITE_STYLE__ONE) race.edition = SITE_STYLE__ONE;
		this._doRacePostProcess(race, options);
		return PropOrder.getOrdered(race, race.__prop || "race");
	}

	static _doRacePostProcess (race, options) {
		this._doPostProcess_removePage(race, options);

		if (!race.entries) return;

		// region Tag
		EntryCoalesceEntryLists.mutCoalesce(race, "entries", {styleHint: options.styleHint});
		TagJsons.mutTagObject(race, {keySet: new Set(["entries"]), isOptimistic: false, styleHint: options.styleHint});
		// endregion

		const isAbilitySet = this._doPostProcess_setAbility(race, options);
		if (!isAbilitySet) {
			if (options.styleHint === SITE_STYLE__CLASSIC) {
				// If there is no ASI info, we assume ~~the worst~~ it's a post-VRGR "lineage" race
				race.lineage = "VRGR";
			}
		}

		// region Race-specific cleanup and generation
		this._doRacePostProcess_size(race, options);
		this._doRacePostProcess_speed(race, options);
		this._doRacePostProcess_speedFlight(race, options);
		this._doRacePostProcess_creatureType(race, options);
		this._doRacePostProcess_darkvision(race, options);

		if (race.entries) race.entries = race.entries.filter(ent => ent.type !== "list" || ent.items?.length);

		SkillTag.tryRunPropsStrictCapsWords(race, ["entries"], {styleHint: options.styleHint});

		RaceLanguageTag.tryRun(race, options);
		RaceImmResVulnTag.tryRun(race, options);
		RaceTraitTag.tryRun(race, options);
		// endregion
	}

	static _getNamedEntry ({race, reName}) {
		const entEntry = race.entries.find(it => reName.test(it.name || ""));
		if (entEntry) return {entry: entEntry, isInRoot: true};

		if (race.entries[0]?.type !== "list") return null;
		const [lst] = race.entries;

		const entList = lst.items.find(it => reName.test(it.name || ""));
		if (!entList) return null;

		return {entry: entList, isInRoot: false, entryParentList: lst};
	}

	static _doRacePostProcess_size (race, options) {
		const {entry, isInRoot, entryParentList} = this._getNamedEntry({race, reName: /^(?:Size|体型)[:：]?$/i}) || {};
		if (entry?.entries?.length !== 1) return options.cbWarning(`无法转换体型\u2014未找到 "体型" 属性！`);

		const text = entry.entries[0];

		const mOnlySize = /^(?<size>Medium|Small|Tiny|中型|小型|微型)\.?$/.exec(text);
		if (mOnlySize) {
			race.size = [
				mOnlySize.groups.size.toUpperCase()[0],
			];

			// Filter out "redundant" size info, as it will be displayed in subtitle
			if (isInRoot) race.entries = race.entries.filter(it => it !== entry);
			else entryParentList.items = entryParentList.items.filter(it => it !== entry);

			return;
		}

		const mSimple = /\b(?:You are|Your size is) (?<size>Medium|Small|Tiny)\.?$/.exec(text)
			|| /, (?:you are|your size is) (?<size>Medium|Small|Tiny)\.?$/.exec(text)
			|| /你(的体型)?[是为](?<size>Medium|Small|Tiny|中型|小型|微型)\.?$/.exec(text);
		if (mSimple) {
			race.size = [
				mSimple.groups.size.toUpperCase()[0],
			];

			// Filter out "redundant" size info, as it will be displayed in subtitle
			if (isInRoot) race.entries = race.entries.filter(it => it !== entry);
			else entryParentList.items = entryParentList.items.filter(it => it !== entry);

			return;
		}

		// "Medium (about 4–5 feet tall)"
		const mSimpleShort = /^(?<size>Medium|Small|Tiny|中型|小型|微型) *[(（][^)）]+[)）]$/.exec(text);
		if (mSimpleShort) {
			race.size = [
				mSimpleShort.groups.size.toUpperCase()[0],
			];

			// Filter out "redundant" size info, as it will be displayed in subtitle
			if (isInRoot) race.entries = race.entries.filter(it => it !== entry);
			else entryParentList.items = entryParentList.items.filter(it => it !== entry);

			return;
		}

		// "Choose whether you are Small or Medium sized."
		const mChooseTwo = /\b(?:You are|Your size is) (?<size1>Medium) or (?<size2>Small)\b/.exec(text)
			|| /\bChoose whether you are (?<size1>Small) or (?<size2>Medium) sized?\b/.exec(text)
			|| /你(的体型)?[是为](?<size1>中型)或(?<size2>小型)/.exec(text);
		if (mChooseTwo) {
			race.size = [
				mChooseTwo.groups.size1.toUpperCase()[0],
				mChooseTwo.groups.size2.toUpperCase()[0],
			];

			if (!isInRoot) {
				entryParentList.items = entryParentList.items.filter(it => it !== entry);
				entry.type = "item";
				race.sizeEntry = entry;
			}

			return;
		}

		// "Medium (about 4-7 feet tall) or Small (about 2-4 feet tall), chosen when you select this species"
		const mChooseTwoSpecies = /^(?<size1>Medium|中型) ?[(（][^)）]+[)）](?: or |或)(?<size2>Small|小型) ?[(（][^)）]+[)）]/i.exec(text);
		if (mChooseTwoSpecies) {
			race.size = [
				mChooseTwoSpecies.groups.size1.toUpperCase()[0],
				mChooseTwoSpecies.groups.size2.toUpperCase()[0],
			];

			if (!isInRoot) {
				entryParentList.items = entryParentList.items.filter(it => it !== entry);
				entry.type = "item";
				race.sizeEntry = entry;
			}

			return;
		}

		options.cbWarning(`体型文本 "${text}" 无法自动转换！`);
	}

	static _doRacePostProcess_speed (race, options) {
		const {entry, isInRoot, entryParentList} = this._getNamedEntry({race, reName: /^(?:Speed|移动速度|速度)[:：]?$/i}) || {};
		if (entry?.entries?.length !== 1) return options.cbWarning(`无法转换移动速度\u2014未找到 "移动速度" 属性！`);

		const text = entry.entries[0];

		const mSimple = /Your (?:base )?(?:walking )?speed is (?<speed>\d+) feet\.?$/.exec(text)
			|| /你?的?(?:基础)?(?:步行|移动)?速度[是为]?(?<speed>\d+)英?尺。?$/.exec(text);
		if (mSimple) {
			race.speed = Number(mSimple.groups.speed);

			// Filter out "redundant" size info, as it will be displayed in subtitle
			if (isInRoot) race.entries = race.entries.filter(it => it !== entry);
			else entryParentList.items = entryParentList.items.filter(it => it !== entry);

			return;
		}

		const mSimpleShort = /^(?<speed>\d+) feet\.?$/.exec(text)
		|| /^(?<speed>\d+) ?英?尺。?$/.exec(text);
		if (mSimpleShort) {
			race.speed = Number(mSimpleShort.groups.speed);

			// Filter out "redundant" size info, as it will be displayed in subtitle
			if (isInRoot) race.entries = race.entries.filter(it => it !== entry);
			else entryParentList.items = entryParentList.items.filter(it => it !== entry);

			return;
		}

		const mAltEqual = /Your (?:base )?walking speed is (?<speed>\d+) feet, and you have a (?<modeAlt>swim(?:ming)?|climb(?:ing)?) speed equal to your walking speed\./.exec(text)
			|| /你的(?:基础)?步行速度[是为] ?(?<speed>\d+) ?英?尺[,，] ?(?:同时|并且)你拥有(?:等同?于你的?步行速度|与你的?步行速度相同)的(?<modeAlt>游泳|攀爬)速度。?/.exec(text);
		if (mAltEqual) {
			const propAlt = this._doRacePostProcess_speed_getAltProp(mAltEqual.groups.modeAlt);
			race.speed = {
				walk: Number(mAltEqual.groups.speed),
				[propAlt]: true,
			};

			if (!isInRoot) {
				entryParentList.items = entryParentList.items.filter(it => it !== entry);
				entry.type = "item";
				race.speedEntry = entry;
			}

			return;
		}

		const mAltSingle = /Your (?:base )?walking speed is (?<speed>\d+) feet, and you have a (?<modeAlt>swim(?:ming)?|climb(?:ing)?) speed of (?<speedAlt>\d+) feet\./.exec(text)
		|| /你的(?:基础)?步行速度[是为] ?(?<speed>\d+) ?英?尺[,，] ?(?:同时|并且)?你拥有 ?(?<speedAlt>\d+) ?英?尺的(?<modeAlt>游泳|攀爬)速度。?/.exec(text);
		if (mAltSingle) {
			const propAlt = this._doRacePostProcess_speed_getAltProp(mAltSingle.groups.modeAlt);
			race.speed = {
				walk: Number(mAltSingle.groups.speed),
				[propAlt]: Number(mAltSingle.groups.speedAlt),
			};

			if (!isInRoot) {
				entryParentList.items = entryParentList.items.filter(it => it !== entry);
				entry.type = "item";
				race.speedEntry = entry;
			}

			return;
		}

		options.cbWarning(`速度文本 "${text}" 无法自动解析！`);
	}

	static _doRacePostProcess_speed_getAltProp (str) {
		switch (str.toLowerCase().trim()) {
			case "游泳":
			case "swimming":
			case "swim":
				return "swim";

			case "攀爬":
			case "climbing":
			case "climb":
				return "climb";

			default: throw new Error(`Unhandled!`);
		}
	}

	static _doRacePostProcess_speedFlight (race, options) {
		if (race.speed == null) return;

		let found = false;

		const walker = MiscUtil.getWalker({isNoModification: true, isBreakOnReturn: true});

		for (const entry of race.entries) {
			walker.walk(
				entry.entries,
				{
					string: (str) => {
						found = (/\byou have a flying speed equal to your walking speed\b/i.test(str)
							&& !/\b(?:temporarily|temporary)\b/i.test(str)
							&& !/\buntil [^.]+ ends\b/i.test(str))
							|| (/你拥有(?:等同?于你的?步行速度|与你的?步行速度相同)的飞行速度/i.test(str)
								&& !/临时/i.test(str)
								&& !/直到[^.]+结束/i.test(str));

						if (found) return true;
					},
				},
			);
			if (found) break;
		}

		if (!found) return;

		if (typeof race.speed === "number") {
			race.speed = {walk: race.speed, fly: true};
		} else {
			race.speed.fly = true;
		}
	}

	static _RE_CREATURE_TYPES = new RegExp(`^(?:You are(?: an?)? |你(?:是|属于)(?:一个)?)(?<type>${Parser.MON_TYPES.map(it => it.uppercaseFirst()).join("|")})(?:生物)?(?:\\.|。|$)`);
	static _RE_CREATURE_TYPES_SHORT = new RegExp(`^(?<type>${Parser.MON_TYPES.map(it => it.uppercaseFirst()).join("|")})\\.?$`);
	static _doRacePostProcess_creatureType (race, options) {
		const {entry, isInRoot, entryParentList} = this._getNamedEntry({race, reName: /^(?:Creature Type|生物类型)[:：]?$/i}) || {};
		if (!entry) return; // If unspecified, defaults to humanoid

		if (entry?.entries?.length !== 1) return options.cbWarning(`无法转换生物类型文本\u2014未找到 "生物类型" 文本！`);

		let text = entry.entries[0];

		const mSimpleShort = this._RE_CREATURE_TYPES_SHORT.exec(text);
		if (mSimpleShort) {
			const type = mSimpleShort.groups.type.toLowerCase();

			// Filter out "redundant" creature type info, as we assume "undefined" = "humanoid"
			if (isInRoot && (type === Parser.TP_HUMANOID || type === Parser.MON_TYPE_TO_PLURAL[Parser.TP_HUMANOID])) {
				race.entries = race.entries.filter(it => it !== entry);
				return;
			}

			race.creatureTypes = [type];
			// entryParentList.items = entryParentList.items.filter(it => it !== entry);

			return;
		}

		let isSimple = true;
		const types = [];
		text = text
			.replace(/^(?:You are a Humanoid|你是(?:一个)?类人生物)(?:\.|。|$)/i, () => {
				types.push(Parser.TP_HUMANOID);
				return "";
			})
			.trim()
			.replace(this._RE_CREATURE_TYPES, (...m) => {
				types.push(m.last().type.toLowerCase());
				return "";
			})
			.trim()
			.replace(/You are also considered an? (?<tag>[-a-z]+) for any prerequisite or effect that requires you to be an? \k<tag>\./, (...m) => {
				race.creatureTypeTags = [m.last().tag.toLowerCase()];
				isSimple = false;
				return "";
			})
			.replace(/如果有任何[前提|先决条件]或效[果应]需要你作为(?:一个)?(?<tag>.+)[,，]你也被视[作为]\k<tag>[.。]/, (...m) => {
				race.creatureTypeTags = [m.last().tag.toLowerCase()];
				isSimple = false;
				return "";
			})
		;

		// Filter out "redundant" creature type info, as we assume "undefined" = "humanoid"
		if (isInRoot) {
			if (types.length === 1
				&& (types[0] === Parser.TP_HUMANOID || types[0] === Parser.MON_TYPE_TO_PLURAL[Parser.TP_HUMANOID])
				&& !race.creatureTypeTags?.length) {
				race.entries = race.entries.filter(it => it !== entry);
			}
		} else {
			race.creatureTypes = types;
			entryParentList.items = entryParentList.items.filter(it => it !== entry);
			if (!isSimple) {
				entry.type = "item";
				race.creatureTypesEntry = entry;
			}
		}

		if (text) {
			options.cbWarning(`生物类型 "${text}" 无法自动转换！`);
		}
	}

	static _doRacePostProcess_darkvision (race, options) {
		const {entry} = this._getNamedEntry({race, reName: /^(?:Darkvision|黑暗视觉)[:：]?$/i}) || {};
		if (!entry?.entries?.length) return;

		const walker = MiscUtil.getWalker({isNoModification: true, isBreakOnReturn: true});
		walker.walk(
			entry,
			{
				string: (str) => {
					const stStripped = Renderer.stripTags(str);

					const mDarkvision = /\bsee [^.]+ dim light [^.]+ (?<radius>\d+) feet [^.]+ bright light/i.exec(stStripped)
					|| /在?(?:昏暗|微光)(?:环境|照明|光照|条件)[下中里][,，]?你(?:可以|能)[在将]你(?:周围)? ?(?<radius>\d+) ?英?尺(?:范围)?内的区域(?:视为|当做)明亮光照/i.exec(stStripped);
					if (mDarkvision) {
						race.darkvision = Number(mDarkvision.groups.radius);
						return true;
					}

					const mDarkvisionShort = /You have Darkvision with a range of (?<radius>\d+) feet/i.exec(stStripped)
						|| /You have (?<radius>\d+) feet of Darkvision/i.exec(stStripped)
						|| /你的黑暗视觉(?:能力)?提升至 ?(?<radius>\d+) ?英?尺/i.exec(stStripped)
						|| /你(?:拥有|获得) ?(?<radius>\d+) ?英?尺的黑暗视觉(?:能力)?/i.exec(stStripped);
					if (mDarkvisionShort) {
						race.darkvision = Number(mDarkvisionShort.groups.radius);
						return true;
					}

					return false;
				},
			},
		);
	}
}

/js/converter/converter-spell.js:
import {ConverterBase} from "./converter-base.js";
import {ConverterUtils} from "./converterutils-utils.js";
import {TagCondition} from "./converterutils-tags.js";
import {AbilityCheckTagger, DamageImmuneTagger, DamageInflictTagger, DamageResTagger, DamageVulnTagger, MiscTagsTagger, SavingThrowTagger, ScalingLevelDiceTagger, SpellAttackTagger} from "./converterutils-spell.js";
import {ConverterConst} from "./converterutils-const.js";
import {TagJsons} from "./converterutils-entries.js";
import {SITE_STYLE__CLASSIC, SITE_STYLE__ONE} from "../consts.js";
import {EntryCoalesceEntryLists, EntryCoalesceRawLines} from "./converterutils-entrycoalesce.js";
import {PropOrder} from "../utils-proporder.js";

export class ConverterSpell extends ConverterBase {
	static _RE_START_RANGE = "(?:Range|范围|距离|施法范围|施法距离)";
	static _RE_START_COMPONENTS = "(?:Components?|组件|组件消耗|成分|施法成分|法术成分)";
	static _RE_START_DURATION = "(?:Duration|持续时间)";
	static _RE_START_CLASS = "(?:Class(?:es)?|职业|施法职业)";

	static _REQUIRED_PROPS = [
		"level",
		"school",
		"time",
		"range",
		"duration",
		"entries",
	];

	/**
	 * Parses spells from raw text pastes
	 * @param inText Input text.
	 * @param options Options object.
	 * @param options.cbWarning Warning callback.
	 * @param options.cbOutput Output callback.
	 * @param options.isAppend Default output append mode.
	 * @param options.source Entity source.
	 * @param options.page Entity page.
	 * @param [options.isAddPageNumber] Whether to include the page in the output. Defaults to true if a page is provided.
	 * @param options.titleCaseFields Array of fields to be title-cased in this entity (if enabled).
	 * @param options.isTitleCase Whether title-case fields should be title-cased in this entity.
	 * @param options.styleHint
	 */
	static doParseText (inText, options) {
		options = this._getValidOptions(options);

		if (!inText || !inText.trim()) return options.cbWarning("没有输入！");
		const toConvert = this._getCleanInput(inText, options)
			.split("\n")
			.filter(it => it && it.trim());
		const spell = {};
		spell.source = options.source;
		// for the user to fill out
		spell.page = options.page;

		let prevLine = null;
		let curLine = null;
		let i;
		for (i = 0; i < toConvert.length; i++) {
			prevLine = curLine;
			curLine = toConvert[i].trim();

			if (curLine === "") continue;

			// name of spell
			if (i === 0) {
				[spell.name, spell.ENG_name] = ConverterUtils.splitNameToChineseAndEnglish(this._getAsTitle("name", curLine, options.titleCaseFields, options.isTitleCase));
				continue;
			}

			// spell level, and school plus ritual
			if (i === 1) {
				this._setCleanLevelSchoolRitual(spell, curLine, options);
				continue;
			}

			// casting time
			if (i === 2) {
				this._setCleanCastingTime(spell, curLine, options);
				continue;
			}

			// range
			if (!spell.range
				&& ConverterUtils.isStatblockLineHeaderStart({reStartStr: this._RE_START_RANGE, line: curLine})) {
				this._setCleanRange(spell, curLine, options);
				continue;
			}

			// components
			if (!spell.components
				&& ConverterUtils.isStatblockLineHeaderStart({reStartStr: this._RE_START_COMPONENTS, line: curLine})
			) {
				this._setCleanComponents(spell, curLine, options);
				continue;
			}

			// duration
			if (!spell.duration
				&& ConverterUtils.isStatblockLineHeaderStart({reStartStr: this._RE_START_DURATION, line: curLine})) {
				// avoid absorbing main body text
				this._setCleanDuration(spell, curLine, options);
				continue;
			}

			// class spell lists (alt)
			if (!spell.classes
				&& ConverterUtils.isStatblockLineHeaderStart({reStartStr: this._RE_START_CLASS, line: curLine})) {
				// avoid absorbing main body text
				this._setCleanClasses(spell, curLine, options);
				continue;
			}

			const ptrI = {_: i};
			spell.entries = EntryCoalesceRawLines.mutGetCoalesced(
				ptrI,
				toConvert,
				{
					fnStop: (curLine) => /^(?:At Higher Levels|Class(?:es)?|Cantrip Upgrade|Using a Higher-Level Spell Slot|升环施法效应|升环施法)/gi.test(curLine),
				},
			);
			i = ptrI._;

			spell.entriesHigherLevel = EntryCoalesceRawLines.mutGetCoalesced(
				ptrI,
				toConvert,
				{
					fnStop: (curLine) => /^Classes|环阶/gi.test(curLine),
				},
			);
			i = ptrI._;

			// class spell lists
			if (i < toConvert.length) {
				curLine = toConvert[i].trim();
				if (ConverterUtils.isStatblockLineHeaderStart({reStartStr: this._RE_START_CLASS, line: curLine})) {
					this._setCleanClasses(spell, curLine, options);
				}
			}
		}

		if (!spell.entriesHigherLevel || !spell.entriesHigherLevel.length) delete spell.entriesHigherLevel;

		this._doSpellPostProcess(spell, options);
		const statsOut = PropOrder.getOrdered(spell, "spell");

		const missingProps = this._REQUIRED_PROPS.filter(prop => statsOut[prop] == null);
		if (missingProps.length) options.cbWarning(`${statsOut.name ? `(${statsOut.name}) ` : ""}缺少词条: ${missingProps.join(", ")}`);

		options.cbOutput(statsOut, options.isAppend);

		return statsOut;
	}

	static _getCleanInput (ipt, options = null) {
		let txt = super._getCleanInput(ipt, options);

		const titles = [
			"Casting Time",
			"(施法)?时间",
			"Range",
			"(施法)?范围",
			"(施法)?距离",
			"Components?",
			"(法术)?成分",
			"Duration",
			"持续时间",
		];

		for (let i = 0; i < titles.length - 1; ++i) {
			const start = titles[i];
			const end = titles[i + 1];
			const re = new RegExp(`(?<line>\\n${start}.*?)(?<suffix>\\n${end})`, "is");

			txt = txt.replace(re, (...m) => {
				return `\n${m.last().line.replace(/\n/g, " ").trim().replace(/ +/g, " ")}${m.last().suffix}`;
			});
		}

		return txt;
	}

	// SHARED UTILITY FUNCTIONS ////////////////////////////////////////////////////////////////////////////////////////
	static _tryConvertSchool (s, {cbMan = null} = {}) {
		const school = (s.school || "").toLowerCase().trim();
		if (!school) return cbMan ? cbMan(`法术学派"${s.school}"无法自动转换。`) : null;

		const out = ConverterSpell._RES_SCHOOL.find(it => it.regex.test(school));
		if (out) {
			s.school = out.output;
			return;
		}
		if (cbMan) cbMan(`法术学派"${s.school}"无法自动转换。`);
	}

	static _doSpellPostProcess (stats, options) {
		this._doPostProcess_removePage(stats, options);

		const doCleanup = () => {
			// remove any empty arrays
			Object.keys(stats).forEach(k => {
				if (stats[k] instanceof Array && stats[k].length === 0) {
					delete stats[k];
				}
			});
		};

		TagCondition.tryTagConditions(stats, {isTagInflicted: true, styleHint: options.styleHint});

		[
			"entries",
			"entriesHigherLevel",
		]
			.forEach(prop => {
				EntryCoalesceEntryLists.mutCoalesce(stats, prop, {styleHint: options.styleHint});
				TagJsons.mutTagObjectStrictCapsWords(stats, {keySet: new Set([prop]), styleHint: options.styleHint});
				TagJsons.mutTagObject(stats, {keySet: new Set([prop]), isOptimistic: false, styleHint: options.styleHint});
			});

		this._addTags(stats, options);
		doCleanup();
	}

	static _addTags (stats, options) {
		DamageInflictTagger.tryRun(stats, options);
		DamageResTagger.tryRun(stats, options);
		DamageVulnTagger.tryRun(stats, options);
		DamageImmuneTagger.tryRun(stats, options);
		SavingThrowTagger.tryRun(stats, options);
		AbilityCheckTagger.tryRun(stats, options);
		SpellAttackTagger.tryRun(stats, options);
		// TODO areaTags
		MiscTagsTagger.tryRun(stats, options);
		ScalingLevelDiceTagger.tryRun(stats, options);
	}

	// SHARED PARSING FUNCTIONS ////////////////////////////////////////////////////////////////////////////////////////
	static _setCleanLevelSchoolRitual (stats, line, options) {
		const rawLine = line;
		line = ConverterUtils.cleanDashes(line).trim();

		const mCantrip = /(?:cantrip|戏法)/i.exec(line);
		const mSpellLeve = /^(?<level>\d+)(?:st|nd|rd|th)?[- ]level/i.exec(line)
			|| /^Level (?<level>\d+)\b/i.exec(line)
			|| /^(?<level>[一二三四五六七八九十]+|\d+)\s?环/i.exec(line);

		if (mCantrip) {
			let trailing = line.slice(mCantrip.index + "cantrip".length, line.length).trim();
			line = line.slice(0, mCantrip.index).trim();

			trailing = this._setCleanLevelSchoolRitual_trailingClassGroup({stats, options, trailing});

			// TODO implement as required (see at e.g. Deep Magic series)
			if (trailing) {
				options.cbWarning(`${stats.name ? `(${stats.name}) ` : ""}环阶/学派/仪式后缀部分"${trailing}"无法自动转换`);
			}

			stats.level = 0;
			stats.school = line;

			this._tryConvertSchool(stats, {cbMan: options.cbWarning});
			return;
		}

		if (mSpellLeve) {
			line = line.slice(mSpellLeve.index + mSpellLeve[0].length);

			let isRitual = false;
			line = line.replace(/\((.*?)(?:[,;]\s*)?ritual(?:[,;]\s*)?(.*?)\)/i, (...m) => {
				isRitual = true;
				// preserve any extra info inside the brackets
				return m[1] || m[2] ? `(${m[1]}${m[2]})` : "";
			}).trim();

			if (isRitual) {
				MiscUtil.set(stats, "meta", "ritual", true);
			}

			stats.level = Parser.textToNumber(mSpellLeve.groups.level);

			// 英文（一般用空格分割）
			let [tkSchool, ...tksSchoolRest] = line.trim().split(" ");
			stats.school = tkSchool;

			if (/^(?:school|spell)$/i.test(tksSchoolRest[0] || 0)) tksSchoolRest.shift();
			let trailing = tksSchoolRest.join(" ");

			// 处理中文（可能因为没有空格而和后续的职业等内容连在一起）
			const cnScoolPattern = new RegExp(`(?:${Object.values(Parser.SP_SCHOOL_ABV_TO_FULL).join("|")})`);
			const mCnScool = cnScoolPattern.exec(tkSchool);
			if (mCnScool) {
				stats.school = mCnScool[0];
				trailing = tkSchool.slice(mCnScool[0].length) + trailing;
			}
			trailing = this._setCleanLevelSchoolRitual_trailingClassGroup({stats, options, trailing});

			// TODO further handling of non-school text (see e.g. Deep Magic series)
			if (trailing) {
				options.cbWarning(`${stats.name ? `(${stats.name}) ` : ""}Level/school/ritual trailing part "${trailing}" requires manual conversion`);
			}

			this._tryConvertSchool(stats, {cbMan: options.cbWarning});
			return;
		}

		options.cbWarning(`${stats.name ? `(${stats.name}) ` : ""}Level/school/ritual part "${rawLine}" requires manual conversion`);
	}

	static _setCleanLevelSchoolRitual_trailingClassGroup ({stats, options, trailing}) {
		if (!trailing) return trailing;

		const classNames = [];

		const out = trailing
			.split(/([（()）])/g)
			.map(tk => {
				return tk
					.split(StrUtil.COMMAS_NOT_IN_PARENTHESES_REGEX)
					.map(tk => {
						return tk
							.replace(new RegExp(ConverterConst.STR_RE_CLASS, "i"), (...m) => {
								classNames.push(m.last().name);
								return "";
							})
							.replace(new RegExp(ConverterConst.STR_RE_CLASS_CN, "i"), (...m) => {
								classNames.push(m.last().name);
								return "";
							})
							.replace(/\s+/g, " ")
						;
					})
					.filter(it => it.trim())
					.join(",");
			})
			.join("")
			.replace(/(?:法术|学派)?\s*[（(]\s*[）)]/g, "")
			.trim();

		if (!classNames.length) return out;

		switch (options.styleHint) {
			case SITE_STYLE__CLASSIC: {
				(stats.groups ||= [])
					.push(
						...classNames.map(name => ({
							name,
							source: stats.source,
						})),
					);
				break;
			}

			case SITE_STYLE__ONE: {
				const tgt = MiscUtil.getOrSet(stats, "classes", "fromClassList", []);
				tgt.push(
					...classNames.map(name => ({
						name,
						source: (name === "Artificer" || name === "奇械师") ? Parser.SRC_EFA : Parser.SRC_XPHB,
					})),
				);
				break;
			}

			default: throw new Error(`Unhandled style "${options.styleHint}"!`);
		}

		return out;
	}

	static _setCleanRange (stats, line, options) {
		const getUnit = (str) => /\b(miles?|mi\.|里|英里)\b/.test(str.toLowerCase()) ? "miles" : "feet";

		const range = ConverterUtils.cleanDashes(ConverterUtils.getStatblockLineHeaderText({reStartStr: this._RE_START_RANGE, line}));

		if (["self", "自身", "自己"].includes(range.toLowerCase())) return stats.range = {type: "point", distance: {type: "self"}};
		if (["special", "特殊"].includes(range.toLowerCase())) return stats.range = {type: "special"};
		if (["unlimited", "无限"].includes(range.toLowerCase())) return stats.range = {type: "point", distance: {type: "unlimited"}};
		if (["unlimited on the same plane", "在同一位面上无限"].includes(range.toLowerCase())) return stats.range = {type: "point", distance: {type: "plane"}};
		if (["sight", "视野"].includes(range.toLowerCase())) return stats.range = {type: "point", distance: {type: "sight"}};
		if (["touch", "触及"].includes(range.toLowerCase())) return stats.range = {type: "point", distance: {type: "touch"}};

		const cleanRange = range.replace(/(\d),(\d)/g, "$1$2");

		const mFeetMiles = /^(?<amount>\d+)\s*(?<unit>feet|foot|ft\.?|miles?|mi\.?|尺|英尺|里|英里)$/i.exec(cleanRange);
		if (mFeetMiles) return stats.range = {type: "point", distance: {type: getUnit(mFeetMiles.groups.unit), amount: Number(mFeetMiles.groups.amount)}};

		const mSelfEmanation = /^(self |自身\s*)[(（](\d+)[- ]?(foot|ft\.?|miles?|mi\.?|尺|英尺|里|英里)( emanation|\s*光环)[)）]$/i.exec(cleanRange);
		if (mSelfEmanation) return stats.range = {type: "emanation", distance: {type: getUnit(mSelfEmanation[2]), amount: Number(mSelfEmanation[1])}};

		const mSelfRadius = /^(self |自身\s*)[(（](\d+)[- ]?(foot|ft\.?|miles?|mi\.?|尺|英尺|里|英里)\s*(radius|半径)[)）]$/i.exec(cleanRange);
		if (mSelfRadius) return stats.range = {type: "radius", distance: {type: getUnit(mSelfRadius[2]), amount: Number(mSelfRadius[1])}};

		const mSelfSphere = /^(self |自身\s*)[(（](\d+)[- ]?(foot|ft\.?|miles?|mi\.?|尺|英尺|里|英里)(?:[- ]radius|\s*半径)?\s*(sphere|的?球状|球形|球型)[)）]$/i.exec(cleanRange);
		if (mSelfSphere) return stats.range = {type: "sphere", distance: {type: getUnit(mSelfSphere[2]), amount: Number(mSelfSphere[1])}};

		const mSelfCone = /^(self |自身\s*)[(（](\d+)[- ]?(foot|ft\.?|miles?|mi\.?|尺|英尺|里|英里)\s*(cone|锥状|锥形|锥型)[)）]$/i.exec(cleanRange);
		if (mSelfCone) return stats.range = {type: "cone", distance: {type: getUnit(mSelfCone[2]), amount: Number(mSelfCone[1])}};

		const mSelfLine = /^(self |自身\s*)[(（](\d+)[- ]?(foot|ft\.?|miles?|mi\.?|尺|英尺|里|英里)\s*(line|线状|线形|线型)[)）]$/i.exec(cleanRange);
		if (mSelfLine) return stats.range = {type: "line", distance: {type: getUnit(mSelfLine[2]), amount: Number(mSelfLine[1])}};

		const mSelfCube = /^(self |自身\s*)[(（](\d+)[- ]?(foot|ft\.?|miles?|mi\.?|尺|英尺|里|英里)\s*(cube|立方体|立方型|立方|正方体)[)）]$/i.exec(cleanRange);
		if (mSelfCube) return stats.range = {type: "cube", distance: {type: getUnit(mSelfCube[2]), amount: Number(mSelfCube[1])}};

		const mSelfHemisphere = /^(self |自身\s*)[(（](\d+)[- ]?(foot|ft\.?|miles?|mi\.?|尺|英尺|里|英里)(?:[- ]radius|\s*半径)?\s*(hemisphere|半球形|半球型|半球)[)）]$/i.exec(cleanRange);
		if (mSelfHemisphere) return stats.range = {type: "hemisphere", distance: {type: getUnit(mSelfHemisphere[2]), amount: Number(mSelfHemisphere[1])}};

		// region Homebrew
		const mPointCube = /^(?<point>\d+)\s*(?<unit>feet|foot|ft\.?|miles?|mi\.?|尺|英尺|里|英里)\s*[(（](\d+)[- ]?(foot|ft\.?|miles?|mi\.?|尺|英尺|里|英里)\s*(cube|立方体|立方型|立方|正方体)[)）]$/i.exec(cleanRange);
		if (mPointCube) return stats.range = {type: "point", distance: {type: getUnit(mPointCube.groups.unit), amount: Number(mPointCube.groups.point)}};
		// endregion

		options.cbWarning(`${stats.name ? `(${stats.name}) ` : ""}施法距离部分"${range}"无法自动转换`);
	}

	static _getCleanTimeUnit (unit, isDuration, options) {
		unit = unit.toLowerCase().trim().replace("个", "");
		switch (unit) {
			case "days":
			case "weeks":
			case "months":
			case "years":
			case "hours":
			case "minutes":
			case "actions":
			case "rounds": return unit.slice(0, -1);

			case "day":
			case "week":
			case "month":
			case "year":
			case "hour":
			case "minute":
			case "action":
			case "round":
			case "reaction": return unit;

			case "bonus action": return "bonus";

			case "日":
			case "天":
				return "day";
			case "周":
			case "星期":
				return "week";
			case "月":
				return "month";
			case "年":
				return "year";
			case "时":
			case "小时":
				return "hour";
			case "分":
			case "分钟":
				return "minute";
			case "动作":
				return "action";
			case "轮":
				return "round";
			case "反应":
				return "reaction";
			case "附赠动作":
				return "bonus";

			default:
				options.cbWarning(`单位部分"${unit}"无法自动转换`);
				return unit;
		}
	}

	static _setCleanCastingTime (stats, line, options) {
		const allParts = ConverterUtils.getStatblockLineHeaderText({reStartStr: "(?:Casting Time|施法时间)", line});
		const parts = /\b(?:reaction|which you (?:take|use))\b/i.test(allParts)
			? [allParts]
			: allParts.split(/; | or /gi);

		stats.time = parts
			.map(it => it.trim())
			.filter(Boolean)
			.map(str => {
				if (str.toLowerCase() === "ritual" || str.toLowerCase() === "仪式") {
					MiscUtil.set(stats, "meta", "ritual", true);
					return null;
				}

				const mNumber = /^(?<count>[一二三四五六七八九十]+|\d+)?(?<rest>.*?)$/.exec(str);

				if (!mNumber) {
					options.cbWarning(`${stats.name ? `(${stats.name}) ` : ""}Casting time part "${str}" requires manual conversion`);
					return str;
				}

				const amount = mNumber.groups.count ? Parser.textToNumber(mNumber.groups.count.trim()) : null;
				const [unit, ...conditionParts] = mNumber.groups.rest.split(", ");

				const mNote = /^(?<unit>.*) \((?<note>.*)\)$/.exec(unit);

				const out = {
					number: amount ?? 1,
					unit: this._getCleanTimeUnit(mNote ? mNote.groups.unit : unit, false, options),
					condition: conditionParts.join(", "),
					note: mNote ? mNote.groups.note : null,
				};
				if (!out.condition) delete out.condition;
				if (!out.note) delete out.note;
				return out;
			})
			.filter(Boolean);
	}

	static _getComponentCurrencyMult ({mCost}) {
		const {currency, currencyLong} = mCost.groups;

		if (currency) return Parser.COIN_CONVERSIONS[Parser.COIN_ABVS.indexOf(currency.toLowerCase())];

		switch (currencyLong.toLowerCase()) {
			case "金币":
			case "gold": {
				return Parser.COIN_CONVERSIONS[Parser.COIN_ABVS.indexOf("gp")];
			}
			default: throw new Error("Unimplemented!");
		}
	}

	static _setCleanComponents (stats, line, options) {
		const components = ConverterUtils.getStatblockLineHeaderText({reStartStr: this._RE_START_COMPONENTS, line});
		const parts = components.split(StrUtil.COMMAS_NOT_IN_PARENTHESES_REGEX);

		stats.components = {};

		parts
			.map(it => it.trim())
			.filter(Boolean)
			.forEach(pt => {
				const lowerPt = pt.toLowerCase();
				switch (lowerPt) {
					case "v": stats.components.v = true; break;
					case "s": stats.components.s = true; break;
					default: {
						if (/^m\s*[(（](.*)[)）]$/i.test(lowerPt)) {
							const materialText = pt.replace(/^m\s*[(（](.*)[)）]$/i, "$1").trim();
							const mCost = /(?<count>\d*,?\d+)\+?\s?(?:(?<currency>cp|sp|ep|gp|pp)|(?:(?<currencyLong>(?:gold|金币))(?: pieces)?))/gi.exec(materialText);
							const isConsumed = /(?:consume|消耗|花费|耗材)/i.test(pt.toLowerCase());

							if (mCost) {
								const valueMult = this._getComponentCurrencyMult({mCost});
								const valueNum = Number(mCost.groups.count.replace(/,/g, ""));

								stats.components.m = {
									text: materialText,
									cost: valueNum * valueMult,
								};
								if (isConsumed) stats.components.m.consume = true;
							} else if (isConsumed) {
								stats.components.m = {
									text: materialText,
									consume: true,
								};
							} else {
								stats.components.m = materialText;
							}
						} else if (lowerPt.startsWith("r ")) stats.components.r = true;
						else options.cbWarning(`${stats.name ? `(${stats.name}) ` : ""}法术成分部分"${pt}"无法自动转换`);
					}
				}
			});
	}

	static _setCleanDuration (stats, line, options) {
		const {durStr, condition} = this._setCleanDuration_getInput({line, options});

		if (["instantaneous", "立即"].includes(durStr.toLowerCase())) return stats.duration = this._setCleanDurationn_getOutput({duration: [{type: "instant"}], condition});
		if (["special", "特殊"].includes(durStr.toLowerCase())) return stats.duration = this._setCleanDurationn_getOutput({duration: [{type: "special"}], condition});
		if (["permanent", "永久"].includes(durStr.toLowerCase())) return stats.duration = this._setCleanDurationn_getOutput({duration: [{type: "permanent"}], condition});

		if (["concentration", "专注"].includes(durStr.toLowerCase())) return stats.duration = this._setCleanDurationn_getOutput({duration: [{type: "special", concentration: true}], condition});

		const mConcOrUpTo = /^(?<conc>(?:concentration|专注)[,，]\s*)?(?:up to|至多)\s*(?<amount>\d+|an?)\s*(?<unit>hour|minute|turn|round|week|month|day|year|时|小时|分|分钟|轮|回合|周|星期|月|天|日|年)(?:s)?$/i.exec(durStr);
		if (mConcOrUpTo) {
			const amount = mConcOrUpTo.groups.amount.toLowerCase().startsWith("a") ? 1 : Number(mConcOrUpTo.groups.amount);
			const out = {type: "timed", duration: {type: this._getCleanTimeUnit(mConcOrUpTo.groups.unit, true, options), amount}};
			if (mConcOrUpTo.groups.conc) out.concentration = true;
			else out.duration.upTo = true;
			return stats.duration = this._setCleanDurationn_getOutput({duration: [out], condition});
		}

		const mTimed = /^(\d+)\s?(hour|minute|turn|round|week|month|day|year|时|小时|分|分钟|轮|回合|周|星期|月|天|日|年)(?:s)?$/i.exec(durStr);

		if (mTimed) return stats.duration = this._setCleanDurationn_getOutput({duration: [{type: "timed", duration: {type: this._getCleanTimeUnit(mTimed[2], true, options), amount: Number(mTimed[1])}}], condition});

		const mDispelledTriggered = /^(?:until dispelled|直到被解除)(?: or triggered|或被?触发)?$/i.exec(durStr);
		if (mDispelledTriggered) {
			const out = {type: "permanent", ends: ["dispel"]};
			if (mDispelledTriggered[1]) out.ends.push("trigger");
			return stats.duration = this._setCleanDurationn_getOutput({duration: [out], condition});
		}

		const mPermDischarged = /^permanent until discharged$/i.exec(durStr);
		if (mPermDischarged) {
			const out = {type: "permanent", ends: ["discharge"]};
			return stats.duration = this._setCleanDurationn_getOutput({duration: [out], condition});
		}

		// TODO handle splitting "or"'d durations up as required

		options.cbWarning(`${stats.name ? `(${stats.name}) ` : ""}持续时间部分"${durStr}"无法自动转换`);
	}

	static _setCleanDuration_getInput ({line, options}) {
		const durRaw = ConverterUtils.getStatblockLineHeaderText({reStartStr: this._RE_START_DURATION, line});

		let condition;
		const durStr = durRaw
			.replace(/\s+\((?<condition>see [^)]+)\)\s*$/, (...m) => {
				condition = m.last().condition;
				return "";
			})
			.trim();

		return {durStr, condition};
	}

	static _setCleanDurationn_getOutput ({duration, condition}) {
		if (condition) duration.forEach(dur => dur.condition = condition);
		return duration;
	}

	static _setCleanClasses (stats, line, options) {
		const classLine = ConverterUtils.getStatblockLineHeaderText({reStartStr: this._RE_START_CLASS, line});
		const classes = classLine.split(StrUtil.COMMAS_NOT_IN_PARENTHESES_REGEX);

		const tgt = MiscUtil.getOrSet(stats, "classes", "fromClassList", []);

		classes
			.map(it => it.trim())
			.filter(Boolean)
			.forEach(pt => {
				let isLegacy = false;
				let lowerPt = pt.toLowerCase()
					.replace(/ \(legacy\)$/, () => {
						isLegacy = true;
						return "";
					})
					.trim();

				const srcPhb = isLegacy
					? Parser.SRC_PHB
					: options.styleHint !== SITE_STYLE__CLASSIC
						? Parser.SRC_XPHB
						: Parser.SRC_PHB;
				const srcArtificer = isLegacy
					? Parser.SRC_TCE
					: options.styleHint !== SITE_STYLE__CLASSIC
						? Parser.SRC_EFA
						: Parser.SRC_TCE;

				switch (lowerPt) {
					case "artificer":
					case "artificers": tgt.push({"name": "Artificer", "source": srcArtificer}); break;
					case "bard":
					case "bards": tgt.push({"name": "Bard", "source": srcPhb}); break;
					case "cleric":
					case "clerics": tgt.push({"name": "Cleric", "source": srcPhb}); break;
					case "druid":
					case "druids": tgt.push({"name": "Druid", "source": srcPhb}); break;
					case "paladin":
					case "paladins": tgt.push({"name": "Paladin", "source": srcPhb}); break;
					case "ranger":
					case "rangers": tgt.push({"name": "Ranger", "source": srcPhb}); break;
					case "sorcerer":
					case "sorcerers": tgt.push({"name": "Sorcerer", "source": srcPhb}); break;
					case "warlock":
					case "warlocks": tgt.push({"name": "Warlock", "source": srcPhb}); break;
					case "wizard":
					case "wizards": tgt.push({"name": "Wizard", "source": srcPhb}); break;
					default: options.cbWarning(`${stats.name ? `(${stats.name}) ` : ""}Class "${lowerPt}" requires manual conversion`); break;
				}
			});

		if (!stats.classes.fromClassList.length) delete stats.classes;
	}
}
ConverterSpell._RES_SCHOOL = Object.entries({
	"transmutation": "T",
	"necromancy": "N",
	"conjuration": "C",
	"abjuration": "A",
	"enchantment": "E",
