import {ConverterUiUtil} from "./converter-ui-utils.js";
import {ConverterUtils} from "./converterutils-utils.js";

const _APPEND_PREPEND_MODE__APPEND = "append";
const _APPEND_PREPEND_MODE__PREPEND = "prepend";

class _ConverterUiSettings extends BaseComponent {
	constructor ({comp, converter, ...rest}) {
		super({...rest});

		this._comp = comp;
		this._converter = converter;
	}

	render ({eleParent}) {
		const iptInputSeparator = ComponentUiUtil.getIptStr(this._comp, "inputSeparator").vee.addClass("ve-code");

		const selAppendPrependMode = ComponentUiUtil.getSelEnum(
			this._comp,
			"appendPrependMode",
			{
				values: [
					_APPEND_PREPEND_MODE__APPEND,
					_APPEND_PREPEND_MODE__PREPEND,
				],
				fnDisplay: val => val === _APPEND_PREPEND_MODE__APPEND ? "追加" : "预加",
			},
		);

		veT`<div class="ve-flex-col ve-mt-3">
			<label class="ve-split-v-center ve-w-100 ve-mb-2" title="A separator used to mark the end of one to-be-converted entity (creature, spell, etc.) so that multiple entities can be converted in one run. If left blank, the entire input text will be parsed as one entity.">
				<span class="ve-w-66 ve-no-shrink ve-mr-2 ve-flex-v-center">输入分隔符</span>
				${iptInputSeparator}
			</label>

			<label class="ve-split-v-center ve-w-100" title="Sets output order when using the &quot;Parse and Add&quot; button, or parsing multiple blocks of text using a separator.">
				<span class="ve-w-66 ve-no-shrink ve-mr-2 ve-flex-v-center">&quot;转换并添加&quot; 行为</span>
				${selAppendPrependMode}
			</label>

			<hr class="ve-hr-3">
		</div>`
			.vee.appendTo(eleParent);

		this._converter.renderSettingsModal({compParent: this._comp, eleParent});
	}
}

export class ConverterUi extends BaseComponent {
	static _STORAGE_INPUT = "converterInput";
	static _STORAGE_STATE = "converterState";

	constructor () {
		super();

		this._editorIn = null;
		this._editorOut = null;

		this._converters = {};

		this._saveInputDebounced = MiscUtil.debounce(() => StorageUtil.pSetForPage(this.constructor._STORAGE_INPUT, this._editorIn.getValue()), VeCt.DUR_DEBOUNCE_SAVE);
		this.saveSettingsDebounced = MiscUtil.debounce(() => StorageUtil.pSetForPage(this.constructor._STORAGE_STATE, this.getBaseSaveableState()), VeCt.DUR_DEBOUNCE_SAVE);

		this._addHookAll("state", () => this.saveSettingsDebounced());

		this.__meta = this._getDefaultMetaState();
		this._meta = this._getProxy("meta", this.__meta);
	}

	set converters (converters) { this._converters = converters; }
	get activeConverter () { return this._converters[this._state.converter]; }

	getInputSeparator () { return this._state.inputSeparator; }
	addHookInputSeparator (hk) { return this._addHookBase("inputSeparator", hk); }
	removeHookInputSeparator (hk) { return this._removeHookBase("inputSeparator", hk); }

	getBaseSaveableState () {
		return {
			...super.getBaseSaveableState(),
			...Object.values(this._converters).mergeMap(it => ({[it.converterId]: it.getBaseSaveableState()})),
		};
	}

	setBaseSaveableStateFrom (toLoad, ...rest) {
		// Avoid crash on missing converter
		if (toLoad?.state?.converter && !this._converters[toLoad.state.converter]) {
			toLoad.state.converter = Object.keys(this._converters)[0];
		}

		super.setBaseSaveableStateFrom(toLoad, ...rest);
	}

	_doRefreshAvailableSources () {
		this._state.availableSources = BrewUtil2.getSources().sort((a, b) => SortUtil.ascSortLower(a.full, b.full))
			.map(it => it.json);
	}

	doRefreshAvailableSources () {
		return this._doRefreshAvailableSources();
	}

	async pInit () {
		// region load state
		const savedState = await StorageUtil.pGetForPage(this.constructor._STORAGE_STATE);
		if (savedState) {
			this.setBaseSaveableStateFrom(savedState);
			Object.values(this._converters)
				.filter(it => savedState[it.converterId])
				.forEach(it => it.setBaseSaveableStateFrom(savedState[it.converterId]));
		}

		// forcibly overwrite available sources with fresh data
		this._doRefreshAvailableSources();
		Object.values(this._converters)
			.filter(it => it.source && !this._state.availableSources.includes(it.source))
			.forEach(it => it.source = "");

		// reset this temp flag
		this._state.hasAppended = false;
		// endregion

		this._editorIn = await EditorUtil.pInitEditor("ipt-converter-input");
		try {
			const prevInput = await StorageUtil.pGetForPage(this.constructor._STORAGE_INPUT);
			if (prevInput) this._editorIn.setValue(prevInput, -1);
		} catch (ignored) { setTimeout(() => { throw ignored; }); }
		this._editorIn.on("change", () => this._saveInputDebounced());

		this._editorOut = await EditorUtil.pInitEditor("ipt-converter-output", {readOnly: true, mode: "ace/mode/json"});

		const btnEnableEditing = veEs(`#btn-enable-edit`)
			.vee.onn("click", () => {
				this._state.outputEnableEditing = !this._state.outputEnableEditing;
			});
		this._addHookBase("outputEnableEditing", () => {
			btnEnableEditing.vee.toggleClass("ve-active", !!this._state.outputEnableEditing);
			this._editorOut.setOptions({readOnly: !this._state.outputEnableEditing});
		})();

		let hovWindowPreview = null;
		veEs(`#btn-preview`)
			.vee.onn("click", async evt => {
				const metaCurr = this._getCurrentEntities();

				if (!metaCurr?.entities?.length) return JqueryUtil.doToast({content: "Nothing to preview!", type: "warning"});
				if (metaCurr.error) return JqueryUtil.doToast({content: `Current output was not valid JSON!`, type: "danger"});

				const entries = !this.activeConverter.prop
					? metaCurr.entities.flat()
					: metaCurr.entities
						.map(ent => {
							// Handle nameless/sourceless entities (e.g. tables)
							if (!ent.name) ent.name = "(Unnamed)";
							if (!ent.source) ent.source = VeCt.STR_GENERIC;

							return {
								type: "statblockInline",
								dataType: this.activeConverter.prop,
								data: ent,
							};
						});

				let content;
				try {
					content = Renderer.hover.getHoverContent_generic({
						type: "entries",
						entries,
					});
				} catch (e) {
					JqueryUtil.doToast({type: "danger", content: `Could not render preview! ${VeCt.STR_SEE_CONSOLE}`});
					throw e;
				}

				if (hovWindowPreview) {
					hovWindowPreview.setContent(content);
					return;
				}

				hovWindowPreview = Renderer.hover.getShowWindow(
					content,
					Renderer.hover.getWindowPositionFromEvent(evt),
					{
						title: "Preview",
						isPermanent: true,
						cbClose: () => {
							hovWindowPreview = null;
						},
					},
				);
			});

		const btnSaveLocal = veEs(`#btn-save-local`).vee.onn("click", async () => {
			const metaCurr = this._getCurrentEntities();

			if (!metaCurr?.entities?.length) return JqueryUtil.doToast({content: "Nothing to save!", type: "warning"});
			if (metaCurr.error) return JqueryUtil.doToast({content: `Current output was not valid JSON!`, type: "danger"});

			const prop = this.activeConverter.prop;

			const invalidSources = metaCurr.entities.map(it => !it.source || !BrewUtil2.hasSourceJson(it.source) ? (it.name || it.caption || "(Unnamed)").trim() : false).filter(Boolean);
			if (invalidSources.length) {
				JqueryUtil.doToast({
					content: `One or more entries have missing or unknown sources: ${invalidSources.join(", ")}`,
					type: "danger",
				});
				return;
			}

			const brewDocEditable = await BrewUtil2.pGetEditableBrewDoc();
			const uneditableSources = metaCurr.entities
				.filter(ent => !(brewDocEditable?.body?._meta?.sources || []).some(src => src.json === ent.source))
				.map(ent => ent.source);
			if (uneditableSources.length) {
				JqueryUtil.doToast({
					content: `One or more entries have sources which belong to non-btn-enable-edit homebrew: ${uneditableSources.join(", ")}`,
					type: "danger",
				});
				return;
			}

			// ignore duplicates
			const _dupes = {};
			const dupes = [];
			const dedupedEntries = metaCurr.entities
				.map(it => {
					const lSource = it.source.toLowerCase();
					const lName = it.name.toLowerCase();
					_dupes[lSource] = _dupes[lSource] || {};
					if (_dupes[lSource][lName]) {
						dupes.push(it.name);
						return null;
					} else {
						_dupes[lSource][lName] = true;
						return it;
					}
				})
				.filter(Boolean);

			if (dupes.length) {
				JqueryUtil.doToast({
					type: "warning",
					content: `Ignored ${dupes.length} duplicate entr${dupes.length === 1 ? "y" : "ies"}`,
				});
			}

			if (!dedupedEntries.length) {
				return JqueryUtil.doToast({
					content: "Nothing to save!",
					type: "warning",
				});
			}

			// handle overwrites
			const brewDoc = await BrewUtil2.pGetOrCreateEditableBrewDoc();
			const overwriteMeta = dedupedEntries
				.map(it => {
					if (!brewDoc?.body?.[prop]) return {entry: it, isOverwrite: false};

					const ix = brewDoc.body[prop].findIndex(bru => bru.name.toLowerCase() === it.name.toLowerCase() && bru.source.toLowerCase() === it.source.toLowerCase());
					if (!~ix) return {entry: it, isOverwrite: false};

					return {
						isOverwrite: true,
						ix,
						entry: it,
					};
				})
				.filter(Boolean);

			const willOverwrite = overwriteMeta.map(it => it.isOverwrite).filter(Boolean);
			if (
				willOverwrite.length
				&& !await InputUiUtil.pGetUserBoolean({title: "Overwrite Entries", htmlDescription: `This will overwrite ${willOverwrite.length} entr${willOverwrite.length === 1 ? "y" : "ies"}. 你确定吗？`, textYes: "Yes", textNo: "Cancel"})
			) {
				return;
			}

			const cpyBrewDoc = MiscUtil.copy(brewDoc);
			overwriteMeta.forEach(meta => {
				if (meta.isOverwrite) return cpyBrewDoc.body[prop][meta.ix] = MiscUtil.copy(meta.entry);
				(cpyBrewDoc.body[prop] = cpyBrewDoc.body[prop] || []).push(MiscUtil.copy(meta.entry));
			});

			await BrewUtil2.pSetEditableBrewDoc(cpyBrewDoc);

			JqueryUtil.doToast({
				type: "success",
				content: `Saved!`,
			});
		});

		this._addHookBase("converter", () => {
			btnSaveLocal.vee.toggleClass("hidden", !this.activeConverter.canSaveLocal);
		})();

		veEs(`#btn-output-download`).vee.onn("click", () => {
			const metaCurr = this._getCurrentEntities();

			if (!metaCurr?.entities?.length) return JqueryUtil.doToast({content: "Nothing to download!", type: "warning"});
			if (metaCurr.error) {
				JqueryUtil.doToast({
					content: `Current output was not valid JSON. Downloading as <span class="ve-code">.txt</span> instead.`,
					type: "warning",
				});
				DataUtil.userDownloadText(`converter-output.txt`, metaCurr.text);
				return;
			}

			const out = {[this.activeConverter.prop]: metaCurr.entities};
			DataUtil.userDownload(`converter-output`, out);
		});

		veEs(`#btn-output-copy`).vee.onn("click", async evt => {
			const btn = evt.target;

			const output = this._outText;
			if (!output || !output.trim()) {
				return JqueryUtil.doToast({
					content: "Nothing to copy!",
					type: "danger",
				});
			}

			await MiscUtil.pCopyTextToClipboard(output);
			JqueryUtil.showCopiedEffect(btn);
		});

		/**
		 * Wrap a function in an error handler which will wipe the error output, and append future errors to it.
		 * @param pToRun
		 */
		const catchErrors = async (pToRun) => {
			try {
				this._proxyAssignSimple("meta", this._getDefaultMetaState());
				await pToRun();
			} catch (x) {
				const splitStack = x.stack.split("\n");
				const atPos = splitStack.length > 1 ? splitStack[1].trim() : "(Unknown location)";
				this._meta.errors = [...this._meta.errors, `${x.message} ${atPos}`];
				setTimeout(() => { throw x; });
			}
		};

		const doConversion = (isAppend) => {
			catchErrors(async () => {
				if (
					isAppend
					&& !this._state.hasAppended
					&& !await InputUiUtil.pGetUserBoolean({title: "确定要这么做吗？", htmlDescription: "此操作可能会覆盖多个条目，你确定要这么做吗？", textYes: "是的", textNo: "取消"})
				) return;

				const chunks = (this._state.inputSeparator
					? this.inText.split(this._state.inputSeparator)
					: [this.inText]).map(it => it.trim()).filter(Boolean);
				if (!chunks.length) {
					this._meta.warnings = [...this._meta.warnings, "No input!"];
					return;
				}

				chunks
					.reverse() // reverse as the append is actually a prepend
					.forEach((chunk, i) => {
						this.activeConverter.handleParse(
							chunk,
							this.doCleanAndOutput.bind(this),
							(warning) => this._meta.warnings = [...this._meta.warnings, warning],
							isAppend || i !== 0, // always clear the output for the first non-append chunk, then append
						);
					});
			});
		};

		veEs("#btn-parse").vee.onn("click", () => doConversion(false));
		veEs(`#btn-parse-and-add`).vee.onn("click", () => doConversion(true));

		veE(document.body)
			.vee.onn("keydown", evt => {
				if (EventUtil.isInInput(evt) || !EventUtil.noModifierKeys(evt)) return;

				const key = EventUtil.getKeyIgnoreCapsLock(evt);
				if (!["+", "-"].includes(key)) return;

				if (!this.activeConverter?.getHasPageNumbers()) return;

				evt.stopPropagation();
				evt.preventDefault();

				this.activeConverter.page += (key === "+" ? 1 : -1);
			});

		this._initSettings();

		this._pInit_dispErrorsWarnings();

		window.dispatchEvent(new Event("toolsLoaded"));
	}

	_pInit_dispErrorsWarnings () {
		const stgErrors = veEs(`#disp-errors`);
		const stgWarnings = veEs(`#disp-warnings`);

		const getRow = ({prefix, text, prop}) => {
			const btnClose = veT`<button class="ve-btn ve-btn-danger ve-btn-xs ve-w-24p" title="Dismiss ${prefix} (SHIFT to Dismiss All)">×</button>`
				.vee.onn("click", evt => {
					if (evt.shiftKey) {
						this._meta[prop] = [];
						return;
					}

					const ix = this._meta[prop].indexOf(text);
					if (!~ix) return;
					this._meta[prop].splice(ix, 1);
					this._meta[prop] = [...this._meta[prop]];
				});

			return veT`<div class="ve-split-v-center ve-py-1">
				<div>[${prefix}] ${text}</div>
				${btnClose}
			</div>`;
		};

		this._addHook("meta", "errors", () => {
			stgErrors.vee.toggle(!!this._meta.errors.length);
			stgErrors.vee.empty();
			this._meta.errors
				.forEach(it => {
					getRow({prefix: "Error", text: it, prop: "errors"})
						.vee.appendTo(stgErrors);
				});
		})();

		this._addHook("meta", "warnings", () => {
			stgWarnings.vee.toggle(!!this._meta.warnings.length);
			stgWarnings.vee.empty();
			this._meta.warnings
				.forEach(it => {
					getRow({prefix: "Warning", text: it, prop: "warnings"})
						.vee.appendTo(stgWarnings);
				});
		})();

		const hkResize = () => this._editorOut.resize();
		this._addHook("meta", "errors", hkResize);
		this._addHook("meta", "warnings", hkResize);
	}

	_getCurrentEntities () {
		const output = this._outText;

		if (!(output || "").trim()) return null;

		try {
			return {entities: JSON.parse(`[${output}]`)};
		} catch (e) {
			return {error: e.message, text: output.trim()};
		}
	}

	_initSettings () {
		ComponentUiUtil.getSelEnum(
			this,
			"converter",
			{
				ele: veEs(`#sel-mode`)
					.vee.attr("disabled", false),
				values: Object.keys(this._converters),
				fnDisplay: converterId => this._converters[converterId].name,
			},
		);

		veEs(`#btn-settings`)
			.vee.attr("disabled", false)
			.vee.onn("click", () => {
				const {eleModalInner} = UiUtil.getShowModal({
					title: "设置",
					isHeaderBorder: true,
					isUncappedHeight: true,
				});

				const compSettings = new _ConverterUiSettings({
					comp: this,
					converter: this.activeConverter,
				});
				compSettings.render({eleParent: eleModalInner});
			});

		const wrpSettings = veEs(`#wrp-settings`);

		let fnsCleanupLast = null;
		this._addHookBase("converter", () => {
			wrpSettings.vee.empty();
			if (fnsCleanupLast) fnsCleanupLast.forEach(fn => fn());
			({fnsCleanupLast} = this.activeConverter.renderSettings({compParent: this, wrpSettings}));

			this._editorIn.setOptions({
				mode: ConverterUiUtil.getAceMode(this.activeConverter?.mode),
			});
		})();
	}

	doCleanAndOutput (obj, append) {
		const objWithName = MiscUtil.getWalker().walk(obj, {
			object: (obj) => {
				if (obj.ENG_name || !obj.name) return obj;
				const [nameChinese, nameEnglish] = ConverterUtils.splitNameToChineseAndEnglish(obj.name);
				obj.name = nameChinese;
				obj.ENG_name = nameEnglish;
				return obj;
			},
		});
		const asCleanString = CleanUtil.getCleanJson(objWithName, {isFast: false});
		if (append) {
			const strs = [asCleanString, this._outText];
			if (this._state.appendPrependMode === ConverterUi._APPEND_PREPEND_MODE__PREPEND) strs.reverse();
			this._outText = strs.map(it => it.trimEnd()).join(",\n");
			this._state.hasAppended = true;
		} else {
			this._outText = asCleanString;
			this._state.hasAppended = false;
		}
	}

	get _outText () { return this._editorOut.getValue(); }
	set _outText (text) { this._editorOut.setValue(text, -1); }

	get inText () { return CleanUtil.getCleanString((this._editorIn.getValue() || "").trim(), {isFast: false}); }
	set inText (text) { this._editorIn.setValue(text, -1); }

	static _DEFAULT_STATE = {
		hasAppended: false,
		appendPrependMode: _APPEND_PREPEND_MODE__APPEND,
		converter: "monster",
		sourceJson: "",
		inputSeparator: "===",
		outputEnableEditing: false,
	};

	_getDefaultState () { return MiscUtil.copy(this.constructor._DEFAULT_STATE); }

	_getDefaultMetaState () {
		return {
			errors: [],
			warnings: [],
		};
	}
}

class BackgroundConverterConst {
	static RE_NAME_SKILLS = /^(?:Skill Proficienc(?:ies|y)|技能熟练项?)[:：]/;
	static RE_NAME_TOOLS = /^(?:Tools?|Tool Proficienc(?:ies|y)|工具|工具熟练项?)[:：]/;
	static RE_NAME_LANGUAGES = /^(?:Languages?|语言)[:：]/;
	static RE_NAME_EQUIPMENT = /^(?:Equipment?:|装备)[:：]/;
}

export class ConverterBackgroundUtil {
	static getEquipmentEntry (background) {
		const list = background.entries.find(ent => ent.type === "list");
		if (!list) return null;
		return list.items.find(ent => BackgroundConverterConst.RE_NAME_EQUIPMENT.test(ent.name));
	}
}

export class EquipmentBreakdown {
	static _WALKER;

	static tryRun (
		bg,
		{
			isSkipExisting = false,
			cbWarning = () => {},
			mappingsManual = {},
			allowlistOrEnds = [],
			blocklistSplits = [],
		} = {},
	) {
		if (!bg.entries) return cbWarning(`No entries found on "${bg.name}"`);

		if (isSkipExisting && bg.startingEquipment) return;
		delete bg.startingEquipment;

		this._WALKER ||= MiscUtil.getWalker({isNoModification: true, isBreakOnReturn: true});

		const entryEquipment = ConverterBackgroundUtil.getEquipmentEntry(bg);
		if (!entryEquipment) return;

		const entry = entryEquipment.entry || entryEquipment.entries[0];
		if (!entry) throw new Error(`Unimplemented!`);

		this._convert({
			bg,
			cbWarning,
			entry,
			mappingsManual,
			allowlistOrEnds,
			blocklistSplits,
		});
	}

	/**
	 * Output structure:
	 *
	 * ```
	 * equipment: [
	 *   {
	 *     "_": [
	 *       <equipment details>
	 *     ]
	 *   },
	 *   {
	 *     "a": [
	 *       <equipment details; choice A>
	 *     ],
	 *     "b": [
	 *       <equipment details; choice B>
	 *     ]
	 *   }
	 * ]
	 * ```
	 *
	 * @param bg
	 * @param cbWarning
	 * @param entry
	 * @param mappingsManual
	 * @param allowlistOrEnds
	 * @param blocklistSplits
	 * @private
	 */
	static _convert (
		{
			bg,
			cbWarning,
			entry,
			mappingsManual,
			allowlistOrEnds,
			blocklistSplits,
		},
	) {
		entry = entry.trim();

		blocklistSplits.forEach((str, i) => entry = entry.replace(str, `__SPLIT_${i}__`));

		if (/^(?:Choose A or B:|选择\s?A\s?或\s?B\s?[:：])/.test(entry)) {
			entry = entry.replace(/^Choose A or B: \(A\)\s*/, "")
				.replace(/^选择\s?A\s?或\s?B\s?[:：]\s?[(（]A[）)]\s*/, "");
			const [ptA, ptB] = entry
				.split(/(?:; or \(B\) |[;；]或[(（]B[)）])\s?/)
				.map(pt => pt.trim()).filter(Boolean);

			const startingA = this._getConvertedPartInfo({
				str: ptA,
				mappingsManual,
				allowlistOrEnds,
				blocklistSplits,
				keyNoChoice: "a",
			});

			const startingB = this._getConvertedPartInfo({
				str: ptB,
				mappingsManual,
				allowlistOrEnds,
				blocklistSplits,
				keyNoChoice: "b",
			});

			if (startingA.length !== 1 || startingB.length !== 1) return cbWarning(`"${bg.name}" Starting equipment requires manual conversion`);

			bg.startingEquipment = [
				Object.assign(startingA[0], startingB[0]),
			];

			return;
		}

		bg.startingEquipment = this._getConvertedPartInfo({
			str: entry,
			mappingsManual,
			allowlistOrEnds,
			blocklistSplits,
		});
	}

	static _getConvertedPartInfo (
		{
			str,
			mappingsManual,
			allowlistOrEnds,
			blocklistSplits,
			keyNoChoice = "_",
		},
	) {
		const parts = str
			.split(/\. /g)
			.map(it => it.trim())
			.map(it => it.split(StrUtil.COMMAS_NOT_IN_PARENTHESES_REGEX).map(it => it.trim()))
			.flat()
			.map(it => {
				return it.replace(/__SPLIT_(\d+)__/gi, (...m) => {
					const ix = Number(m[1]);
					return blocklistSplits[ix];
				});
			});

		const out = parts
			.map(pt => {
				// Strip leading "and" and trailing punctuation
				pt = pt
					.trim()
					.replace(/^(?:and |和|以及)/i, "")
					.replace(/[.!?。！？]$/, "")
					.trim();

				// Split up choices
				const ptChoices = this._splitChoices({str: pt, allowlistOrEnds})
					.map(c => c.trim().replace(/[,，、]$/, "").trim());

				const outChoices = ptChoices
					.map(ch => {
						const chOriginal = ch;

						// Pull out quantities
						let quantity = 1;
						ch = ch
							.replace(/^(any one|an|a|one|two|three|four|five|six|seven|eight|nine|ten|\d+)/i, (...m) => {
								quantity = Parser.textToNumber(
									m[1]
										.replace(/^any/i, "").trim(),
								);
								return "";
							})
							.replace(/^(任意一|一|一|两|三|四|五|六|七|八|九|十|\d+)[\u4e00-\u9fa5]/i, (...m) => {
								quantity = Parser.textToNumber(
									m[1]
										.replace(/^任意/i, "").trim(),
								);
								return "";
							})
							.replace(/\((?<amount>\d+) days' worth\)$/i, (...m) => {
								const {amount} = m.at(-1);
								quantity = Parser.textToNumber(amount.trim());
								return m[0];
							})
							.replace(/[(（](?<amount>\d+)天份[)）]$/i, (...m) => {
								const {amount} = m.at(-1);
								quantity = Parser.textToNumber(amount.trim());
								return m[0];
							})
							.trim();

						if (isNaN(quantity)) throw new Error(`Quantity found in "${chOriginal}" was not a number!`);

						// Pull out coinage
						let valueCp = 0;
						let cntValueContainingWith = 0;
						let cntValueWorth = 0;
						ch = ch
							// Remove trailing parenthetical parts, e.g. "... (Azorius-minted 1-zino coins)"
							.replace(/(containing|with|worth) (\d+\s*[csgep]p)(\s+\([^)]+\))?/gi, (...m) => {
								switch (m[1].toLowerCase().trim()) {
									case "containing":
									case "with": cntValueContainingWith += 1; break;
									case "worth": cntValueWorth += 1; break;
									default: throw new Error(`Unhandled "${m[1]}"`);
								}

								valueCp += Parser.coinValueToNumber(m[2]);
								return "";
							})
							.replace(/(包括|含有|内含|价值)\s?(\d+\s*(?:[csgep]p|金币|银币|铜币|铂金币|银金币|白金币))(\s+[(（][^)）]+[)）])?的?/gi, (...m) => {
								switch (m[1].toLowerCase().trim()) {
									case "包括":
									case "含有":
									case "内含": cntValueContainingWith += 1; break;
									case "价值": cntValueWorth += 1; break;
									default: throw new Error(`Unhandled "${m[1]}"`);
								}

								valueCp += Parser.coinValueToNumber(m[2]);
								return "";
							})
							.replace(/\s+/g, " ")
							.trim()
							// Handle e.g. "1 sp"--the quantity will have been pulled out already
							.replace(/^[csgep]p|金币|银币|铜币|铂金币|银金币|白金币$/gi, (...m) => {
								valueCp = Parser.coinValueToNumber(`${quantity} ${m[0]}`);
								return "";
							})
							.trim()
							// Handle e.g. "(10 gp)"
							.replace(/[(（](\d+\s*(?:[csgep]p|金币|银币|铜币|铂金币|银金币|白金币))[)）]/gi, (...m) => {
								valueCp += Parser.coinValueToNumber(m[1]);
								return "";
							})
							.trim();

						// Pull out "set of... " for clothes
						if (/clothes/i.test(ch)) {
							ch = ch.replace(/^set of /i, "");
						}

						// Pull out parenthetical parts that aren't in @item tags
						const ptParenMeta = this._getWithoutParenParts(ch);
						let ptDisplay = ch; // Keep a copy of the part to display as the item name
						let ptDisplayNoTags = Renderer.stripTags(ptDisplay);

						let ptPlain = ptParenMeta.plain.map(it => it.trim()).join(" ").trim();
						let ptParens = ptParenMeta.inParens.map(it => it.trim()).join(" ").trim();

						// Handle any manual mappings
						if (mappingsManual[chOriginal]) {
							return mappingsManual[chOriginal];
						}

						// Handle any pure coinage
						if (!ptPlain && valueCp) {
							return {value: valueCp};
						}

						// If the plain part seems to just be a single @item tag, use this
						const mItem = /{@item ([^}]+)}/.exec(ptPlain);
						const mFilter = /{@filter ([^}]+)}/.exec(ptPlain);

						// If the plain part is a flavorful name of an @item, use this
						const mItemParens = /^\({@item ([^}]+)}\)$/.exec(ptParens);

						if (mItem) {
							// consider doing something with displayText?
							const [name, source, displayText] = mItem[1].split("|").map(it => it.trim()).filter(Boolean);
							const idItem = [name, source].join("|").toLowerCase();

							const equipmentType = this._getEquipmentType(idItem);
							if (equipmentType) {
								const info = {equipmentType};

								if (quantity !== 1) info.quantity = quantity;
								if (ptPlain !== ptDisplay) info.displayName = ptDisplayNoTags;

								return info;
							}

							if (quantity !== 1 || ptPlain !== ptDisplay || valueCp) {
								const info = {item: idItem};

								if (quantity !== 1) info.quantity = quantity;
								if (ptPlain !== ptDisplay) info.displayName = ptDisplayNoTags;
								if (valueCp) info.containsValue = valueCp;

								return info;
							}

							if (!ptPlain.startsWith("{@") || !ptPlain.endsWith("}")) {
								return {
									item: idItem,
									displayName: ptDisplayNoTags,
								};
							}

							return idItem;
						}

						if (mFilter) {
							// Strip junk text
							let ptPlainFilter = ptPlain
								.replace(/^set of/gi, "").trim()
								.replace(/ you are proficient with$/gi, "").trim()
								.replace(/ with which you are proficient$/gi, "").trim()
								.replace(/ of your choice$/gi, "").trim()
								.replace(/ \([^)]+\)/gi, "").trim()
								// Brew
								.replace(/^wind /gi, "").trim();

							// We expect that the entire text is now a filter tag
							if (!ptPlainFilter.startsWith("{@") || !ptPlainFilter.endsWith("}")) throw new Error(`Text "${ptPlainFilter}" was not a single tag!`);

							const equipmentType = this._getEquipmentType(mFilter[1].split("|")[0], {isStrict: true});
							const info = {equipmentType};
							if (quantity !== 1) info.quantity = quantity;
							if (valueCp) info.containsValue = valueCp;
							return info;
						}

						if (mItemParens) {
							// consider doing something with displayText?
							const [name, source, displayText] = mItemParens[1].split("|").map(it => it.trim()).filter(Boolean);
							const idItem = [name, source].join("|").toLowerCase();

							const info = {
								item: idItem,
								displayName: ptPlain,
							};

							if (quantity !== 1) info.quantity = quantity;
							if (valueCp) info.containsValue = valueCp;

							return info;
						}

						// Otherwise, create a custom item
						const info = {special: ptDisplayNoTags.trim()};
						if (quantity !== 1) info.quantity = quantity;
						if (valueCp) {
							if (cntValueWorth > cntValueContainingWith) info.worthValue = valueCp;
							else info.containsValue = valueCp;
						}
						return info;
					})
					.flat();

				// Assign each choice a letter (or use underscore if it's the only choice)
				if (outChoices.length === 1) {
					if (outChoices[0].isList) return {[keyNoChoice]: outChoices[0].data};
					return {[keyNoChoice]: [outChoices[0]]};
				}

				const outPart = {};
				outChoices.forEach((ch, i) => {
					const letter = Parser.ALPHABET[i].toLowerCase();
					outPart[letter] = [ch];
				});
				return outPart;
			});

		// Combine no-choice sections together
		const outReduced = [];
		out
			.forEach(info => {
				if (!info[keyNoChoice]) return outReduced.push(info);

				const existing = outReduced.find(x => x[keyNoChoice]);
				if (existing) return existing[keyNoChoice].push(...info[keyNoChoice]);
				return outReduced.push(info);
			});

		return outReduced;
	}

	static _splitChoices ({str, allowlistOrEnds}) {
		const out = [];

		let expectAt = false;
		let braceDepth = 0;
		let parenDepth = 0;
		let stack = "";
		for (let i = 0; i < str.length; ++i) {
			const c = str[i];
			switch (c) {
				case "（":
				case "(": {
					if (expectAt) { braceDepth--; expectAt = false; }

					stack += c;
					parenDepth++;

					break;
				}
				case "）":
				case ")": {
					if (expectAt) { braceDepth--; expectAt = false; }

					stack += c;
					if (parenDepth) parenDepth--;

					break;
				}
				case "{": {
					if (expectAt) { braceDepth--; expectAt = false; }

					stack += c;
					braceDepth++;
					expectAt = true;

					break;
				}
				case "}": {
					if (expectAt) { braceDepth--; expectAt = false; }

					stack += c;
					if (braceDepth) braceDepth--;

					break;
				}

				case "@": { expectAt = false; stack += c; break; }

				case " ": {
					if (expectAt) { braceDepth--; expectAt = false; }

					stack += c;
					if (
						!braceDepth
						&& !parenDepth
					) {
						// An oxford comma implies earlier commas in this part are separating or'd parts, so back-split
						if (
							stack.endsWith(", or ")
							&& !allowlistOrEnds.some(it => stack.endsWith(it))
						) {
							const backSplit = stack.slice(0, -5).split(StrUtil.COMMAS_NOT_IN_PARENTHESES_REGEX).map(it => it.trim());
							out.push(...backSplit);
							stack = "";
						} else if (
							stack.endsWith(" or ")
							&& !allowlistOrEnds.some(it => stack.endsWith(it))
						) {
							out.push(stack.slice(0, -4));
							stack = "";
						}
					}

					break;
				}

				default: {
					if (expectAt) { braceDepth--; expectAt = false; }
					stack += c;
					break;
				}
			}
		}

		out.push(stack);

		// Split two conjoined items
		if (out.length === 1 && out[0].includes(" and ")) {
			let cntItem = 0;
			out[0].replace(/{@item/g, () => {
				cntItem++;
				return "";
			});
			if (cntItem > 1) {
				if (cntItem !== 2) throw new Error(`Unhandled conjunction count "${cntItem}"`);

				const spl = out[0].split(" and ");
				out[0] = spl[0];
				out.push(spl[1]);
			}
		}

		return out;
	}

	static _getWithoutParenParts (str) {
		const out = [];
		const outParens = [];

		let expectAt = false;
		let braceDepth = 0;
		let parenCount = 0;
		let stack = "";
		for (let i = 0; i < str.length; ++i) {
			const c = str[i];
			switch (c) {
				case "（":
				case "(": {
					if (expectAt) { braceDepth--; expectAt = false; }

					if (!braceDepth) {
						if (!parenCount) {
							out.push(stack);
							stack = "";
						}

						parenCount++;
					}

					stack += c;

					break;
				}
				case "）":
				case ")": {
					if (expectAt) { braceDepth--; expectAt = false; }

					stack += c;

					if (!braceDepth && parenCount) {
						parenCount--;

						if (!parenCount) {
							outParens.push(stack);
							stack = "";
						}
					}

					break;
				}
				case "{": {
					if (expectAt) { braceDepth--; expectAt = false; }

					braceDepth++;
					expectAt = true;

					stack += c;

					break;
				}
				case "}": {
					if (expectAt) { braceDepth--; expectAt = false; }

					stack += c;
					if (braceDepth) braceDepth--;

					break;
				}

				case "@": { expectAt = false; stack += c; break; }

				default: {
					if (expectAt) { braceDepth--; expectAt = false; }
					stack += c; break;
				}
			}
		}

		// Gather any leftovers
		if (!braceDepth) {
			if (!parenCount) out.push(stack);
			else outParens.push(stack);
		} else {
			out.push(stack);
		}

		return {plain: out.filter(Boolean), inParens: outParens.filter(Boolean)};
	}

	static _getEquipmentType (str, {isStrict = false} = {}) {
		switch (str.toLowerCase().trim()) {
			case "artisan's tools":
			case "artisan's tools|xphb":
			case "工匠工具":
			case "工匠工具|xphb":
				return "toolArtisan";
			case "gaming set":
			case "gaming set|xphb":
			case "赌具":
			case "赌具|xphb":
				return "setGaming";
			case "musical instrument":
			case "musical instrument|xphb":
			case "乐器":
			case "乐器|xphb":
				return "instrumentMusical";

			default: {
				if (!isStrict) return null;
				throw new Error(`Unhandled filter type "${str}"`);
			}
		}
	}
}

export class BackgroundSkillTollLanguageEquipmentCoalesce {
	static tryRun (
		bg,
		{
			cbWarning = () => {},
		} = {},
	) {
		if (!bg.entries) return;

		const [entriesToCompact, entriesOther] = bg.entries.segregate(ent => this._isToCompact(ent));

		if (!entriesToCompact.length) return;

		const list = {
			"type": "list",
			"style": "list-hang-notitle",
		};
		list.items = entriesToCompact
			.map(ent => {
				return ent.entries.length === 1
					? {
						type: "item",
						name: ent.name,
						entry: ent.entries[0],
					}
					: {
						type: "item",
						name: ent.name,
						entries: ent.entries,
					};
			});

		bg.entries = [
			list,
			...entriesOther,
		];
	}

	static _RES_COMPACT = [
		BackgroundConverterConst.RE_NAME_SKILLS,
		BackgroundConverterConst.RE_NAME_TOOLS,
		BackgroundConverterConst.RE_NAME_LANGUAGES,
		BackgroundConverterConst.RE_NAME_EQUIPMENT,
	];

	static _isToCompact (ent) {
		return this._RES_COMPACT
			.some(re => re.test(ent.name));
	}
}

export class BackgroundSkillToolLanguageTag {
	static tryRun (
		bg,
		{
			cbWarning = () => {},
		} = {},
	) {
		const list = bg.entries.find(ent => ent.type === "list");
		if (!list) return;

		this._doSkillTag({bg, list, cbWarning});
		this._doToolTag({bg, list, cbWarning});
		this._doLanguageTag({bg, list, cbWarning});
	}

	static _doSkillTag ({bg, list, cbWarning}) {
		const skillProf = list.items.find(ent => BackgroundConverterConst.RE_NAME_SKILLS.test(ent.name));
		if (!skillProf) return;

		const mOneStaticOneChoice = /^(?<predefined>.*)\band one choice from the following:(?<choices>.*)$/i.exec(skillProf.entry)
		|| /^(?<predefined>.*)并从(?<choices>.*)中选择一项$/i.exec(skillProf.entry);
		if (mOneStaticOneChoice) {
			const predefined = {};
			mOneStaticOneChoice.groups.predefined
				.replace(/{@skill (?<skill>[^}]+)/g, (...m) => {
					predefined[m.last().skill.toLowerCase().trim()] = true;
					return "";
				});

			if (!Object.keys(predefined).length) return cbWarning(`(${bg.name}) Skills require manual tagging`);

			const choices = [];
			mOneStaticOneChoice.groups.choices
				.replace(/{@skill (?<skill>[^}]+)/g, (...m) => {
					choices.push(m.last().skill.toLowerCase().trim());
					return "";
				});

			bg.skillProficiencies = [
				{
					...predefined,
					choose: {
						from: choices,
					},
				},
			];

			return;
		}

		if (/^Two of the following:/.test(skillProf.entry)
			|| /^从.*中任?选择?两项/.test(skillProf.entry)) {
			const choices = [];
			skillProf.entry
				.replace(/{@skill (?<skill>[^}]+)/g, (...m) => {
					choices.push(m.last().skill.toLowerCase().trim());
					return "";
				});

			bg.skillProficiencies = [
				{
					choose: {
						from: choices,
						count: 2,
					},
				},
			];

			return;
		}

		if (!/^({@skill [^}]+}(?:, | and |，|、|和)?)+$/.test(skillProf.entry)) return cbWarning(`(${bg.name}) 的技能需要手动打Tag`);

		bg.skillProficiencies = [
			skillProf.entry
				.split(/, | and |，|、|和/)
				.map(ent => ent.trim())
				.mergeMap(str => {
					const reTag = /^{@skill (?<skill>[^}]+)}$/.exec(str);
					if (reTag) return {[Parser.cnSkillToEn(reTag.groups.skill.toLowerCase().trim().replace(/\|xphb$/, ""))]: true};
					throw new Error(`无法找到${str}中的技能Tag`);
				}),
		];
	}

	static _TOOL_GROUP_MAPPINGS = {
		"gaming set": "anyGamingSet",
		"赌具": "anyGamingSet",
		"artisan's tools": "anyArtisansTool",
		"工匠工具": "anyArtisansTool",
		"musical instrument": "anyMusicalInstrument",
		"乐器": "anyMusicalInstrument",
	};

	static _doToolTag ({bg, list, cbWarning}) {
		const toolProf = list.items.find(ent => BackgroundConverterConst.RE_NAME_TOOLS.test(ent.name));
		if (!toolProf) return;

		const entry = Renderer.stripTags(toolProf.entry.toLowerCase())
			.replace(/\(see [^)]+\)/g, "").trim()
			.replace(/(?:choose )?one (?:type|kind) of gaming set/g, "gaming set")
			.replace(/(?:自选|选择)?(?:一|1)(?:种|个)赌具/g, "gaming set")
			.replace(/(?:choose )?one (?:type|kind) of artisan's tools/g, "artisan's tools")
			.replace(/(?:自选|选择)?(?:一|1)(?:种|个)工匠工具/g, "artisan's tools")
			.replace(/(?:choose )?one (?:type|kind) of gaming set/g, "gaming set")
			.replace(/(?:choose )?one (?:type|kind) of musical instrument/g, "musical instrument")
			.replace(/(?:自选|选择)?(?:一|1)(?:种|个)乐器/g, "musical instrument")
			.replace(/(?:choose )?one other set of artisan's tools/g, "artisan's tools")
			.replace(/(?:自选|选择)?(?:另外|其他)的?(?:一|1)(?:种|个)工匠工具/g, "artisan's tools")
			.replace(/(?:自选|选择)?(?:一|1)(?:种|个)其他的?工匠工具/g, "artisan's tools")
			.replace(/s' supplies/g, "'s supplies")
		;

		const isChoice = /\bany |\bchoose |\bone type|\bchoice|\bor |选择|任意|任一|一种|或/g.exec(entry);
		const isSpecial = /\bspecial|特殊/.exec(entry);

		if (!isChoice && !isSpecial) {
			bg.toolProficiencies = [
				entry.toLowerCase()
					.split(/,\s?(?![^(]*\))| or | and |[,，]\s?(?![^(（]*[)）])|或|和|以及/g)
					.filter(Boolean)
					.map(pt => pt.trim())
					.filter(pt => pt)
					.mergeMap(pt => {
						const group = this._TOOL_GROUP_MAPPINGS[pt];
						if (group) return {[group]: 1};
						return {[pt]: true};
					}),
			];
			return;
		}

		if (isChoice) {
			const entryClean = entry
				.replace(/^either /gi, "");

			const out = {};
			// TODO(kiwee) 这些回来在处理吧，太多了
			switch (entryClean) {
				case "cartographer's tools or navigator's tools":
					out.choose = {from: ["navigator's tools", "cartographer's tools"]};
					break;
				case "disguise kit, and artisan's tools or gaming set":
					out["disguise kit"] = true;
					out.choose = {from: ["anyArtisansTool", "anyGamingSet"]};
					break;
				case "any one musical instrument or gaming set of your choice, likely something native to your homeland":
					out.choose = {from: ["anyMusicalInstrument", "anyGamingSet"]};
					break;
				case "your choice of a gaming set or a musical instrument":
					out.choose = {from: ["anyMusicalInstrument", "anyGamingSet"]};
					break;
				case "musical instrument or artisan's tools":
					out.choose = {from: ["anyMusicalInstrument", "anyArtisansTool"]};
					break;
				case "one type of artistic artisan's tools and one musical instrument":
					out["anyArtisansTool"] = true;
					out["anyMusicalInstrument"] = true;
					break;
				case "choose two from among gaming set, one musical instrument, and thieves' tools":
					out.choose = {
						from: ["anyGamingSet", "anyMusicalInstrument", "thieves' tools"],
						count: 2,
					};
					break;
				case "artisan's tools, or navigator's tools, or an additional language":
					out.choose = {from: ["anyArtisansTool", "navigator's tools"]};
					break;
				case "gaming set or musical instrument":
					out.choose = {from: ["anyGamingSet", "anyMusicalInstrument"]};
					break;
				case "calligrapher's supplies or alchemist's supplies":
					out.choose = {from: ["calligrapher's supplies", "alchemist's supplies"]};
					break;
				case "choose musical instrument":
					out["anyMusicalInstrument"] = true;
					break;
				default:
					cbWarning(`(${bg.name}) Tool proficiencies require manual tagging in "${entry}"`);
			}
			bg.toolProficiencies = [out];
			return;
		}

		if (isSpecial) {
			cbWarning(`(${bg.name}) Tool proficiencies require manual tagging in "${entry}"`);
		}
	}

	static _doLanguageTag ({bg, list, cbWarning}) {
		const langProf = list.items.find(ent => BackgroundConverterConst.RE_NAME_LANGUAGES.test(ent.name));
		if (!langProf) return;

		const languageProficiencies = this._getLanguageTags({langProf});
		if (!languageProficiencies) {
			cbWarning(`(${bg.name}) 的语言熟练项："${langProf.entry}" 需要手动打Tag`);
			return;
		}
		bg.languageProficiencies = languageProficiencies;
	}

	static _getLanguageTags ({langProf}) {
		let str = (langProf.entry || langProf.entries[0])
			.replace(/\bElven\b/, "Elvish")
			.replace(/\([^)]+ recommended\)$/, "")
			.trim();

		const reStrLanguage = `(${Parser.LANGUAGES_ALL.map(it => it.escapeRegexp()).join("|")})`;

		const mSingle = new RegExp(`^${reStrLanguage}$`, "i").exec(str);
		if (mSingle) return [{[mSingle[1].toLowerCase()]: true}];

		const mDoubleAnd = new RegExp(`^${reStrLanguage}(?: and | ?[和与] ?)${reStrLanguage}$`, "i").exec(str);
		if (mDoubleAnd) return [{[mDoubleAnd[1].toLowerCase()]: true, [mDoubleAnd[2].toLowerCase()]: true}];

		const mDoubleAndChoose = new RegExp(`^${reStrLanguage} and one other language of your choice$`, "i").exec(str)
		|| new RegExp(`^${reStrLanguage}(?:与|和|以及)另?一[项门]你?(?:自选|选择)的语言$`, "i").exec(str)
		|| new RegExp(`^${reStrLanguage}(?:与|和|以及)你?(?:自选|选择)的另?一[项门]语言$`, "i").exec(str);
		if (mDoubleAndChoose) return [{[mDoubleAndChoose[1].toLowerCase()]: true, "anyStandard": true}];

		const mDoubleOr = new RegExp(`^${reStrLanguage}(?: or | ?或 ?)${reStrLanguage}$`, "i").exec(str);
		if (mDoubleOr) return [{[mDoubleOr[1].toLowerCase()]: true}, {[mDoubleOr[2].toLowerCase()]: true}];

		const mNumAny = /^(?:any )?((?<count>one|two) )?of your choice$/i.exec(str)
		|| /^你?(?:自选|选择)的?(?:任意)?(?<count>一|两|三|四)?门?语言$/i.exec(str);
		if (mNumAny) return [{"anyStandard": Parser.textToNumber(mNumAny.groups?.count || "one")}];

		const mNumExotic = /^(?:(?:any|choose) )?((?<count>one|two) )?exotic language(?: \([^)]+\))?$/i.exec(str)
		|| /^(你?(?:自选|选择)?的?(?:任意)?(?<count>一|两|三|四)?门?)?特种语言$/i.exec(str);
		if (mNumExotic) return [{"anyExotic": Parser.textToNumber(mNumExotic.groups?.count || "one")}];

		const mSingleOrAlternate = new RegExp(`^${reStrLanguage} or one of your choice if you already speak ${reStrLanguage}$`, "i").exec(str)
		|| new RegExp(`^${reStrLanguage}，或如果你已经熟悉${reStrLanguage}了就自选一门语言$`, "i").exec(str);

		if (mSingleOrAlternate) return [{[mSingle[1].toLowerCase()]: true}, {"anyStandard": 1}];

		return null;
	}
}

