class LootGenMagicItemSubItems extends LootGenMagicItem {
	constructor (
		{
			subItems,
			isInlineReroll = false,
			...others
		},
	) {
		super(others);
		this._subItems = subItems;
		this._isInlineReroll = isInlineReroll;
	}

	getExtensionExportMeta () {
		if (!this._state.isSpellScroll) return super.getExtensionExportMeta();

		return {
			page: UrlUtil.PG_SPELLS,
			entity: this._state.spell,
			options: {
				isSpellScroll: true,
			},
		};
	}

	_getRender () {
		const dispBaseEntry = this._getRender_getDispBaseEntry();
		const dispRoll = this._getRender_getDispRoll();

		const stgSpellScroll = _LootGenMagicItemSpellUtils.getBindEles({
			spells: this._spells,
			comp: this,
			rendererWrapped: this._rendererWrapped,
			isVerbose: true,
		});

		const btnRerollSubItem = veT`<span class="ve-roller render-roller">[${I18nUtil.get("common.button.reroll")}]</span>`
			.vee.onn("mousedown", evt => evt.preventDefault())
			.vee.onn("click", () => {
				const itemRolled = RollerUtil.rollOnArray(this._subItems);
				if (!itemRolled) return;
				this._state.item = itemRolled;
				if (this._isInlineReroll) this._state.baseEntry = `{@item ${DataUtil.proxy.getUidPacked("item", itemRolled, "item", {isMaintainCase: true})}}`;
			});

		const dispSubItem = this._isInlineReroll
			? null
			: veT`<div class="ve-ml-2"></div>`;
		if (!this._isInlineReroll) {
			this._addHookBase("item", () => {
				if (!this._state.item) return;
				dispSubItem.vee.html(this._rendererWrapped.er(`{@item ${DataUtil.proxy.getUidPacked("item", this._state.item, "item", {isMaintainCase: true})}}`));
			})();
		}

		this._addHookBase("item", () => {
			if (this._state.item?.spellScrollLevel == null) {
				this._proxyAssignSimple("state", {
					isSpellScroll: false,
					spellLevel: null,
					spell: null,
				});
				return;
			}

			this._proxyAssignSimple("state", {
				isSpellScroll: true,
				spellLevel: this._state.item.spellScrollLevel,
				spell: RollerUtil.rollOnArray(this._spells.filter(it => it.level === this._state.item.spellScrollLevel)),
			});
		})();

		const btnReroll = this._getBtnReroll();

		const ptSubItem = this._subItems.length
			? veT`<div class="ve-flex-v-center ve-italic ve-mr-2">
					<span>(</span>
					${btnRerollSubItem}
					${dispSubItem}
					<span>)</span>
				</div>`
			: null;

		return veT`<li class="ve-split-v-center">
			<div class="ve-flex-v-center ve-flex-wrap ve-pr-3 ve-min-w-0">
				${dispBaseEntry}
				${ptSubItem}
				${stgSpellScroll}
				${dispRoll}
			</div>
			${btnReroll}
		</li>`;
	}

	_getDefaultState () {
		return {
			...super._getDefaultState(),
			isSpellScroll: false,
			spellLevel: null,
			spell: null,
		};
	}
}

export class LootGenMagicItemTable extends LootGenMagicItem {
	static async pGetSubRollMeta ({min, max, subTable}) {
		const subRowRoll = RollerUtil.randomise(max, min);
		const subRow = subTable.find(it => subRowRoll >= it.min && subRowRoll <= (it.max ?? it.min));

		return {
			subRowRoll,
			subRow,
			subItem: await this._pGetMagicItemRoll_pGetItem({nameOrUid: subRow.item}),
		};
	}

	constructor (
		{
			table,
			tableMinRoll,
			tableMaxRoll,
			tableEntry,
			tableRoll,
			...others
		},
	) {
		super(others);
		this._table = table;
		this._tableMinRoll = tableMinRoll;
		this._tableMaxRoll = tableMaxRoll;
		this._state.tableEntry = tableEntry;
		this._state.tableRoll = tableRoll;
	}

	_getRender () {
		const dispBaseEntry = this._getRender_getDispBaseEntry();
		const dispRoll = this._getRender_getDispRoll();

		const dispTableEntry = this._getRender_getDispBaseEntry({prop: "tableEntry"});
		const dispTableRoll = this._getRender_getDispRoll({prop: "tableRoll"});

		const btnReroll = this._getBtnReroll();

		const btnRerollSub = veT`<span class="ve-roller render-roller ve-small ve-self-flex-end">[${I18nUtil.get("common.button.reroll")}]</span>`
			.vee.onn("mousedown", evt => evt.preventDefault())
			.vee.onn("click", async () => {
				const {subRowRoll, subRow, subItem} = await LootGenMagicItemTable.pGetSubRollMeta({
					min: this._tableMinRoll,
					max: this._tableMaxRoll,
					subTable: this._table,
				});

				this._state.item = subItem;
				this._state.tableEntry = subRow.item;
				this._state.tableRoll = subRowRoll;
			});

		return veT`<li class="ve-flex-col">
			<div class="ve-split-v-center">
				<div class="ve-flex-v-center ve-flex-wrap ve-pr-3 ve-min-w-0">
					${dispBaseEntry}
					${dispRoll}
				</div>
				${btnReroll}
			</div>
			<div class="ve-split-v-center ve-pl-2">
				<div class="ve-flex-v-center ve-flex-wrap ve-pr-3 ve-min-w-0">
					<span class="ve-ml-1 ve-mr-2">&rarr;</span>
					${dispTableEntry}
					${dispTableRoll}
				</div>
				${btnRerollSub}
			</div>
		</li>`;
	}
}

