	_validateMeta () {
		// ensure expected objects exist
		const setOn = this._meta || this.__meta;
		if (!setOn.profSave) setOn.profSave = {};
		if (!setOn.profSkill) setOn.profSkill = {};
		if (!setOn.autoCalc) setOn.autoCalc = {};
	}

