import {BuilderBase} from "./makebrew-builder-base.js";
import {BuilderUi} from "./makebrew-builderui.js";
import {TagCondition} from "../converter/converterutils-tags.js";
import {RenderBestiary} from "../render-bestiary.js";

export class LegendaryGroupBuilder extends BuilderBase {
	constructor () {
		super({
			prop: "legendaryGroup",
		});

		this._renderOutputDebounced = MiscUtil.debounce(() => this._renderOutput(), 50);
	}

	async pHandleClickLoadExisting () {
		const result = await SearchWidget.pGetUserLegendaryGroupSearch();
		if (result) {
			const legGroup = MiscUtil.copy(await DataLoader.pCacheAndGet(result.page, result.source, result.hash));
			return this.pHandleLoadExistingData(legGroup);
		}
	}

	/**
	 * @param legGroup
	 * @param [opts]
	 * @param [opts.meta]
	 */
	async pHandleLoadExistingData (legGroup, opts) {
		opts = opts || {};

		legGroup.name = `${legGroup.name} (Copy)`;
		legGroup.source = this._ui.source;

		delete legGroup.uniqueId;

		const meta = {...(opts.meta || {}), ...this._getInitialMetaState({nameOriginal: legGroup.name, isModified: true})};

		this.setStateFromLoaded({s: legGroup, m: meta});

		this.renderInput();
		this.renderOutput();
	}

	_getInitialState () {
		return {
			...super._getInitialState(),
			name: "新传奇组",
			lairActions: [],
			regionalEffects: [],
			mythicEncounter: [],
			source: this._ui ? this._ui.source : "",
		};
	}

	setStateFromLoaded (state) {
		if (!state?.s || !state?.m) return;

		this._doResetProxies();

		if (!state.s.uniqueId) state.s.uniqueId = CryptUtil.uid();

		this.__state = state.s;
		this.__meta = state.m;
	}

	doHandleSourcesAdd () { /* No-op */ }

	_renderInputImpl () {
		this._doCreateProxies();
		this._doBindHeaderElements();
		this._renderInputMain();
	}

	_renderInputMain () {
		this._sourcesCache = MiscUtil.copy(this._ui.allSources);
		const wrp = this._ui.wrpInput.vee.empty();

		const _cb = () => {
			// Prefer numerical pages if possible
			if (!isNaN(this._state.page)) this._state.page = Number(this._state.page);

			// do post-processing
			TagCondition.tryTagConditions(this._state, {isTagInflicted: true, styleHint: this._meta.styleHint});

			this.renderOutput();
			this.doUiSave();
			this._meta.isModified = true;
		};
		const cb = MiscUtil.debounce(_cb, 33);
		this._cbCache = cb; // cache for use when updating sources

		// initialise tabs
		this._resetTabs({tabGroup: "input"});

		const tabOptsShared = {hasBorder: true, hasBackground: true};
		const tabs = this._renderTabs(
			[
				new TabUiUtil.TabMeta({...tabOptsShared, name: "描述"}),
				new TabUiUtil.TabMeta({...tabOptsShared, name: "巢穴动作"}),
				new TabUiUtil.TabMeta({...tabOptsShared, name: "区域效应"}),
				new TabUiUtil.TabMeta({...tabOptsShared, name: "神话遭遇"}),
			],
			{
				tabGroup: "input",
				cbTabChange: this.doUiSave.bind(this),
			},
		);
		const [infoTab, lairActionsTab, regionalEffectsTab, mythicEncounterTab] = tabs;
		veT`<div class="ve-flex-v-center ve-w-100 ve-no-shrink ve-ui-tab__wrp-tab-heads--border">${tabs.map(it => it.btnTab)}</div>`.vee.appendTo(wrp);
		tabs.forEach(it => it.wrpTab.vee.appendTo(wrp));

		// INFO
		BuilderUi.getStateIptString("中文名", cb, this._state, {nullable: false}, "name").vee.appendTo(infoTab.wrpTab);
		BuilderUi.getStateIptString("英文名", cb, this._state, {nullable: true}, "ENG_name").vee.appendTo(infoTab.wrpTab);
		this._selSource = this.getSourceInput(cb).vee.appendTo(infoTab.wrpTab);

		// LAIR ACTIONS
		this.__getLairActionsInput(cb).vee.appendTo(lairActionsTab.wrpTab);

		// REGIONAL EFFECTS
		this.__getRegionalEffectsInput(cb).vee.appendTo(regionalEffectsTab.wrpTab);

		// MYTHIC ENCOUNTER
		this.__getMythicEncounterEffectsInput(cb).vee.appendTo(mythicEncounterTab.wrpTab);
	}

	__getLairActionsInput (cb) {
		return BuilderUi.getStateIptEntries("巢穴动作", cb, this._state, {}, "lairActions");
	}

	__getRegionalEffectsInput (cb) {
		return BuilderUi.getStateIptEntries("区域效应", cb, this._state, {}, "regionalEffects");
	}

	__getMythicEncounterEffectsInput (cb) {
		return BuilderUi.getStateIptEntries("神话遭遇", cb, this._state, {}, "mythicEncounter");
	}

	renderOutput () {
		this._renderOutputDebounced();
	}

	_renderOutput () {
		const wrp = this._ui.wrpOutput.vee.empty();

		// initialise tabs
		this._resetTabs({tabGroup: "output"});
		const tabs = this._renderTabs(
			[
				new TabUiUtil.TabMeta({name: "传奇组"}),
				new TabUiUtil.TabMeta({name: "数据"}),
			],
			{
				tabGroup: "output",
				cbTabChange: this.doUiSave.bind(this),
			},
		);
		const [legGroupTab, dataTab] = tabs;
		veT`<div class="ve-flex-v-center ve-w-100 ve-no-shrink">${tabs.map(it => it.btnTab)}</div>`.vee.appendTo(wrp);
		tabs.forEach(it => it.wrpTab.vee.appendTo(wrp));

		// Legendary Group
		const tblLegGroup = veT`<table class="ve-w-100 ve-stats"></table>`.vee.appendTo(legGroupTab.wrpTab);
		tblLegGroup.vee.appends(RenderBestiary.getRenderedLegendaryGroup(this._state));

		// Data
		const asCode = Renderer.get().render({
			type: "entries",
			entries: [
				{
					type: "code",
					name: `Data`,
					preformatted: JSON.stringify(DataUtil.cleanJson(MiscUtil.copy(this._state)), null, "\t"),
				},
			],
		});
		veT`<table class="ve-stats ve-stats--book mkbru__wrp-output-tab-data">
			${Renderer.utils.getBorderTr()}
			<tr><td colspan="6">${asCode}</td></tr>
			${Renderer.utils.getBorderTr()}
		</table>`
			.vee.appendTo(dataTab.wrpTab);
	}

	async pDoPostSave () { await this._ui.creatureBuilder.pUpdateLegendaryGroups(); }
	async pDoPostDelete () { await this._ui.creatureBuilder.pUpdateLegendaryGroups(); }
}

