		tabs.forEach(it => it.wrpTab.vee.appendTo(wrp));

		// INFO
		BuilderUi.getStateIptString("中文名", cb, this._state, {nullable: false}, "name").vee.appendTo(infoTab.wrpTab);
		BuilderUi.getStateIptString("英文名", cb, this._state, {nullable: true}, "ENG_name").vee.appendTo(infoTab.wrpTab);
		this._selSource = this.getSourceInput(cb).vee.appendTo(infoTab.wrpTab);
		this.__getOtherSourcesInput(cb).vee.appendTo(infoTab.wrpTab);
		BuilderUi.getStateIptString("页码", cb, this._state, {}, "page").vee.appendTo(infoTab.wrpTab);
		BuilderUi.getStateIptEnum("环节", cb, this._state, {nullable: false, fnDisplay: (it) => Parser.spLevelToFull(it), vals: [...new Array(21)].map((_, i) => i)}, "level").vee.appendTo(infoTab.wrpTab);
		BuilderUi.getStateIptEnum("学派", cb, this._state, {nullable: false, fnDisplay: (it) => Parser.spSchoolAbvToFull(it), vals: [...Parser.SKL_ABVS]}, "school").vee.appendTo(infoTab.wrpTab);
		BuilderUi.getStateIptStringArray(
			"子学派",
			cb,
			this._state,
			{
				shortName: "子学派",
				title: "在一些自制法术中出现，例如“时械”子学派。",
			},
			"subschools",
		).vee.appendTo(infoTab.wrpTab);

		// TEXT
		this.__getTimeInput(cb).vee.appendTo(detailsTab.wrpTab);
		this.__getRangeInput(cb).vee.appendTo(detailsTab.wrpTab);
		this.__getComponentInput(cb).vee.appendTo(detailsTab.wrpTab);
		this.__getMetaInput(cb).vee.appendTo(detailsTab.wrpTab);
		this.__getDurationInput(cb).vee.appendTo(detailsTab.wrpTab);
		BuilderUi.getStateIptEntries("说明", cb, this._state, {fnPostProcess: BuilderUi.fnPostProcessDice}, "entries").vee.appendTo(detailsTab.wrpTab);
		const iptEntriesHigherLevelMeta = BuilderUi.getStateIptEntries(
			"&quot;升环施法&quot; 说明",
			cb,
			this._state,
