		rowOptionalFeatures.vee.appendTo(sourcesTab.wrpTab);
		const {row: rowFeats, doRefresh: doRefreshFeats} = this.__getFeats(cb);
		rowFeats.vee.appendTo(sourcesTab.wrpTab);
