		).vee.appendTo(miscTab.wrpTab);
		BuilderUi.getStateIptBooleanArray(
			"效应区域",
			cb,
			this._state,
			{
				vals: Object.keys(Parser.SPELL_AREA_TYPE_TO_FULL),
