			${wrpRowsAsi}

			${stgRace}

			${stgBackground}

			<hr class="ve-hr-3 ve-hr--dotted">
			<h4 class="ve-my-2 ve-bold">${I18nUtil.get("page.statgen.additional_feats")}</h4>
			<label class="ve-w-100 ve-flex-v-center ve-mb-2">
				<div class="ve-mr-2 ve-no-shrink">${I18nUtil.get("page.statgen.number_of_additional_feats")}:</div>${wrpCountFeatsCustom}
			</label>
			${wrpRowsCustom}
		`;
