export class UtilsBlocklist {
	static _PROPS_NO_BLOCKLIST = new Set([
		"itemProperty",
		"itemType",
		"spellList",
		"adventureTuple",
		"bookTuple",
		"map",
		"roll20Spell",
		"makebrewCreatureTrait",
	]);
	static _PROP_RE_FOUNDRY = /^foundry[A-Z]/;

	/* -------------------------------------------- */

	/**
	 * @param {Array} arr
	 * @param {?string} prop
	 * @param {boolean} isIgnoreBlocklist
	 * @param {?Function} fnMissingSource
	 * @param {?Function} fnMissingProp
	 */
	static getBlocklistFilteredArray (arr, {prop = null, isIgnoreBlocklist = false, fnMissingSource = null, fnMissingProp = null} = {}) {
		if (!arr || !(arr instanceof Array)) return arr;

		return arr
			.filter(ent => {
				const propEnt = ent.__prop || prop;

				// Ignore "Generic" entries, as we expect them to be synthetic
				if (SourceUtil.getEntitySource(ent) === VeCt.STR_GENERIC) return true;

				if (propEnt && this._PROPS_NO_BLOCKLIST.has(propEnt)) return true;
				if (propEnt && this._PROP_RE_FOUNDRY.test(propEnt)) return false;

				// region Sanity check
				if (!SourceUtil.getEntitySource(ent)) {
					if (fnMissingSource) fnMissingSource({ent});
					return true;
				}

				const hashBuilder = UrlUtil.URL_TO_HASH_BUILDER[propEnt];
				if (!hashBuilder) {
					if (fnMissingProp) fnMissingProp({ent, propEnt});
					return true;
				}
				// endregion

				if (!isIgnoreBlocklist && this._isExcludedEntity({ent, propEnt, hashBuilder})) return false;

				if (!isIgnoreBlocklist) this._mutExcludeSubEntities({ent, propEnt});

				return true;
			});
	}

	/* -------------------------------------------- */

	static _isExcludedEntity ({ent, propEnt, hashBuilder}) {
		switch (propEnt) {
			case "item":
			case "baseitem":
			case "itemGroup":
			case "magicvariant":
			case "_specificVariant": {
				return Renderer.item.isExcluded(ent);
			}

			case "race": {
				return this._isExcludedRaceSubrace(ent)
					|| this._isExcludedEntityGeneric({ent, propEnt, hashBuilder});
			}

			default: return this._isExcludedEntityGeneric({ent, propEnt, hashBuilder});
		}
	}

	static _isExcludedRaceSubrace ({ent, propEnt}) {
		if (propEnt !== "race") return false;
		return ent._subraceName
			&& ExcludeUtil.isExcluded(
				UrlUtil.URL_TO_HASH_BUILDER["subrace"]({name: ent._subraceName, source: ent.source, raceName: ent._baseName, raceSource: ent._baseSource}),
				"subrace",
				SourceUtil.getEntitySource(ent),
				{isNoCount: true},
			);
	}

	static _isExcludedEntityGeneric ({ent, propEnt, hashBuilder}) {
		return ExcludeUtil.isExcluded(
			hashBuilder(ent),
			propEnt,
			SourceUtil.getEntitySource(ent),
			{isNoCount: true},
		);
	}

	/* -------------------------------------------- */

	static _mutExcludeSubEntities ({ent, propEnt}) {
		switch (propEnt) {
			case "class": return this._mutExcludeSubEntities_class({ent});
		}
	}

	static _mutExcludeSubEntities_class ({ent}) {
		if (ent.classFeatures?.length) {
			ent.classFeatures = ent.classFeatures
				.filter(cf => {
					if (cf.hash == null) return true;

					return !ExcludeUtil.isExcluded(
						cf.hash,
						"classFeature",
						cf.source,
						{isNoCount: true},
					);
				});
		}

		if (ent.subclasses?.length) {
			ent.subclasses = ent.subclasses
				.filter(sc => {
					if (sc.source === VeCt.STR_GENERIC) return false;

					return !ExcludeUtil.isExcluded(
						UrlUtil.URL_TO_HASH_BUILDER["subclass"](sc),
						"subclass",
						sc.source,
						{isNoCount: true},
					);
				});

			ent.subclasses
				.forEach(sc => {
					if (!sc.subclassFeatures) return;

					sc.subclassFeatures = sc.subclassFeatures
						.filter(scf => {
							if (scf.hash == null) return true;

							return !ExcludeUtil.isExcluded(
								scf.hash,
								"subclassFeature",
								scf.source,
								{isNoCount: true},
							);
						});
				});
		}
	}
}

/js/utils-brew/utils-brew-base.js:
import {BrewUtilShared} from "./utils-brew-helpers.js";
import {BrewDoc} from "./utils-brew-models.js";
import {SITE_STYLE__CLASSIC, SITE_STYLE__ONE} from "../consts.js";
import {FontManager} from "../utils-font.js";
import {BrewDocContentMigrator} from "./utils-brew-content-migrator.js";

export class BrewUtil2Base {
	_STORAGE_KEY_LEGACY;
	_STORAGE_KEY_LEGACY_META;

	// Keep these distinct from the OG brew key, so users can recover their old brew if required.
	_STORAGE_KEY;
	_STORAGE_KEY_META;

	_STORAGE_KEY_RELOAD_MESSAGE;
	_STORAGE_KEY_CUSTOM_URL;
	_STORAGE_KEY_MIGRATION_VERSION;

	_VERSION;

	_PATH_LOCAL_DIR;
	_PATH_LOCAL_INDEX;

	ID;
	IS_EDITABLE;
	PAGE_MANAGE;
	URL_REPO_DEFAULT;
	URL_REPO_ROOT_DEFAULT;
	DISPLAY_NAME;
	DISPLAY_NAME_PLURAL;
	DEFAULT_AUTHOR;
	STYLE_BTN;
	IS_PREFER_DATE_ADDED;
	IS_ADD_BTN_ALL_PARTNERED;

	_LOCK = new VeLock({name: this.constructor.name});

	_cache_iteration = 0;
	_cache_brewsProc = null;
	_cache_metas = null;
	_cache_sourceStyles = null;
	_cache_brews = null;
	_cache_brewsLocal = null;

	_isDirty = false;

	_brewsTemp = [];
	_addLazy_brewsTemp = [];

	_storage = StorageUtil;

	_eleStyle = null;

	_parent = null;

	/**
	 * @param {?BrewUtil2Base} parent
	 */
	constructor ({parent = null} = {}) {
		this._parent = parent;
	}

	/* -------------------------------------------- */

	_pActiveInit = null;

	pInit () {
		this._pActiveInit ||= (async () => {
			// region Ensure the local homebrew cache is hot, to allow us to fetch from it later in a sync manner.
			//   This is necessary to replicate the "meta" caching done for non-local brew.
			await this._pGetBrew_pGetLocalBrew();
			// endregion

			this._pInit_doBindDragDrop();
			this._pInit_pDoLoadFonts().then(null);
			await this._pInit_pDoShowReloadMessage();
		})();
		return this._pActiveInit;
	}

	static _isPrereleaseDroppedJson (json) {
		return json._meta?.sources?.every(src => SourceUtil.isPrereleaseSource(src?.json || ""));
	}

	static _IS_INIT_SHARED_DRAG_DROP = false;

	static _initSharedDragDrop () {
		if (this._IS_INIT_SHARED_DRAG_DROP) return;

		document.body.addEventListener("drop", async evt => {
			if (EventUtil.isInInput(evt)) return;

			evt.stopPropagation();
			evt.preventDefault();

			const files = evt.dataTransfer?.files;
			if (!files?.length) return;

			const pFiles = [...files].map((file, i) => {
				if (!/\.json$/i.test(file.name)) return null;

				return new Promise(resolve => {
					const reader = new FileReader();
					reader.onload = () => {
						let json;
						try {
							json = JSON.parse(reader.result);
						} catch (ignored) {
							return resolve(null);
						}

						resolve({name: file.name, json});
					};

					reader.readAsText(files[i]);
				});
			});

			const fileMetas = (await Promise.allSettled(pFiles))
				.filter(({status}) => status === "fulfilled")
				.map(({value}) => value)
				.filter(Boolean);

			const [prereleaseFileMetas, brewFileMetas] = fileMetas.segregate(fileMeta => this._isPrereleaseDroppedJson(fileMeta.json));

			if (prereleaseFileMetas.length) await PrereleaseUtil.pAddBrewsFromFiles(prereleaseFileMetas);
			if (brewFileMetas.length) await BrewUtil2.pAddBrewsFromFiles(brewFileMetas);

			[PrereleaseUtil, BrewUtil2]
				.find(it => it.isReloadRequired())
				?.doLocationReload();
		});

		document.body.addEventListener("dragover", evt => {
			if (EventUtil.isInInput(evt)) return;

			evt.stopPropagation();
			evt.preventDefault();
		});

		this._IS_INIT_SHARED_DRAG_DROP = true;
	}

	_pInit_doBindDragDrop () {
		this.constructor._initSharedDragDrop();
	}

	async _pInit_pDoLoadFonts () {
		const fontMetas = Object.entries(
			(this._getBrewMetas() || [])
				.map(({_meta}) => _meta?.fonts || {})
				.mergeMap(it => it),
		)
			.map(([fontId, fontUrl]) => ({fontId, fontUrl}));
		if (!fontMetas.length) return;

		fontMetas
			.forEach(({fontId, fontUrl}) => FontManager.addFontLazy({fontId, fontUrl}));

		const {errors} = await FontManager.pFinalizeLazy();

		if (!errors.length) return;

		errors.forEach(({message}) => JqueryUtil.doToast({type: "danger", content: message}));
		setTimeout(() => { throw new Error(errors.map(({message, reason}) => [message, reason].join("\n")).join("\n\n")); });
	}

	async _pInit_pDoShowReloadMessage () {
		const messageInfo = await this._storage.pGet(this._STORAGE_KEY_RELOAD_MESSAGE);
		if (!messageInfo) return;
		await this._storage.pRemove(this._STORAGE_KEY_RELOAD_MESSAGE);
		try {
			JqueryUtil.doToast({
				...messageInfo,
				content: veE({outer: messageInfo.contentHtml}),
			});
		} catch (e) {
			setTimeout(() => { throw e; });
		}
	}

	/* -------------------------------------------- */

	async pGetCustomUrl () { return this._storage.pGet(this._STORAGE_KEY_CUSTOM_URL); }

	async pSetCustomUrl (val) {
		await (!val
			? this._storage.pRemove(this._STORAGE_KEY_CUSTOM_URL)
			: this._storage.pSet(this._STORAGE_KEY_CUSTOM_URL, val));

		if (typeof location !== "undefined") location.reload();
	}

	/* -------------------------------------------- */

	isReloadRequired () { return this._isDirty; }

	doLocationReload ({isRetainHash = false} = {}) {
		if (!isRetainHash) {
			if (typeof Hist !== "undefined") Hist.doPreLocationReload();
			else window.location.hash = "";
		}

		location.reload();
	}

	async pSetReloadMessage (messageInfo) {
		await this._storage.pSet(this._STORAGE_KEY_RELOAD_MESSAGE, messageInfo);
	}

	/* -------------------------------------------- */

	_getBrewMetas () {
		return [
			...(this._storage.syncGet(this._STORAGE_KEY_META) || []),
			...(this._cache_brewsLocal || []).map(brew => this._getBrewDocReduced(brew)),
		];
	}

	_setBrewMetas (val) {
		this._cache_metas = null;
		this._cache_sourceStyles = null;
		return this._storage.syncSet(this._STORAGE_KEY_META, val);
	}

	/** Fetch the brew as though it has been loaded from site URL. */
	async pGetBrewProcessed () {
		if (this._cache_brewsProc) return this._cache_brewsProc; // Short-circuit if the cache is already available

		try {
			const lockToken = await this._LOCK.pLock();
			if (this._cache_brewsProc) return this._cache_brewsProc;
			await this._pGetBrewProcessed_({lockToken});
		} catch (e) {
			setTimeout(() => { throw e; });
			this._cache_brewsProc ||= {};
		} finally {
			this._LOCK.unlock();
		}
		return this._cache_brewsProc;
	}

	async _pGetBrewProcessed_ ({lockToken}) {
		const cpyBrews = MiscUtil.copyFast([
			...await this.pGetBrew({lockToken}),
			...this._brewsTemp,
		]);
		if (!cpyBrews.length) return this._cache_brewsProc = {};

		await this._pGetBrewProcessed_pDoBlocklistExtension({cpyBrews});

		// Add per-file diagnostics
		cpyBrews.forEach(({head, body}) => this._pGetBrewProcessed_mutDiagnostics({head, body}));

		// Merge into single object; apply data migrations
		const cpyBrewsMerged = this._pGetBrewProcessed_getMergedOutput({cpyBrews});

		// Apply "_copy" etc.
		this._cache_brewsProc = await DataUtil.pDoMetaMerge(CryptUtil.uid(), cpyBrewsMerged, {isSkipMetaMergeCache: true});

		return this._cache_brewsProc;
	}

	/** Homebrew files can contain embedded blocklists. */
	async _pGetBrewProcessed_pDoBlocklistExtension ({cpyBrews}) {
		for (const {body} of cpyBrews) {
			if (!body?.blocklist?.length || !(body.blocklist instanceof Array)) continue;
			await ExcludeUtil.pExtendList(body.blocklist);
		}
	}

	_pGetBrewProcessed_mutDiagnostics ({head, body}) {
		if (!head.filename) return;

		for (const arr of Object.values(body)) {
			if (!(arr instanceof Array)) continue;
			for (const ent of arr) {
				if (!("__prop" in ent)) break;
				ent.__diagnostic = {filename: head.filename};
			}
		}
	}

	_pGetBrewProcessed_getMergedOutput ({cpyBrews}) {
		return BrewDoc.mergeObjects(undefined, ...cpyBrews.map(({body}) => body));
	}

	/**
	 * TODO refactor such that this is not necessary
	 * @deprecated
	 */
	getBrewProcessedFromCache (prop) {
		return this._cache_brewsProc?.[prop] || [];
	}

	/* -------------------------------------------- */

	/** Fetch the raw brew from storage. */
	async pGetBrew ({lockToken} = {}) {
		if (this._cache_brews) return this._cache_brews;

		try {
			lockToken = await this._LOCK.pLock({token: lockToken});
			if (this._cache_brews) return this._cache_brews;

			const out = [
				...(await this._pGetBrewRaw({lockToken})),
				...(await this._pGetBrew_pGetLocalBrew({lockToken})),
			];

			return this._cache_brews = out
				// Ensure no brews which lack sources are loaded
				.filter(brew => brew?.body?._meta?.sources?.length);
		} finally {
			this._LOCK.unlock();
		}
	}

	/* -------------------------------------------- */

	async pGetBrewBySource (source, {lockToken} = {}) {
		const brews = await this.pGetBrew({lockToken});
		return brews.find(brew => brew?.body?._meta?.sources?.some(src => src?.json === source));
	}

	/* -------------------------------------------- */

	async _pGetBrew_pGetLocalBrew ({lockToken} = {}) {
		if (this._cache_brewsLocal) return this._cache_brewsLocal;
		if (globalThis.IS_VTT || IS_DEPLOYED || typeof window === "undefined") return this._cache_brewsLocal = [];

		await BrewDocContentMigrator.pInit();

		try {
			await this._LOCK.pLock({token: lockToken});
			if (this._cache_brewsLocal) return this._cache_brewsLocal;
			return (await this._pGetBrew_pGetLocalBrew_());
		} finally {
			this._LOCK.unlock();
		}
	}

	async _pGetBrew_pGetLocalBrew_ () {
		// auto-load from `prerelease/` and `homebrew/`, for custom versions of the site
		const indexLocal = await DataUtil.loadJSON(`${Renderer.get().baseUrl}${this._PATH_LOCAL_INDEX}`);
		if (!indexLocal?.toImport?.length) return this._cache_brewsLocal = [];
		if (indexLocal.bundle) {
			const veBundle = await DataUtil.loadRawJSON(`${Renderer.get().baseUrl}${this._PATH_LOCAL_DIR}/${indexLocal.bundle}`);
			return this._cache_brewsLocal = veBundle.map(({name, json}) => {
				const url = `${Renderer.get().baseUrl}${this._PATH_LOCAL_DIR}/${name}`;
				return this._getBrewDoc({json, url, filename: UrlUtil.getFilename(url), isLocal: true});
			});
		}

		const brewDocs = (await indexLocal.toImport
			.pMap(async name => {
				name = `${name}`.trim();
				const url = /^https?:\/\//.test(name) ? name : `${Renderer.get().baseUrl}${this._PATH_LOCAL_DIR}/${name}`;
				const filename = UrlUtil.getFilename(url);
				try {
					const json = await DataUtil.loadRawJSON(url);
					return this._getBrewDoc({json, url, filename, isLocal: true});
				} catch (e) {
					JqueryUtil.doToast({type: "danger", content: `Failed to load local homebrew from URL "${url}"! ${VeCt.STR_SEE_CONSOLE}`});
					setTimeout(() => { throw e; });
					return null;
				}
			}))
			.filter(Boolean);

		return this._cache_brewsLocal = brewDocs;
	}

	/* -------------------------------------------- */

	async _pGetBrewRaw ({lockToken} = {}) {
		await BrewDocContentMigrator.pInit();

		try {
			await this._LOCK.pLock({token: lockToken});
			return (await this._pGetBrewRaw_());
		} finally {
			this._LOCK.unlock();
		}
	}

	async _pGetBrewRaw_ () {
		const brewRaw = (await this._storage.pGet(this._STORAGE_KEY)) || [];

		// Assume that any potential migration has been completed if the user has new homebrew
		if (brewRaw.length) return brewRaw;

		const {version, existingMeta, existingBrew} = await this._pGetMigrationInfo();

		if (version === this._VERSION) return brewRaw;

		if (!existingMeta || !existingBrew) {
			await this._storage.pSet(this._STORAGE_KEY_MIGRATION_VERSION, this._VERSION);
			return brewRaw;
		}

		// If the user has no new homebrew, and some old homebrew, migrate the old homebrew.
		// Move the existing brew to the editable document--we do this as there is no guarantee that the user has not e.g.
		//   edited the brew they had saved.
		const brewEditable = this._getNewEditableBrewDoc();

		const cpyBrewEditableDoc = BrewDoc.fromObject(brewEditable, {isCopy: true})
			.mutMerge({
				json: {
					_meta: existingMeta || {},
					...existingBrew,
				},
			});

		await this._pSetBrew_({val: [cpyBrewEditableDoc], isInitialMigration: true});

		// Update the version, but do not delete the legacy brew--if the user really wants to get rid of it, they can
		//   clear their storage/etc.
		await this._storage.pSet(this._STORAGE_KEY_MIGRATION_VERSION, this._VERSION);

		JqueryUtil.doToast(`Migrated ${this.DISPLAY_NAME} from version ${version} to version ${this._VERSION}!`);

		return this._storage.pGet(this._STORAGE_KEY);
	}

	_getNewEditableBrewDoc () {
		const json = {_meta: {sources: []}};
		return this._getBrewDoc({json, isEditable: true});
	}

	/* -------------------------------------------- */

	async _pGetMigrationInfo () {
		// If there is no migration support, return default info
		if (!this._STORAGE_KEY_LEGACY && !this._STORAGE_KEY_LEGACY_META) return {version: this._VERSION, existingBrew: null, existingMeta: null};

		const version = await this._storage.pGet(this._STORAGE_KEY_MIGRATION_VERSION);

		// Short-circuit if we know we're already on the right version, to avoid loading old data
		if (version === this._VERSION) return {version};

		const existingBrew = await this._storage.pGet(this._STORAGE_KEY_LEGACY);
		const existingMeta = await this._storage.syncGet(this._STORAGE_KEY_LEGACY_META);

		return {
			version: version ?? 1,
			existingBrew,
			existingMeta,
		};
	}

	/* -------------------------------------------- */

	getCacheIteration () { return this._cache_iteration; }

	/* -------------------------------------------- */

	async pSetBrew (val, {lockToken} = {}) {
		try {
			await this._LOCK.pLock({token: lockToken});
			await this._pSetBrew_({val});
		} finally {
			this._LOCK.unlock();
		}
	}

	async _pSetBrew_ ({val, isInitialMigration}) {
		this._mutBrewsForSet(val);

		if (!isInitialMigration) {
			if (this._cache_brewsProc) this._cache_iteration++;
			this._cache_brews = null;
			this._cache_brewsProc = null;
		}
		await this._storage.pSet(this._STORAGE_KEY, val);

		if (!isInitialMigration) this._isDirty = true;
	}

	_mutBrewsForSet (val) {
		if (!(val instanceof Array)) throw new Error(`${this.DISPLAY_NAME.uppercaseFirst()} array must be an array!`);

		this._setBrewMetas(val.map(brew => this._getBrewDocReduced(brew)));
	}

	/* -------------------------------------------- */

	_getBrewId (brew) {
		if (brew.head.url) return brew.head.url;
		if (brew.body._meta?.sources?.length) return brew.body._meta.sources.map(src => (src.json || "").toLowerCase()).sort(SortUtil.ascSortLower).join(" :: ");
		return null;
	}

	_getNextBrews (brews, brewsToAdd) {
		const idsToAdd = new Set(brewsToAdd.map(brews => this._getBrewId(brews)).filter(Boolean));
		brews = brews.filter(brew => {
			const id = this._getBrewId(brew);
			if (id == null) return true;
			return !idsToAdd.has(id);
		});
		return [...brews, ...brewsToAdd]
			.sort((a, b) => SortUtil.ascSortLower(a.head?.filename || "", b.head?.filename || ""));
	}

	/* -------------------------------------------- */

	async _pLoadParentDependencies ({unavailableSources}) {
		if (!unavailableSources?.length) return false;
		if (!this._parent) return false;

		await Promise.allSettled(unavailableSources.map(async source => {
			const url = await this._parent.pGetSourceUrl(source);
			if (!url) return;
			await this._parent.pAddBrewFromUrl(url, {isLazy: true});
		}));
		await this._parent.pAddBrewsLazyFinalize();

		return false;
	}

	/* -------------------------------------------- */

	async _pGetBrewDependencies ({brewDocs, brewsRaw = null, brewsRawLocal = null, isIgnoreNetworkErrors = false, isLoadReferences = false, lockToken}) {
		try {
			lockToken = await this._LOCK.pLock({token: lockToken});
			return (await this._pGetBrewDependencies_({brewDocs, brewsRaw, brewsRawLocal, isIgnoreNetworkErrors, isLoadReferences, lockToken}));
		} finally {
			this._LOCK.unlock();
		}
	}

	async _pGetBrewDependencies_ ({brewDocs, brewsRaw = null, brewsRawLocal = null, isIgnoreNetworkErrors = false, isLoadReferences = false, lockToken}) {
		const urlRoot = await this.pGetCustomUrl();
		const brewIndex = await this._pGetBrewDependencies_getBrewIndex({urlRoot, isIgnoreNetworkErrors});

		const toLoadSources = [];
		const loadedSources = new Set();

		const unavailableSources = new Set();
		const brewDocsDependencies = [];

		brewsRaw = brewsRaw || await this._pGetBrewRaw({lockToken});
		brewsRawLocal = brewsRawLocal || await this._pGetBrew_pGetLocalBrew({lockToken});

		brewDocs.forEach(brewDoc => this._pGetBrewDependencies_mutAddLoaded({loadedSources, brewDoc}));
		brewsRaw.forEach(brewDoc => this._pGetBrewDependencies_mutAddLoaded({loadedSources, brewDoc}));
		brewsRawLocal.forEach(brewDoc => this._pGetBrewDependencies_mutAddLoaded({loadedSources, brewDoc}));

		brewDocs
			.forEach(brewDoc => {
				const {available, unavailable} = this._getBrewDependencySources({brewDoc, brewIndex, isLoadReferences});
				available.forEach(src => this._pGetBrewDependencies_mutAddToLoad({loadedSources, toLoadSources, src}));
				unavailable.forEach(src => unavailableSources.add(src));
			});

		while (toLoadSources.length) {
			const src = toLoadSources.pop();
			if (loadedSources.has(src)) continue;
			loadedSources.add(src);

			const url = this.getFileUrl(brewIndex[src], urlRoot);
			const brewDocDep = await this._pGetBrewDocFromUrl({url});
			brewDocsDependencies.push(brewDocDep);
			this._pGetBrewDependencies_mutAddLoaded({loadedSources, brewDoc: brewDocDep});

			const {available, unavailable} = this._getBrewDependencySources({brewDoc: brewDocDep, brewIndex, isLoadReferences});
			available.forEach(src => this._pGetBrewDependencies_mutAddToLoad({loadedSources, toLoadSources, src}));
			unavailable.forEach(src => unavailableSources.add(src));
		}

		return {
			brewDocsDependencies,
			unavailableSources: [...unavailableSources].sort(SortUtil.ascSortLower),
		};
	}

	_pGetBrewDependencies_mutAddLoaded ({loadedSources, brewDoc}) {
		(brewDoc.body._meta?.sources || [])
			.filter(src => src.json)
			.forEach(src => loadedSources.add(src.json));
	}

	_pGetBrewDependencies_mutAddToLoad ({loadedSources, toLoadSources, src}) {
		if (loadedSources.has(src) || toLoadSources.includes(src)) return;
		toLoadSources.push(src);
	}

	async _pGetBrewDependencies_getBrewIndex ({urlRoot, isIgnoreNetworkErrors = false}) {
		try {
			return (await this.pGetSourceIndex(urlRoot));
		} catch (e) {
			// Support limited use for e.g. offline file uploads
			if (isIgnoreNetworkErrors) return {};
			throw e;
		}
	}

	async pGetSourceUrl (source) {
		const urlRoot = await this.pGetCustomUrl();
		const brewIndex = await this.pGetSourceIndex(urlRoot);

		if (brewIndex[source]) return this.getFileUrl(brewIndex[source], urlRoot);

		const sourceLower = source.toLowerCase();
		if (brewIndex[sourceLower]) return this.getFileUrl(brewIndex[sourceLower], urlRoot);

		const sourceOriginal = Object.keys(brewIndex).find(k => k.toLowerCase() === sourceLower);
		if (!brewIndex[sourceOriginal]) return null;
		return this.getFileUrl(brewIndex[sourceOriginal], urlRoot);
	}

	/* -------------------------------------------- */

	/** @abstract */
	async pGetSourceIndex (urlRoot) { throw new Error("Unimplemented!"); }
	/** @abstract */
	getFileUrl (path, urlRoot) { throw new Error("Unimplemented!"); }
	/** @abstract */
	async pLoadTimestamps (urlRoot) { throw new Error("Unimplemented!"); }
	/** @abstract */
	async pLoadPropIndex (urlRoot) { throw new Error("Unimplemented!"); }
	/** @abstract */
	async pLoadMetaIndex (urlRoot) { throw new Error("Unimplemented!"); }
	/** @abstract */
	async pLoadAdventureBookIdsIndex (urlRoot) { throw new Error("Unimplemented!"); }

	async pGetCombinedIndexes () {
		const urlRoot = await this.pGetCustomUrl();

		const indexes = await this._pGetCombinedIndexes_pGetIndexes({urlRoot});
		// Tolerate e.g. opening when offline
		if (!indexes) return null;

		const {timestamps, propIndex, metaIndex, sourceIndex} = indexes;

		const pathToMeta = {};
		Object.entries(propIndex)
			.forEach(([prop, pathToDir]) => {
				Object.entries(pathToDir)
					.forEach(([path, dir]) => {
						pathToMeta[path] = pathToMeta[path] || {dir, props: []};
						pathToMeta[path].props.push(prop);
					});
			});

		Object.entries(sourceIndex)
			.forEach(([src, path]) => {
				if (!pathToMeta[path]) return;
				(pathToMeta[path].sources ||= []).push(src);
			});

		return Object.entries(pathToMeta)
			.map(([path, meta]) => {
				const out = {
					urlDownload: this.getFileUrl(path, urlRoot),
					path,
					name: UrlUtil.getFilename(path),
					dirProp: this.getDirProp(meta.dir),
					props: meta.props,
					sources: meta.sources,
				};

				const spl = out.name.trim().replace(/\.json$/, "").split(";").map(it => it.trim());
				if (spl.length > 1) {
					out._brewName = spl[1];
					out._brewAuthor = spl[0];
				} else {
					out._brewName = spl[0];
					out._brewAuthor = this.DEFAULT_AUTHOR;
				}

				out._brewAdded = timestamps[out.path]?.a ?? 0;
				out._brewModified = timestamps[out.path]?.m ?? 0;
				out._brewPublished = timestamps[out.path]?.p ?? 0;
				out._brewInternalSources = metaIndex[out.name]?.n || [];
				out._brewStatus = metaIndex[out.name]?.s || "ready";
				out._brewTranslator = metaIndex[out.name]?.t || "机翻";
				out._brewIsPartnered = !!metaIndex[out.name]?.p;
				out._brewEdition = metaIndex[out.name]?.e === 0 ? SITE_STYLE__CLASSIC : SITE_STYLE__ONE;
				out._brewPropDisplayName = this.getPropDisplayName(out.dirProp);

				return out;
			})
			.sort((a, b) => SortUtil.ascSortLower(a._brewName, b._brewName));
	}

	async _pGetCombinedIndexes_pGetIndexes ({urlRoot}) {
		try {
			const [timestamps, propIndex, metaIndex, sourceIndex] = await Promise.all([
				this.pLoadTimestamps(urlRoot),
				this.pLoadPropIndex(urlRoot),
				this.pLoadMetaIndex(urlRoot),
				this.pGetSourceIndex(urlRoot),
			]);
			return {
				timestamps,
				propIndex,
				metaIndex,
				sourceIndex,
			};
		} catch (e) {
			JqueryUtil.doToast({content: `Failed to load ${this.DISPLAY_NAME} indexes! ${VeCt.STR_SEE_CONSOLE}`, type: "danger"});
			setTimeout(() => { throw e; });
			return null;
		}
	}

	/* -------------------------------------------- */

	_PROPS_DEPS = ["dependencies", "includes"];

	_getBrewDependencySources ({brewDoc, brewIndex, isLoadReferences = false}) {
		const sources = new Set();

		this._PROPS_DEPS.forEach(prop => {
			const obj = brewDoc.body._meta?.[prop];
			if (!obj || !Object.keys(obj).length) return;

			// "All content from <x> source"
			const cpyObj = MiscUtil.copyFast(obj);
			if (cpyObj["*"]) {
				cpyObj["*"]
					.forEach(src => sources.add(src));
				delete cpyObj["*"];
				return;
			}

			// "Content from <dataProperty> from <x> source"
			// Note that current implementation is functionally the same as that of
			//   the `*` property, above, but this is not guaranteed to remain true.
			// Specifying exact data properties is preferred, where possible.
			Object.values(cpyObj)
				.flat()
				.forEach(src => sources.add(src));
		});

		if (isLoadReferences) {
			brewDoc.body._test?.references
				?.forEach(src => sources.add(src));
		}

		const [available, unavailable] = [...sources]
			.segregate(src => brewIndex[src]);

		return {available, unavailable};
	}

	async pAddBrewFromUrl (url, {isLazy, isLoadReferences = false} = {}) {
		let brewDocs = []; let unavailableSources = [];

		try {
			({brewDocs, unavailableSources} = await this._pAddBrewFromUrl({url, isLazy, isLoadReferences}));
		} catch (e) {
			JqueryUtil.doToast({type: "danger", content: `Failed to load ${this.DISPLAY_NAME} from URL "${url}"! ${VeCt.STR_SEE_CONSOLE}`});
			setTimeout(() => { throw e; });
			return [];
		}

		await this._pLoadParentDependencies({unavailableSources});
		return brewDocs;
	}

	async _pGetBrewDocFromUrl ({url}) {
		const json = await DataUtil.loadRawJSON(url);
		return this._getBrewDoc({json, url, filename: UrlUtil.getFilename(url)});
	}

	async _pAddBrewFromUrl ({url, lockToken, isLazy, isLoadReferences}) {
		const brewDoc = await this._pGetBrewDocFromUrl({url});

		if (isLazy) {
			try {
				await this._LOCK.pLock({token: lockToken});
				this._addLazy_brewsTemp.push(brewDoc);
			} finally {
				this._LOCK.unlock();
			}

			return {brewDocs: [brewDoc], unavailableSources: []};
		}

		const brewDocs = [brewDoc]; const unavailableSources = [];
		try {
			lockToken = await this._LOCK.pLock({token: lockToken});
			const brews = MiscUtil.copyFast(await this._pGetBrewRaw({lockToken}));

			const {brewDocsDependencies, unavailableSources: unavailableSources_} = await this._pGetBrewDependencies({brewDocs, brewsRaw: brews, isLoadReferences, lockToken});
			brewDocs.push(...brewDocsDependencies);
			unavailableSources.push(...unavailableSources_);

			const brewsNxt = this._getNextBrews(brews, brewDocs);
			await this.pSetBrew(brewsNxt, {lockToken});
		} finally {
			this._LOCK.unlock();
		}

		return {brewDocs, unavailableSources};
	}

	async pAddBrewsFromFiles (files) {
		if (!files?.length) return;

		let brewDocs = []; let unavailableSources = [];

		try {
			const lockToken = await this._LOCK.pLock();
			({brewDocs, unavailableSources} = await this._pAddBrewsFromFiles({files, lockToken}));
		} catch (e) {
			JqueryUtil.doToast({type: "danger", content: `Failed to load ${this.DISPLAY_NAME} from file(s)! ${VeCt.STR_SEE_CONSOLE}`});
			setTimeout(() => { throw e; });
			return [];
		} finally {
			this._LOCK.unlock();
		}

		await this._pLoadParentDependencies({unavailableSources});
		return brewDocs;
	}

	async _pAddBrewsFromFiles ({files, lockToken}) {
		const brewDocs = files.map(file => this._getBrewDoc({json: file.json, filename: file.name}));

		const brews = MiscUtil.copyFast(await this._pGetBrewRaw({lockToken}));

		const {brewDocsDependencies, unavailableSources} = await this._pGetBrewDependencies({brewDocs, brewsRaw: brews, isIgnoreNetworkErrors: true, lockToken});
		brewDocs.push(...brewDocsDependencies);

		const brewsNxt = this._getNextBrews(brews, brewDocs);
		await this.pSetBrew(brewsNxt, {lockToken});

		return {brewDocs, unavailableSources};
	}

	async pAddBrewsLazyFinalize () {
		let brewDocs = []; let unavailableSources = [];

		try {
			const lockToken = await this._LOCK.pLock();
			({brewDocs, unavailableSources} = await this._pAddBrewsLazyFinalize_({lockToken}));
		} catch (e) {
			JqueryUtil.doToast({type: "danger", content: `Failed to finalize ${this.DISPLAY_NAME_PLURAL}! ${VeCt.STR_SEE_CONSOLE}`});
			setTimeout(() => { throw e; });
			return [];
		} finally {
			this._LOCK.unlock();
		}

		await this._pLoadParentDependencies({unavailableSources});
		return brewDocs;
	}

	async _pAddBrewsLazyFinalize_ ({lockToken}) {
		const brewsTempDeduped = this._addLazy_brewsTemp
			.reduce(
				(accum, brew) => {
					if (accum.checksums[brew.head.checksum]) return accum;
					accum.deduped.push(brew);
					accum.checksums[brew.head.checksum] = true;
					return accum;
				},
				{deduped: [], checksums: {}},
			)
			.deduped;
		const brewsRaw = await this._pGetBrewRaw({lockToken});
		const {brewDocsDependencies, unavailableSources} = await this._pGetBrewDependencies({brewDocs: brewsTempDeduped, brewsRaw, lockToken});
		const brewDocs = MiscUtil.copyFast(brewDocsDependencies);
		const brewsNxt = this._getNextBrews(MiscUtil.copyFast(brewsRaw), [...brewsTempDeduped, ...brewDocsDependencies]);
		await this.pSetBrew(brewsNxt, {lockToken});
		this._addLazy_brewsTemp = [];
		return {brewDocs, unavailableSources};
	}

	async pPullAllBrews ({brews = null} = {}) {
		try {
			const lockToken = await this._LOCK.pLock();
			return (await this._pPullAllBrews_({lockToken, brews}));
		} finally {
			this._LOCK.unlock();
		}
	}

	async _pPullAllBrews_ ({lockToken, brews = null}) {
		const brewDocsUpdated = [];

		const brewsCur = MiscUtil.copyFast(await this._pGetBrewRaw({lockToken}));
		const allowlistDocIdLocals = new Set(
			brews
				? brews.map(brew => brew.head.docIdLocal)
				: brewsCur.map(brew => brew.head.docIdLocal),
		);

		const brewsNxt = await brewsCur
			.pMap(async brew => {
				if (!allowlistDocIdLocals.has(brew.head.docIdLocal)) return brew;

				if (!this.isPullable(brew)) return brew;

				const json = await DataUtil.loadRawJSON(brew.head.url, {isBustCache: true});

				const localLastModified = brew.body._meta?.dateLastModified ?? 0;
				const sourceLastModified = json._meta?.dateLastModified ?? 0;

				if (sourceLastModified <= localLastModified) return brew;

				const brewDoc = BrewDoc.fromObject(brew).mutUpdate({json});
				brewDocsUpdated.push(brewDoc);
				return brewDoc.toObject();
			});

		if (!brewDocsUpdated.length) return brewDocsUpdated;

		await this.pSetBrew(brewsNxt, {lockToken});
		return brewDocsUpdated;
	}

	isPullable (brew) { return !brew.head.isEditable && !!brew.head.url; }

	async pPullBrew (brew) {
		try {
			const lockToken = await this._LOCK.pLock();
			return (await this._pPullBrew_({brew, lockToken}));
		} finally {
			this._LOCK.unlock();
		}
	}

	async _pPullBrew_ ({brew, lockToken}) {
		const brews = await this._pGetBrewRaw({lockToken});
		if (!brews?.length) return;

		let isPull = false;
		const brewsNxt = await brews.pMap(async it => {
			if (it.head.docIdLocal !== brew.head.docIdLocal || !this.isPullable(it)) return it;

			const json = await DataUtil.loadRawJSON(it.head.url, {isBustCache: true});

			const localLastModified = it.body._meta?.dateLastModified ?? 0;
			const sourceLastModified = json._meta?.dateLastModified ?? 0;

			if (sourceLastModified <= localLastModified) return it;

			isPull = true;
			return BrewDoc.fromObject(it).mutUpdate({json}).toObject();
		});

		if (!isPull) return isPull;

		await this.pSetBrew(brewsNxt, {lockToken});
		return isPull;
	}

	async pAddBrewFromLoaderTag (ele) {
		ele = veE(ele);
		if (!ele.vee.hasClass("ve-rd__wrp-loadbrew--ready")) return; // an existing click is being handled
		let jsonPath = ele.vee.attr("data-rd-loader-path");
		const name = ele.vee.attr("data-rd-loader-name");
		const cached = ele.vee.html();
		const cachedTitle = ele.vee.tooltip();
		ele.vee.tooltip("");
		ele.vee.removeClass("ve-rd__wrp-loadbrew--ready").vee.html(`${name.qq()}<span class="glyphicon glyphicon-refresh ve-rd__loadbrew-icon ve-rd__loadbrew-icon--active"></span>`);

		jsonPath = jsonPath.unescapeQuotes();
		if (!UrlUtil.isFullUrl(jsonPath)) {
			const brewUrl = await this.pGetCustomUrl();
			jsonPath = this.getFileUrl(jsonPath, brewUrl);
		}

		await this.pAddBrewFromUrl(jsonPath);
		ele.vee.html(`${name.qq()}<span class="glyphicon glyphicon-saved ve-rd__loadbrew-icon"></span>`);
		setTimeout(() => ele.vee.html(cached).vee.addClass("ve-rd__wrp-loadbrew--ready").vee.tooltip(cachedTitle), 500);
	}

	_isMatchingCombinedIndexInfo (info) {
		return info._brewIsPartnered;
	}

	async pGetCntBrewsPartnered () {
		const combinedIndexes = await this.pGetCombinedIndexes();
		if (!combinedIndexes) return 0;
		return combinedIndexes.filter(it => this._isMatchingCombinedIndexInfo(it)).length;
	}

	async pAddBrewsPartnered ({isSilent = false} = {}) {
		const combinedIndexes = await this.pGetCombinedIndexes();
		if (!combinedIndexes) return [];

		const brewInfos = combinedIndexes.filter(it => this._isMatchingCombinedIndexInfo(it));
		if (!brewInfos.length) {
			if (!isSilent) JqueryUtil.doToast({type: "warning", content: `Did not find any partnered ${this.DISPLAY_NAME} to load!`});
			return [];
		}

		if (!isSilent) JqueryUtil.doToast(`Found ${brewInfos.length} partnered ${brewInfos.length === 1 ? this.DISPLAY_NAME : this.DISPLAY_NAME_PLURAL}; loading...`);

		await brewInfos
			.pMap(brewInfo => this.pAddBrewFromUrl(brewInfo.urlDownload, {isLazy: true}));

		const brewDocsAdded = await this.pAddBrewsLazyFinalize();

		if (!isSilent) {
			const numAdded = brewInfos.length + brewDocsAdded.length;

			if (numAdded) JqueryUtil.doToast(`Loaded ${numAdded} partnered ${numAdded === 1 ? this.DISPLAY_NAME : this.DISPLAY_NAME_PLURAL}!`);
			else JqueryUtil.doToast({type: "warning", content: `Did not load any partnered ${this.DISPLAY_NAME}!`});
		}

		return brewDocsAdded;
	}

	/**
	 * Permit files which only contain an exported blocklist, by providing them with a randomly-generated source.
	 */
	static _mutEnsureBlocklistSource ({json, filename}) {
		if (!json || json._meta?.sources != null) return;
		if (!json.blocklist || !(json.blocklist instanceof Array)) return;
		if (Object.entries(json).some(([prop, val]) => prop !== "blocklist" && val instanceof Array)) return;

		(json._meta ||= {}).sources = [
			{
				json: CryptUtil.uid(),
				abbreviation: "BLOCK",
				full: `Content Blocklist`,
			},
		];
	}

	_getBrewDoc ({json, url = null, filename = null, isLocal = false, isEditable = false}) {
		this.constructor._mutEnsureBlocklistSource({json, filename});

		return BrewDoc.fromValues({
			head: {
				json,
				url,
				filename,
				isLocal,
				isEditable,
			},
			body: json,
		}).toObject();
	}

	_getBrewDocReduced (brewDoc) { return {docIdLocal: brewDoc.head.docIdLocal, _meta: brewDoc.body._meta}; }

	async pDeleteBrews (brews) {
		try {
			const lockToken = await this._LOCK.pLock();
			await this._pDeleteBrews_({brews, lockToken});
		} finally {
			this._LOCK.unlock();
		}
	}

	async _pDeleteBrews_ ({brews, lockToken}) {
		const brewsStored = await this._pGetBrewRaw({lockToken});
		if (!brewsStored?.length) return;

		const idsToDelete = new Set(brews.map(brew => brew.head.docIdLocal));

		const nxtBrews = brewsStored.filter(brew => !idsToDelete.has(brew.head.docIdLocal));
		await this.pSetBrew(nxtBrews, {lockToken});
	}

	async pDeleteUneditableBrews () {
		try {
			const lockToken = await this._LOCK.pLock();
			await this._pDeleteUneditableBrews_({lockToken});
		} finally {
			this._LOCK.unlock();
		}
	}

	async _pDeleteUneditableBrews_ ({lockToken}) {
		const brewsStored = await this._pGetBrewRaw({lockToken});
		if (!brewsStored?.length) return;

		const nxtBrews = brewsStored.filter(brew => brew.head.isEditable);
		await this.pSetBrew(nxtBrews, {lockToken});
	}

	async pUpdateBrew (brew) {
		try {
			const lockToken = await this._LOCK.pLock();
			await this._pUpdateBrew_({brew, lockToken});
		} finally {
			this._LOCK.unlock();
		}
	}

	async _pUpdateBrew_ ({brew, lockToken}) {
		const brews = await this._pGetBrewRaw({lockToken});
		if (!brews?.length) return;

		const nxtBrews = brews.map(it => it.head.docIdLocal !== brew.head.docIdLocal ? it : brew);
		await this.pSetBrew(nxtBrews, {lockToken});
	}

	// region Editable
	/** @abstract */
	pGetEditableBrewDoc (brew) { throw new Error("Unimplemented"); }
	/** @abstract */
	pGetOrCreateEditableBrewDoc () { throw new Error("Unimplemented"); }
	/** @abstract */
	pSetEditableBrewDoc () { throw new Error("Unimplemented"); }
	/** @abstract */
	pGetEditableBrewEntity (prop, uniqueId, {isDuplicate = false} = {}) { throw new Error("Unimplemented"); }
	/** @abstract */
	pPersistEditableBrewEntity (prop, ent) { throw new Error("Unimplemented"); }
	/** @abstract */
	pRemoveEditableBrewEntity (prop, uniqueId) { throw new Error("Unimplemented"); }
	/** @abstract */
	pAddSource (sourceObj) { throw new Error("Unimplemented"); }
	/** @abstract */
	pEditSource (sourceObj) { throw new Error("Unimplemented"); }
	/** @abstract */
	pIsEditableSourceJson (sourceJson) { throw new Error("Unimplemented"); }
	/** @abstract */
	pMoveOrCopyToEditableBySourceJson (sourceJson) { throw new Error("Unimplemented"); }
	/** @abstract */
	pMoveToEditable ({brews}) { throw new Error("Unimplemented"); }
	/** @abstract */
	pCopyToEditable ({brews}) { throw new Error("Unimplemented"); }
	/** @abstract */
	pHasEditableSourceJson () { throw new Error("Unimplemented"); }
	// endregion

	// region Rendering/etc.
	_PAGE_TO_PROPS__SPELLS = [...UrlUtil.PAGE_TO_PROPS[UrlUtil.PG_SPELLS], "spellFluff"];
	_PAGE_TO_PROPS__BESTIARY = ["monster", "legendaryGroup", "monsterFluff", "encounterShape"];

	_PAGE_TO_PROPS = {
		[UrlUtil.PG_SPELLS]: this._PAGE_TO_PROPS__SPELLS,
		[UrlUtil.PG_CLASSES]: ["class", "subclass", "classFeature", "subclassFeature"],
		[UrlUtil.PG_BESTIARY]: this._PAGE_TO_PROPS__BESTIARY,
		[UrlUtil.PG_BACKGROUNDS]: ["background"],
		[UrlUtil.PG_FEATS]: ["feat"],
		[UrlUtil.PG_OPT_FEATURES]: ["optionalfeature"],
		[UrlUtil.PG_RACES]: [...UrlUtil.PAGE_TO_PROPS[UrlUtil.PG_RACES], "raceFluff"],
		[UrlUtil.PG_OBJECTS]: ["object"],
		[UrlUtil.PG_TRAPS_HAZARDS]: ["trap", "hazard"],
		[UrlUtil.PG_DEITIES]: ["deity"],
		[UrlUtil.PG_ITEMS]: [...UrlUtil.PAGE_TO_PROPS[UrlUtil.PG_ITEMS], "itemFluff"],
		[UrlUtil.PG_REWARDS]: ["reward"],
		[UrlUtil.PG_PSIONICS]: ["psionic"],
		[UrlUtil.PG_VARIANTRULES]: ["variantrule"],
		[UrlUtil.PG_CONDITIONS_DISEASES]: ["condition", "disease", "status"],
		[UrlUtil.PG_ADVENTURES]: ["adventure", "adventureData"],
		[UrlUtil.PG_BOOKS]: ["book", "bookData"],
		[UrlUtil.PG_TABLES]: ["table", "tableGroup"],
		[UrlUtil.PG_MAKE_BREW]: [
			...this._PAGE_TO_PROPS__SPELLS,
			...this._PAGE_TO_PROPS__BESTIARY,
			"makebrewCreatureTrait",
		],
		[UrlUtil.PG_MANAGE_BREW]: ["*"],
		[UrlUtil.PG_MANAGE_PRERELEASE]: ["*"],
		[UrlUtil.PG_DEMO_RENDER]: ["*"],
		[UrlUtil.PG_VEHICLES]: ["vehicle", "vehicleUpgrade"],
		[UrlUtil.PG_ACTIONS]: ["action"],
		[UrlUtil.PG_CULTS_BOONS]: ["cult", "boon"],
		[UrlUtil.PG_LANGUAGES]: ["language", "languageScript"],
		[UrlUtil.PG_CHAR_CREATION_OPTIONS]: ["charoption"],
		[UrlUtil.PG_RECIPES]: ["recipe"],
		[UrlUtil.PG_CLASS_SUBCLASS_FEATURES]: ["classFeature", "subclassFeature"],
		[UrlUtil.PG_DECKS]: ["card", "deck"],
		[UrlUtil.PG_BASTIONS]: ["facility", "facilityFluff"],
		[UrlUtil.PG_HOMECRAFTS]: ["crochetPattern", "crochetPatternFluff"],
	};

	getPageProps ({page, isStrict = false, fallback = null} = {}) {
		page = this._getBrewPage(page);

		const out = this._PAGE_TO_PROPS[page];
		if (out) return out;
		if (fallback) return fallback;

		if (isStrict) throw new Error(`No ${this.DISPLAY_NAME} properties defined for category ${page}`);

		return null;
	}

	getPropPages () {
		return Object.entries(this._PAGE_TO_PROPS)
			.map(([page, props]) => [page, props.filter(it => it !== "*")])
			.filter(([, props]) => props.length)
			.map(([page]) => page);
	}

	_getBrewPage (page) {
		return page || (globalThis.IS_VTT ? this.PAGE_MANAGE : UrlUtil.getCurrentPage());
	}

	getDirProp (dir) {
		switch (dir) {
			case "creature": return "monster";
			case "makebrew": return "makebrewCreatureTrait";
			case "encounterbuilder": return "encounterShape";
			case "crochetpattern": return "crochetPattern";
		}
		return dir;
	}

	getPropDisplayName (prop) {
		switch (prop) {
			case "collection": return "合集";
			case "adventure": return "冒险模组/描述";
			case "book": return "书籍/描述";
		}
		return Parser.getPropDisplayName(prop);
	}
	// endregion

	// region Sources
	_initSync () {
		this._doCacheMetas();
		this._doPopulateStyles();
	}

	_doCacheMetas () {
		if (this._cache_metas) return;

		this._cache_metas = {};

		(this._getBrewMetas() || [])
			.forEach(({_meta}) => {
				Object.entries(_meta || {})
					.forEach(([prop, val]) => {
						if (!val) return;
						if (typeof val !== "object") return;

						if (val instanceof Array) {
							(this._cache_metas[prop] = this._cache_metas[prop] || []).push(...MiscUtil.copyFast(val));
							return;
						}

						this._cache_metas[prop] = this._cache_metas[prop] || {};
						Object.assign(this._cache_metas[prop], MiscUtil.copyFast(val));
					});
			});

		// Add a special "_sources" cache, which is a lookup-friendly object (rather than "sources", which is an array)
		this._cache_metas["_sources"] = (this._getBrewMetas() || [])
			.mergeMap(({_meta}) => {
				return (_meta?.sources || [])
					.mergeMap(src => ({[(src.json || "").toLowerCase()]: {...MiscUtil.copyFast(src), edition: _meta.edition || SITE_STYLE__CLASSIC}}));
			});
	}

	_doPopulateStyles () {
		if (this._cache_sourceStyles) return;

		this._cache_sourceStyles = true;

		if (typeof window === "undefined") return;

		if (!this._eleStyle) {
			this._eleStyle = document.createElement("style");
			this._eleStyle.setAttribute("name", `styles-vet-${this._PATH_LOCAL_DIR}`);
			document.head.appendChild(this._eleStyle);
		}

		const stack = [""];

		Object.entries(this._cache_metas["_sources"])
			.forEach(([source, meta]) => {
				const color = this._sourceJsonToColor({source});
				const colorNight = this._sourceJsonToColor({source, isNight: true});

				if (!color && !colorNight) return;
				const sourceClassname = Parser.sourceJsonToSourceClassname(source, {sourceJson: meta.json});

				if (color) {
					stack[0] += `.${sourceClassname} {
	color: #${color} !important;
	border-color: #${color} !important;
	text-decoration-color: #${color} !important
}
`;
				}

				if (colorNight) {
					stack[0] += `.ve-night-mode .${sourceClassname} {
	color: #${colorNight} !important;
	border-color: #${colorNight} !important;
	text-decoration-color: #${colorNight} !important
}
`;
				}
			});

		this._eleStyle.innerHTML = stack[0];
	}

	_sourceJsonToColor ({source, isNight = false} = {}) {
		if (!source) return "";
		source = source.toLowerCase();
		const prop = isNight ? "colorNight" : "color";
		if (!this._cache_metas["_sources"][source]?.[prop]) return "";
		return BrewUtilShared.getValidColor(this._cache_metas["_sources"][source][prop]);
	}

	getPopoutStyleElementHtml () {
		if (!this._eleStyle) return "";
		return this._eleStyle.outerHTML;
	}

	hasSourceJson (source) {
		if (!source) return false;
		source = source.toLowerCase();
		return !!this.getMetaLookup("_sources")[source];
	}

	sourceJsonToFull (source) {
		if (!source) return "";
		source = source.toLowerCase();
		return this.getMetaLookup("_sources")[source]?.full || source;
	}

	sourceJsonToAbv (source) {
		if (!source) return "";
		source = source.toLowerCase();
		return this.getMetaLookup("_sources")[source]?.abbreviation || source;
	}

	sourceJsonToDate (source) {
		if (!source) return "";
		source = source.toLowerCase();
		return this.getMetaLookup("_sources")[source]?.dateReleased || "1970-01-01";
	}

	sourceJsonToSource (source) {
		if (!source) return null;
		source = source.toLowerCase();
		return this.getMetaLookup("_sources")[source];
	}

	isClassicSource (source) {
		if (!source) return "";
		source = source.toLowerCase();
		return this.getMetaLookup("_sources")[source]?.edition === SITE_STYLE__CLASSIC;
	}

	getSources () {
		this._initSync();
		return Object.values(this._cache_metas["_sources"]);
	}
	// endregion

	// region Other meta
	getMetaLookup (type) {
		if (!type) return null;
		this._initSync();
		return this._cache_metas[type];
	}
	// endregion

	/**
	 * Merge together a loaded JSON (or loaded-JSON-like) object and a processed homebrew object.
	 * @param data
	 * @param homebrew
	 */
	getMergedData (data, homebrew) {
		const out = {};
		Object.entries(data)
			.forEach(([prop, val]) => {
				if (!homebrew[prop]) {
					out[prop] = [...val];
					return;
				}

				if (!(homebrew[prop] instanceof Array)) throw new Error(`${this.DISPLAY_NAME.uppercaseFirst()} was not array!`);
				if (!(val instanceof Array)) throw new Error(`Data was not array!`);
				out[prop] = [...val, ...homebrew[prop]];
			});

		return out;
	}

	// region Search
	/**
	 * Get data in a format similar to the main search index
	 */
	async pGetSearchIndex ({id = 0, isDecompress = true, isIncludeExtendedSourceInfo = false, isSkipNonPartnered = false} = {}) {
		const indexer = new Omnidexer(id);

		const brew = await this.pGetBrewProcessed();

		// Run these in serial, to prevent any ID race condition antics
		await [...Omnidexer.TO_INDEX__FROM_INDEX_JSON, ...Omnidexer.TO_INDEX]
			.pSerialAwaitMap(async arbiter => {
				if (arbiter.isSkipBrew) return;

				if (
					!Object.keys(brew).some(prop => arbiter.hasBrewProp(prop))
					&& !brew[arbiter.listProp]?.length
				) return;

				if (arbiter.pFnPreProcBrew) {
					const toProc = await arbiter.pFnPreProcBrew.bind(arbiter)(brew);
					await indexer.pAddToIndex(arbiter, toProc, {isIncludeExtendedSourceInfo, isSkipNonPartnered});
					return;
				}

				await indexer.pAddToIndex(arbiter, brew, {isIncludeExtendedSourceInfo, isSkipNonPartnered});
			});

		const index = indexer.getIndex();
		if (!isDecompress) return index;

		return Omnidexer.decompressIndex(index);
	}

	async pGetAdditionalSearchIndices (highestId, addiProp) {
		const indexer = new Omnidexer(highestId + 1);

		const brew = await this.pGetBrewProcessed();

		await [...Omnidexer.TO_INDEX__FROM_INDEX_JSON, ...Omnidexer.TO_INDEX]
			.filter(it => it.additionalIndexes && (brew[it.listProp] || []).length)
			.pMap(it => {
				Object.entries(it.additionalIndexes)
					.filter(([prop]) => prop === addiProp)
					.pMap(async ([, pGetIndex]) => {
						const toIndex = await pGetIndex(indexer, {[it.listProp]: brew[it.listProp]});
						toIndex.forEach(add => indexer.pushToIndex(add));
					});
			});

		return Omnidexer.decompressIndex(indexer.getIndex());
	}

	async pGetAlternateSearchIndices (highestId, altProp) {
		const indexer = new Omnidexer(highestId + 1);

		const brew = await this.pGetBrewProcessed();

		await [...Omnidexer.TO_INDEX__FROM_INDEX_JSON, ...Omnidexer.TO_INDEX]
			.filter(ti => ti.alternateIndexes && (brew[ti.listProp] || []).length)
			.pSerialAwaitMap(async arbiter => {
				await Object.keys(arbiter.alternateIndexes)
					.filter(prop => prop === altProp)
					.pSerialAwaitMap(async prop => {
						await indexer.pAddToIndex(arbiter, brew, {alt: arbiter.alternateIndexes[prop]});
					});
			});

		return Omnidexer.decompressIndex(indexer.getIndex());
	}
	// endregion

	// region Export to URL
	async pGetUrlExportableSources () {
		const brews = await this._pGetBrewRaw();
		const brewsExportable = brews
			.filter(brew => !brew.head.isEditable && !brew.head.isLocal);
		return brewsExportable.flatMap(brew => (brew.body._meta?.sources || []).map(src => src.json)).unique();
	}
	// endregion
}

/js/utils-brew/utils-brew-content-migrat:
export class BrewDocContentMigrator {
	static _IS_INIT = false;

	static async pInit () {
		if (this._IS_INIT) return;
		await Renderer.redirect.pInit();
		this._IS_INIT = true;
	}

	/* ----- */

	static mutMakeCompatible (json) {
		if (!this._IS_INIT) throw new Error(`Homebrew migrator was not initialized!`);

		this._mutMakeCompatible_item(json);
		this._mutMakeCompatible_race(json);
		this._mutMakeCompatible_monster(json);
		this._mutMakeCompatible_trap(json);
		this._mutMakeCompatible_object(json);
		this._mutMakeCompatible_subclass(json);
		this._mutMakeCompatible_class_classSpells(json);
		this._mutMakeCompatible_subclass_subclassSpells(json);
		this._mutMakeCompatible_spell(json);
	}

	/* ----- */

	static _mutMakeCompatible_item (json) {
		if (!json.variant) return false;

		// 2022-07-09
		json.magicvariant = json.variant;
		delete json.variant;
	}

	/* ----- */

	static _mutMakeCompatible_race (json) {
		if (!json.subrace) return false;

		json.subrace.forEach(sr => {
			if (!sr.race) return;
			sr.raceName = sr.race.name;
			sr.raceSource = sr.race.source || sr.source || Parser.SRC_PHB;
		});
	}

	/* ----- */

	static _mutMakeCompatible_monster (json) {
		if (!json.monster) return false;

		json.monster.forEach(mon => {
			// 2022-03-22
			if (typeof mon.size === "string") mon.size = [mon.size];

			// 2022-05-29
			if (mon.summonedBySpell && !mon.summonedBySpellLevel) mon.summonedBySpellLevel = 1;
		});
	}

	/* ----- */

	static _mutMakeCompatible_trap (json) {
		if (!json.trap) return false;

		json.trap.forEach(ent => {
			// 2024-11-13
			if (ent.rating) return;

			if (!ent.tier && !ent.level && !ent.threat) return;

			ent.rating = [
				{
					tier: ent.tier,
					level: ent.level,
					threat: ent.threat,
				},
			];
			delete ent.tier;
			delete ent.level;
			delete ent.threat;
		});
	}

	/* ----- */

	static _mutMakeCompatible_object (json) {
		if (!json.object) return false;

		json.object.forEach(obj => {
			// 2023-10-07
			if (typeof obj.size === "string") obj.size = [obj.size];
		});
	}

	/* ----- */

	static _mutMakeCompatible_subclass (json) {
		this._mutMakeCompatible_subclass_oneSubclassCopies(json);
	}

	static _PROPS_SUBCLASS_MAINTAIN = ["name", "source", "shortName", "className"];
	static _PROPS_SUBCLASS_COPY = [...this._PROPS_SUBCLASS_MAINTAIN, "classSource"];

	static _PROPS_SUBCLASS_FEATURE_MAINTAIN = ["name", "className", "source", "subclassShortName", "subclassSource"];
	static _PROPS_SUBCLASS_FEATURE_COPY = [...this._PROPS_SUBCLASS_FEATURE_MAINTAIN, "level", "classSource"];

	static _MIN_SUBCLASS_FEATURE_LEVEL = 3; // 2024+ classes all gain initial subclass features at level 3

	static _isOneToCopySubclass (sc) {
		if (sc.source !== Parser.SRC_XPHB && sc.classSource === Parser.SRC_PHB) return true;
		if (sc.className === "Artificer" && sc.source !== Parser.SRC_EFA && sc.classSource === Parser.SRC_TCE) return true;
		return false;
	}

	/**
	 * @since 2024-09-20
	 * Copy subclasses (and subclass features, if they are below level 3) from reprinted 2014-era classes to
	 *   their 2024-era counterparts
	 *
	 * @see 5ET-BUG-176 -- if subclass features below level 3, then `subclassFeature` `_copy` generated, which
	 * breaks if referenced `subclassFeature` is missing in the brew.
	 */
	static _mutMakeCompatible_subclass_oneSubclassCopies (json) {
		const hasCopies = (json.subclass || []).some(sc => this._isOneToCopySubclass(sc));
		if (!hasCopies) return false;

		const internalCopies = MiscUtil.getOrSet(json, "_meta", "internalCopies", []);
		if (!internalCopies.includes("subclass")) internalCopies.push("subclass");

		const outSubclasses = [];
		const outSubclassFeatures = [];
		const depsSubclass = new Set();

		json.subclass
			.filter(sc => this._isOneToCopySubclass(sc))
			.forEach(sc => {
				const classSource = sc.className === "Artificer" ? Parser.SRC_EFA : Parser.SRC_XPHB;
				const scNxt = {
					classSource,
				};
				this._PROPS_SUBCLASS_MAINTAIN.forEach(prop => scNxt[prop] = MiscUtil.copyFast(sc[prop]));
				scNxt._copy = {
					...Object.fromEntries(
						this._PROPS_SUBCLASS_COPY
							.map(prop => [prop, MiscUtil.copyFast(sc[prop])]),
					),
					"_preserve": {
						"page": true,
						"otherSources": true,
						"referenceSources": true,
						"srd": true,
						"basicRules": true,
						"reprintedAs": true,
					},
				};

				if (sc.hasFluff || sc.hasFluffImages) {
					scNxt.fluff = {
						_subclassFluff: Object.fromEntries(
							this._PROPS_SUBCLASS_COPY
								.map(prop => [prop, MiscUtil.copyFast(sc[prop])]),
						),
					};
				}

				const fauxScHash = UrlUtil.URL_TO_HASH_BUILDER["subclass"](scNxt);
				const scExisting = json.subclass.find(sc => UrlUtil.URL_TO_HASH_BUILDER["subclass"](sc) === fauxScHash);

				// If the brew already defines a version of the subclass for the 2024-era class, avoid making one
				if (scExisting) return;

				// `.subclassFeatures` may not exist for e.g. "_copy" subclasses; always "_copy" these
				const [scfRefsLowLevel, scfRefsOther] = (sc.subclassFeatures || [])
					.segregate(scfRef => {
						const uid = scfRef.subclassFeature || scfRef;
						const unpacked = DataUtil.class.unpackUidSubclassFeature(uid, {isLower: true});
						return unpacked.level < this._MIN_SUBCLASS_FEATURE_LEVEL && unpacked.classSource !== VeCt.STR_GENERIC.toLowerCase();
					});

				outSubclasses.push(scNxt);

				if (!scfRefsLowLevel.length) return;

				scNxt.subclassFeatures = [
					...scfRefsLowLevel
						.map(scfRef => {
							const uid = scfRef.subclassFeature || scfRef;
							const unpacked = DataUtil.class.unpackUidSubclassFeature(uid);

							// When copying a site subclass feature re-used in a homebrew subclass,
							//   include the site class as a dependency.
							// Note that we do not do this for e.g. homebrew depending on homebrew,
							//   as we assume the brew already defines this relationship.
							const sourceJson = Parser.sourceJsonToJson(unpacked.source);
							if (SourceUtil.isSiteSource(sourceJson)) {
								depsSubclass.add(unpacked.className.toLowerCase());
							}

							const scfNxt = {
								classSource,
								level: this._MIN_SUBCLASS_FEATURE_LEVEL,
							};
							this._PROPS_SUBCLASS_FEATURE_MAINTAIN.forEach(prop => scfNxt[prop] = MiscUtil.copyFast(unpacked[prop]));
							scfNxt._copy = {
								...Object.fromEntries(
									this._PROPS_SUBCLASS_FEATURE_COPY
										.map(prop => [prop, MiscUtil.copyFast(unpacked[prop])]),
								),
								"_preserve": {
									"page": true,
								},
							};

							outSubclassFeatures.push(scfNxt);

							const uidNxt = DataUtil.class.packUidSubclassFeature(scfNxt);
							if (scfRef.subclassFeature) {
								return {
									...MiscUtil.copy(scfRef),
									subclassFeature: uidNxt,
								};
							}
							return uidNxt;
						}),
					...scfRefsOther,
				];
			});

		if (outSubclasses.length) json.subclass.push(...outSubclasses);
		if (outSubclassFeatures.length) (json.subclassFeature ||= []).push(...outSubclassFeatures);

		if (outSubclassFeatures.length && !internalCopies.includes("subclassFeature")) internalCopies.push("subclassFeature");

		if (depsSubclass.size) {
			const tgt = MiscUtil.getOrSet(json, "_meta", "dependencies", "subclass", []);
			depsSubclass.forEach(dep => {
				if (!tgt.includes(dep)) tgt.push(dep);
			});
		}

		return true;
	}

	/* ----- */

	static _mutMakeCompatible_classSubclassSpells_getMigrated (arr) {
		return arr
			.filter(uid => typeof uid === "string")
			.map(it => it.trim())
			.filter(Boolean)
			.map(uid => {
				const redirect = Renderer.redirect.getRedirectByUid("spell", uid);
				if (!redirect) return null;
				return DataUtil.proxy.getUid("spell", redirect);
			})
			.filter(Boolean);
	}

	/**
	 * @since 2024-11-28
	 * As a temporary measure, for classes which have `classSpells`, make XPHB copies of PHB spell entries.
	 * @deprecated TODO(Future) remove/rework when moving to a better solution for homebrew spell sources
	 */
	static _mutMakeCompatible_class_classSpells (json) {
		if (!json.class) return false;

		json.class
			.forEach(cls => {
				if (!cls.classSpells) return;
				cls.classSpells = [...cls.classSpells, ...this._mutMakeCompatible_classSubclassSpells_getMigrated(cls.classSpells)];
			});
	}

	/**
	 * @since 2024-11-28
	 * As a temporary measure, for subclasses which have `subclassSpells`, make XPHB copies of PHB spell entries.
	 * @deprecated TODO(Future) remove/rework when moving to a better solution for homebrew spell sources
	 */
	static _mutMakeCompatible_subclass_subclassSpells (json) {
		if (!json.subclass) return false;

		json.subclass
			.forEach(sc => {
				if (sc.subclassSpells) sc.subclassSpells = [...sc.subclassSpells, ...this._mutMakeCompatible_classSubclassSpells_getMigrated(sc.subclassSpells)];

				if (sc.subSubclassSpells) {
					Object.entries(sc.subSubclassSpells)
						.forEach(([k, arr]) => {
							sc.subSubclassSpells[k] = [...arr, ...this._mutMakeCompatible_classSubclassSpells_getMigrated(arr)];
						});
				}
			});
	}

	/* ----- */

	/**
	 * @since 2024-10-06
	 * As a temporary measure, for spells which have `classes.fromClassList`, make XPHB copies of PHB class entries.
	 * @deprecated TODO(Future) remove/rework when moving to a better solution for homebrew spell sources
	 */
	static _mutMakeCompatible_spell (json) {
		if (!json.spell) return false;

		this._mutMakeCompatible_spell_classProp({json, prop: "fromClassList"});
		this._mutMakeCompatible_spell_classProp({json, prop: "fromClassListVariant"});
	}

	static _mutMakeCompatible_spell_classProp ({json, prop}) {
		json.spell
			.forEach(ent => {
				if (!ent?.classes?.[prop]?.length) return;

				const phbNames = {};
				const tceNames = {};
				const xphbNames = {};
				const efaNames = {};

				ent.classes[prop]
					.forEach(classMeta => {
						if (classMeta.source === Parser.SRC_PHB) phbNames[classMeta.name] = classMeta;
						if (classMeta.name === "Artificer" && classMeta.source === Parser.SRC_TCE) tceNames[classMeta.name] = classMeta;

						if (classMeta.source === Parser.SRC_XPHB) xphbNames[classMeta.name] = true;
						if (classMeta.name === "Artificer" && classMeta.source === Parser.SRC_EFA) efaNames[classMeta.name] = true;
					});

				Object.keys(xphbNames).forEach(name => delete phbNames[name]);
				Object.keys(efaNames).forEach(name => delete tceNames[name]);

				Object.values(phbNames)
					.forEach(classMeta => ent.classes[prop].push({...classMeta, source: Parser.SRC_XPHB}));
				Object.values(tceNames)
					.forEach(classMeta => ent.classes[prop].push({...classMeta, source: Parser.SRC_EFA}));
			});
	}
}

