import {EVNT_VALCHANGE} from "../filter/filter-constants.js";

export class GetBrewUi {
	static _RenderState = class {
		constructor () {
			this.pageFilter = null;
			this.list = null;
			this.listSelectClickHandler = null;
			this.previewButtonHandler = null;
			this.cbAll = null;
			this.btnTogglePreviewAll = null;
		}
	};

	static _TypeFilter = class extends Filter {
		constructor ({brewUtil}) {
			const pageProps = brewUtil.getPageProps({fallback: ["*"]});
			super({
				header: "Category",
				cnHeader: "类别",
				items: [],
				displayFn: brewUtil.getPropDisplayName.bind(brewUtil),
				selFn: prop => pageProps.includes("*") || pageProps.includes(prop),
				isSortByDisplayItems: true,
			});
			this._brewUtil = brewUtil;
		}

		_getHeaderControls_addExtraStateBtns (opts, wrpStateBtnsOuter) {
			const menu = ContextUtil.getMenu(
				this._brewUtil.getPropPages()
					.map(page => ({page, displayPage: UrlUtil.pageToDisplayPage(page)}))
					.sort(SortUtil.ascSortProp.bind(SortUtil, "displayPage"))
					.map(({page, displayPage}) => {
						return new ContextUtil.Action(
							displayPage,
							() => {
								const propsActive = new Set(this._brewUtil.getPageProps({page, fallback: []}));
								Object.keys(this._state).forEach(prop => this._state[prop] = propsActive.has(prop) ? 1 : 0);
							},
						);
					}),
			);

			const btnPage = veE({
				tag: "button",
				clazz: `ve-btn ve-btn-default ve-w-100 ve-btn-xs`,
				txt: `根据页面筛选...`,
				click: evt => ContextUtil.pOpenMenu(evt, menu),
			});

			veE({
				tag: "div",
				clazz: `ve-btn-group ve-mr-2 ve-w-100 ve-flex-v-center`,
				children: [
					btnPage,
				],
			}).vee.prependTo(wrpStateBtnsOuter);
		}
	};

	static _PageFilterGetBrew = class extends PageFilterBase {
		static _STATUS_FILTER_DEFAULT_DESELECTED = new Set(["wip", "deprecated", "invalid"]);

		constructor ({brewUtil}) {
			super();

			this._brewUtil = brewUtil;

			this._typeFilter = new GetBrewUi._TypeFilter({brewUtil});
			this._statusFilter = new Filter({
				header: "Status",
				cnHeader: "状态",
				items: [
					"ready",
					"wip",
					"deprecated",
					"invalid",
				],
				displayFn: it => {
					switch (it) {
						case "ready": return "就绪";
						case "wip": return "进行中";
						case "deprecated": return "已弃用";
						case "invalid": return "无效";
					}
				},
				itemSortFn: null,
				deselFn: it => this.constructor._STATUS_FILTER_DEFAULT_DESELECTED.has(it),
			});
			this._miscFilter = new Filter({
				header: "Miscellaneous",
				cnHeader: "杂项",
				items: ["合作方", "范例"],
				deselFn: it => it === "范例",
			});
		}

		static mutateForFilters (brewInfo) {
			brewInfo._fMisc = [];
			if (brewInfo._brewAuthor && brewInfo._brewAuthor.toLowerCase().startsWith("sample -")) brewInfo._fMisc.push("范例");
			if (brewInfo.sources?.some(ab => ab.startsWith(Parser.SRC_UA_ONE_PREFIX))) brewInfo._fMisc.push("One D&D");
			if (brewInfo._brewIsPartnered) brewInfo._fMisc.push("合作方");
		}

		addToFilters (it, isExcluded) {
			if (isExcluded) return;

			this._typeFilter.addItem(it.props);
			this._miscFilter.addItem(it._fMisc);
		}

		async _pPopulateBoxOptions (opts) {
			opts.filters = [
				this._typeFilter,
				this._statusFilter,
				this._miscFilter,
			];
		}

		toDisplay (values, it) {
			return this._filterBox.toDisplay(
				values,
				it.props,
				it._brewStatus,
				it._fMisc,
			);
		}
	};

	static _ListUiPreviewButtonHandlerBrew = class extends ListUiPreviewButtonHandlerBase {
		static _BLOCKLIST_NAMES = {
			"classFeature": new Set(["Ability Score Improvement"]),
		};

		_doAppendPrimaryView ({entity, elePreviewWrpInner}) {
			this._pGetBrewSummary({entity})
				.then(brewSummary => {
					const propMetas = Object.entries(brewSummary)
						.map(([prop, metas]) => [Parser.getPropDisplayName(prop), {prop, metas}])
						.sort(([propNameA], [propNameB]) => SortUtil.ascSortLower(propNameA, propNameB))
						.map(([propName, {prop, metas}], ix, arr) => {
							const metasFilt = metas
								.filter(meta => !this.constructor._BLOCKLIST_NAMES[prop]?.has(meta.name))
								.filter(
									function (meta) { return this.has(meta.name) ? false : this.add(meta.name); },
									new Set(),
								);

							const dispToggleExpand = veT`<span class="ve-mr-2" title="SHIFT-Click to Toggle All">[+]</span>`;

							const dispHeader = veT`<div class="ve-w-100 ve-py-1 ve-bb-1p-trans ve-flex-v-center">
								${dispToggleExpand}
								<b class="ve-mr-1">${propName.qq()}</b>
								<span class="ve-muted" title="Note that duplicate/unwanted names are not displayed in the list below.">(${metas.length})</span>
							</div>`
								.vee.onn("click", evt => {
									evt.stopPropagation();
									evt.preventDefault();

									const isExpand = doToggle();

									if (!evt.shiftKey) return;

									propMetas
										.filter(propMeta => propMeta !== out)
										.forEach(propMeta => propMeta.doToggle({isExpand}));
								});

							const htmlLis = metasFilt
								.map(meta => {
									return `<div class="ve-w-100 ve-pr-1p ve-py-1p ve-flex ve-relative">
										<span class="ve-no-shrink">${meta.name.qq()}</span>${meta.page ? `<span class="ve-w-100 ve-min-w-0 ve-relative ve-top-n3p ve-mx-1 ve-bb-1p manbrew-get-preview__sep-page"></span><span class="ve-no-shrink ve-muted ve-small-caps" title="Page ${meta.page}">p${meta.page}</span>` : ""}
									</div>`;
								})
								.join("");

							const dispBody = veT`<div class="ve-mb-0 ve-columns-3 ve-hidden ve-pl-4 ve-mt-1">
								${htmlLis}
							</div>`;

							const doToggle = ({isExpand = null} = {}) => {
								isExpand ??= dispToggleExpand.vee.txt() === "[+]";
								dispToggleExpand.vee.txt(isExpand ? `[\u2212]` : "[+]");

								dispBody.vee.toggle(isExpand);

								return isExpand;
							};
							if (arr.length === 1) doToggle();

							const out = {
								wrp: veT`<div class="ve-flex-col ve-w-100">
									${dispHeader}
									${dispBody}
								</div>`,
								doToggle,
							};

							return out;
						});

					veT`<div class="ve-flex-col ve-w-100">${propMetas.map(meta => meta.wrp)}</div>`
						.vee.appendTo(elePreviewWrpInner);
				});
		}

		async _pGetBrewSummary ({entity}) {
			const jsonRaw = await DataUtil.loadRawJSON(entity.urlDownload);

			return Object.fromEntries(
				Object.entries(jsonRaw)
					.filter(([k, arr]) => {
						if (k.startsWith("_")) return false;

						if (k.startsWith("foundry") || k.endsWith("Fluff")) return false;
						if (["adventureData", "bookData"].includes(k)) return false;

						if (arr == null || !(arr instanceof Array)) return false;

						return true;
					})
					.map(([prop, arr]) => {
						return [
							prop,
							arr
								.map(ent => {
									if (!ent?.name) return null;
									return {
										name: ent.name,
										page: SourceUtil.getEntityPage(ent),
									};
								})
								.filter(Boolean)
								.sort((a, b) => SortUtil.ascSortLower(a.name, b.name) || SortUtil.ascSort(a.page, b.page)),
						];
					})
					.filter(([, metas]) => metas.length),
			);
		}
	};

	static async pDoGetBrew ({brewUtil, isModal: isParentModal = false} = {}) {
		return new Promise((resolve, reject) => {
			const ui = new this({brewUtil, isModal: true});
			const rdState = new this._RenderState();
			const {eleModalInner} = UiUtil.getShowModal({
				isHeight100: true,
				title: `获取${brewUtil.DISPLAY_NAME.toTitleCase()}`,
				isUncappedHeight: true,
				isWidth100: true,
				overlayColor: isParentModal ? "transparent" : undefined,
				isHeaderBorder: true,
				cbClose: async () => {
					await ui.pHandlePreCloseModal({rdState});
					resolve([...ui._brewsLoaded]);
				},
			});
			ui.pInit()
				.then(() => ui.pRender(eleModalInner, {rdState}))
				.catch(e => reject(e));
		});
	}

	_sortUrlList (a, b, o) {
		a = this._dataList[a.getId()];
		b = this._dataList[b.getId()];

		switch (o.sortBy) {
			case "name": return this.constructor._sortUrlList_byName(a, b);
			case "author": return this.constructor._sortUrlList_orFallback(a, b, SortUtil.ascSortLower, "_brewAuthor");
			case "translator": return this.constructor._sortUrlList_orFallback(a, b, SortUtil.ascSortLower, "_brewTranslator");
			case "category": return this.constructor._sortUrlList_orFallback(a, b, SortUtil.ascSortLower, "_brewPropDisplayName");
			case "added": return this.constructor._sortUrlList_orFallback(a, b, SortUtil.ascSort, "_brewAdded");
			case "modified": return this.constructor._sortUrlList_orFallback(a, b, SortUtil.ascSort, "_brewModified");
			case "published": return this.constructor._sortUrlList_orFallback(a, b, SortUtil.ascSort, "_brewPublished");
			default: throw new Error(`No sort order defined for property "${o.sortBy}"`);
		}
	}

	static _sortUrlList_byName (a, b) { return SortUtil.ascSortLowerPropNumeric("_brewName", a, b); }
	static _sortUrlList_orFallback (a, b, fn, prop) { return fn(a[prop], b[prop]) || this._sortUrlList_byName(a, b); }

	constructor ({brewUtil, isModal} = {}) {
		this._brewUtil = brewUtil;
		this._isModal = isModal;

		this._dataList = null;

		this._brewsLoaded = []; // Track the brews we load during our lifetime
	}

	async pInit () {
		this._dataList = ((await this._brewUtil.pGetCombinedIndexes()) || [])
			.filter(info => this._isMatchingIndexInfo(info));
	}

	_isMatchingIndexInfo (info) {
		return true;
	}

	async pHandlePreCloseModal ({rdState}) {
		// region If the user has selected list items, prompt to load them before closing the modal
		const cntSel = rdState.list.items.filter(it => it.data.cbSel.checked).length;
		if (!cntSel) return;

		const isSave = await InputUiUtil.pGetUserBoolean({
			title: `已选择 ${this._brewUtil.DISPLAY_NAME}`,
			htmlDescription: `你选择了${cntSel} ${cntSel === 1 ? this._brewUtil.DISPLAY_NAME : this._brewUtil.DISPLAY_NAME_PLURAL}但没有加载。你是否要加载 ${cntSel === 1 ? "它" : "它们"}?`,
			textYes: "加载",
			textNo: "取消",
		});
		if (!isSave) return;

		await this._pHandleClick_btnAddSelected({rdState});
		// endregion
	}

	async pRender (wrp, {rdState} = {}) {
		rdState = rdState || new this.constructor._RenderState();

		rdState.pageFilter = new this.constructor._PageFilterGetBrew({brewUtil: this._brewUtil});

		const btnAddSelected = veT`<button class="ve-btn ${this._brewUtil.STYLE_BTN} ve-btn-sm ve-col-0-5 ve-text-center" disabled title="Add Selected"><span class="glyphicon glyphicon-save"></button>`;

		const wrpRows = veT`<div class="list ve-smooth-scroll ve-max-h-unset"><div class="ve-lst__row ve-flex-col"><div class="ve-lst__wrp-cells ve-lst__row-border ve-lst__row-inner ve-flex ve-w-100"><i>加载中...</i></div></div></div>`;

		const btnFilter = veT`<button class="ve-btn ve-btn-default ve-btn-sm">筛选</button>`;

		const btnToggleSummaryHidden = veT`<button class="ve-btn ve-btn-default" title="切换筛选摘要显示"><span class="glyphicon glyphicon-resize-small"></span></button>`;

		const iptSearch = veT`<input type="search" class="search manbrew__search ve-form-control ve-w-100 ve-lst__search ve-lst__search--no-border-h" placeholder="搜索${this._brewUtil.DISPLAY_NAME}...">`
			.vee.onn("keydown", evt => this._pHandleKeydown_iptSearch(evt, rdState));
		const dispCntVisible = veT`<div class="ve-lst__wrp-search-visible ve-no-events ve-flex-vh-center"></div>`;

		rdState.cbAll = veE({
			tag: "input",
			type: "checkbox",
		});

		rdState.btnTogglePreviewAll = veT`<button class="ve-btn ve-btn-default ve-btn-xs ve-col-0-5">${ListUiPreviewButtonHandlerBase.HTML_GLYPHICON_EXPAND}</button>`;

		const btnReset = veT`<button class="ve-btn ve-btn-default ve-btn-sm">重置</button>`;

		const wrpMiniPills = veT`<div class="ve-fltr__mini-view ve-btn-group"></div>`;

		const btnSortAddedPublished = this._brewUtil.IS_PREFER_DATE_ADDED
			? `<button class="ve-col-1-2 sort ve-btn ve-btn-default ve-btn-xs" data-sort="added">收录时间</button>`
			: `<button class="ve-col-1-2 sort ve-btn ve-btn-default ve-btn-xs" data-sort="published">发布时间</button>`;

		const wrpSort = veT`<div class="filtertools manbrew__filtertools ve-btn-group ve-input-group ve-input-group--bottom ve-flex ve-no-shrink">
			<label class="ve-col-0-5 ve-pr-0 ve-btn ve-btn-default ve-btn-xs ve-flex-vh-center">${rdState.cbAll}</label>
			${rdState.btnTogglePreviewAll}
			<button class="ve-col-3-5 sort ve-btn ve-btn-default ve-btn-xs" data-sort="name">名称</button>
			<button class="ve-col-3-1 sort ve-btn ve-btn-default ve-btn-xs" data-sort="author">作者</button>
			<button class="ve-col-3-1 sort ve-btn ve-btn-default ve-btn-xs" data-sort="translator">翻译</button>
			<button class="ve-col-1-2 sort ve-btn ve-btn-default ve-btn-xs" data-sort="category">分类</button>
			<button class="ve-col-1-2 sort ve-btn ve-btn-default ve-btn-xs" data-sort="modified">修改时间</button>
			${btnSortAddedPublished}
			<button class="sort ve-col-1 ve-btn ve-btn-default ve-btn-xs ve-grow" disabled>来源</button>
		</div>`;

		veT(wrp)`
		<div class="ve-mt-1"><i>公共仓库中可用的${this._brewUtil.DISPLAY_NAME}列表。点击名称加载${this._brewUtil.DISPLAY_NAME}，或直接查看源码。${this._brewUtil.IS_EDITABLE ? `<br>
		欢迎贡献; 查看<a href="${this._brewUtil.URL_REPO_DEFAULT}/blob/master/README.md" target="_blank" rel="noopener noreferrer">README</a>或者<a target="_blank" href="https://qm.qq.com/cgi-bin/qm/qr?k=zo7jw88cLsqp2hAkK3ssn_kEbtvy8vu4&jump_from=webapi&authKey=yyG97ItP+M1BGl171cFJ+vzAmHZGRMdvKompSckZjpj8gYcCUV/3efeHvaD3850/"><img border="0" src="//pub.idqqimg.com/wpa/images/group.png" alt="5et汉化组" title="5et汉化组"></a>。` : ""}</i></div>
		<hr class="ve-hr-3">
		<div class="ve-lst__form-top">
			${btnAddSelected}
			${btnFilter}
			${btnToggleSummaryHidden}
			<div class="ve-w-100 ve-relative">
				${iptSearch}
				<div id="lst__search-glass" class="ve-lst__wrp-search-glass ve-no-events ve-flex-vh-center"><span class="glyphicon glyphicon-search"></span></div>
				${dispCntVisible}
			</div>
			${btnReset}
		</div>
		${wrpMiniPills}
		${wrpSort}
		${wrpRows}`;

		rdState.list = new List({
			iptSearch,
			wrpList: wrpRows,
			fnSort: this._sortUrlList.bind(this),
			isFuzzy: true,
			isSkipSearchKeybindingEnter: true,
		});

		rdState.list.on("updated", () => dispCntVisible.vee.html(`${rdState.list.visibleItems.length}/${rdState.list.items.length}`));

		rdState.listSelectClickHandler = new ListSelectClickHandler({list: rdState.list});
		rdState.listSelectClickHandler.bindSelectAllCheckbox(rdState.cbAll);
		rdState.previewButtonHandler = new this.constructor._ListUiPreviewButtonHandlerBrew();
		rdState.previewButtonHandler.bindPreviewAllButton({btnAll: rdState.btnTogglePreviewAll, list: rdState.list});
		SortUtil.initBtnSortHandlers(wrpSort, rdState.list);

		this._dataList.forEach((brewInfo, ix) => {
			const {listItem} = this._pRender_getUrlRowMeta(rdState, brewInfo, ix);
			rdState.list.addItem(listItem);
		});

		await rdState.pageFilter.pInitFilterBox({
			iptSearch: iptSearch,
			btnReset: btnReset,
			btnOpen: btnFilter,
			btnToggleSummaryHidden,
			wrpMiniPills,
			namespace: `get-homebrew-${UrlUtil.getCurrentPage()}`,
		});

		this._dataList.forEach(it => rdState.pageFilter.mutateAndAddToFilters(it));

		rdState.list.init();

		rdState.pageFilter.trimState();
		rdState.pageFilter.filterBox.render();

		rdState.pageFilter.filterBox.on(
			EVNT_VALCHANGE,
			this._handleFilterChange.bind(this, rdState),
		);

		this._handleFilterChange(rdState);

		btnAddSelected
			.vee.prop("disabled", false)
			.vee.onn("click", () => this._pHandleClick_btnAddSelected({rdState}));

		iptSearch.vee.focus();
	}

	_handleFilterChange (rdState) {
		const f = rdState.pageFilter.filterBox.getValues();
		rdState.list.filter(li => rdState.pageFilter.toDisplay(f, this._dataList[li.getId()]));
	}

	_pRender_getUrlRowMeta (rdState, brewInfo, ix) {
		const epochAddedPublished = this._brewUtil.IS_PREFER_DATE_ADDED ? brewInfo._brewAdded : brewInfo._brewPublished;
		const timestampAddedPublished = epochAddedPublished
			? DatetimeUtil.getDateStr({date: new Date(epochAddedPublished * 1000), isShort: true, isPad: true})
			: "";
		const timestampModified = brewInfo._brewModified
			? DatetimeUtil.getDateStr({date: new Date(brewInfo._brewModified * 1000), isShort: true, isPad: true})
			: "";

		const cbSel = veE({
			tag: "input",
			clazz: "ve-no-events",
			type: "checkbox",
		});

		const btnAdd = veE({
			tag: "span",
			clazz: `ve-col-3-5 ve-bold manbrew__load_from_url ve-pl-0 ve-clickable`,
			txt: brewInfo._brewName,
			click: evt => this._pHandleClick_btnGetRemote({evt, btn: btnAdd, url: brewInfo.urlDownload}),
		});

		const btnShowHidePreview = veT`<span class="ve-col-0-5 ve-px-0 ve-flex-vh-center ve-lst__btn-toggle-expand ve-self-flex-stretch ve-no-select">[+]</span>`;

		const dispExpandedInner = veT`<div class="ve-flex-col ve-py-3 ve-ml-col-1 ve-w-100 ve-bb-0 ve-accordion__wrp-preview-inner manbrew-get-preview__wrp-preview"></div>`;
		const dispExpandedOuter = veT`<div class="ve-flex ve-hidden ve-relative ve-accordion__wrp-preview ve-w-100">
			<div class="ve-vr-0 ve-absolute ve-accordion__vr-preview ve-accordion__vr-preview--col-1"></div>
			${dispExpandedInner}
		</div>`;

		const eleLi = veE({
			tag: "div",
			clazz: `ve-lst__row ve-lst__row-inner ve-not-clickable ve-lst__row-border ve-no-select ve-flex-col ve-no-shrink`,
			children: [
				veE({
					tag: "div",
					clazz: `ve-lst__wrp-cells ve-flex ve-w-100`,
					children: [
						veE({
							tag: "label",
							clazz: `ve-col-0-5 ve-flex-vh-center ve-self-flex-stretch`,
							children: [cbSel],
						}),
						btnShowHidePreview,
						btnAdd,
						veE({tag: "span", clazz: "ve-col-3-1", txt: brewInfo._brewAuthor}),
						veE({tag: "span", clazz: "ve-col-3-1", text: brewInfo._brewTranslator}),
						veE({tag: "span", clazz: "ve-col-1-2 ve-text-center ve-mobile-sm__text-clip-ellipsis", txt: brewInfo._brewPropDisplayName, title: brewInfo._brewPropDisplayName}),
						veE({tag: "span", clazz: "ve-col-1-2 ve-text-center ve-code", txt: timestampModified}),
						veE({tag: "span", clazz: "ve-col-1-2 ve-text-center ve-code", txt: timestampAddedPublished}),
						veE({
							tag: "span",
							clazz: "manbrew__source ve-text-center ve-pr-0 ve-grow",
							children: [
								veE({
									tag: "a",
									txt: `View Raw`,
								})
									.vee.attr("href", brewInfo.urlDownload)
									.vee.attr("target", "_blank")
									.vee.attr("rel", "noopener noreferrer"),
							],
						}),
					],
				}),
				dispExpandedOuter,
			],
			keydown: evt => this._pHandleKeydown_row(evt, {rdState, btnAdd, url: brewInfo.urlDownload, listItem}),
		})
			.vee.attr("tabindex", ix);

		const listItem = new ListItem({
			id: ix,
			ele: eleLi,
			name: brewInfo._brewName,
			values: {
				author: brewInfo._brewAuthor,
				// category: brewInfo._brewPropDisplayName, // Unwanted in search
				internalSources: brewInfo._brewInternalSources, // Used for search
				ENG_name: brewInfo.ENG_name,
				ENG_hash: UrlUtil.autoEncodeEngHash(brewInfo),
			},
			data: {
				btnAdd,
				cbSel,
				btnShowHidePreview,
				pFnDoDownload: ({isLazy = false} = {}) => this._pHandleClick_btnGetRemote({btn: btnAdd, url: brewInfo.urlDownload, isLazy}),
			},
		});

		eleLi.addEventListener("click", evt => rdState.listSelectClickHandler.handleSelectClick(listItem, evt, {isPassThroughEvents: true}));

		rdState.previewButtonHandler.bindPreviewButton({entity: brewInfo, listItem, btnShowHidePreview});

		return {
			listItem,
		};
	}

	async _pHandleKeydown_iptSearch (evt, rdState) {
		switch (evt.key) {
			case "Enter": {
				const firstItem = rdState.list.visibleItems[0];
				if (!firstItem) return;
				await firstItem.data.pFnDoDownload();
				return;
			}

			case "ArrowDown": {
				const firstItem = rdState.list.visibleItems[0];
				if (firstItem) {
					evt.stopPropagation();
					evt.preventDefault();
					firstItem.ele.focus();
				}
			}
		}
	}

	async _pHandleClick_btnAddSelected ({rdState}) {
		const listItems = rdState.list.items.filter(it => it.data.cbSel.checked);

		if (!listItems.length) return JqueryUtil.doToast({type: "warning", content: `Please select some ${this._brewUtil.DISPLAY_NAME_PLURAL} first!`});

		if (listItems.length > 25 && !await InputUiUtil.pGetUserBoolean({title: "你确定吗？", htmlDescription: `<div>You are about to load ${listItems.length} ${this._brewUtil.DISPLAY_NAME} files.<br>Loading large quantities of ${this._brewUtil.DISPLAY_NAME_PLURAL} can lead to performance and stability issues.</div>`, textYes: "Continue"})) return;

		rdState.cbAll.checked = false;
		rdState.list.items.forEach(item => {
			item.data.cbSel.checked = false;
			item.ele.classList.remove("list-multi-selected");
		});

		await Promise.allSettled(listItems.map(it => it.data.pFnDoDownload({isLazy: true})));
		const lazyDepsAdded = await this._brewUtil.pAddBrewsLazyFinalize();
		this._brewsLoaded.push(...lazyDepsAdded);
		JqueryUtil.doToast(`已选择的${this._brewUtil.DISPLAY_NAME}资源加载完成`);
	}

	async _pHandleClick_btnGetRemote ({evt, btn, url, isLazy}) {
		if (!(url || "").trim()) return JqueryUtil.doToast({type: "danger", content: `${this._brewUtil.DISPLAY_NAME.uppercaseFirst()} had no download URL!`});

		if (evt) {
			evt.stopPropagation();
			evt.preventDefault();
		}

		const cachedHtml = btn.vee.html();
		btn.vee.txt("Loading...").vee.attr("disabled", true);
		const brewsAdded = await this._brewUtil.pAddBrewFromUrl(url, {isLazy});
		this._brewsLoaded.push(...brewsAdded);
		btn.vee.txt("Done!");
		setTimeout(() => btn.vee.html(cachedHtml).vee.attr("disabled", false), VeCt.DUR_INLINE_NOTIFY);
	}

	async _pHandleKeydown_row (evt, {rdState, btnAdd, url, listItem}) {
		switch (evt.key) {
			case "Enter": return this._pHandleClick_btnGetRemote({evt, btn: btnAdd, url});

			case "ArrowUp": {
				const ixCur = rdState.list.visibleItems.indexOf(listItem);

				if (~ixCur) {
					const prevItem = rdState.list.visibleItems[ixCur - 1];
					if (prevItem) {
						evt.stopPropagation();
						evt.preventDefault();
						prevItem.ele.focus();
					}
					return;
				}

				const firstItem = rdState.list.visibleItems[0];
				if (firstItem) {
					evt.stopPropagation();
					evt.preventDefault();
					firstItem.ele.focus();
				}
				return;
			}

			case "ArrowDown": {
				const ixCur = rdState.list.visibleItems.indexOf(listItem);

				if (~ixCur) {
					const nxtItem = rdState.list.visibleItems[ixCur + 1];
					if (nxtItem) {
						evt.stopPropagation();
						evt.preventDefault();
						nxtItem.ele.focus();
					}
					return;
				}

				const lastItem = rdState.list.visibleItems.last();
				if (lastItem) {
					evt.stopPropagation();
					evt.preventDefault();
					lastItem.ele.focus();
				}
			}
		}
	}
}

