import {DmScreenExiledPanelJoystickMenu} from "../dmscreen-joystickmenu.js";

export class DmScreenSidemenuHistory extends BaseComponent {
	constructor ({board}) {
		super();

		this._board = board;

		this._wrpSideMenu = null;
		this._wrpHistory = null;

		this._wrpHistoryPanels = null;
	}

	/* -------------------------------------------- */

	setIsFullscreen (val) {
		this._state.isFullscreen = !!val;
	}

	/* -------------------------------------------- */

	init () {
		this._wrpSideMenu = veEs(`#dm-screen-sidemenu`);
		this._wrpHistory = veEs(`#dm-screen-sidemenu-history`);

		this._addHookBase("isVisible", () => {
			if (this._state.isVisible) this.doUpdateRender();
			this._wrpHistory.vee.toggleClass("dmsmh__wrp-history--open", !!this._state.isVisible);
		})();

		this._addHookBase("isFullscreen", () => {
			this._wrpHistory.vee.toggleClass("ve-bt-1p", !this._state.isFullscreen);
		})();

		const bodyOnMousedown = evt => {
			if (this._wrpSideMenu.contains(evt.target)) return;

			this._state.isVisible = false;
		};

		veE(document.body)
			.vee.onn("mousedown", bodyOnMousedown)
			.vee.onn("touchstart", bodyOnMousedown)
		;
	}

	/* -------------------------------------------- */

	render () {
		const btnHistClear = veT`<button class="ve-btn ve-btn-danger ve-btn-xs">清空</button>`
			.vee.onn("click", () => {
				this._board.exiledPanels.forEach(p => p.destroy());
				this._board.exiledPanels = [];
				this.doUpdateRender();
			});

		this._wrpHistoryPanels = veT`<div class="ve-flex-col ve-w-100 ve-h-100 ve-min-h-0 ve-overflow-y-auto ve-overflow-x-hidden"></div>`;

		veT(this._wrpHistory)`
			<div class="ve-w-100 ve-mb-2 ve-split-v-center">
				<span class="ve-small-caps">近期删除</span>
				${btnHistClear}
			</div>
			<hr class="ve-hr-2">
			${this._wrpHistoryPanels}
		`;
	}

	/* -------------------------------------------- */

	getBtnToggle () {
		const btnToggle = veT`<button class="ve-btn ve-btn-default ve-bc-0 ve-br-0 ve-bl-0 ve-mb-4" title="变更历史"><span class="fas fa-clock-rotate-left"></span></button>`
			.vee.onn("click", () => this._state.isVisible = !this._state.isVisible);

		this._addHookBase("isVisible", () => btnToggle.vee.toggleClass("ve-active", this._state.isVisible))();

		return btnToggle;
	}

	/* -------------------------------------------- */

	doUpdateRender () {
		this._board.exiledPanels
			.forEach(p => p.getContentWrapper().vee.detach());

		this._wrpHistoryPanels.vee.empty();

		this._board.exiledPanels
			.forEach((panel, i) => {
				const btnRemove = veT`<div class="panel-history-control-remove-wrapper"><span class="panel-history-control-remove glyphicon glyphicon-remove" title="Remove"></span></div>`
					.vee.onn("click", () => {
						this._board.exiledPanels[i].destroy();
						this._board.exiledPanels.splice(i, 1);
						this.doUpdateRender();
					});

				const ctrlMove = veT`<div class="panel-history-control-middle" title="Move"></div>`;

				const wrpHistItem = veT`<div class="sidemenu__history-item ve-no-shrink">
					<div class="sidemenu__history-item-cover">
						${btnRemove}
						${ctrlMove}
					</div>

					${panel.getContentWrapper()}
				</div>`
					.vee.tooltip(panel.getActiveTabTitle())
					.vee.appendTo(this._wrpHistoryPanels);

				DmScreenExiledPanelJoystickMenu.bindCtrlMoveHandlers({
					board: this._board,
					panel,
					ctrlMove,
					wrpHistItem,
					btnRemove,
					fnUpdateParentRender: this.doUpdateRender.bind(this),
					fnOnPanelDragStart: this._onPanelDragStart.bind(this),
				});
			});

		this._board.doSaveStateDebounced();
	}

	_onPanelDragStart () {
		this._state.isVisible = false;
	}

	/* -------------------------------------------- */

	_getDefaultState () {
		return {
			isVisible: false,
			isFullscreen: false,
		};
	}
}

import {PANEL_TYP_EMPTY} from "../dmscreen-consts.js";

export class RenderableCollectionSaveSlotStatesSidebar extends RenderableCollectionGenericRows {
	constructor (
		{
			board,
			comp,
			wrpRows,
		},
	) {
		super(comp, "saveSlotStates", wrpRows, {namespace: "sidebar", isDiffMode: true});
		this._board = board;
	}

	_getWrpRow () {
		return veT`<button class="ve-btn ve-btn-default ve-bc-0 ve-bt-0 ve-br-0 ve-bl-0 ve-text-clip-ellipsis ve-no-shrink ve-p-0 ve-text-center ve-h-34p"></button>`;
	}

	static _HANDLER_CANCEL_EDIT;

	static _doBindHandlerCancelEdit ({fnDoDisableEditable}) {
		if (this._HANDLER_CANCEL_EDIT) {
			veE(document.body).vee.off("click", this._HANDLER_CANCEL_EDIT);
			this._HANDLER_CANCEL_EDIT = null;
		}

		this._HANDLER_CANCEL_EDIT = fnDoDisableEditable;
		veE(document.body).vee.onn("click", fnDoDisableEditable);
	}

	_populateRow ({comp, wrpRow, entity}) {
		wrpRow
			.vee.onn("click", async () => {
				await this._board.pHandleClick_setActiveSaveSlot(entity.id);
			});

		let isEditable = false;
		const doToggleEditable = () => {
			isEditable = !isEditable;

			dispName.vee.toggle(!isEditable);
			iptNameShort.vee.toggle(isEditable);

			if (!isEditable) return;

			this.constructor._doBindHandlerCancelEdit({
				fnDoDisableEditable: () => {
					if (isEditable) doToggleEditable();
				},
			});

			iptNameShort
				.vee.focus()
				.vee.select();
		};

		const dispName = veT`<span class="ve-h-100"></span>`;
		comp._addHookBase("ns", () => dispName.vee.txt(comp._state.ns ? `${comp._state.ns}` : `${entity.id}`))();

		const iptNameShort = ComponentUiUtil.getIptStr(
			comp,
			"ns",
			{
				html: `<input class="ve-text-center ve-hidden ve-form-control ve-input-xs form-control--minimal ve-text-center ve-b-0 ve-p-0 ve-h-100 ve-w-100 dmsm__ipt-name-short" placeholder="${entity.id}">`,
			},
		)
			.vee.onn("keydown", evt => {
				if (evt.key !== "Enter") return;
				if (isEditable) doToggleEditable();
			});

		wrpRow
			.vee.onn("contextmenu", evt => {
				evt.preventDefault();
				evt.stopPropagation();

				if (!comp._state.isActive) return;

				doToggleEditable();
			});

		const hkName = () => wrpRow.vee.tooltip(`加载存档面板${comp._state.n ? `"${comp._state.n}"` : comp._state.ns ? `"${comp._state.ns}"` : `${entity.id}`}`);
		comp._addHookBase("n", hkName);
		comp._addHookBase("ns", hkName);
		hkName();

		comp._addHookBase("isActive", () => {
			wrpRow.vee.toggleClass("ve-active", !!comp._state.isActive);
			if (!comp._state.isActive && isEditable) doToggleEditable();
		})();

		veT(wrpRow)`
			${dispName}
			${iptNameShort}
		`;
	}
}

