class _InitiativeTrackerMonsterAddCustomizer extends BaseComponent {
	static _RenderState = class {
		constructor () {
			this.cbDoClose = null;
		}
	};

	constructor ({mon}) {
		super();
		this._mon = mon;
	}

	async pGetShowModalResults () {
		const rdState = new this.constructor._RenderState();

		const {eleModalInner, eleModalFooter, doClose, pGetResolved} = UiUtil.getShowModal({
			title: `自定义生物 \u2014 ${this._mon.name}`,
			isHeaderBorder: true,
			hasFooter: true,
			isMinHeight0: true,
		});
		rdState.cbDoClose = doClose;

		const iptCustomName = ComponentUiUtil.getIptStr(this, "customName");

		veT(eleModalInner)`
			<div class="ve-flex-col ve-py-2 ve-w-100 ve-h-100 ve-overflow-y-auto">
				<label class="ve-split-v-center ve-mb-2">
					<span class="ve-w-200p ve-text-right ve-no-shrink ve-mr-2 ve-bold">自定义名字:</span>
					${iptCustomName}
				</label>
				${this._render_getEleRowScaler()}
			</div>
		`;

		veT(eleModalFooter)`
			${this._render_getEleFooter({rdState})}
		`;

		return pGetResolved();
	}

	_render_getEleRowScaler () {
		const isShowCrScaler = Parser.crToNumber(this._mon.cr) !== VeCt.CR_UNKNOWN;
		const isShowSpellLevelScaler = !isShowCrScaler && this._mon.summonedBySpellLevel != null;
		const isShowClassLevelScaler = !isShowSpellLevelScaler && (this._mon.summonedByClass != null || this._mon.summonedScaleByPlayerLevel);

		if (!isShowCrScaler && !isShowSpellLevelScaler && !isShowClassLevelScaler) return null;

		if (isShowSpellLevelScaler) {
			const sel = Renderer.monster.getSelSummonSpellLevel(this._mon)
				.vee.onn("change", async () => {
					const val = Number(sel.vee.val());
					this._state.scaledSummonSpellLevel = !~val ? null : val;
					if (this._state.scaledSummonSpellLevel == null) return delete this._state.displayName;
					this._state.displayName = (await ScaleSpellSummonedCreature.scale(this._mon, this._state.scaledSummonSpellLevel))._displayName;
				});

			return veT`<label class="ve-split-v-center ve-mb-2">
				<span class="ve-w-200p ve-text-right ve-no-shrink ve-mr-2 ve-bold">法术环阶:</span>
				${sel}
			</label>`;
		}

		if (isShowClassLevelScaler) {
			const sel = Renderer.monster.getSelSummonClassLevel(this._mon)
				.on("change", async () => {
					const val = Number(sel.vee.val());
					this._state.scaledSummonClassLevel = !~val ? null : val;
					if (this._state.scaledSummonClassLevel == null) return delete this._state.displayName;
					this._state.displayName = (await ScaleClassSummonedCreature.scale(this._mon, this._state.scaledSummonClassLevel))._displayName;
				});

			return veT`<label class="ve-split-v-center ve-mb-2">
				<span class="ve-w-200p ve-text-right ve-no-shrink ve-mr-2 ve-bold">${this._mon.summonedByClass != null ? "职业等级" : "等级"}:</span>
				${sel}
			</label>`;
		}

		const dispScaledCr = veT`<span class="ve-inline-block"></span>`;
		this._addHookBase("scaledCr", () => dispScaledCr.vee.txt(this._state.scaledCr ? Parser.numberToCr(this._state.scaledCr) : `${(this._mon.cr.cr || this._mon.cr)} (默认)`))();

		const btnScaleCr = veT`<button class="ve-btn ve-btn-default ve-btn-xs ve-mr-2"><span class="glyphicon glyphicon-signal"></span></button>`
			.vee.onn("click", async () => {
				const crBase = this._mon.cr.cr || this._mon.cr;

				const cr = await InputUiUtil.pGetUserScaleCr({default: crBase});
				if (cr == null) return;

				if (crBase === cr) {
					delete this._state.scaledCr;
					delete this._state.displayName;
					return;
				}
				this._state.scaledCr = Parser.crToNumber(cr);
				this._state.displayName = (await ScaleCreature.scale(this._mon, this._state.scaledCr))._displayName;
			});

		return veT`<label class="ve-split-v-center ve-mb-2">
			<span class="ve-w-200p ve-text-right ve-no-shrink ve-mr-2 ve-bold">CR:</span>
			<span class="ve-flex-v-center ve-mr-auto">
				${btnScaleCr}
				${dispScaledCr}
			</span>
		</label>`;
	}

	_render_getEleFooter ({rdState}) {
		const btnSave = veT`<button class="ve-btn ve-btn-primary ve-btn-sm ve-w-100">保存</button>`
			.vee.onn("click", () => {
				rdState.cbDoClose(
					true,
					MiscUtil.copyFast(this.__state),
				);
			});

		return veT`<div class="ve-w-100 ve-py-3 ve-no-shrink">
			${btnSave}
		</div>`;
	}

	_getDefaultState () {
		return {
			customName: null,
			displayName: null,
			scaledCr: null,
			scaledSummonSpellLevel: null,
			scaledSummonClassLevel: null,
		};
	}
}

export class InitiativeTrackerMonsterAdd extends BaseComponent {
	static _RESULTS_MAX_DISPLAY = 75; // hard cap at 75 results

	static _RenderState = class {
		constructor () {
			this.cbDoClose = null;
		}
	};

	constructor ({board, isRollHp}) {
		super();
		this._board = board;

		this._state.isRollHp = isRollHp;
	}

	_getDefaultState () {
		return {
			isRollHp: false,
			cntToAdd: 1,
			cntToAddCustom: 13,
		};
	}

	_getCntToAdd () {
		return this._state.cntToAdd === -1
			? Math.max(1, this._state.cntToAddCustom)
			: this._state.cntToAdd;
	}

	/* -------------------------------------------- */

	_getCbCntToAdd ({cnt}) {
		const cb = veT`<input type="radio" class="ve-ui-search__ipt-search-sub-ipt">`;
		cb.vee.onn("change", () => {
			this._state.cntToAdd = cnt;
		});
		this._addHookBase("cntToAdd", () => cb.vee.prop("checked", this._state.cntToAdd === cnt))();
		return cb;
	}

	_getIptCntToAddCustom () {
		const iptCntToAddCustom = ComponentUiUtil.getIptInt(
			this,
			"cntToAddCustom",
			1,
			{
				html: `<input type="number" class="ve-form-control ve-ui-search__ipt-search-sub-ipt-custom">`,
				min: 1,
			},
		);

		this._addHookBase("cntToAdd", () => {
			if (this._state.cntToAdd !== -1) return;
			iptCntToAddCustom.vee.select();
		})();

		iptCntToAddCustom.vee.onn("click", () => {
			this._state.cntToAdd = -1;
		});

		return iptCntToAddCustom;
	}

	/**
	 * @return {Promise<[boolean, _MonstersToLoad]>}
	 */
	async pGetShowModalResults () {
		const rdState = new this.constructor._RenderState();

		const flags = {
			doClickFirst: false,
			isWait: false,
		};

		const {eleModalInner, doClose, pGetResolved} = UiUtil.getShowModal();
		rdState.cbDoClose = doClose;

		const iptSearch = veT`<input class="ve-ui-search__ipt-search search ve-form-control" placeholder="搜索...">`
			.vee.disableSpellcheck();

		veT`<div class="ve-split ve-no-shrink">
			${iptSearch}

			<div class="ve-ui-search__ipt-search-sub-wrp ve-flex-v-center ve-pr-0">
				<div class="ve-mr-1">添加</div>
				<label class="ve-ui-search__ipt-search-sub-lbl">${this._getCbCntToAdd({cnt: 1})} 1</label>
				<label class="ve-ui-search__ipt-search-sub-lbl">${this._getCbCntToAdd({cnt: 2})} 2</label>
				<label class="ve-ui-search__ipt-search-sub-lbl">${this._getCbCntToAdd({cnt: 3})} 3</label>
				<label class="ve-ui-search__ipt-search-sub-lbl">${this._getCbCntToAdd({cnt: 5})} 5</label>
				<label class="ve-ui-search__ipt-search-sub-lbl">${this._getCbCntToAdd({cnt: 8})} 8</label>
				<label class="ve-ui-search__ipt-search-sub-lbl">${this._getCbCntToAdd({cnt: -1})} ${this._getIptCntToAddCustom()}</label>
			</div>

			<label class="ve-ui-search__ipt-search-sub-wrp ve-flex-vh-center">${ComponentUiUtil.getCbBool(this, "isRollHp").vee.addClass("ve-mr-1")} <span>随机 HP</span></label>
		</div>`.vee.appendTo(eleModalInner);

		const wrpResults = veT`<div class="ve-ui-search__wrp-results"></div>`.vee.appendTo(eleModalInner);

		const showMsgIpt = () => {
			flags.isWait = true;
			wrpResults.vee.empty().vee.appends(SearchWidget.getSearchEnter());
		};

		const showMsgDots = () => wrpResults.vee.empty().vee.appends(SearchWidget.getSearchLoading());

		const showNoResults = () => {
			flags.isWait = true;
			wrpResults.vee.empty().vee.appends(SearchWidget.getSearchNoResults());
		};

		const ptrRows = {_: []};

		const pDoSearch = async () => {
			const searchTerm = iptSearch.vee.val().trim();

			const index = this._board.availContent["生物"];
			const results = await OmnisearchBacking.pGetFilteredResults(
				index.search(searchTerm, {
					fields: {
						n: {boost: 5, expand: true},
						cn: {boost: 5, expand: true},
						s: {expand: true},
					},
					bool: "AND",
					expand: true,
				}),
				{
					searchTerm,
				},
			);
			const resultCount = results.length ? results.length : index.documentStore.length;
			const toProcess = results.length ? results : Object.values(index.documentStore.docs).slice(0, 75).map(it => ({doc: it}));

			wrpResults.vee.empty();
			ptrRows._ = [];
			if (toProcess.length) {
				if (flags.doClickFirst) {
					await this._render_pHandleClickRow({rdState}, toProcess[0]);
					flags.doClickFirst = false;
					return;
				}

				const results = toProcess.slice(0, this.constructor._RESULTS_MAX_DISPLAY);

				results.forEach(res => {
					const row = this._render_getSearchRow({rdState, res}).vee.appendTo(wrpResults);
					SearchWidget.bindRowHandlers({result: res, row, ptrRows, pFnHandleClick: this._render_pHandleClickRow.bind(this, {rdState}), iptSearch});
					ptrRows._.push(row);
				});

				if (resultCount > this.constructor._RESULTS_MAX_DISPLAY) {
					const diff = resultCount - this.constructor._RESULTS_MAX_DISPLAY;
					if (I18nUtil.LANGUAGES_INDEX === "zh_CN") {
						wrpResults.vee.appends(`<div class="ve-ui-search__row ve-ui-search__row--readonly">...${diff}条结果被隐藏，请调整搜索条件。</div>`);
					} else {
						wrpResults.vee.appends(`<div class="ve-ui-search__row ve-ui-search__row--readonly">...${diff} more result${diff === 1 ? " was" : "s were"} hidden. Refine your search!</div>`);
					}
				}
			} else {
				if (!searchTerm.trim()) showMsgIpt();
				else showNoResults();
			}
		};

		SearchWidget.bindAutoSearch(iptSearch, {
			flags,
			pFnSearch: pDoSearch,
			fnShowWait: showMsgDots,
			ptrRows,
		});

		iptSearch.vee.focus();
		await pDoSearch();

		return pGetResolved();
	}

	async _render_pHandleClickRow ({rdState}, res) {
		await rdState.cbDoClose(
			true,
			new _MonstersToLoad({
				count: this._getCntToAdd(),
				name: res.doc.cn,
				source: res.doc.s,
				isRollHp: this._state.isRollHp,
			}),
		);
	}

	_render_getSearchRow ({rdState, res}) {
		const btnCustomize = veT`<button class="ve-btn ve-btn-default ve-btn-xxs" title="自定义"><span class="glyphicon glyphicon-stats"></span></button>`
			.vee.onn("click", async evt => {
				evt.stopPropagation();
				await this._render_pHandleClickCustomize({rdState, res});
			});

		return veT`
			<div class="ve-ui-search__row ve-flex-v-center" tabindex="0">
				<span>${res.doc.cn}</span>
				<div class="ve-flex-vh-center">
					<span class="ve-mr-2">${res.doc.s ? `<i title="${Parser.sourceJsonToFull(res.doc.s)}">${Parser.sourceJsonToAbv(res.doc.s)}${res.doc.p ? ` p${res.doc.p}` : ""}</i>` : ""}</span>
					${btnCustomize}
				</div>
			</div>
		`;
	}

	async _render_pHandleClickCustomize ({rdState, res}) {
		const mon = await DataLoader.pCacheAndGet(UrlUtil.PG_BESTIARY, res.doc.s, res.doc.u);
		if (!mon) return;

		const comp = new _InitiativeTrackerMonsterAddCustomizer({mon});

		const resModal = await comp.pGetShowModalResults();
		if (resModal == null) return;

		const [isDataEntered, data] = resModal;
		if (!isDataEntered) return;

		await rdState.cbDoClose(
			true,
			new _MonstersToLoad({
				count: this._getCntToAdd(),
				name: res.doc.n,
				source: res.doc.s,
				isRollHp: this._state.isRollHp,
				...data,
			}),
		);
	}
}

class _InitiativeTrackerNetworkingP2pMetaV1 {
	constructor () {
		this.rows = [];
		this.serverInfo = null;
		this.serverPeer = null;
	}
}

class _InitiativeTrackerNetworkingP2pMetaV0 {
	constructor () {
		this.rows = [];
		this.serverInfo = null;
	}
}

export class InitiativeTrackerNetworking {
	constructor ({board}) {
		this._board = board;

		this._p2pMetaV1 = new _InitiativeTrackerNetworkingP2pMetaV1();
		this._p2pMetaV0 = new _InitiativeTrackerNetworkingP2pMetaV0();
	}

	/* -------------------------------------------- */

	sendStateToClients ({fnGetToSend}) {
		return this._sendMessageToClients({fnGetToSend});
	}

	sendShowImageMessageToClients ({imageHref}) {
		return this._sendMessageToClients({
			fnGetToSend: () => ({
				type: "showImage",
				payload: {
					imageHref,
				},
			}),
		});
	}

	_sendMessageToClients ({fnGetToSend}) {
		let toSend = null;

		// region V1
		if (this._p2pMetaV1.serverPeer) {
			if (!this._p2pMetaV1.serverPeer.hasConnections()) return;

			toSend ||= fnGetToSend();
			this._p2pMetaV1.serverPeer.pSendMessage(toSend);
		}
		// endregion

		// region V0
		if (this._p2pMetaV0.serverInfo) {
			this._p2pMetaV0.rows = this._p2pMetaV0.rows.filter(row => !row.isDeleted);
			this._p2pMetaV0.serverInfo = this._p2pMetaV0.serverInfo.filter(row => {
				if (row.isDeleted) {
					row.server.close();
					return false;
				}
				return true;
			});

			toSend ||= fnGetToSend();
			try {
				this._p2pMetaV0.serverInfo.filter(info => info.server.isActive).forEach(info => info.server.sendMessage(toSend));
			} catch (e) { setTimeout(() => { throw e; }); }
		}
		// endregion
	}

	/* -------------------------------------------- */

	/**
	 * @param opts
	 * @param opts.doUpdateExternalStates
	 * @param [opts.btnStartServer]
	 * @param [opts.btnGetToken]
	 * @param [opts.btnGetLink]
	 * @param [opts.fnDispServerStoppedState]
	 * @param [opts.fnDispServerRunningState]
	 */
	async startServerV1 (opts) {
		opts = opts || {};

		if (this._p2pMetaV1.serverPeer) {
			await this._p2pMetaV1.serverPeer.pInit();
			return {
				isRunning: true,
				token: this._p2pMetaV1.serverPeer?.token,
			};
		}

		try {
			if (opts.btnStartServer) opts.btnStartServer.vee.prop("disabled", true);
			this._p2pMetaV1.serverPeer = new PeerVeServer();
			await this._p2pMetaV1.serverPeer.pInit();
			if (opts.btnGetToken) opts.btnGetToken.vee.prop("disabled", false);
			if (opts.btnGetLink) opts.btnGetLink.vee.prop("disabled", false);

			this._p2pMetaV1.serverPeer.on("connection", connection => {
				const pConnected = new Promise(resolve => {
					connection.on("open", () => {
						resolve(true);
						opts.doUpdateExternalStates();
					});
				});
				const pTimeout = MiscUtil.pDelay(5 * 1000, false);
				Promise.race([pConnected, pTimeout])
					.then(didConnect => {
						if (!didConnect) {
							JqueryUtil.doToast({content: `Connecting to "${connection.label.escapeQuotes()}" has taken more than 5 seconds! The connection may need to be re-attempted.`, type: "warning"});
						}
					});
			});

			window.addEventListener("beforeunload", evt => {
				const message = `The connection will be closed`;
				(evt || window.event).message = message;
				return message;
			});

			if (opts.fnDispServerRunningState) opts.fnDispServerRunningState();

			return {
				isRunning: true,
				token: this._p2pMetaV1.serverPeer?.token,
			};
		} catch (e) {
			if (opts.fnDispServerStoppedState) opts.fnDispServerStoppedState();
			if (opts.btnStartServer) opts.btnStartServer.vee.prop("disabled", false);
			this._p2pMetaV1.serverPeer = null;
