		const btnConfigure = veT`<button class="ve-btn ve-btn-default ve-btn-xs ve-mr-2" title="${I18nUtil.get("common.button.configure")} (${I18nUtil.get("page.dmscreen.shift_to_open_settings")})"><span class="glyphicon glyphicon-cog"></span></button>`
