		const btnReset = veT`<button title="${I18nUtil.get("page.dmscreen.reset_tracker")}" class="ve-btn ve-btn-danger ve-btn-xs dm-init-lockable"><span class="glyphicon glyphicon-trash"></span></button>`
			.vee.onn("click", async () => {
