									row.entity.name,
									row.entity.source,
									row.entity.scaledCr,
									row.entity.scaledSummonSpellLevel,
									row.entity.scaledSummonClassLevel,
								]
									.join("__");

								if (accum[uidRow]) {
									accum[uidRow].count++;
									return accum;
								}

								accum[uidRow] = {entityPrime: row.entity, count: 1};

								return accum;
							},
