	 */
	render ({stgGroup}) { throw new Error("Unimplemented!"); }

	/* -------------------------------------------- */

	doCleanup () { /* Implement as required */ }

	/* -------------------------------------------- */

	mutDeExternalize ({out}) { /* Specific to Bestiary integration; implement as required. */ }
}

