import {EncounterBuilderSpendInfo, EncounterPartyPlayerMeta} from "../encounterbuilder-models-other.js";
import {TIER_UNKNOWN} from "../consts/encounterbuilder-consts.js";

export class EncounterPartyMetaUtils {
	static getThresholds (
		{
			tiers,
			tierToLevelSpend,
			levelMetas,
			tierAboveMax,
		},
	) {
		if (Object.values(tierToLevelSpend).some(arr => arr.length !== 21)) throw new Error(`Expected level 0-20 value for each tier!`);

		const thresholds = Object.fromEntries(tiers.map(tier => [tier, 0]));

		levelMetas
			.forEach(meta => {
				Object.entries(tierToLevelSpend)
					.forEach(([tier, xps]) => thresholds[tier] += xps[meta.level] * meta.count);
			});

		const [tierBelowMax, tierMax] = tiers.filter(tier => tier in tierToLevelSpend).slice(-2);
		thresholds[tierAboveMax] = thresholds[tierMax] + (thresholds[tierMax] - thresholds[tierBelowMax]);

		return thresholds;
	}
}

export class EncounterPartyMetaBudgetTierProviderSpendUpTo {
	constructor ({tiersExtended, thresholds, deltaBudgetMinInclusive}) {
		this._tiersExtended = tiersExtended;
		this._thresholds = thresholds;
		this._deltaBudgetMinInclusive = deltaBudgetMinInclusive;
	}

	getBudget (tier) {
		return this._thresholds[tier];
	}

	getBudgetRange (tier) {
		const ixTier = this._tiersExtended.indexOf(tier);
		if (!~ixTier) throw new Error(`Unhandled difficulty level: "${tier}"`);

		if (!ixTier) return {budgetMin: 0, budgetMax: this.getBudget(tier)};

		const budgetMinBase = this._thresholds[this._tiersExtended[ixTier - 1]];
		const budgetMaxBase = this.getBudget(tier);

		if (budgetMinBase === budgetMaxBase) {
			return {
				budgetMin: budgetMinBase,
				budgetMax: budgetMaxBase,
			};
		}

		return {
			budgetMin: budgetMinBase + this._deltaBudgetMinInclusive,
			budgetMax: budgetMaxBase,
		};
	}

	getBudgetRangeApprox (tier) {
		const budget = this.getBudget(tier);
		return {budgetMin: budget * 0.8, budgetMax: budget};
	}

	getEncounterTier (encounterXpInfo) {
		// Remove a tier if the tier above has the same threshold
		//   e.g. _Flee, Mortals!_ 1st-level "Easy"/"Standard"
		const thresholds = MiscUtil.copyFast(this._thresholds);
		this._tiersExtended
			.forEach((tier, ix, arr) => {
				const tierNxt = arr[ix + 1];
				if (!tierNxt) return;
				if (thresholds[tier] !== thresholds[tierNxt]) return;
				delete thresholds[tier];
			});

		for (const tier of this._tiersExtended) {
			if (encounterXpInfo.adjustedSpend <= thresholds[tier]) return tier;
		}
		return this._tiersExtended.at(-1);
	}
}

/**
 * @abstract
 */
export class EncounterPartyMetaBase {
	_thresholds;

	/**
	 * @param {Array<EncounterPartyPlayerMeta>} playerMetas
	 */
	constructor (playerMetas) {
		/** @type {Array<EncounterPartyPlayerMeta>} */
		this.levelMetas = [];

		// Combine such that each `level` has at most one entry, with the total count for players of that level
		playerMetas.forEach(it => {
			const existingLvl = this.levelMetas.find(x => x.level === it.level);
			if (existingLvl) existingLvl.count += it.count;
			else this.levelMetas.push(new EncounterPartyPlayerMeta({count: it.count, level: it.level}));
		});

		this.cntPlayers = 0;
		this.avgPlayerLevel = 0;
		this.maxPlayerLevel = 0;

		this.xpToNextLevel = 0;

		this.levelMetas
			.forEach(meta => {
				this.cntPlayers += meta.count;
				this.avgPlayerLevel += meta.level * meta.count;
				this.maxPlayerLevel = Math.max(this.maxPlayerLevel, meta.level);

				this.xpToNextLevel += meta.getXpToNextLevel();
			});

		if (this.cntPlayers) this.avgPlayerLevel /= this.cntPlayers;
	}

	/**
	 * @param {Array<EncounterBuilderCreatureGroupBase>} creatureGroups
	 * @return {EncounterBuilderSpendInfo}
	 */
	getEncounterSpendInfo (creatureGroups) {
		// Avoid including e.g. "summon" creatures.
		// Note that this effectively discounts non-XP-carrying creatures from "creature count XP multiplier"
		//   calculations. This is intentional; we make the simplifying assumption that if a creature doesn't carry XP,
		//   it should have no impact on the difficulty encounter.
		creatureGroups = creatureGroups
			.filter(creatureGroup => creatureGroup.getCrNumber() != null)
			.sort((a, b) => SortUtil.ascSort(b.getCrNumber(), a.getCrNumber()));

		return this._getEncounterSpendInfo({creatureGroups});
	}

	/**
	 * @abstract
	 * @return {EncounterBuilderSpendInfo}
	 */
	_getEncounterSpendInfo ({creatureGroups}) {
		throw new Error(`Unimplemented!`);
	}

	/**
	 * @abstract
	 * @return {number}
	 */
	getBudget (tier) {
		throw new Error(`Unimplemented!`);
	}

	/**
	 * @abstract
	 * @return {{budgetMin: number, budgetMax: number}}
	 */
	getBudgetRange (tier) {
		throw new Error(`Unimplemented!`);
	}

	/**
	 * @abstract
	 * @return {{budgetMin: number, budgetMax: number}}
	 */
	getBudgetRangeApprox (tier) {
		throw new Error(`Unimplemented!`);
	}

	/**
	 * @abstract
	 * @return {string}
	 */
	_getEncounterTier (encounterXpInfo) {
		throw new Error(`Unimplemented!`);
	}

	/**
	 * @abstract
	 * @return {string}
	 */
	getEncounterTier (encounterXpInfo) {
		if (!encounterXpInfo?.playerCount) return TIER_UNKNOWN;
		return this._getEncounterTier(encounterXpInfo);
	}

	_getTierBudget ({tier, multiplier = null} = {}) {
		return (this._thresholds[tier] || 0) * (multiplier ?? 1);
	}

	/**
	 * @return {string}
	 */
	getTierDisplayBudget (tier, {multiplier = null} = {}) {
		return this._getTierBudget({tier, multiplier})?.toLocaleStringVe();
	}

	/**
	 * @abstract
	 * @return {number}
	 */
	getCrCutoff (creatureGroups) {
		throw new Error(`Unimplemented!`);
	}

	/**
	 * @abstract
	 * @return {number}
	 */
	getPlayerAdjustedSpendMultiplier (cntCreatures) {
		throw new Error(`Unimplemented!`);
	}
}

import {EncounterPartyMetaBase, EncounterPartyMetaUtils} from "./encounter-partymeta-base.js";
import {EncounterBuilderSpendInfo} from "../encounterbuilder-models-other.js";
import {LEVEL_TO_XP_DAILY, MONSTER_COUNT_TO_XP_MULTIPLIER, TIER_ABSURD, TIER_TO_LEVEL_XP, TIER_TRIVIAL, TIERS_EXTENDED} from "../consts/encounterbuilder-consts-classic.js";

export class EncounterPartyMetaClassic extends EncounterPartyMetaBase {
	/**
	 * @param {Array<EncounterPartyPlayerMeta>} playerMetas
	 */
	constructor (playerMetas) {
		super(playerMetas);

		this._thresholds = EncounterPartyMetaUtils.getThresholds({
			tiers: TIERS_EXTENDED,
			tierToLevelSpend: TIER_TO_LEVEL_XP,
			levelMetas: this.levelMetas,
			tierAboveMax: TIER_ABSURD,
		});

		this._dailyBudget = this.levelMetas
			.map(meta => LEVEL_TO_XP_DAILY[meta.level] * meta.count)
			.sum();
	}

	_getEncounterSpendInfo ({creatureGroups}) {
		let baseSpend = 0;
		let relevantCount = 0;
		let count = 0;

		const crCutoff = this.getCrCutoff(creatureGroups);
		creatureGroups
			.forEach(creatureGroup => {
				if (creatureGroup.getCrNumber() >= crCutoff) relevantCount += creatureGroup.getCount();
				count += creatureGroup.getCount();
				baseSpend += (creatureGroup.getXp() || 0) * creatureGroup.getCount();
			});

		const playerAdjustedSpendMult = this.getPlayerAdjustedSpendMultiplier(relevantCount, this.cntPlayers);

		const adjustedSpend = playerAdjustedSpendMult * baseSpend;
		return new EncounterBuilderSpendInfo({
			baseSpend,
			relevantCount,
			count,
			adjustedSpend,
			crCutoff,
			playerCount: this.cntPlayers,
			playerAdjustedSpendMult,
		});
	}

	getBudget (tier) {
		const ixTier = TIERS_EXTENDED.indexOf(tier);
		if (!~ixTier) throw new Error(`Unhandled difficulty level: "${tier}"`);

		return this._thresholds[TIERS_EXTENDED[ixTier + 1]] - 1;
	}

	getBudgetRange (tier) {
		return {budgetMin: this._thresholds[tier], budgetMax: this.getBudget(tier)};
	}

	getBudgetRangeApprox (tier) {
		return this.getBudgetRange(tier);
	}

	_getEncounterTier (encounterXpInfo) {
		const tierMaximum = TIERS_EXTENDED.at(-1);
		if (encounterXpInfo.adjustedSpend >= this._thresholds[tierMaximum]) return TIER_ABSURD;

		for (const tier of [...TIERS_EXTENDED].reverse()) {
			if (encounterXpInfo.adjustedSpend >= this._thresholds[tier]) return tier;
		}

		return TIER_TRIVIAL;
	}

	/** Return true if at least a third of the party is level 5+. */
	_isPartyLevelFivePlus () {
		const [levelMetasHigher, levelMetasLower] = this.levelMetas.partition(it => it.level >= 5);
		const cntLower = levelMetasLower.map(it => it.count).reduce((a, b) => a + b, 0);
		const cntHigher = levelMetasHigher.map(it => it.count).reduce((a, b) => a + b, 0);
		return (cntHigher / (cntLower + cntHigher)) >= 0.333;
	}

	getCrCutoff (creatureGroups) {
		creatureGroups = creatureGroups
			.filter(creatureGroup => creatureGroup.getCrNumber() != null)
			.sort((a, b) => SortUtil.ascSort(b.getCrNumber(), a.getCrNumber()));
		if (!creatureGroups.length) return 0;

		// no cutoff for CR 0-2
		if (creatureGroups[0].getCrNumber() <= 2) return 0;

		// ===============================================================================================================
		// "When making this calculation, don't count any monsters whose challenge rating is significantly below the average
		// challenge rating of the other monsters in the group unless you think the weak monsters significantly contribute
		// to the difficulty of the encounter." -- DMG, p. 82
		// ===============================================================================================================

		// "unless you think the weak monsters significantly contribute to the difficulty of the encounter"
		// For player levels <5, always include every monster. We assume that levels 5> will have strong
		//   AoE/multiattack, allowing trash to be quickly cleared.
		if (!this._isPartyLevelFivePlus()) return 0;

		// Spread the CRs into a single array
		const crValues = [];
		creatureGroups.forEach(creatureGroup => {
			const cr = creatureGroup.getCrNumber();
			for (let i = 0; i < creatureGroup.getCount(); ++i) crValues.push(cr);
		});

		// TODO(Future) allow this to be controlled by the user
		let CR_THRESH_MODE = "statisticallySignificant";

		switch (CR_THRESH_MODE) {
			// "Statistically significant" method--note that this produces very passive filtering; the threshold is below
			//   the minimum CR in the vast majority of cases.
			case "statisticallySignificant": {
				const cpy = MiscUtil.copy(crValues)
					.sort(SortUtil.ascSort);

				const avg = cpy.mean();
				const deviation = cpy.meanAbsoluteDeviation();

				return avg - (deviation * 2);
			}

			case "5etools": {
				// The ideal interpretation of this:
				//   "don't count any monsters whose challenge rating is significantly below the average
				//   challenge rating of the other monsters in the group"
				// Is:
				//   Arrange the creatures in CR order, lowest to highest. Remove the lowest CR creature (or one of them, if there
				//   are ties). Calculate the average CR without this removed creature. If the removed creature's CR is
				//   "significantly below" this average, repeat the process with the next lowest CR creature.
				// However, this can produce a stair-step pattern where our average CR keeps climbing as we remove more and more
				//   creatures. Therefore, only do this "remove creature -> calculate average CR" step _once_, and use the
				//   resulting average CR to calculate a cutoff.

				const crMetas = [];

				// If there's precisely one CR value, use it
				if (crValues.length === 1) {
					crMetas.push({
						mean: crValues[0],
						deviation: 0,
					});
				} else {
					// Get an average CR for every possible encounter without one of the creatures in the encounter
					for (let i = 0; i < crValues.length; ++i) {
						const crValueFilt = crValues.filter((_, j) => i !== j);
						const crMean = crValueFilt.mean();
						const crStdDev = Math.sqrt((1 / crValueFilt.length) * crValueFilt.map(it => (it - crMean) ** 2).reduce((a, b) => a + b, 0));
						crMetas.push({mean: crMean, deviation: crStdDev});
					}
				}

				// Sort by descending average CR -> ascending deviation
				crMetas.sort((a, b) => SortUtil.ascSort(b.mean, a.mean) || SortUtil.ascSort(a.deviation, b.deviation));

				// "significantly below the average" -> cutoff at half the average
				return crMetas[0].mean / 2;
			}

			default:
				return 0;
		}
	}

	getPlayerAdjustedSpendMultiplier (cntCreatures) {
		const baseVal = cntCreatures >= MONSTER_COUNT_TO_XP_MULTIPLIER.length
			? 4
			: this._getMonsterCountXpMultiplier(cntCreatures);

		if (this.cntPlayers < 3) return baseVal >= 3 ? baseVal + 1 : baseVal + 0.5;
		if (this.cntPlayers > 5) return baseVal === 4 ? 3 : baseVal - 0.5;
		return baseVal;
	}

	_getMonsterCountXpMultiplier (cntCreatures) {
		if (!cntCreatures) return MONSTER_COUNT_TO_XP_MULTIPLIER[0];
		if (cntCreatures > MONSTER_COUNT_TO_XP_MULTIPLIER.length) return MONSTER_COUNT_TO_XP_MULTIPLIER.at(-1);
		return MONSTER_COUNT_TO_XP_MULTIPLIER[cntCreatures - 1];
	}

	getDailyBudget () {
		return this._dailyBudget;
	}
}

import {EncounterPartyMetaBase, EncounterPartyMetaBudgetTierProviderSpendUpTo, EncounterPartyMetaUtils} from "./encounter-partymeta-base.js";
import {EncounterBuilderSpendInfo} from "../encounterbuilder-models-other.js";
import {LEVEL_CR_CAP, TIER_EXTREME, TIER_TO_LEVEL_CR, TIERS, TIERS_EXTENDED} from "../consts/encounterbuilder-consts-mcdmfleemortals.js";

export class EncounterPartyMetaMcdmFleeMortals extends EncounterPartyMetaBase {
	/**
	 * @param {Array<EncounterPartyPlayerMeta>} playerMetas
	 */
	constructor (playerMetas) {
		super(playerMetas);

		this._thresholds = EncounterPartyMetaUtils.getThresholds({
			tiers: TIERS,
			tierToLevelSpend: TIER_TO_LEVEL_CR,
			levelMetas: this.levelMetas,
			tierAboveMax: TIER_EXTREME,
		});

		this._budgetTierProvider = new EncounterPartyMetaBudgetTierProviderSpendUpTo({
			tiersExtended: TIERS_EXTENDED,
			thresholds: this._thresholds,
			deltaBudgetMinInclusive: 1 / 16,
		});
	}

	_getEncounterSpendInfo ({creatureGroups}) {
		let baseSpend = 0;
		let count = 0;

		creatureGroups
			.forEach(creatureGroup => {
				count += creatureGroup.getCount();
				baseSpend += (creatureGroup.getCrNumber() || 0) * creatureGroup.getCount();
			});

		return new EncounterBuilderSpendInfo({
			baseSpend,
			relevantCount: count,
			count,
			adjustedSpend: baseSpend,
			crCutoff: 0,
			playerCount: this.cntPlayers,
			playerAdjustedSpendMult: 1,
		});
	}

	getBudget (tier) {
		return this._budgetTierProvider.getBudget(tier);
	}

	getBudgetRange (tier) {
		return this._budgetTierProvider.getBudgetRange(tier);
	}

	getBudgetRangeApprox (tier) {
		return this._budgetTierProvider.getBudgetRangeApprox(tier);
	}

	getTierDisplayBudget (tier, {multiplier = null} = {}) {
		return Parser.numberToVulgar(this._getTierBudget({tier, multiplier}));
	}

	_getEncounterTier (encounterXpInfo) {
		return this._budgetTierProvider.getEncounterTier(encounterXpInfo);
	}

	getCrCutoff (creatureGroups) {
		// "Once you choose the desired difficulty of your encounter, you can determine its CR budget.
		//   To do so, you'll need to know the average character level of the party (rounding down)."
		const avgPlayerLevel = Math.floor(this.avgPlayerLevel);
		const ix = Math.max(
			0,
			Math.min(
				LEVEL_CR_CAP.length - 1,
				avgPlayerLevel - 1,
			),
		);
		return LEVEL_CR_CAP[ix];
	}

	// Unused in Flee, Mortals! rules
	getPlayerAdjustedSpendMultiplier (cntCreatures) { return 1; }
}

