import {EncounterPartyPlayerMeta} from "../encounterbuilder-models-other.js";
import {EncounterBuilderRandomizerTemplated} from "../randomizer/encounterbuilder-randomizer-templated.js";
import {BUDGET_MODE_CR, BUDGET_MODE_XP} from "../consts/encounterbuilder-consts.js";
import {EncounterbuilderAdjusterTemplated} from "../adjuster/encounterbuilder-adjuster-slots.js";
import {SITE_STYLE__CLASSIC, SITE_STYLE__ONE} from "../../consts.js";
import {EncounterBuilderTtkClassic} from "../ttk/encounterbuilder-ttk-classic.js";
import {EncounterbuilderTtkOne} from "../ttk/encounterbuilder-ttk-one.js";
import {ENCOUNTER_SHAPE_CUSTOM_NAME, ENCOUNTER_SHAPE_CUSTOM_SOURCE, ENCOUNTER_SHAPE_RANDOM_NAME, ENCOUNTER_SHAPE_RANDOM_SOURCE} from "../encounterbuilder-consts.js";

export class TierHtmlProviderBase {
	_budgetMode;
	_tierTitles;

	getTierName ({tier}) {
		return Parser.encounterDifficultyToCn(tier);
	}

	getTierHtml ({partyMeta, tier}) {
		const title = this.getTierTitle({tier});
		const ptTierName = this.getTierName({tier}) || "?";
		const ptTierBudget = partyMeta.cntPlayers
			? (partyMeta?.getTierDisplayBudget(tier) || "?")
			: "?";

		return `<span class="ve-help-subtle" ${title ? `title="${title}"` : ""}>${ptTierName}:</span> ${ptTierBudget} ${this._getBudgetUnit()}`;
	}

	getTierTitle ({tier}) {
		return this._tierTitles[tier] || "";
	}

	_getBudgetUnit () {
		switch (this._budgetMode) {
			case BUDGET_MODE_XP: return "XP";
			case BUDGET_MODE_CR: return "CR";
			default: throw new Error(`Unhandled budget mode "${this._budgetMode}"!`);
		}
	}

	/* -------------------------------------------- */

	_getPtRatioSpentPct ({ratioSpent}) {
		const ptPct = (ratioSpent * 100).toFixed(2).replace(/\.0+$/, "")
			.padStart(3, "\u2007");

		return `<span class="ve-mr-1">${ptPct}%</span>`;
	}

	getSpentHtml (
		{
			partyMeta,
			tier,
			ratioSpent = null,
		},
	) {
		if (!partyMeta || !tier || ratioSpent == null) return "";

		const ptTierBudgetSpent = partyMeta.getTierDisplayBudget(tier, {multiplier: ratioSpent});
		const ptTierBudgetTotal = partyMeta.getTierDisplayBudget(tier);

		return `${this._getPtRatioSpentPct({ratioSpent})} <span class="ve-small ve-muted">(${ptTierBudgetSpent}/${ptTierBudgetTotal} ${this._getBudgetUnit()})</span>`;
	}

	getGroupSpentHtml (
		{
			partyMeta,
			tier,
			ratioSpent,
			cntMin,
			cntMax,
		},
	) {
		if (!partyMeta || !tier || ratioSpent == null) return "";

		const unit = this._getBudgetUnit();

		if (cntMin === cntMax || !ratioSpent) {
			const ptTierBudgetSpent = partyMeta.getTierDisplayBudget(tier, {multiplier: ratioSpent});
			const ptTierBudgetSpentPerCreature = cntMin
				? partyMeta.getTierDisplayBudget(tier, {multiplier: ratioSpent / cntMin})
				: 0;
			return `<span class="ve-small ve-small-caps ve-split-v-center" title="${ptTierBudgetSpentPerCreature} ${unit} Per Creature (${ptTierBudgetSpent} ${unit} Total)">
				${this._getPtRatioSpentPct({ratioSpent})}
				<span class="ve-muted">(${ptTierBudgetSpentPerCreature} ${unit} ea.)</span>
			</span>`;
		}

		const ptTierBudgetSpentPerCreatureMin = cntMin
			? partyMeta.getTierDisplayBudget(tier, {multiplier: ratioSpent / cntMin})
			: 0;
		const ptTierBudgetSpentMin = cntMin
			? partyMeta.getTierDisplayBudget(tier, {multiplier: ratioSpent})
			: 0;
		const ptTierBudgetSpentPerCreatureMax = cntMax
			? partyMeta.getTierDisplayBudget(tier, {multiplier: ratioSpent / cntMax})
			: 0;
		const ptTierBudgetSpentMax = cntMax
			? partyMeta.getTierDisplayBudget(tier, {multiplier: ratioSpent})
			: 0;
		return `<span class="ve-small ve-small-caps ve-split-v-center" title="${ptTierBudgetSpentPerCreatureMin}\u2013${ptTierBudgetSpentPerCreatureMax} ${unit} Per Creature (${ptTierBudgetSpentMin}\u2013${ptTierBudgetSpentMax} ${unit} Total)">
			${this._getPtRatioSpentPct({ratioSpent})}
			<span class="ve-muted">(${ptTierBudgetSpentPerCreatureMin}\u2013${ptTierBudgetSpentPerCreatureMax} ${unit} ea.)</span>
		</span>`;
	}
}

/**
 * @abstract
 */
export class EncounterBuilderRulesBase extends BaseComponent {
	rulesId;
	displayName;
	_tierHtmlProvider;

	_budgetMode;

	constructor (
		{
			comp,
			cache,
			encounterShapesLookup,
			rendererWrapped,
		},
	) {
		if (!rendererWrapped) throw new Error(`Missing required "rendererWrapped" option!`);

		super();

		this._comp = comp;
		this._cache = cache;
		this._encounterShapesLookup = encounterShapesLookup;
		this._rendererWrapped = rendererWrapped;
	}

	/* -------------------------------------------- */

	getBudgetMode () { return this._budgetMode; }

	isCustomEncounterShape () { return this._state.shapeHashRandom === UrlUtil.URL_TO_HASH_BUILDER["encounterShape"]({name: ENCOUNTER_SHAPE_CUSTOM_NAME, source: ENCOUNTER_SHAPE_CUSTOM_SOURCE}); }

	/* -------------------------------------------- */

	addHookOnSave (hk) { return this._addHookAll("state", hk); }

	addHookTierRandom (hk) { return this._addHookBase("tierRandom", hk); }
	addHookShapeHashRandom (hk) { return this._addHookBase("shapeHashRandom", hk); }

	/* -------------------------------------------- */

	setStateFrom (toLoad, isOverwrite = false) {
		if (!toLoad) return super.setStateFrom(toLoad, isOverwrite);

		if (!this._encounterShapesLookup.getEncounterShape(toLoad.state.shapeHashRandom)) {
			toLoad.state.shapeHashRandom = UrlUtil.URL_TO_HASH_BUILDER["encounterShape"]({name: ENCOUNTER_SHAPE_RANDOM_NAME, source: ENCOUNTER_SHAPE_RANDOM_SOURCE});
		}

		super.setStateFrom(toLoad, isOverwrite);
	}

	/* -------------------------------------------- */

	/**
	 * @abstract
	 * @return void
	 */
	render ({stgSettingsRules, stgRandomAndAdjust, stgGroup, stgDifficulty}) { throw new Error("Unimplemented!"); }

	/* -------------------------------------------- */

	/**
	 * @abstract
	 * @return string
	 */
	getDisplaySummary () { throw new Error("Unimplemented!"); }

	/* -------------------------------------------- */

	/**
	 * @abstract
	 * @param {?number} ratioSpent
	 * @param {?EncounterPartyMetaBase} partyMeta
	 * @return string
	 */
	getDisplayBudgetSpent (
		{
			ratioSpent,
			partyMeta = null,
		},
	) {
		partyMeta ??= this.getEncounterPartyMeta();

		return this._tierHtmlProvider.getSpentHtml({
			partyMeta,
			tier: this._state.tierRandom,
			ratioSpent,
		});
	}

	/**
	 * @abstract
	 * @param {number} ratioSpent
	 * @param {EncounterPartyMetaBase} partyMeta
	 * @param {?number} cntMin
	 * @param {?number} cntMax
	 * @return string
	 */
	getDisplayGroupBudgetSpent (
		{
			ratioSpent,
			partyMeta = null,
			cntMin = null,
			cntMax = null,
		},
	) {
		partyMeta ??= this.getEncounterPartyMeta();

		return this._tierHtmlProvider.getGroupSpentHtml({
			partyMeta,
			tier: this._state.tierRandom,
			ratioSpent,
			cntMin,
			cntMax,
		});
	}

	/* -------------------------------------------- */

	async _pDoGenerateRandomEncounter ({shapeHash, tier}) {
		const partyMeta = this.getEncounterPartyMeta();

		const {budgetMin, budgetMax} = partyMeta.getBudgetRange(tier);

		const randomizer = new EncounterBuilderRandomizerTemplated({
			partyMeta,
			cache: this._cache,
			budgetMin,
			budgetMax,
			budgetMode: this._budgetMode,
			encounterShapesLookup: this._encounterShapesLookup,
			encounterShapeHash: shapeHash,
		});

		const randomCreatureGroups = await randomizer.pGetRandomEncounter({
			creatureGroupsLocked: this._comp.creatureGroups.filter(creatureGroup => creatureGroup.getIsLocked()),
		});

		if (randomCreatureGroups != null) this._comp.creatureGroups = randomCreatureGroups;
	}

	async _pDoAdjustEncounter ({tier}) {
		const partyMeta = this.getEncounterPartyMeta();

		const {budgetMin, budgetMax} = partyMeta.getBudgetRangeApprox(tier);

		const adjuster = new EncounterbuilderAdjusterTemplated({
			partyMeta,
			cache: this._cache,
			budgetMin,
			budgetMax,
			budgetMode: this._budgetMode,
		});

		const adjustedCreatureGroups = await adjuster.pGetAdjustedEncounter({
			creatureGroups: this._comp.creatureGroups,
		});

		if (adjustedCreatureGroups != null) this._comp.creatureGroups = adjustedCreatureGroups;
	}

	/* -------------------------------------------- */

	_getRenderedWrpRandomAndAdjust (
		{
			tiers,
		},
	) {
		const stgRandom = this._getRenderedWrpRandomAndAdjust_getStgRandom({tiers})
			.vee.addClass("ve-mobile-lg__mb-2");
		const stgAdjust = this._getRenderedWrpRandomAndAdjust_getAdjustMeta({tiers});

		return veT`<div class="ve-flex-col">
			<div class="ve-flex-v-center ve-mobile-lg__flex-col ve-mobile-lg__flex-ai-start">
				${stgRandom}

				<div class="ve-vr-2 ve-min-h-24p ve-mobile-lg__hidden"></div>

				${stgAdjust}
			</div>
		</div>`
			.vee.hide();
	}

	_getRenderedWrpRandomAndAdjust_getStgRandom ({tiers}) {
		const selTier = ComponentUiUtil.getSelEnum(
			this,
			"tierRandom",
			{
				html: `<select class="ve-form-control ve-h-34p ve-br-0"></select>`,
				values: tiers,
				fnDisplay: val => Parser.encounterDifficultyToCn(val),
			},
		);

		const selShapeType = ComponentUiUtil.getSelEnum(
			this,
			"shapeHashRandom",
			{
				html: `<select class="ve-form-control ve-h-34p ve-br-0 ve-w-100"></select>`,
				values: this._encounterShapesLookup.getHashList(),
				fnDisplay: val => this._encounterShapesLookup.getEncounterShape(val).name,
			},
		);

		const btnGenerate = veT`<button class="ve-btn ve-btn-primary ve-h-34p" title="Generate Encounter"><span class="glyphicon glyphicon-play"></span></button>`
			.vee.onn("click", async () => {
				if (
					this._encounterShapesLookup.isCustomEncounterHash(this._state.shapeHashRandom)
				) {
					if (!this._comp.customShapeGroups?.length) return JqueryUtil.doToast({type: "warning", content: `Your custom encounter does not contain any creature groups! Please add a creature group first.`});
					if (this._comp.customShapeGroups.map(({entity}) => entity.ratioPercentage).sum() !== 100) return JqueryUtil.doToast({type: "warning", content: `Your custom encounter has un-allocated budget! Please allocate the full budget first.`});
				}

				await this._pDoGenerateRandomEncounter({
					shapeHash: this._state.shapeHashRandom,
					tier: this._state.tierRandom,
				});
			});

		return veT`<div class="ve-flex-v-center ve-input-group ve-w-100">
			${selTier}
			${selShapeType}
			${btnGenerate}
		</div>`;
	}

	_getRenderedWrpRandomAndAdjust_getBtnSendToFoundry () {
		if (globalThis.IS_VTT || !ExtensionUtil.ACTIVE) return null;

		return veT`<button title="Send to Foundry" class="no-print ve-btn ve-btn-md ve-btn-default ve-ml-2"><span class="glyphicon glyphicon-send"></span></button>`
			.vee.onn("click", async () => {
				const encounterActorName = await InputUiUtil.pGetUserString({title: "Encounter Actor Name", isSkippable: true});

				await ExtensionUtil.pDoSend({
					type: "5etools.encounterbuilder.encounter",
					data: {
						encounterActorName,
						creatureMetasSerial: this._comp.creatureGroups
							.map(({entity}) => ({
								creature: entity.creature,
								count: entity.count,
							})),
					},
				});
			});
	}

	_getRenderedWrpRandomAndAdjust_getAdjustMeta ({tiers}) {
		const getButtonText = tier => `调整至${Parser.encounterDifficultyToCn(tier)}难度`;
		const getButtonTitle = tier => `调整当前遭遇至${Parser.encounterDifficultyToCn(tier)}难度`;

		const pSetTier = async ({tier = null} = {}) => {
			if (tier) this._state.tierAdjust = tier;

			await this._pDoAdjustEncounter({tier: this._state.tierAdjust});
		};

		const btn = veT`<button class="ve-btn ve-btn-primary ecgen__btn-adjust"></button>`
			.vee.onn("click", async evt => {
				evt.preventDefault();
				await pSetTier();
			});

		this._addHookBase("tierAdjust", () => {
			btn
				.vee.txt(getButtonText(this._state.tierAdjust))
				.vee.tooltip(getButtonTitle(this._state.tierAdjust));
		})();

		const menu = ContextUtil.getMenu(
			tiers
				.map(tier => new ContextUtil.Action(
					getButtonText(tier),
					async () => pSetTier({tier}),
					{
						title: getButtonTitle(tier),
					},
				)),
		);

		const dispCaret = veT`<span class="ve-caret"></span>`;
		menu.on("open", () => dispCaret.vee.addClass("ve-caret--up"));
		menu.on("close", () => dispCaret.vee.removeClass("ve-caret--up"));

		const btnMenu = veT`<button class="ve-btn ve-btn-primary ve-w-24p ve-px-0">${dispCaret}</button>`
			.vee.onn("click", evt => {
				if (menu.isOpen()) {
					evt.preventDefault();
					evt.stopPropagation();
					return menu.close();
				}

				const bcr = btnMenu.getBoundingClientRect();
				return ContextUtil.pOpenMenu(evt, menu, {
					xPos: (window.innerWidth - bcr.right) + window.scrollX,
					isFromRight: true,
					yPos: bcr.bottom + window.scrollY + 1,
				});
			});

		const btnSendToFoundry = this._getRenderedWrpRandomAndAdjust_getBtnSendToFoundry();

		return veT`<div class="ve-flex-v-center ve-relative ve-no-shrink">
			<div class="ve-btn-group ve-flex-v-center">
				${btn}
				${btnMenu}
			</div>
			${btnSendToFoundry}
		</div>`;
	}

	/* -------------------------------------------- */

	_getRenderedDispsTierMeta ({tiers}) {
		const dispsLookup = Object.fromEntries(
			tiers
				.map(tier => [tier, veT`<div></div>`]),
		);

		const onHookPulseDeriverPartyMeta = ({partyMeta}) => {
			const encounterXpInfo = partyMeta.getEncounterSpendInfo(this._comp.creatureGroups);

			const tier = partyMeta.getEncounterTier(encounterXpInfo);

			Object.entries(dispsLookup)
				.forEach(([tier_, disp]) => {
					disp
						.vee.toggleClass("ve-bold", tier === tier_)
						.vee.html(
							this._tierHtmlProvider.getTierHtml({
								partyMeta,
								tier: tier_,
							}),
						);
				});
		};

		return {
			disps: tiers.map(tier => dispsLookup[tier]),
			onHookPulseDeriverPartyMeta,
		};
	}

	/* -------------------------------------------- */

	static _TITLE_XP_TO_NEXT_LEVEL = "小队内每位成员升级到下一等级所需的合计XP。";

	_getRenderedExpToLevel ({partyMeta}) {
		return `<span class="ve-help-subtle" title="${this.constructor._TITLE_XP_TO_NEXT_LEVEL}">升级所需XP:</span> ${partyMeta?.xpToNextLevel ? partyMeta?.xpToNextLevel.toLocaleStringVe() : "?"} XP`;
	}

	/* -------------------------------------------- */

	getEncounterPartyMeta () { return this._getEncounterPartyMeta(this._comp.getPartyPlayerMetas()); }

	/**
	 * @abstract
	 * @param {Array<EncounterPartyPlayerMeta>} playerMetas
	 * @return {EncounterPartyMetaBase}
	 */
	_getEncounterPartyMeta (playerMetas) { throw new Error("Unimplemented!"); }

	/* -------------------------------------------- */

	static _TITLE_TTK = "击杀时间（Time to Kill）:小队完成此遭遇的预估轮数（假设都是单目标伤害的情况）";

	_getTtkProvider ({partyMeta, styleHint}) {
		const sharedOpts = {partyMeta, creatureGroups: this._comp.creatureGroups};

		switch (styleHint) {
			case SITE_STYLE__CLASSIC: return new EncounterBuilderTtkClassic(sharedOpts);
			case SITE_STYLE__ONE: return new EncounterbuilderTtkOne(sharedOpts);
			default: throw new Error(`Unhandled style "${styleHint}"!`);
		}
	}

	_getTtkHtml ({partyMeta, styleHint = null}) {
		styleHint ||= VetoolsConfig.get("styleSwitcher", "style");

		const ptTtk = partyMeta.cntPlayers
			? `${this._getTtkProvider({partyMeta, styleHint}).getApproxTurnsToKill().toFixed(2)} <span title="Rounds" class="ve-small-caps">rnd.</span>`
			: `<span class="ve-muted">?</span>`;

		return `<span class="ve-help" title="${this.constructor._TITLE_TTK}">TTK:</span> ${ptTtk}`;
	}

	/* -------------------------------------------- */

	doCleanup () { /* Implement as required */ }

	/* -------------------------------------------- */

	_getDefaultState () {
		return {
			tierRandom: null,
			shapeHashRandom: UrlUtil.URL_TO_HASH_BUILDER["encounterShape"]({name: ENCOUNTER_SHAPE_RANDOM_NAME, source: ENCOUNTER_SHAPE_RANDOM_SOURCE}),
		};
	}
}

import {EncounterBuilderRulesBase, TierHtmlProviderBase} from "./encounterbuilder-rules-base.js";
import {EncounterPartyMetaClassic} from "../partymeta/encounter-partymeta-classic.js";
import {TIER_ABSURD, TIER_DEADLY, TIER_EASY, TIER_HARD, TIER_MEDIUM, TIERS, TIERS_EXTENDED} from "../consts/encounterbuilder-consts-classic.js";
import {BUDGET_MODE_XP} from "../consts/encounterbuilder-consts.js";
import {EncounterbuilderUiThermometer} from "../encounterbuilder-ui-thermometer.js";

class _TierHtmlProviderClassic extends TierHtmlProviderBase {
	_budgetMode = BUDGET_MODE_XP;
	_tierTitles = {
		easy: "一次简单的遭遇不会消耗角色们的资源或给他们带来严重的危险。他们可能会失去一点生命值，但是胜利还是相当有保障的。",
		medium: "一次中等的遭遇通常会让玩家们经历一两次惊心时刻，但是不会对角色们造成任何伤亡。只是其中若干人员可能会需要使用治疗资源。",
		hard: "对冒险者们而言，一次困难的遭遇可能会发展得很糟糕。较弱的角色可能会在战斗中被清除，甚至有较小的可能导致一个或多个角色因此死亡。",
		deadly: "对某些玩家而言，致命的遭遇可以造成足以致命的后果。此时需要优秀的策略和快速的思考才能确保生还，而队伍失败时也必须承当相应的风险。",
		absurd: "“荒谬”的遭遇按规则来说属于致命的遭遇，但在此处单独划分一类，旨在提供一种额外的工具，用于精准判断某场 “致命” 遭遇的实际致命程度。其XP的计算方式为：致命 +（致命 - 困难）",
	};
}

class _EncounterBuilderUiHelp {
	static getHelpEntry ({partyMeta, encounterSpendInfo}) {
		return {
			type: "entries",
			entries: [
				`{@b Adjusted by a ${encounterSpendInfo.playerAdjustedSpendMult}× multiplier, based on a minimum challenge rating threshold of approximately ${`${encounterSpendInfo.crCutoff.toFixed(2)}`.replace(/[,.]?0+$/, "")}*&dagger;, and a party size of ${encounterSpendInfo.playerCount} players.}`,
				// `{@note * If the maximum challenge rating is two or less, there is no minimum threshold. Similarly, if less than a third of the party are level 5 or higher, there is no minimum threshold. Otherwise, for each creature in the encounter, the average CR of the encounter is calculated while excluding that creature. The highest of these averages is then halved to produce a minimum CR threshold. CRs less than this minimum are ignored for the purposes of calculating the final CR multiplier.}`,
				`{@note * If the maximum challenge rating is two or less, there is no minimum threshold. Similarly, if less than a third of the party are level 5 or higher, there is no minimum threshold. Otherwise, for each creature in the encounter in lowest-to-highest CR order, the average CR of the encounter is calculated while excluding that creature. Then, if the removed creature's CR is more than one deviation less than  this average, the process repeats. Once the process halts, this threshold value (average minus one deviation) becomes the final CR cutoff.}`,
				`<hr>`,
				{
					type: "quote",
					entries: [
						`&dagger; [...] don't count any monsters whose challenge rating is significantly below the average challenge rating of the other monsters in the group [...]`,
					],
					"by": `{@book ${Parser.sourceJsonToFull(Parser.SRC_DMG)}, page 82|DMG|3|4 Modify Total XP for Multiple Monsters}`,
				},
				`<hr>`,
				{
					"type": "table",
					"caption": "Encounter Multipliers",
					"colLabels": [
						"Number of Monsters",
						"Multiplier",
					],
					"colStyles": [
						"col-6 text-center",
						"col-6 text-center",
					],
					"rows": [
						[
							"1",
							"×1",
						],
						[
							"2",
							"×1.5",
						],
						[
							"3-6",
							"×2",
						],
						[
							"7-10",
							"×2.5",
						],
						[
							"11-14",
							"×3",
						],
						[
							"15 or more",
							"×4",
						],
					],
				},
				...(partyMeta && partyMeta.cntPlayers < 3
					? [
						{
							type: "quote",
							entries: [
								"If the party contains fewer than three characters, apply the next highest multiplier on the Encounter Multipliers table.",
							],
							"by": `{@book ${Parser.sourceJsonToFull(Parser.SRC_DMG)}, page 83|DMG|3|Party Size}`,
						},
					]
					: partyMeta && partyMeta.cntPlayers >= 6
						? [
							{
								type: "quote",
								entries: [
									"If the party contains six or more characters, use the next lowest multiplier on the table. Use a multiplier of 0.5 for a single monster.",
								],
								"by": `{@book ${Parser.sourceJsonToFull(Parser.SRC_DMG)}, page 83|DMG|3|Party Size}`,
							},
						]
						: []
				),
			],
		};
	}
}

export class EncounterBuilderRulesClassic extends EncounterBuilderRulesBase {
	rulesId = "classic";
	displayName = "经典 (5e/2014)";
	_tierHtmlProvider = new _TierHtmlProviderClassic();

	_budgetMode = BUDGET_MODE_XP;

	render ({stgSettingsRules, stgRandomAndAdjust, stgGroupSummary, stgDifficulty}) {
		const {wrpSettingsRules} = this._render_settingsRules({stgSettingsRules});
		const {wrpRandomAndAdjust} = this._render_randomAndAdjust({stgRandomAndAdjust});
		const {wrpGroupSummary} = this._render_groupSummary({stgGroupSummary});
		const {wrpDifficulty} = this._render_difficulty({stgDifficulty});

		return {
			eles: [
				wrpSettingsRules,
				wrpRandomAndAdjust,
				wrpGroupSummary,
				wrpDifficulty,
			],
		};
	}

	_render_settingsRules ({stgSettingsRules}) {
		const wrpSettingsRules = veT`<div class="ve-flex-col">
			<div class="ve-flex ve-mb-2">${this._rendererWrapped.er(`{@note 基于{@book ${Parser.sourceJsonToFull(Parser.SRC_DMG)}|DMG|3|创建战斗遭遇}}第81页的“遭遇构筑”规则`)}</div>
		</div>`
			.vee.appendTo(stgSettingsRules);

		return {
			wrpSettingsRules,
		};
	}

	_render_randomAndAdjust ({stgRandomAndAdjust}) {
		const wrpRandomAndAdjust = this._getRenderedWrpRandomAndAdjust({
			tiers: TIERS,
		});

		wrpRandomAndAdjust.vee.appendTo(stgRandomAndAdjust);

		return {wrpRandomAndAdjust};
	}

	/* -------------------------------------------- */

	static _TITLE_BUDGET_DAILY = "粗略预估小队成员进行一次长休前能够完成的遭遇XP";

	_render_groupSummary ({stgGroupSummary}) {
		const {
			disps: dispsTierXp,
			onHookPulseDeriverPartyMeta: onHookPulseDeriverPartyMetaTierXp,
		} = this._getRenderedDispsTierMeta({
			tiers: TIERS_EXTENDED,
		});

		const thermometer = new EncounterbuilderUiThermometer({
			tierHtmlProvider: this._tierHtmlProvider,
			tiers: TIERS_EXTENDED,
			tiersActionable: TIERS,
			thresholdColors: {
				[TIER_EASY]: MiscUtil.COLOR_HEALTHY,
				[TIER_MEDIUM]: MiscUtil.COLOR_HURT,
				[TIER_HARD]: MiscUtil.COLOR_BLOODIED,
				[TIER_DEADLY]: MiscUtil.COLOR_DEFEATED,
				[TIER_ABSURD]: MiscUtil.COLOR_DEAD,
			},
			pFnDoGenerateRandomEncounter: this._pDoGenerateRandomEncounter.bind(this),
			pFnDoAdjustEncounter: this._pDoAdjustEncounter.bind(this),
		});

		const dispTtk = veT`<div></div>`;

		const dispBudgetDaily = veT`<div></div>`;
		const dispExpToLevel = veT`<div class="ve-muted"></div>`;

		const dispThermometer = thermometer.render()
			.vee.addClass("ve-mt-2");

		this._comp.addHookPulseDeriverPartyMeta(() => {
			const partyMeta = this.getEncounterPartyMeta();
			const encounterSpendInfo = partyMeta.getEncounterSpendInfo(this._comp.creatureGroups);
			const tier = partyMeta.getEncounterTier(encounterSpendInfo);

			onHookPulseDeriverPartyMetaTierXp({partyMeta});

			const spendCap = partyMeta.getBudgetRange(TIER_ABSURD).budgetMin + (partyMeta.getBudgetRange(TIER_ABSURD).budgetMin - partyMeta.getBudgetRange(TIER_DEADLY).budgetMin);
			thermometer.setInfo({
				spendValue: encounterSpendInfo.adjustedSpend,
				spendCap,
				thresholds: Object.fromEntries(
					TIERS_EXTENDED
						.map(tier => [tier, tier === TIER_ABSURD ? spendCap : partyMeta.getBudget(tier)]),
				),
				tier: tier,
				cntPlayers: partyMeta.cntPlayers,
			});

			dispTtk
				.vee.html(this._getTtkHtml({partyMeta}));

			dispBudgetDaily
				.vee.html(`<span class="ve-help-subtle" title="${this.constructor._TITLE_BUDGET_DAILY}">每日XP:</span> ${partyMeta?.getDailyBudget() ? partyMeta.getDailyBudget().toLocaleStringVe() : `?`} XP`);

			dispExpToLevel.vee.html(this._getRenderedExpToLevel({partyMeta}));
		})();

		const wrpGroupSummary = veT`<div class="ve-text-right">
			${dispsTierXp}
			${dispThermometer}
			<hr class="ve-hr-2">
			${dispTtk}
			<hr class="ve-hr-2">
			${dispBudgetDaily}
			${dispExpToLevel}
		</div>`
			.vee.hide()
			.vee.appendTo(stgGroupSummary);

		return {
			wrpGroupSummary,
		};
	}

	/* -------------------------------------------- */

	_render_difficulty ({stgDifficulty}) {
		const hrHasCreatures = veT`<hr class="ve-hr-1">`;
		const wrpDifficultyCols = veT`<div class="ve-flex">
			${this._renderGroupAndDifficulty_getDifficultyLhs()}
			${this._renderGroupAndDifficulty_getDifficultyRhs()}
		</div>`;

		this._comp.addHookPulseDeriverPartyMeta(() => {
			const encounterSpendInfo = this.getEncounterPartyMeta().getEncounterSpendInfo(this._comp.creatureGroups);
			hrHasCreatures.vee.toggle(encounterSpendInfo.relevantCount);
			wrpDifficultyCols.vee.toggle(encounterSpendInfo.relevantCount);
		})();

		const wrpDifficulty = veT`<div class="ve-flex-col ve-w-100">
			${hrHasCreatures}
			${wrpDifficultyCols}
		</div>`
			.vee.hide()
			.vee.appendTo(stgDifficulty);

		return {
			wrpDifficulty,
		};
	}

	_renderGroupAndDifficulty_getDifficultyLhs () {
		const dispDifficulty = veT`<h4 class="ve-my-2"></h4>`;

		this._comp.addHookPulseDeriverPartyMeta(() => {
			const partyMeta = this.getEncounterPartyMeta();

			const encounterSpendInfo = partyMeta.getEncounterSpendInfo(this._comp.creatureGroups);

			const tier = partyMeta.getEncounterTier(encounterSpendInfo);

			dispDifficulty
				.vee.html(`难度: <span class="ve-help-subtle">${Parser.encounterDifficultyToCn(tier)}</span>`)
				.vee.tooltip(new _TierHtmlProviderClassic().getTierTitle({tier}));
		})();

		return veT`<div class="ve-w-50">
			${dispDifficulty}
		</div>`;
	}

	_renderGroupAndDifficulty_getDifficultyRhs () {
		const dispXpRawTotal = veT`<h4></h4>`;
		const dispXpRawPerPlayer = veT`<i></i>`;

		const hovXpAdjustedInfo = veT`<span class="glyphicon glyphicon-info-sign ve-mr-2"></span>`;

		const dispXpAdjustedTotal = veT`<h4 class="ve-flex-v-center"></h4>`;
		const dispXpAdjustedPerPlayer = veT`<i></i>`;

		let infoHoverId = null;
		this._comp.addHookPulseDeriverPartyMeta(() => {
			const partyMeta = this.getEncounterPartyMeta();

			const encounterSpendInfo = partyMeta.getEncounterSpendInfo(this._comp.creatureGroups);

			dispXpRawTotal.vee.txt(`合计XP: ${encounterSpendInfo.baseSpend?.toLocaleStringVe() || "?"}`);
			dispXpRawPerPlayer.vee.txt(
				partyMeta?.cntPlayers
					? `每位玩家 (${Math.floor(encounterSpendInfo.baseSpend / partyMeta?.cntPlayers)?.toLocaleStringVe()})`
					: "",
			);

			const infoEntry = _EncounterBuilderUiHelp.getHelpEntry({partyMeta, encounterSpendInfo});

			if (infoHoverId == null) {
				const hoverMeta = Renderer.hover.getMakePredefinedHover(infoEntry, {isBookContent: true});
				infoHoverId = hoverMeta.id;

				hovXpAdjustedInfo
					.vee.off("mouseover")
					.vee.off("mousemove")
					.vee.off("mouseleave")
					.vee.onn("mouseover", function (event) { hoverMeta.mouseOver(event, this); })
					.vee.onn("mousemove", function (event) { hoverMeta.mouseMove(event, this); })
					.vee.onn("mouseleave", function (event) { hoverMeta.mouseLeave(event, this); });
			} else {
				Renderer.hover.updatePredefinedHover(infoHoverId, infoEntry);
			}

			dispXpAdjustedTotal.vee.html(`Adjusted XP <span class="ve-small ve-muted ve-ml-2" title="XP Multiplier">(×${encounterSpendInfo.playerAdjustedSpendMult})</span>: <b class="ve-ml-2">${encounterSpendInfo.adjustedSpend.toLocaleStringVe()}</b>`);

			dispXpAdjustedPerPlayer.vee.txt(
				partyMeta?.cntPlayers
					? `(每位玩家${Math.floor(encounterSpendInfo.adjustedSpend / partyMeta.cntPlayers).toLocaleStringVe()})`
					: "",
			);
		})();

		return veT`<div class="ve-w-50 ve-text-right">
			${dispXpRawTotal}
			<div>${dispXpRawPerPlayer}</div>
			<div class="ve-flex-v-center ve-flex-h-right">${hovXpAdjustedInfo}${dispXpAdjustedTotal}</div>
			<div>${dispXpAdjustedPerPlayer}</div>
		</div>`;
	}

	_getEncounterPartyMeta (playerMetas) {
		return new EncounterPartyMetaClassic(playerMetas);
	}

	/* -------------------------------------------- */

	getDisplaySummary () {
		const encounterXpInfo = this
			.getEncounterPartyMeta()
			.getEncounterSpendInfo(this._comp.creatureGroups);

		return [
			`${encounterXpInfo.baseSpend.toLocaleStringVe()} XP`,
			encounterXpInfo.baseSpend !== encounterXpInfo.adjustedSpend
				? `(<span class="ve-help" title="Adjusted Encounter XP">Enc</span>: ${encounterXpInfo.adjustedSpend.toLocaleStringVe()} XP)`
				: "",
		]
			.filter(Boolean)
			.join(" ");
	}

	/* -------------------------------------------- */

	_getDefaultState () {
		return {
			...super._getDefaultState(),
			tierRandom: TIER_MEDIUM,
			tierAdjust: TIER_MEDIUM,
		};
	}
}

