			.getEncounterSpendInfo(this._comp.creatureGroups);

		return `<span title="Total Encounter CR">${Parser.numberToVulgar(encounterXpInfo.baseSpend)} CR</span> (${this._getEncounterXp().toLocaleStringVe()} XP)`;
