		},
	) {
		this._partyMeta = partyMeta;
		this._spendKeys = spendKeys;
		this._budgetMin = budgetMin;
		this._budgetMax = budgetMax;
		this._budgetMode = budgetMode;

		this._creatureGroupsLocked = creatureGroupsLocked;
	}

	/**
	 * @abstract
	 * @return {EncounterTemplateOptions}
	 */
	getEncounterTemplateInfo () { throw new Error("Unimplemented!"); }

	_getMaxCreatureCount ({cntMin, cntLockedCreatures}) {
		const cntMax = Math.ceil(this._partyMeta.cntPlayers * 2.2);

		// If we would use all our expected count on locked creatures, attempt to add 1-3 extra creatures
		if (cntMax <= cntMin) return cntLockedCreatures + 3;
		return cntMax;
	}

	_getMaxDesiredCreatureTypes () {
		// 2-5 different creature types is the core desirable range
		let cnt = RollerUtil.randomise(4) + 1;
		if (cnt < 5) return cnt;
		// On a 5, repeated 1/4 chance of adding +1 creature type
		while (RollerUtil.randomise(4) === 4) ++cnt;
		return cnt;
	}

	/**
	 * @return {_CategorizedCreatureSlotBundles}
	 */
	_getCategorizedCreatureSlotBundles ({creatureSlotBundles}) {
		const creatureSlotBundleMetas = creatureSlotBundles
			.map(creatureSlotBundle => {
				const cntCreatures = creatureSlotBundle
					.map(slot => slot.count)
					.sum();
				const playerAdjustedSpendMult = this._partyMeta.getPlayerAdjustedSpendMultiplier(cntCreatures);

				return {
					creatureSlotBundle,
					spendTotal: creatureSlotBundle
						.map(creatureSlot => creatureSlot.getTotalSpend({playerAdjustedSpendMult}))
						.sum(),
				};
			});

		// If there are templates which fit in the expected min-max range, prefer these
		// Otherwise, prefer templates with the smallest distance from the min-max range
		const minDelta = Math.min(
			...creatureSlotBundleMetas
				.map(({spendTotal}) => Math.abs(this._budgetMin - spendTotal)),
		);
		const closestSpendTotal = this._budgetMin - minDelta;

		return {
			creatureSlotBundlesIdeal: creatureSlotBundleMetas
				.filter(({spendTotal}) => spendTotal >= this._budgetMin)
				.map(({creatureSlotBundle}) => creatureSlotBundle),
			creatureSlotBundlesFallback: creatureSlotBundleMetas
				.filter(({spendTotal}) => spendTotal === closestSpendTotal)
				.map(({creatureSlotBundle}) => creatureSlotBundle),
		};
	}

	_getTemplateOptions ({categorizedCreatureSlotBundlesBase, categorizedCreatureSlotBundlesAdditional}) {
		const isPreferAdditional = Math.random() < 0.15;

		const getByProp = (prop) => {
			const isBase = !!categorizedCreatureSlotBundlesBase?.[prop]?.length;
			const isAdditional = !!categorizedCreatureSlotBundlesAdditional?.[prop]?.length;

			if (isAdditional && isBase) {
				if (isPreferAdditional) return categorizedCreatureSlotBundlesAdditional[prop];
				else return categorizedCreatureSlotBundlesBase[prop];
			}
			if (isBase) return categorizedCreatureSlotBundlesBase[prop];
			if (isAdditional) return categorizedCreatureSlotBundlesAdditional[prop];
			return null;
		};

		const inRange = getByProp("creatureSlotBundlesIdeal");
		if (inRange?.length) return inRange;

		return getByProp("creatureSlotBundlesFallback");
	}
}

export class CreatureSlot {
	constructor ({spendAmount, count}) {
		this.spendAmount = spendAmount;
		this.count = count;
	}

	getTotalSpend ({playerAdjustedSpendMult, countAdditional = 0}) { return this.spendAmount * (this.count + countAdditional) * playerAdjustedSpendMult; }
}

export class EncounterTemplateOptions {
	/**
	 * @param {Array<Array<CreatureSlot>>} templateOptions
	 * @param {?string} message
	 * @param {boolean} isUniqueKeys
	 */
	constructor (
		{
			templateOptions = undefined,
			message = undefined,
			isUniqueKeys = false,
		} = {},
	) {
		this.templateOptions = templateOptions;
		this.message = message;
		this.isUniqueKeys = isUniqueKeys;
	}
}

import {EncounterSizer} from "./encounterbuilder-templater-sizer.js";
import {CreatureSlot, EncounterTemplateOptions} from "./encounterbuilder-templater-models.js";
import {EncounterBuilderTemplaterBase} from "./encounterbuilder-templater-base.js";

export class EncounterBuilderTemplaterRandom extends EncounterBuilderTemplaterBase {
	getEncounterTemplateInfo () {
		const cntLockedCreatures = this._creatureGroupsLocked
			.map(creatureGroup => creatureGroup.getCount())
			.sum();

		const lowestSpendAmount = Math.min(...this._spendKeys);
		const lowestNonFreeSpendAmount = this._spendKeys.filter(Boolean).length
			? Math.min(...this._spendKeys.filter(Boolean))
			: null;

		const cntMin = Math.max(1, cntLockedCreatures);
		const cntMax = this._getMaxCreatureCount({cntMin, cntLockedCreatures});

		if (cntMin > cntMax) return new EncounterTemplateOptions({message: "Too many locked creatures! Unlock some, or add more players."});

		const {encounterSizeInfosBase, encounterSizeInfosAdditional} = new EncounterSizer({
			partyMeta: this._partyMeta,
			budgetMin: this._budgetMin,
			budgetMax: this._budgetMax,
			budgetMode: this._budgetMode,
		})
			.getEncounterSizeInfosGroups({
				creatureGroupsLocked: this._creatureGroupsLocked,
				slotSeeds: null,
				cntLockedCreatures,
				lowestSpendAmount,
				lowestNonFreeSpendAmount,
				cntMin,
				cntMax,
			});

		if (!encounterSizeInfosBase.length && !encounterSizeInfosAdditional.length) return new EncounterTemplateOptions();

		const creatureSlotBundlesBase = this._getEncounterMetasCreatureSlotBundles({
			cntLockedCreatures,
			lowestSpendAmount,
			encounterSizeMetas: encounterSizeInfosBase,
		});

		const creatureSlotBundlesAdditional = this._getEncounterMetasCreatureSlotBundles({
			cntLockedCreatures,
			lowestSpendAmount,
			encounterSizeMetas: encounterSizeInfosAdditional,
		});

		return new EncounterTemplateOptions({
			templateOptions: this._getTemplateOptions({
				categorizedCreatureSlotBundlesBase: this._getCategorizedCreatureSlotBundles({
					creatureSlotBundles: creatureSlotBundlesBase,
				}),
				categorizedCreatureSlotBundlesAdditional: this._getCategorizedCreatureSlotBundles({
					creatureSlotBundles: creatureSlotBundlesAdditional,
				}),
			}),
		});
	}

	/**
	 * @return {Array<Array<CreatureSlot>>}
	 */
	_getEncounterMetasCreatureSlotBundles (
		{
			cntLockedCreatures,
			lowestSpendAmount,
			encounterSizeMetas,
		},
	) {
		return encounterSizeMetas
			.map(({cntCreatures, playerAdjustedSpendMult}) => {
				const spendLocked = this._creatureGroupsLocked
					.map(creatureGroup => creatureGroup.getCount() * creatureGroup.getSpend({budgetMode: this._budgetMode}) * playerAdjustedSpendMult)
					.sum();

				const slots = Array.from({length: cntCreatures - cntLockedCreatures}, () => new CreatureSlot({
					spendAmount: lowestSpendAmount,
					count: 1,
				}));

				const cntSlotsDesired = Math.max(1, this._getMaxDesiredCreatureTypes() - this._creatureGroupsLocked.length);
				const slotsMerged = [];
				slots.forEach(slot => {
					if (slotsMerged.length < cntSlotsDesired) return slotsMerged.push(slot);
					RollerUtil.rollOnArray(slotsMerged).count += slot.count;
				});

				const ixsRemaining = [...slotsMerged.keys()];

				while (ixsRemaining.length) {
					const ix = RollerUtil.rollOnArray(ixsRemaining);
					const slotToBump = slotsMerged[ix];
					const spendCur = slotToBump.spendAmount;

					const ixSpendNxt = this._spendKeys.indexOf(spendCur);
					if (!~ixSpendNxt) throw new Error(`Could not find "${spendCur}" in cache keys "${this._spendKeys.join(", ")}. This should never occur!`);

					const spendNxt = this._spendKeys[ixSpendNxt + 1];
					if (spendNxt == null) {
						ixsRemaining.splice(ixsRemaining.indexOf(ix), 1);
						continue;
					}

					slotToBump.spendAmount = spendNxt;

					if (
						(spendLocked + slotsMerged.map(slot => slot.getTotalSpend({playerAdjustedSpendMult})).sum()) > this._budgetMax
					) {
						slotToBump.spendAmount = spendCur;
						ixsRemaining.splice(ixsRemaining.indexOf(ix), 1);
					}
				}

				return slotsMerged;
			});
	}
}

import {EncounterSizer} from "./encounterbuilder-templater-sizer.js";
import {CreatureSlot, EncounterTemplateOptions} from "./encounterbuilder-templater-models.js";
import {EncounterBuilderTemplaterBase} from "./encounterbuilder-templater-base.js";

export class EncounterBuilderTemplaterSeeded extends EncounterBuilderTemplaterBase {
	/**
	 * @param {Array<number>} slotSeeds
	 * @param rest
	 */
	constructor ({slotSeeds, ...rest}) {
		super({...rest});
		this._slotSeeds = slotSeeds;
	}

	getEncounterTemplateInfo () {
		const cntLockedCreatures = this._creatureGroupsLocked
			.map(creatureGroup => creatureGroup.getCount())
			.sum();
		const cntSlotSeeds = this._slotSeeds?.length || 0;

		const lowestSpendAmount = Math.min(...this._slotSeeds);
		const lowestNonFreeSpendAmount = this._slotSeeds.filter(Boolean).length
			? Math.min(...this._slotSeeds.filter(Boolean))
			: null;

		const cntMin = Math.max(1, cntLockedCreatures + cntSlotSeeds);
		const cntMax = this._getMaxCreatureCount({cntMin, cntLockedCreatures});

		if (cntMin > cntMax) return new EncounterTemplateOptions({message: "Too many locked creatures! Unlock some, or add more players."});

		const {encounterSizeInfosBase, encounterSizeInfosAdditional} = new EncounterSizer({
			partyMeta: this._partyMeta,
			budgetMin: this._budgetMin,
			budgetMax: this._budgetMax,
			budgetMode: this._budgetMode,
		})
			.getEncounterSizeInfosGroups({
				creatureGroupsLocked: this._creatureGroupsLocked,
				slotSeeds: this._slotSeeds,
				cntLockedCreatures,
				lowestSpendAmount,
				lowestNonFreeSpendAmount,
				cntMin,
				cntMax,
			});

		if (!encounterSizeInfosBase.length && !encounterSizeInfosAdditional.length) return new EncounterTemplateOptions();

		const creatureSlotBundlesBase = this._getEncounterMetasCreatureSlotBundlesFromSeeds({
			cntLockedCreatures,
			lowestSpendAmount,
			encounterSizeMetas: encounterSizeInfosBase,
		});

		const creatureSlotBundlesAdditional = this._getEncounterMetasCreatureSlotBundlesFromSeeds({
			cntLockedCreatures,
			lowestSpendAmount,
			encounterSizeMetas: encounterSizeInfosAdditional,
		});

		return new EncounterTemplateOptions({
			templateOptions: this._getTemplateOptions({
				categorizedCreatureSlotBundlesBase: this._getCategorizedCreatureSlotBundles({
					creatureSlotBundles: creatureSlotBundlesBase,
				}),
				categorizedCreatureSlotBundlesAdditional: this._getCategorizedCreatureSlotBundles({
					creatureSlotBundles: creatureSlotBundlesAdditional,
				}),
			}),
		});
	}

	/**
	 * @param {number} cntLockedCreatures
	 * @param {Array<_EncounterSizeInfo>} encounterSizeMetas
	 **
	 * @return {Array<Array<CreatureSlot>>}
	 */
	_getEncounterMetasCreatureSlotBundlesFromSeeds (
		{
			cntLockedCreatures,
			encounterSizeMetas,
		},
	) {
		const slotSeeds = [...this._slotSeeds]
			.sort(SortUtil.ascSort);

		const slotSeedsSpendable = [...slotSeeds]
			.reverse()
			.unique();

		return encounterSizeMetas
			.flatMap(({cntCreatures, playerAdjustedSpendMult}) => {
				const spendLocked = this._creatureGroupsLocked
					.map(creatureGroup => creatureGroup.getCount() * creatureGroup.getSpend({budgetMode: this._budgetMode}) * playerAdjustedSpendMult)
					.sum();

				const slots = slotSeeds
					.map(spendAmount => new CreatureSlot({
						spendAmount,
						count: 1,
					}));

				const cntToAdd = cntCreatures - cntLockedCreatures - slotSeeds.length;
				if (cntToAdd < 0) throw new Error(`Should never occur!`);
				if (!cntToAdd) return [slots];

				const spendAmountToSlot = slots
					.reduce((accum, slot) => {
						(accum[slot.spendAmount] ||= []).push(slot);
						return accum;
					}, {});

				const getBudgetSpent = () => slots.map(slot => slot.getTotalSpend({playerAdjustedSpendMult})).sum() - spendLocked;

				const recurseFillSlots = (
					{
						operations,
						cpySlotSeedsSpendable,
						budgetRemaining,
						cntCreaturesAdded,
					},
				) => {
					if (cntCreaturesAdded >= cntToAdd) return cntToAdd - cntCreaturesAdded;
					if (!cpySlotSeedsSpendable.length) return cntToAdd - cntCreaturesAdded;

					for (let ixSlotSeed = 0; ixSlotSeed < cpySlotSeedsSpendable.length; ++ixSlotSeed) {
						const slotSeed = cpySlotSeedsSpendable[ixSlotSeed];
						if ((slotSeed * playerAdjustedSpendMult) > budgetRemaining) continue;

						const slot = RollerUtil.rollOnArray(spendAmountToSlot[slotSeed]);
						slot.count += 1;
						operations.push({slotSeed, slot, ixSlotSeed});

						return recurseFillSlots({
							operations,
							cpySlotSeedsSpendable,
							budgetRemaining: budgetRemaining - (slotSeed * playerAdjustedSpendMult),
							cntCreaturesAdded: cntCreaturesAdded + 1,
						});
					}

					const maxSpend = Math.max(...operations.map(({slotSeed}) => slotSeed));
					const ixUndo = operations.findIndex(({slotSeed}) => slotSeed === maxSpend);

					const [opUndo] = operations.splice(ixUndo, 1);
					if (!opUndo) return cntToAdd - cntCreaturesAdded;

					const {slotSeed, slot} = opUndo;
					slot.count -= 1;

					return recurseFillSlots({
						operations,
						cpySlotSeedsSpendable: cpySlotSeedsSpendable
							.filter(slotSeed_ => slotSeed_ !== slotSeed),
						budgetRemaining: budgetRemaining + (slotSeed * playerAdjustedSpendMult),
						cntCreaturesAdded: cntCreaturesAdded - 1,
					});
				};

				// Try "random spend first", as it produces more interesting results
				const cntToAddUnusedShuffle = recurseFillSlots({
					operations: [],
					cpySlotSeedsSpendable: [...slotSeedsSpendable].shuffle(),
					budgetRemaining: this._budgetMax - getBudgetSpent(),
					cntCreaturesAdded: 0,
				});
				if (!cntToAddUnusedShuffle && getBudgetSpent() >= this._budgetMin) return [slots];

				// If we couldn't find an encounter with "random spend first", reset, and use "largest spend first"
				slots.forEach(slot => slot.count = 1);

				recurseFillSlots({
					operations: [],
					cpySlotSeedsSpendable: [...slotSeedsSpendable],
					budgetRemaining: this._budgetMax - getBudgetSpent(),
					cntCreaturesAdded: 0,
				});

				return [slots];
			});
	}
}

import {CreatureSlot} from "./encounterbuilder-templater-models.js";

class _EncounterSizeInfo {
	constructor ({cntCreatures, playerAdjustedSpendMult, isAboveBudgetMin}) {
		this.cntCreatures = cntCreatures;
		this.playerAdjustedSpendMult = playerAdjustedSpendMult;
		this.isAboveBudgetMin = isAboveBudgetMin;
	}
}

class _EncounterSizeInfosGroup {
	/**
	 * @param {?Array<_EncounterSizeInfo>} encounterSizeInfosBase
	 * @param {?Array<_EncounterSizeInfo>} encounterSizeInfosAdditional
	 */
	constructor ({encounterSizeInfosBase, encounterSizeInfosAdditional} = {}) {
		this.encounterSizeInfosBase = encounterSizeInfosBase || [];
		this.encounterSizeInfosAdditional = encounterSizeInfosAdditional || [];
	}
}

export class EncounterSizer {
	constructor ({partyMeta, budgetMin, budgetMax, budgetMode}) {
		this._partyMeta = partyMeta;
		this._budgetMin = budgetMin;
		this._budgetMax = budgetMax;
		this._budgetMode = budgetMode;
	}

	// This is obviously horribly impractical, but if the user is e.g. attempting to adjust an encounter
	//   of only CR 1/8 creatures for a party of level 20 characters, then they probably expect/want
	//   absurd results.
	// Fighting `2,000× Giant Crab` _is_ pretty funny.
	static _MAX_ENCOUNTER_SIZE = 2_500;

	/**
	 * @return {_EncounterSizeInfosGroup}
	 */
	getEncounterSizeInfosGroups (
		{
			creatureGroupsLocked,
			slotSeeds = null,
			cntLockedCreatures,
			lowestSpendAmount,
			lowestNonFreeSpendAmount = null,
			cntMin,
			cntMax,
		},
	) {
		const seededSlotsMin = slotSeeds
			? [...slotSeeds]
				.sort(SortUtil.ascSort)
				.map(spendAmount => new CreatureSlot({
					spendAmount,
					count: 1,
				}))
			: null;

		// Check both with/without using "free" creatures; this allows us to find solutions which meet the desired number:
		//   - by spamming free creatures
		//   - by avoiding free creatures
		//   - by having a healthy mix of both
		const encounterSizeMetaPairsBase = Array.from({length: (cntMax - cntMin) + 1}, (_, i) => cntMin + i)
			.map(cntCreatures => ({
				encounterSizeMeta: this._getEncounterSizeMeta({
					creatureGroupsLocked,
					cntLockedCreatures,
					lowestSpendAmount,
					seededSlotsMin,
					cntCreatures,
				}),
				encounterSizeMetaNonFree: lowestNonFreeSpendAmount == null
					? null
					: this._getEncounterSizeMeta({
						creatureGroupsLocked,
						cntLockedCreatures,
						lowestSpendAmount: lowestNonFreeSpendAmount,
						seededSlotsMin,
						cntCreatures,
					}),
			}))
			.filter(({encounterSizeMeta}) => encounterSizeMeta);

		// If every option was over budget, bail out
		if (!encounterSizeMetaPairsBase.length) return new _EncounterSizeInfosGroup();

		// If we *only* have "free" creatures, use what we have, as no amount of addition will help
		if (lowestNonFreeSpendAmount == null) {
			return new _EncounterSizeInfosGroup({
				encounterSizeInfosBase: encounterSizeMetaPairsBase
					.map(({encounterSizeMeta}) => encounterSizeMeta),
			});
		}

		// Otherwise, attempt to extend the list until we find something in the exact range (or exhaust the available size options)
		// Always attempt to generate *some* additional size metas, but reduce the amount if we already have any which are valid.
		const encounterSizeMetaPairsAdditional = [];

		// Give up after too many encounters which only work with "free" creatures
		//   If we have seeds, allow for an additional instance of each "free" seed
		const cntAdditional = (slotSeeds || []).filter(slotSeed => !slotSeed).length
			+ Math.max(0, 5 - encounterSizeMetaPairsBase.length)
			+ Math.floor(Math.random() * 8);
		let triesNonFreeMiss = cntAdditional;
		for (let cntCreatures = cntMax + 1; cntCreatures < cntMax + this.constructor._MAX_ENCOUNTER_SIZE; ++cntCreatures) {
			const encounterSizeMeta = this._getEncounterSizeMeta({
				creatureGroupsLocked,
				cntLockedCreatures,
				lowestSpendAmount,
				seededSlotsMin,
				cntCreatures,
			});
			const encounterSizeMetaNonFree = this._getEncounterSizeMeta({
				creatureGroupsLocked,
				cntLockedCreatures,
				lowestSpendAmount: lowestNonFreeSpendAmount,
				seededSlotsMin,
				cntCreatures,
			});

			// Larger encounters don't work; we've exhausted all options
			if (!encounterSizeMeta) break;

			if (!encounterSizeMetaNonFree) {
				if (!--triesNonFreeMiss) break;
			}

			encounterSizeMetaPairsAdditional.push({encounterSizeMeta, encounterSizeMetaNonFree});
		}

		const getRandomItems = (arr, cnt) => {
			if (arr.length <= cnt) return arr;
			const out = [];
			const cpy = arr.slice();
			for (let i = 0; i < cnt; ++i) {
				const ix = RollerUtil.randomise(cpy.length) - 1;
				const [itm] = cpy.splice(ix, 1);
				out.push(itm);
			}
			return out;
		};

		return new _EncounterSizeInfosGroup({
			encounterSizeInfosBase: encounterSizeMetaPairsBase
				.map(({encounterSizeMeta}) => encounterSizeMeta),
			encounterSizeInfosAdditional: getRandomItems(encounterSizeMetaPairsAdditional, cntAdditional)
				.map(({encounterSizeMeta}) => encounterSizeMeta),
		});
	}

	_getEncounterSizeMeta (
		{
			creatureGroupsLocked,
			cntLockedCreatures,
			lowestSpendAmount,
			seededSlotsMin,
			cntCreatures,
		},
	) {
		if (seededSlotsMin && cntCreatures < seededSlotsMin.length) throw new Error(`Should never occur!`);

		const playerAdjustedSpendMult = this._partyMeta.getPlayerAdjustedSpendMultiplier(cntCreatures);

		let spendLocked = 0;
		let spendLowestUnlocked = seededSlotsMin
			? 0
			: (lowestSpendAmount * playerAdjustedSpendMult * cntCreatures);

		// If this number of creatures can never produce a valid encounter, skip it
		if (spendLowestUnlocked > this._budgetMax) return null;

		if (cntLockedCreatures) {
			spendLocked = creatureGroupsLocked
				.map(creatureGroup => creatureGroup.getCount() * creatureGroup.getSpend({budgetMode: this._budgetMode}) * playerAdjustedSpendMult)
				.sum();
			const spendUnlockedMin = lowestSpendAmount * playerAdjustedSpendMult * (cntCreatures - cntLockedCreatures);

			if ((spendLocked + spendUnlockedMin) > this._budgetMax) return null;

			spendLowestUnlocked += spendLocked;
		}

		if (seededSlotsMin) {
			// If we're using seeded slots, add all additional creatures to the cheapest slot,
			//   and check if this could ever be a valid encounter
			const cntAdditionalCheapest = cntCreatures - seededSlotsMin.length;
			const spendSeeded = seededSlotsMin
				.map((slot, i) => slot.getTotalSpend({playerAdjustedSpendMult, countAdditional: i === 0 ? cntAdditionalCheapest : 0}))
				.sum();
			if ((spendLocked + spendSeeded) > this._budgetMax) return null;

			spendLowestUnlocked += spendSeeded;
		}

		return new _EncounterSizeInfo({
			cntCreatures,
			playerAdjustedSpendMult,
			isAboveBudgetMin: spendLowestUnlocked >= this._budgetMin,
		});
	}
}

import {CreatureSlot, EncounterTemplateOptions} from "./encounterbuilder-templater-models.js";
import {EncounterBuilderTemplaterBase} from "./encounterbuilder-templater-base.js";

class _ResolvedEncounterShape {
	constructor ({name, source, groups}) {
		this.name = name;
		this.source = source;
		this.groups = groups;
	}
}

// TODO(Future) support "free" creatures?
export class EncounterbuilderTemplaterTemplated extends EncounterBuilderTemplaterBase {
	constructor ({encounterShape, ...rest}) {
		super({...rest});
		this._encounterShape = encounterShape;
	}

	getEncounterTemplateInfo () {
		if (this._creatureGroupsLocked?.length) return new EncounterTemplateOptions({message: `Only the "Random" encounter type may be used with locked creatures! Unlock your creatures, or use the "Random" encounter type.`});

		const resolvedEncounterShapes = this._getResolvedEncounterShapes();
		if (!resolvedEncounterShapes.length) return new EncounterTemplateOptions({message: `Failed to generate encounter! You may need to add some players first.`});

		const creatureSlotBundles = resolvedEncounterShapes
			.flatMap(encounterShape => {
				const cntCreatures = encounterShape.groups
					.map(group => group.count)
					.sum();

				return this._getPossibleBudgets({cntCreatures})
					.map(budget => {
						let budgetRemaining = budget;

						const creatureSlots = encounterShape.groups
							.map(group => {
								const groupBudget = group.ratio
									? budget * group.ratio
									: budgetRemaining;

								const singleCreatureBudget = groupBudget / group.count;

								const availableSpendKeys = this._spendKeys
									// Don't allow "free" creatures
									// TODO(Future)
									.filter(Boolean)
									.filter(spendKey => spendKey <= singleCreatureBudget);

								if (!availableSpendKeys.length) return null;

								const spendAmount = Math.max(...availableSpendKeys);

								budgetRemaining -= group.count * spendAmount;

								return new CreatureSlot({
									spendAmount,
									count: group.count,
								});
							});

						if (creatureSlots.some(it => it == null)) return null;
						return creatureSlots;
					})
					.filter(Boolean);
			});

		if (!creatureSlotBundles.length) return new EncounterTemplateOptions();

		return new EncounterTemplateOptions({
			templateOptions: this._getTemplateOptions({
				categorizedCreatureSlotBundlesBase: this._getCategorizedCreatureSlotBundles({
					creatureSlotBundles: creatureSlotBundles,
				}),
			}),
			isUniqueKeys: true,
		});
	}

	/* -------------------------------------------- */

	_getNumericalTerm (val) {
		if (val.num != null && val.denom != null) return val.num / val.denom;
		return val;
	}

	_getValueInRange ({min, max, forceMinMax, isRound = false}) {
		if (forceMinMax === "min") return min;
		if (forceMinMax === "max") return max;

		if (max < min) max = min;
		let interp = Math.random() * (max - min);
		if (isRound) interp = Math.round(interp);
		return min + interp;
	}

	_getEvaluatedTerm ({term, forceMinMax = null, isRound = false}) {
		if (term.exact != null) {
			return this._getNumericalTerm(term.exact);
		}

		if (term.min != null && term.max != null) {
			return this._getValueInRange({
				min: this._getNumericalTerm(term.min),
				max: this._getNumericalTerm(term.max),
				forceMinMax,
				isRound,
			});
		}

		if (term.formulaMin != null && term.formulaMax) {
			let [min, max] = [
				term.formulaMin,
				term.formulaMax,
			]
				.map(formula => {
					const out = Renderer.dice.parseRandomise2(formula.replace(/\bplayers\b/g, this._partyMeta.cntPlayers));
					if (isNaN(out)) throw new Error(`Could not evaluate formula "${formula}"!`);
					return out;
				});
			return this._getValueInRange({min, max, forceMinMax, isRound});
		}

		throw new Error(`Unhandled term "${JSON.stringify(term, null, "\t")}"!`);
	}

	_getResolvedEncounterShapes () {
		return this._encounterShape.shapeTemplate
			.flatMap(shapeTemplate => {
				const cpyShapeTemplate = MiscUtil.copyFast(shapeTemplate);

				return this._getResolvedEncounterShapesFromShapeTemplate({
					name: this._encounterShape.name,
					source: this._encounterShape.source,
					shapeTemplate: cpyShapeTemplate,
				});
			})
			.filter(Boolean);
	}

	_getResolvedEncounterShapesFromShapeTemplate ({name, source, shapeTemplate}) {
		if (!this.constructor._isEncounterShapeShapeTemplateVariable({shapeTemplate})) {
			return [
				this._getResolvedEncounterShapeFromTemplate({name, source, shapeTemplate}),
			]
				.filter(Boolean);
		}

		return [
			this._getResolvedEncounterShapeFromTemplate({name, source, shapeTemplate, forceMinMax: "min"}),
			this._getResolvedEncounterShapeFromTemplate({name, source, shapeTemplate}),
			this._getResolvedEncounterShapeFromTemplate({name, source, shapeTemplate, forceMinMax: "max"}),
		]
			.filter(Boolean);
	}

	static _isEncounterShapeShapeTemplateVariable ({shapeTemplate}) {
		return shapeTemplate.groups
			.some(group => {
				return [
					"count",
					"ratio",
				]
					.some(prop => {
						if (group[prop] == null) return false;
						if (group[prop].exact != null) return false;
						return group[prop].min != null || group[prop].formulaMin != null;
					});
			});
	}

	/**
	 * @param name
	 * @param source
	 * @param shapeTemplate
	 * @param {"min" | "max" | null} forceMinMax
	 */
	_getResolvedEncounterShapeFromTemplate ({name, source, shapeTemplate, forceMinMax = null}) {
		const cpyShapeTemplate = MiscUtil.copyFast(shapeTemplate);

		cpyShapeTemplate.groups = cpyShapeTemplate.groups
			.map(group => {
				return {
					...group.count
						? {count: {exact: this._getEvaluatedTerm({term: group.count, forceMinMax, isRound: true})}}
						: {},
					...group.ratio
						? {ratio: {exact: this._getEvaluatedTerm({term: group.ratio, forceMinMax})}}
						: {},
				};
			})
			.filter(group => group.count?.exact);

		if (!cpyShapeTemplate.groups.length) return null;

		this._mutShapeTemplateAddRatios({shapeTemplate: cpyShapeTemplate});

		const resolvedGroups = cpyShapeTemplate.groups
			.map(group => {
				return {
					count: group.count ? this._getEvaluatedTerm({term: group.count, forceMinMax, isRound: true}) : null,
					ratio: group.ratio ? this._getEvaluatedTerm({term: group.ratio, forceMinMax}) : null,
				};
			})
			.filter(group => group.count);

		return new _ResolvedEncounterShape({
			name,
			source,
			groups: resolvedGroups,
		});
	}

	_mutShapeTemplateAddRatios ({shapeTemplate}) {
		const [nonRatioGroups, ratioGroups] = shapeTemplate.groups.segregate(group => group.ratio == null);
		if (!nonRatioGroups.length) return;

		const {usedMinRatio, usedMaxRatio} = ratioGroups
			.reduce((accum, group) => {
				if (group.ratio.exact != null) {
					accum.usedMinRatio += this._getNumericalTerm(group.ratio.exact);
					accum.usedMaxRatio += this._getNumericalTerm(group.ratio.exact);
					return accum;
				}

				if (group.ratio.min != null && group.ratio.max != null) {
					accum.usedMinRatio += this._getNumericalTerm(group.ratio.min);
					accum.usedMaxRatio += this._getNumericalTerm(group.ratio.max);
					return accum;
				}

				throw new Error(`Unhandled group ratio "${JSON.stringify(group.ratio, null, "\t")}"!`);
			}, {usedMinRatio: 0, usedMaxRatio: 0});

		const minRatioToDistribute = Math.max(1 - usedMinRatio, 0);
		const maxRatioToDistribute = Math.max(1 - usedMaxRatio, 0);

		nonRatioGroups
			.forEach(group => {
				if (minRatioToDistribute === maxRatioToDistribute) {
					group.ratio = {exact: minRatioToDistribute / nonRatioGroups.length};
					return;
				}
				group.ratio = {min: minRatioToDistribute / nonRatioGroups.length, max: maxRatioToDistribute / nonRatioGroups.len};
			});
	}

	/* -------------------------------------------- */

	_getPossibleBudgets ({cntCreatures}) {
		const spendMultiplier = this._partyMeta.getPlayerAdjustedSpendMultiplier(cntCreatures);

		return this._getPossibleBudgetsPreMultiplier()
			.map(budget => budget / spendMultiplier);
	}

	_getPossibleBudgetsPreMultiplier () {
		if (this._budgetMin === this._budgetMax) return [this._budgetMin];

		const deltaBudget = this._budgetMax - this._budgetMin;
		const cntInterpPoints = 4; // 20%, 40%, 60%, 80%
		const fudgeAmount = 1 / (cntInterpPoints + 1) / 2; // 10% fudge, applied as +/- 5%

		return [
			this._budgetMin, // 0%
			...Array.from({length: cntInterpPoints})
				.map((_, i) => {
					const fudgedMult = ((i + 1) / (cntInterpPoints + 1))
						- fudgeAmount
						+ (Math.random() * fudgeAmount);
					return this._budgetMin + (deltaBudget * fudgedMult);
				}),
			this._budgetMax, // 100%
		];
	}
}

