import {FilterRegistry} from "../filter-registry.js";

/** @abstract */
export class FilterBase extends BaseComponent {
	/** @type {FilterBox} */
	_filterBox = null;

	/** @type {FilterSnapshotManager} */
	_snapshotManager = null;

	/**
	 * @param opts
	 * @param opts.header Filter header (name)
	 * @param [opts.headerDisplayName] Filter display name
	 * @param [opts.headerHelp] Filter header help text (tooltip)
	 */
	constructor (opts) {
		super();

		this.header = opts.header;
		this._headerDisplayName = opts.headerDisplayName;
		this._headerHelp = opts.headerHelp;
		this.cnHeader = opts.cnHeader;

		this.__meta = {...this.getDefaultMeta()};
		this._meta = this._getProxy("meta", this.__meta);

		this.__uiMeta = {...this.getDefaultUiMeta()};
		this._uiMeta = this._getProxy("uiMeta", this.__uiMeta);

		this._hasUserSavedState = false;
		this._fnsTeardown = [];
	}

	_getHeaderDisplayName () {
		return this.cnHeader || this._headerDisplayName || this.header;
	}

	_getRenderedHeader () {
		return `<span ${this._headerHelp ? `title="${this._headerHelp.escapeQuotes()}" class="ve-help-subtle"` : ""}>${this._getHeaderDisplayName()}</span>`;
	}

	set filterBox (it) { this._filterBox = it; }
	set snapshotManager (it) { this._snapshotManager = it; }

	show () { this._uiMeta.isHidden = false; }
	hide () { this._uiMeta.isHidden = true; }

	addHookAllState (hk) {
		this._addHookAll("state", hk);
	}

	getBaseSaveableState () {
		return {
			meta: {...this.__meta},
			uiMeta: {...this.__uiMeta},
		};
	}

	_getNextState_base () {
		return {
			[this.header]: {
				state: MiscUtil.copyFast(this.__state),
				meta: MiscUtil.copyFast(this.__meta),
				uiMeta: MiscUtil.copyFast(this.__uiMeta), // read-only
			},
		};
	}

	setStateFromNextState (nxtState) {
		this._proxyAssignSimple("state", nxtState[this.header].state, true);
		this._proxyAssignSimple("meta", nxtState[this.header].meta, true);
	}

	reset ({isResetAll = false, snapshots = null} = {}) {
		const nxtState = this.getResetState({isResetAll, snapshots});
		this.setStateFromNextState(nxtState);
	}

	getResetState ({isResetAll = false, snapshots = null} = {}) {
		const nxtState = this._getNextState_base();
		this._mutNextState_reset({nxtState, isResetAll});
		this._mutNextState_fromSnapshots({nxtState, isResetAll, snapshots});
		return nxtState;
	}

	_mutNextState_resetBase ({nxtState, isResetAll = false}) {
		Object.assign(nxtState[this.header].meta, MiscUtil.copy(this.getDefaultMeta()));
	}

	getMetaSubHashes () {
		const compressedMeta = this._getCompressedMeta();
		if (!compressedMeta) return null;
		return [UrlUtil.packSubHash(this.getSubHashPrefix("meta", this.header), compressedMeta)];
	}

	_mutNextState_meta_fromSubHashState (nxtState, subHashState) {
		const hasMeta = this._mutNextState_meta_fromSubHashState_mutGetHasMeta(nxtState, subHashState, this.getDefaultMeta());
		if (!hasMeta) this._mutNextState_resetBase({nxtState});
	}

	_mutNextState_meta_fromSubHashState_mutGetHasMeta (nxtState, state, defaultMeta) {
		let hasMeta = false;

		Object.entries(state)
			.forEach(([k, vals]) => {
				const prop = FilterBase.getProp(k);
				if (prop !== "meta") return;

				hasMeta = true;
				const data = vals.map(v => UrlUtil.mini.decompress(v));
				Object.keys(defaultMeta).forEach((k, i) => {
					if (data[i] !== undefined) nxtState[this.header].meta[k] = data[i];
					else nxtState[this.header].meta[k] = defaultMeta[k];
				});
			});

		return hasMeta;
	}

	setBaseStateFromLoaded (toLoad) {
		Object.assign(this._meta, toLoad.meta);
		if (toLoad.uiMeta) Object.assign(this._uiMeta, toLoad.uiMeta);
	}

	getSubHashPrefix (prop, header) {
		if (FilterBase._SUB_HASH_PREFIXES[prop]) {
			const prefix = this._filterBox.getNamespacedHashKey(FilterBase._SUB_HASH_PREFIXES[prop]);
			return `${prefix}${header.toUrlified()}`;
		}
		throw new Error(`Unknown property "${prop}"`);
	}

	static getProp (prefix) {
		return Parser._parse_bToA(FilterBase._SUB_HASH_PREFIXES, prefix);
	}

	_getBtnMobToggleControls (wrpControls) {
		const btnMobToggleControls = veE({
			tag: "button",
			clazz: `ve-btn ve-btn-xs ve-btn-default ve-mobile-sm__visible ve-ml-auto ve-px-3 ve-mr-2`,
			html: `<span class="glyphicon glyphicon-option-vertical"></span>`,
			click: () => this._uiMeta.isMobileHeaderHidden = !this._uiMeta.isMobileHeaderHidden,
		});
		const hkMobHeaderHidden = () => {
			btnMobToggleControls.vee.toggleClass("ve-active", !this._uiMeta.isMobileHeaderHidden);
			wrpControls.vee.toggleClass("ve-mobile-sm__hidden", !!this._uiMeta.isMobileHeaderHidden);
		};
		this._addHook("uiMeta", "isMobileHeaderHidden", hkMobHeaderHidden);
		hkMobHeaderHidden();

		return btnMobToggleControls;
	}

	getChildFilters () { return []; }

	/**
	 * @abstract
	 * @return {object}
	 */
	getDefaultMeta () { throw new Error("Unimplemented!"); }
	getDefaultUiMeta () { return {...FilterBase._DEFAULT_UI_META}; }

	/**
	 * @param vals Previously-read filter value may be passed in for performance.
	 */
	isActive (vals) {
		vals = vals || this.getValues();
		return vals[this.header]._isActive;
	}

	_getCompressedMeta () {
		const defaultMeta = this.getDefaultMeta();
		const isAnyNotDefault = Object.keys(defaultMeta).some(k => this._meta[k] !== defaultMeta[k]);
		if (!isAnyNotDefault) return null;

		let keys = Object.keys(defaultMeta);

		// Pop keys from the end if they match the default value
		while (keys.length && defaultMeta[keys.last()] === this._meta[keys.last()]) keys.pop();

		return keys.map(k => UrlUtil.mini.compress(this._meta[k] === undefined ? defaultMeta[k] : this._meta[k]));
	}

	_getBtnShowHide ({isMulti = false} = {}) {
		return veE({
			tag: "button",
			clazz: `ve-btn ve-btn-default ${isMulti ? "ve-btn-xxs" : "ve-btn-xs"}`,
			click: () => this._uiMeta.isHidden = !this._uiMeta.isHidden,
			html: I18nUtil.get("common.button.hide"),
		});
	}

	_getBtnMenu ({isMulti = false} = {}) {
		if (isMulti) return null;

		let menu = null;

		return veE({
			tag: "button",
			clazz: `ve-btn ve-btn-default ve-btn-xs`,
			click: evt => {
				if (!menu) {
					this._fnsTeardown.push(() => {
						ContextUtil.deleteMenu(menu);
						menu = null;
					});
				}

				menu ||= ContextUtil.getMenu([
					new ContextUtil.Action(
						"Take Snapshot",
						async () => {
							await this._snapshotManager.pHandleClick_takeSnapshot({
								filters: [this],
								nameDefault: this._getHeaderDisplayName(),
							});
						},
					),
					new ContextUtil.Action(
						"Take Snapshot and Add to Default Deck",
						async () => {
							await this._snapshotManager.pHandleClick_takeSnapshotToDefaultDeck({
								filters: [this],
								nameDefault: this._getHeaderDisplayName(),
							});
						},
					),
					null,
					new ContextUtil.Action(
						"Manage Snapshots",
						async () => {
							await this._snapshotManager.pHandleClick_manageSnapshots({activeTab: "snapshots"});
						},
					),
				]);

				ContextUtil.pOpenMenu(evt, menu).then(null);
			},
			html: `<span title="其他选项" class="glyphicon glyphicon-option-vertical"></span>`,
		});
	}

	/* -------------------------------------------- */

	_getStateNotDefault_generic ({nxtState = null, isIgnoreSnapshot = false} = {}) {
		const state = nxtState?.[this.header]?.state || this.__state;

		return Object.entries(state)
			.filter(([k, v]) => {
				if (k.startsWith("_")) return false;
				const defState = this._getDefaultItemState(k, {isIgnoreSnapshot});
				return defState !== v;
			});
	}

	/* -------------------------------------------- */

	_getSnapshots_generic () {
		return [
			{
				header: this.header,
				state: this._getSnapshots_state(),
				meta: this._getSnapshots_meta(),
			},
		];
	}

	_getSnapshots_state () {
		return Object.fromEntries(
			// Ignore snapshot, as we want to diff against the built-in state
			this._getStateNotDefault({isIgnoreSnapshot: true}),
		);
	}

	_getSnapshots_meta () {
		const metaDefault = this.getDefaultMeta();

		return Object.fromEntries(
			Object.entries(this.__meta)
				.filter(([k, v]) => metaDefault[k] !== v),
		);
	}

	/* -------------------------------------------- */

	isAnySnapshotRelevant ({snapshots}) {
		const snapshotsFilter = (snapshots || []).filter(snapshot => snapshot.header === this.header);
		return !!snapshotsFilter.length;
	}

	/* -------------------------------------------- */

	_mutNextState_fromSnapshots_generic ({nxtState, snapshots = null}) {
		const snapshotsFilter = (snapshots || []).filter(snapshot => snapshot.header === this.header);

		MiscUtil.getOrSet(nxtState, this.header, "state", {});
		MiscUtil.getOrSet(nxtState, this.header, "meta", {});

		// Apply snapshots in order listed
		snapshotsFilter
			.forEach(snapshot => {
				this._mutNextState_fromSnapshots_state({nxtState, snapshot});
				this._mutNextState_fromSnapshots_meta({nxtState, snapshot});
			});
	}

	_mutNextState_fromSnapshots_state_generic ({nxtState, snapshot}) {
		const appliedKeys = new Set(Object.keys(snapshot.state || {}));

		Object.entries(snapshot.state || {})
			.forEach(([k, v]) => nxtState[this.header].state[k] = v);

		Object.keys(nxtState[this.header].state)
			.filter(k => !appliedKeys.has(k))
			// Ignore snapshot, as we want to diff against the built-in defaults
			.forEach(k => nxtState[this.header].state[k] = this._getDefaultItemState(k, {isIgnoreSnapshot: true}));
	}

	_mutNextState_fromSnapshots_meta_generic ({nxtState, snapshot}) {
		const appliedKeys = new Set(Object.keys(snapshot.meta || {}));

		Object.entries(snapshot.meta || {})
			.forEach(([k, v]) => nxtState[this.header].meta[k] = v);

		const defaultMeta = this.getDefaultMeta();
		Object.entries(defaultMeta)
			.filter(([k]) => !appliedKeys.has(k))
			.forEach(([k, v]) => nxtState[this.header].meta[k] = v);
	}

	/* -------------------------------------------- */

	doTeardown () {
		this._fnsTeardown.forEach(fn => fn());
		this._fnsTeardown = [];
		this._doTeardown();
	}

	/* -------------------------------------------- */

	_getDisplayStatePart_getHeader ({isPlainText = false} = {}) {
		if (isPlainText) return `${this._getHeaderDisplayName()}: `;
		return `<span class="ve-text-right ve-w-140p ve-no-shrink ve-mr-2 ve-bold">${this._getHeaderDisplayName()}:</span>`;
	}

	/* -------------------------------------------- */

	/**
	 * @param {?object} nxtState
	 * @param {boolean} isIgnoreSnapshot
	 * @return {boolean}
	 */
	isAnyStateNotDefault ({nxtState = null, isIgnoreSnapshot = false} = {}) {
		const anyNotDefault = this._getStateNotDefault({nxtState, isIgnoreSnapshot});
		return !!anyNotDefault.length;
	}

	/* -------------------------------------------- */

	/** @abstract */
	render () { throw new Error(`Unimplemented!`); }
	/** @abstract */
	renderMinis () { throw new Error(`Unimplemented!`); }

	/** @abstract */
	getValues ({nxtState = null} = {}) { throw new Error(`Unimplemented!`); }

	/** @abstract */
	getSnapshots () { throw new Error(`Unimplemented!`); }

	/**
	 * @abstract
	 * @param {object} nxtState
	 * @param {boolean} isResetAll
	 * @return {void}
	 */
	_mutNextState_reset ({nxtState, isResetAll = false}) { throw new Error(`Unimplemented!`); }
	/**
	 * @abstract
	 * @param {object} nxtState
	 * @param {?Array<object>} snapshots
	 * @return {void}
	 */
	_mutNextState_fromSnapshots ({nxtState, snapshots = null}) { throw new Error("Unimplemented!"); }
	/**
	 * @abstract
	 * @param {object} nxtState
	 * @param {object} snapshot
	 * @return {void}
	 */
	_mutNextState_fromSnapshots_state ({nxtState, snapshot}) { throw new Error("Unimplemented!"); }
	/**
	 * @abstract
	 * @param {object} nxtState
	 * @param {object} snapshot
	 * @return {void}
	 */
	_mutNextState_fromSnapshots_meta ({nxtState, snapshot}) { throw new Error("Unimplemented!"); }

	/**
	 * @abstract
	 * @param {object} nxtState
	 * @param {boolean} isIgnoreSnapshot
	 * @return {object}
	 */
	_getStateNotDefault ({nxtState = null, isIgnoreSnapshot = false} = {}) { throw new Error("Unimplemented!"); }
	/**
	 * @abstract
	 * @param {string} k
	 * @param {boolean} isIgnoreSnapshot
	 * @return {*}
	 */
	_getDefaultItemState (k, {isIgnoreSnapshot = false} = {}) { throw new Error("Unimplemented!"); }

	/** @abstract */
	update () { throw new Error(`Unimplemented!`); }
	/** @abstract */
	toDisplay () { throw new Error(`Unimplemented!`); }
	/** @abstract */
	addItem () { throw new Error(`Unimplemented!`); }
	/**
	 * @abstract
	 * N.B.: due to a bug in Chrome, these return a copy of the underlying state rather than a copy of the proxied state
	 */
	getSaveableState () { throw new Error(`Unimplemented!`); }
	/** @abstract */
	setStateFromLoaded () { throw new Error(`Unimplemented!`); }
	/** @abstract */
	getSubHashes () { throw new Error(`Unimplemented!`); }
	/** @abstract */
	getNextStateFromSubhashState () { throw new Error(`Unimplemented!`); }
	/** @abstract */
	setFromValues () { throw new Error(`Unimplemented!`); }
	/** @abstract */
	handleSearch () { throw new Error(`Unimplemented!`); }
	/** @abstract */
	getFilterTagPart () { throw new Error(`Unimplemented`); }
	/**
	 * @abstract
	 * @param {?object} nxtState
	 * @param {boolean} isIgnoreSnapshot
	 * @return {?string}
	 */
	getDisplayStatePart ({nxtState = null, isIgnoreSnapshot = false} = {}) { throw new Error(`Unimplemented`); }
	/**
	 * @abstract
	 * @param {?object} nxtState
	 * @param {boolean} isIgnoreSnapshot
	 * @param {boolean} isPlainText
	 * @return {Array<string>}
	 */
	getDisplayStatePartsHtml ({nxtState = null, isIgnoreSnapshot = false} = {}) { throw new Error(`Unimplemented`); }
	/** @abstract */
	getSnapshotPreviews (snapshots) { throw new Error(`Unimplemented`); }
	_doTeardown () { /* No-op */ }
	trimState_ () { /* No-op */ }
}

FilterBase._DEFAULT_UI_META = {
	isHidden: false,
	isMobileHeaderHidden: true,
};

// These are assumed to be the same length (4 characters)
FilterBase._SUB_HASH_STATE_PREFIX = "flst";
FilterBase._SUB_HASH_META_PREFIX = "flmt";
FilterBase._SUB_HASH_NESTS_HIDDEN_PREFIX = "flnh";
FilterBase._SUB_HASH_OPTIONS_PREFIX = "flop";
FilterBase._SUB_HASH_PREFIXES = {
	state: FilterBase._SUB_HASH_STATE_PREFIX,
	meta: FilterBase._SUB_HASH_META_PREFIX,
	nestsHidden: FilterBase._SUB_HASH_NESTS_HIDDEN_PREFIX,
	options: FilterBase._SUB_HASH_OPTIONS_PREFIX,
};

FilterRegistry.registerSubhashes(Object.values(FilterBase._SUB_HASH_PREFIXES));

import {FilterItem, FilterItemBase, FilterItemRegistry} from "../filter-item.js";
import {FilterBase} from "./filter-filter-base.js";
import {MISC_FILTER_VALUE__BASIC_RULES_2014, MISC_FILTER_VALUE__BASIC_RULES_2024, MISC_FILTER_VALUE__SRD_5_1, MISC_FILTER_VALUE__SRD_5_2, PILL_STATE__IGNORE, PILL_STATE__NO, PILL_STATE__YES, PILL_STATES, getPillStateDisplayClass} from "../filter-constants.js";
import {FilterUtils} from "../filter-utils.js";

class FilterTransientOptions {
	/**
	 * @param opts Options object.
	 * @param [opts.isExtendDefaultState]
	 */
	constructor (opts) {
		this.isExtendDefaultState = opts.isExtendDefaultState;
	}
}

export class CompSearch extends BaseComponent {
	_getDefaultState () {
		return {
			searchTermParent: "",
		};
	}
}

export class Filter extends FilterBase {
	static _getAsFilterItem (item) {
		if (item instanceof FilterItemBase) return item;
		if (FilterItemRegistry.isSerialized(item)) return FilterItemRegistry.getDeserialized(item);
		return new FilterItem({item});
	}

	static _getAsFilterItems (items) {
		return items ? items.map(it => this._getAsFilterItem(it)) : null;
	}

	static _getEntryVal_getFIlterItemItem (entryVal) {
		return entryVal != null && typeof entryVal === "object"
			? entryVal.item
			: entryVal;
	}

	static _getEntryVal_isIgnoreRed (entryVal) {
		return entryVal != null
			&& typeof entryVal === "object"
			&& entryVal.isIgnoreRed;
	}

	static _validateItemNests (items, nests) {
		if (!nests) return;
		items = items.filter(it => it.nest);
		const noNest = items.find(it => !nests[it.nest]);
		if (noNest) throw new Error(`Filter does not have matching nest: "${noNest.item}" (call addNest first)`);
		const invalid = items.find(it => !it.nest || !nests[it.nest]);
		if (invalid) throw new Error(`Invalid nest: "${invalid.item}"`);
	}

	/** A single-item version of the above, for performance. */
	static _validateItemNest (item, nests) {
		if (!nests || !item.nest) return;
		if (!nests[item.nest]) throw new Error(`Filter does not have matching nest: "${item.item}" (call addNest first)`);
		if (!item.nest || !nests[item.nest]) throw new Error(`Invalid nest: "${item.item}"`);
	}

	/**
	 * @param opts Options object.
	 * @param opts.header Filter header (name)
	 * @param [opts.headerHelp] Filter header help text (tooltip)
	 * @param opts.items Array of filter items, as strings, `FilterItem` instances, or serialized filter-item objects. E.g. `["DMG", "VGM"]`.
	 * @param [opts.nests] Key-value object of `"Nest Name": {...nestMeta}`. Nests are used to group/nest filters.
	 * @param [opts.displayFn] Function which translates an item to a displayable form, e.g. `"MM` -> "Monster Manual"`
	 * @param [opts.displayFnMini] Function which translates an item to a shortened displayable form, e.g. `"UABravoCharlie` -> "UABC"`
	 * @param [opts.displayFnTitle] Function which translates an item to a form for displaying in a "title" tooltip
	 * @param [opts.selFn] Function which returns true if an item should be displayed by default; false otherwise.
	 * @param [opts.deselFn] Function which returns true if an item should be hidden by default; false otherwise.
	 * @param [opts.itemSortFn] Function which should be used to sort the `items` array if new entries are added.
	 *        Defaults to ascending alphabetical sort.
	 * @param [opts.itemSortFnMini] Function which should be used to sort the `items` array when rendering mini-pills.
	 * @param [opts.groupFn] Function which takes an item and assigns it to a group.
	 * @param [opts.groupNameFn] Function which takes a group and returns a group name;
	 * @param [opts.minimalUi] True if the filter should render with a reduced UI, false otherwise.
	 * @param [opts.umbrellaItems] Items which should, when set active, show everything in the filter. E.g. "All".
	 * @param [opts.umbrellaExcludes] Items which should ignore the state of any `umbrellaItems`
	 * @param [opts.isSortByDisplayItems] If items should be sorted by their display value, rather than their internal value.
	 * @param [opts.pFnOnChange] Function to be run when a filter item changes.
	 * @param [opts.isMiscFilter] If this is the Misc. filter (containing "SRD" and "Basic Rules" tags).
	 * @param [opts.compSearch] Component responsible for managing search term update propagation.
	 */
	constructor (opts) {
		super(opts);
		this._items = Filter._getAsFilterItems(opts.items || []);
		this.__itemsSet = new Set(this._items.map(it => it.item)); // Cache the items as a set for fast exists checking
		this._nests = opts.nests;
		this._displayFn = opts.displayFn;
		this._displayFnMini = opts.displayFnMini;
		this._displayFnTitle = opts.displayFnTitle;
		this._selFn = opts.selFn;
		this._selFnCache = null;
		this._deselFn = opts.deselFn;
		this._itemSortFn = opts.itemSortFn === undefined ? SortUtil.ascSort : opts.itemSortFn;
		this._itemSortFnMini = opts.itemSortFnMini;
		this._groupFn = opts.groupFn;
		this._groupNameFn = opts.groupNameFn;
		this._minimalUi = opts.minimalUi;
		this._umbrellaItems = Filter._getAsFilterItems(opts.umbrellaItems);
		this._umbrellaExcludes = Filter._getAsFilterItems(opts.umbrellaExcludes);
		this._isSortByDisplayItems = !!opts.isSortByDisplayItems;
		this._pFnOnChange = opts.pFnOnChange;
		this._isReprintedFilter = !!opts.isMiscFilter && this._items.some(it => it.item === "重印" || it.item === "Reprinted");
		this._isSrdFilter = !!opts.isMiscFilter && this._items.some(it => it.item === MISC_FILTER_VALUE__SRD_5_1 || it.item === MISC_FILTER_VALUE__SRD_5_2);
		this._isBasicRulesFilter = !!opts.isMiscFilter && this._items.some(it => it.item === MISC_FILTER_VALUE__BASIC_RULES_2014 || it.item === MISC_FILTER_VALUE__BASIC_RULES_2024);

		Filter._validateItemNests(this._items, this._nests);

		this._filterBox = null;
		this._items.forEach(it => this._defaultItemState(it, {isForce: true}));
		this.__wrpFilter = null;
		this.__wrpPills = null;

		this.__wrpMiniPills = null;
		this._miniPillItemsHooked = new Set();
		this._miniPillAnchor = null;
		this._pMiniPillsRender = null;

		this.__wrpNestHeadInner = null;
		this._updateNestSummary = null;
		this.__nestsHidden = {};
		this._nestsHidden = this._getProxy("nestsHidden", this.__nestsHidden);
		this._isNestsDirty = false;
		this._isItemsDirty = false;
		this._pillGroupsMeta = {};

		this._compSearch = opts.compSearch || new CompSearch();
	}

	get isReprintedFilter () { return this._isReprintedFilter; }
	get isSrdFilter () { return this._isSrdFilter; }
	get isBasicRulesFilter () { return this._isBasicRulesFilter; }

	getSaveableState () {
		return {
			[this.header]: {
				...this.getBaseSaveableState(),
				state: {...this.__state},
				nestsHidden: {...this.__nestsHidden},
			},
		};
	}

	_getMigratedLoadedState (state, {isUserSavedState = false} = {}) {
		if (!state) return state;

		const out = {...state};

		if (this._isReprintedFilter) {
			// Legacy typo compatibility: drop the old key rather than preserving its state, as older broken versions
			// could persist a bad "exclude reprinted" state which empties pages like Spells.
			delete out["重置"];

			// One-time repair for already-migrated bad states: if the user's saved state only excludes "重印",
			// treat it as corrupted legacy state and clear it.
			if (isUserSavedState) {
				const activeEntries = Object.entries(out).filter(([, v]) => !!v);
				if (
					activeEntries.length === 1
					&& (activeEntries[0][0] === "重印" || activeEntries[0][0] === "Reprinted")
					&& activeEntries[0][1] === PILL_STATE__NO
				) {
					delete out[activeEntries[0][0]];
				}
			}
		}

		return out;
	}

	setStateFromLoaded (filterState, {isUserSavedState = false} = {}) {
		if (!filterState?.[this.header]) return;

		const toLoad = filterState[this.header];
		this._hasUserSavedState = this._hasUserSavedState || isUserSavedState;
		this.setBaseStateFromLoaded(toLoad);
		Object.assign(this._state, this._getMigratedLoadedState(toLoad.state, {isUserSavedState}));
		Object.assign(this._nestsHidden, toLoad.nestsHidden);
	}

	_getStateNotDefault ({nxtState = null, isIgnoreSnapshot = false} = {}) {
		return this._getStateNotDefault_generic({nxtState, isIgnoreSnapshot});
	}

	/* -------------------------------------------- */

	getSubHashes ({isAllowNonExtension = false} = {}) {
		const subhashesExtension = this._getSubHashes_asExtension();
		if (!isAllowNonExtension || subhashesExtension == null) return subhashesExtension;

		const subhashesNonExtension = this._getSubHashes_asNonExtension();
		if (subhashesNonExtension == null) return subhashesExtension;

		if (subhashesExtension.join("").length < subhashesNonExtension.join("")) return subhashesExtension;
		return subhashesNonExtension;
	}

	_getSubHashes_getSerializedStateSubhash (kvEntries) {
		// serialize state as `key=value` pairs
		const serPillStates = kvEntries.map(([k, v]) => `${k.toUrlified()}=${v}`);
		return UrlUtil.packSubHash(this.getSubHashPrefix("state", this.header), serPillStates);
	}

	_getSubHashes_asExtension () {
		const out = [];

		const baseMeta = this.getMetaSubHashes();
		if (baseMeta) out.push(...baseMeta);

		// Ignore snapshot, as subhashes need to be portable
		const areNotDefaultState = this._getStateNotDefault({isIgnoreSnapshot: true});
		if (areNotDefaultState.length) {
			out.push(this._getSubHashes_getSerializedStateSubhash(areNotDefaultState));
		}

		const areNotDefaultNestsHidden = Object.entries(this._nestsHidden).filter(([k, v]) => this._nests[k] && !(this._nests[k].isHidden === v));
		if (areNotDefaultNestsHidden.length) {
			// serialize nestsHidden as `key=value` pairs
			const nestsHidden = areNotDefaultNestsHidden.map(([k]) => `${k.toUrlified()}=1`);
			out.push(UrlUtil.packSubHash(this.getSubHashPrefix("nestsHidden", this.header), nestsHidden));
		}

		if (!out.length) return null;

		// Always extend default state
		out.push(UrlUtil.packSubHash(this.getSubHashPrefix("options", this.header), ["extend"]));
		return out;
	}

	_getSubHashes_asNonExtension () {
		const out = [];

		const baseMeta = this.getMetaSubHashes();
		// Ignore snapshot, as tags need to be portable
		const areNotDefaultState = this._getStateNotDefault({isIgnoreSnapshot: true});
		const areNotDefaultNestsHidden = Object.entries(this._nestsHidden).filter(([k, v]) => this._nests[k] && !(this._nests[k].isHidden === v));

		if (!baseMeta?.length && !areNotDefaultState.length && !areNotDefaultNestsHidden.length) return null;

		if (baseMeta) out.push(...baseMeta);

		out.push(this._getSubHashes_getSerializedStateSubhash(
			Object.entries(this._state)
				.filter(([k]) => !k.startsWith("_"))
				.filter(([, v]) => v),
		));

		if (areNotDefaultNestsHidden.length) {
			// serialize nestsHidden as `key=value` pairs
			const nestsHidden = areNotDefaultNestsHidden.map(([k]) => `${k.toUrlified()}=1`);
			out.push(UrlUtil.packSubHash(this.getSubHashPrefix("nestsHidden", this.header), nestsHidden));
		}

		if (!out.length) return null;

		return out;
	}

	/* -------------------------------------------- */

	getSnapshots () { return this._getSnapshots_generic(); }

	/* -------------------------------------------- */

	_mutNextState_fromSnapshots ({nxtState, snapshots = null}) { return this._mutNextState_fromSnapshots_generic({nxtState, snapshots}); }
	_mutNextState_fromSnapshots_state ({nxtState, snapshot}) { return this._mutNextState_fromSnapshots_state_generic({nxtState, snapshot}); }
	_mutNextState_fromSnapshots_meta ({nxtState, snapshot}) { return this._mutNextState_fromSnapshots_meta_generic({nxtState, snapshot}); }

	/* -------------------------------------------- */

	getFilterTagPart () {
		// Ignore snapshot, as tags need to be portable
		const areNotDefaultState = this._getStateNotDefault({isIgnoreSnapshot: true});
		const compressedMeta = this._getCompressedMeta();

		// If _any_ value is non-default, we need to include _all_ values in the tag
		// The same goes for meta values
		if (!areNotDefaultState.length && !compressedMeta) return null;

		const pt = Object.entries(this._state)
			.filter(([k]) => !k.startsWith("_"))
			.filter(([, v]) => v)
			.map(([k, v]) => `${v === PILL_STATE__NO ? "!" : ""}${FilterUtils.getEscapedPipes(k)}`)
			.join(";")
			.toLowerCase();

		return [
			this.header.toLowerCase(),
			pt,
			compressedMeta ? compressedMeta.join(HASH_SUB_LIST_SEP) : null,
		]
			.filter(it => it != null)
			.join("=");
	}

	/* -------------------------------------------- */

	getDisplayStatePart ({nxtState = null, isIgnoreSnapshot = false} = {}) {
		const pts = this._getDisplayStateParts({nxtState, isIgnoreSnapshot, isPlainText: true});
		if (!pts.length) return null;
		return pts.join(", ");
	}

	getDisplayStatePartsHtml ({nxtState = null, isIgnoreSnapshot = false} = {}) {
		return this._getDisplayStateParts({nxtState, isIgnoreSnapshot});
	}

	_getDisplayStateParts ({nxtState = null, isIgnoreSnapshot = false, isPlainText = false}) {
		const state = nxtState?.[this.header]?.state || this.__state;

		const areNotDefaultState = this._getStateNotDefault({nxtState, isIgnoreSnapshot});

		// If _any_ value is non-default, we need to include _all_ values in the tag
		if (!areNotDefaultState.length) return [];

		const ptState = Object.entries(state)
			.filter(([k]) => !k.startsWith("_"))
			.filter(([, v]) => v)
			.map(([k, v]) => {
				const item = this._items.find(item => `${item.item}` === k);
				if (!item) return null; // Should never occur

				const dispItem = this._displayFn ? this._displayFn(item.item, item) : item.item;
				return {v, dispItem};
			})
			.filter(Boolean)
			.sort(SortUtil.ascSortLowerProp.bind(SortUtil, "dispItem"))
			.map(({v, dispItem}) => {
				if (isPlainText) return `${v === PILL_STATE__NO ? "not " : ""}${dispItem}`;

				return `<span class="ve-fltr__disp-state ${getPillStateDisplayClass(v)}">${dispItem}</span>`;
			})
			.join(", ");

		if (!ptState) {
			if (isPlainText) return [`${this._getHeaderDisplayName()}: (cleared)`];
			return [
				`${this._getDisplayStatePart_getHeader({isPlainText})}<span class="ve-italic ve-fltr__disp-state ve-fltr__disp-state--ignore">(cleared)</span>`,
			];
		}

		return [
			`${this._getDisplayStatePart_getHeader({isPlainText})}${ptState}`,
		];
	}

	/* -------------------------------------------- */

	getSnapshotPreviews (snapshots) {
		const filterSnapshot = snapshots.find(filterSnapshot => filterSnapshot.header === this.header && Object.keys(filterSnapshot.state || {}).length);
		if (!filterSnapshot) return [];

		// Additionally render any state which this filter shows as non-ignore by default, to present a more useful
		//   overview
		const nonDefaultCurrentState = Object.keys(this._state)
			.map(k => [k, this._getDefaultItemState(k, {isIgnoreSnapshot: true})])
			.filter(([, v]) => v);

		const [entriesWithItems, entriesWithoutItems] = Object.entries(filterSnapshot.state)
			.segregate(([k]) => this.__itemsSet.has(k));

		const ptWithItems = [
			...entriesWithItems,
			...nonDefaultCurrentState,
		]
			.unique(([k]) => k)
			.map(([k, v]) => {
				return {
					item: this._items.find(item => item.item === k),
					v,
				};
			})
			.sort(({item: itemA}, {item: itemB}) => this._itemSortFn ? this._itemSortFn(itemA, itemB) : 0)
			.map(({item, v}) => {
				const rdDisplay = this._getDisplayText(item);
				return `<span class="ve-fltr__pill ve-fltr__pill--display-only" data-state="${PILL_STATES[v]}">${rdDisplay}</span>`;
			})
			.join("");

		const ptWithoutItems = entriesWithoutItems.length
			? `<span class="ve-muted ve-italic ve-fltr__pill ve-fltr__pill--display-only" data-state="${PILL_STATES[PILL_STATE__IGNORE]}">And ${entriesWithoutItems.length} more item${entriesWithoutItems.length === 1 ? "" : "s"}.</span>`
			: "";

		return [
			`<div class="ve-flex-col ve-my-1">
				<h5 class="ve-mt-0 ve-mb-1">${this._getHeaderDisplayName()}</h5>
				<div class="ve-flex-wrap ve-w-100">
					${ptWithItems}${ptWithoutItems}
				</div>
			</div>`,
		];
	}

	/* -------------------------------------------- */

	/**
	 * Get transient options used when setting state from URL.
	 * @private
	 */
	_getOptionsFromSubHashState (state) {
		// `flopsource:thing1~thing2` => `{options: ["thing1", "thing2"]}`
		const opts = {};
		Object.entries(state).forEach(([k, vals]) => {
			const prop = FilterBase.getProp(k);
			switch (prop) {
				case "options": {
					vals.forEach(val => {
						switch (val) {
							case "extend": {
								opts.isExtendDefaultState = true;
							}
						}
					});
				}
			}
		});
		return new FilterTransientOptions(opts);
	}

	setStateFromNextState (nxtState) {
		super.setStateFromNextState(nxtState);
		this._proxyAssignSimple("nestsHidden", nxtState[this.header].nestsHidden, true);
	}

	getNextStateFromSubhashState (state) {
		const nxtState = this._getNextState_base();

		if (state == null) {
			this._mutNextState_reset({nxtState});
			return nxtState;
		}

		this._mutNextState_meta_fromSubHashState(nxtState, state);
		const transientOptions = this._getOptionsFromSubHashState(state);

		let hasState = false;
		let hasNestsHidden = false;

		Object.entries(state).forEach(([k, vals]) => {
			const prop = FilterBase.getProp(k);
			switch (prop) {
				case "state": {
					hasState = true;
					if (transientOptions.isExtendDefaultState) {
						Object.keys(nxtState[this.header].state)
							// Ignore snapshot, as subhashes are portable
							.forEach(k => nxtState[this.header].state[k] = this._getDefaultItemState(k, {isIgnoreSnapshot: true}));
					} else {
						// This allows e.g. @filter tags to cleanly specify their sources
						Object.keys(nxtState[this.header].state).forEach(k => nxtState[this.header].state[k] = PILL_STATE__IGNORE);
					}

					vals.forEach(v => {
						const [statePropLower, state] = v.split("=");
						const stateProp = Object.keys(nxtState[this.header].state).find(k => k.toLowerCase() === statePropLower);
						if (stateProp) nxtState[this.header].state[stateProp] = Number(state);
					});
					break;
				}
				case "nestsHidden": {
					hasNestsHidden = true;
					Object.keys(nxtState[this.header].nestsHidden).forEach(k => {
						const nestKey = Object.keys(this._nests).find(it => k.toLowerCase() === it.toLowerCase());
						nxtState[this.header].nestsHidden[k] = this._nests[nestKey] && this._nests[nestKey].isHidden;
					});
					vals.forEach(v => {
						const [nestNameLower, state] = v.split("=");
						const nestName = Object.keys(nxtState[this.header].nestsHidden).find(k => k.toLowerCase() === nestNameLower);
						if (nestName) nxtState[this.header].nestsHidden[nestName] = !!Number(state);
					});
					break;
				}
			}
		});

		if (!hasState) this._mutNextState_reset({nxtState});
		if (!hasNestsHidden && this._nests) this._mutNextState_resetNestsHidden({tgt: nxtState[this.header].nestsHidden});

		return nxtState;
	}

	setFromValues (values) {
		if (!values[this.header]) return;

		const stateNxt = {};
		Object.keys(this._state).forEach(k => stateNxt[k] = PILL_STATE__IGNORE);
		Object.assign(stateNxt, this._getMigratedLoadedState(values[this.header]));

		this._proxyAssignSimple("state", stateNxt);
	}

	setValue (k, v) { this._state[k] = v; }

	_mutNextState_resetNestsHidden ({tgt}) {
		if (!this._nests) return;
		Object.entries(this._nests).forEach(([nestName, nestMeta]) => tgt[nestName] = !!nestMeta.isHidden);
	}

	_defaultItemState (item, {isForce = false} = {}) {
		// Avoid setting state for new items if the user already has active filter state. This prevents the case where e.g.:
		//   - The user has cleared their source filter;
		//   - A new source is added to the site;
		//   - The new source becomes the *only* selected item in their filter.
		if (!isForce && this._hasUserSavedState && !Object.values(this.__state).some(Boolean)) return this._state[item.item] = PILL_STATE__IGNORE;

		this._state[item.item] = this._getDefaultItemState(item.item);
	}

	_getDefaultItemState (k, {isIgnoreSnapshot = false} = {}) {
		if (isIgnoreSnapshot) return this._getDefaultState_base(k);

		const fromSnapshot = this._snapshotManager?.getResolvedValue(this.header, "state", k);
		if (fromSnapshot != null) return fromSnapshot;

		return this._getDefaultState_base(k);
	}

	_getDefaultState_base (k) {
		// if both a selFn and a deselFn are specified, we default to deselecting
		return this._deselFn && this._deselFn(k) ? PILL_STATE__NO : this._selFn && this._selFn(k) ? PILL_STATE__YES : PILL_STATE__IGNORE;
	}

	_getDisplayText (item) {
		return this._displayFn ? this._displayFn(item.item, item) : item.item;
	}

	_getDisplayTextMini (item) {
		return this._displayFnMini
			? this._displayFnMini(item.item, item)
			: this._getDisplayText(item);
	}

	_getPill (item) {
		const displayText = this._getDisplayText(item);

		const btnPill = veE({
			tag: "div",
			clazz: "ve-fltr__pill",
			html: displayText,
			click: evt => this._getPill_handleClick({evt, item}),
			contextmenu: evt => this._getPill_handleContextmenu({evt, item}),
		});

		this._getPill_bindHookState({btnPill, item});

		item.searchText = displayText.toLowerCase();

		return btnPill;
	}

	_getPill_handleClick ({evt, item}) {
		if (evt.shiftKey) {
			this._doSetPillsClear();
		}

		if (++this._state[item.item] > PILL_STATE__NO) this._state[item.item] = PILL_STATE__IGNORE;
	}

	_getPill_handleContextmenu ({evt, item}) {
		evt.preventDefault();

		if (evt.shiftKey) {
			this._doSetPillsClear();
		}

		if (--this._state[item.item] < PILL_STATE__IGNORE) this._state[item.item] = PILL_STATE__NO;
	}

	_getPill_bindHookState ({btnPill, item}) {
		this._addHook("state", item.item, () => {
			const val = PILL_STATES[this._state[item.item]];
			btnPill.vee.attr("data-state", val);
		})();
	}

	setTempFnSel (tempFnSel) {
		this._selFnCache = this._selFnCache || this._selFn;
		if (tempFnSel) this._selFn = tempFnSel;
		else this._selFn = this._selFnCache;
	}

	updateMiniPillClasses () {
		this._items.filter(it => it.btnMini).forEach(it => {
			const isDefaultDesel = this._deselFn && this._deselFn(it.item);
			const isDefaultSel = this._selFn && this._selFn(it.item);
			it.btnMini
				.vee.toggleClass("ve-fltr__mini-pill--default-desel", isDefaultDesel)
				.vee.toggleClass("ve-fltr__mini-pill--default-sel", isDefaultSel);
		});
	}

	_getBtnMini (item) {
		const toDisplay = this._getDisplayTextMini(item);

		const btnMini = veE({
			tag: "div",
			clazz: `ve-fltr__mini-pill ${this._filterBox.isMinisHidden(this.header) ? "ve-hidden" : ""} ${this._deselFn && this._deselFn(item.item) ? "ve-fltr__mini-pill--default-desel" : ""} ${this._selFn && this._selFn(item.item) ? "ve-fltr__mini-pill--default-sel" : ""}`,
			html: toDisplay,
			title: `${this._displayFnTitle ? `${this._displayFnTitle(item.item, item)} (` : ""}Filter: ${this._getHeaderDisplayName()}${this._displayFnTitle ? ")" : ""}`,
			click: () => {
				this._state[item.item] = PILL_STATE__IGNORE;
				this._filterBox.fireChangeEvent();
			},
		}).vee.attr("data-state", PILL_STATES[this._state[item.item] || 0]);

		const hideHook = () => btnMini.vee.toggleClass("ve-hidden", this._filterBox.isMinisHidden(this.header));
		this._filterBox.registerMinisHiddenHook(this.header, hideHook);

		return btnMini;
	}

	_doSetPillsAll ({isIgnoreSearchTermParent = false} = {}) {
		this._doSetPillsBulk({stateTarget: PILL_STATE__YES, isIgnoreSearchTermParent});
	}

	_doSetPillsClear ({isIgnoreSearchTermParent = false} = {}) {
		this._doSetPillsBulk({stateTarget: PILL_STATE__IGNORE, isIgnoreSearchTermParent});
	}

	_doSetPillsNone ({isIgnoreSearchTermParent = false} = {}) {
		this._doSetPillsBulk({stateTarget: PILL_STATE__NO, isIgnoreSearchTermParent});
	}

	_doSetPillsBulk ({stateTarget, isIgnoreSearchTermParent = false} = {}) {
		if (isIgnoreSearchTermParent || !this._compSearch._state.searchTermParent) {
			this._proxyAssignSimple(
				"state",
				Object.keys(this._state)
					.mergeMap(k => ({[k]: stateTarget})),
				true,
			);
			return;
		}

		const {
			itemsVisible: searchVisibleItems,
			itemsNotVisible: searchNotVisibleItems,
		} = this._getSearchVisibleItems({searchTerm: this._compSearch._state.searchTermParent});

		if (!searchVisibleItems.length) {
			this._proxyAssignSimple(
				"state",
				Object.keys(this._state)
					.mergeMap(k => ({[k]: stateTarget})),
				true,
			);
			return;
		}

		this._proxyAssignSimple(
			"state",
			{
				...Object.fromEntries(
					searchVisibleItems
						.map(itm => [itm.item, stateTarget]),
				),
				...Object.fromEntries(
					searchNotVisibleItems
						.map(itm => [itm.item, PILL_STATE__IGNORE]),
				),
			},
			true,
		);
	}

	_doSetPinsDefault () {
		this.reset();
	}

	_getHeaderControls (opts) {
		const btnAll = veE({
			tag: "button",
			clazz: `ve-btn ve-btn-default ${opts.isMulti ? "ve-btn-xxs" : "ve-btn-xs"} ve-fltr__h-btn--all ve-w-100`,
			click: evt => this._doSetPillsAll({isIgnoreSearchTermParent: !!evt.shiftKey}),
			html: "全选",
		});
		const btnClear = veE({
			tag: "button",
			clazz: `ve-btn ve-btn-default ${opts.isMulti ? "ve-btn-xxs" : "ve-btn-xs"} ve-fltr__h-btn--clear ve-w-100`,
			click: evt => this._doSetPillsClear({isIgnoreSearchTermParent: !!evt.shiftKey}),
			html: "清除",
		});
		const btnNone = veE({
			tag: "button",
			clazz: `ve-btn ve-btn-default ${opts.isMulti ? "ve-btn-xxs" : "ve-btn-xs"} ve-fltr__h-btn--none ve-w-100`,
			click: evt => this._doSetPillsNone({isIgnoreSearchTermParent: !!evt.shiftKey}),
			html: "全无",
		});
		this._compSearch._addHookBase("searchTermParent", () => {
			const tooltipIgnoreSearch = this._compSearch._state.searchTermParent
				? `SHIFT to Ignore Search`
				: null;
			btnAll.vee.tooltip(tooltipIgnoreSearch);
			btnClear.vee.tooltip(tooltipIgnoreSearch);
			btnNone.vee.tooltip(tooltipIgnoreSearch);
		})();

		const btnDefault = veE({
			tag: "button",
			clazz: `ve-btn ve-btn-default ${opts.isMulti ? "ve-btn-xxs" : "ve-btn-xs"} ve-w-100`,
			click: () => this._doSetPinsDefault(),
			html: "缺省",
		});

		const wrpStateBtnsOuter = veE({
			tag: "div",
			clazz: "ve-flex-v-center ve-fltr__h-wrp-state-btns-outer",
			children: [
				veE({
					tag: "div",
					clazz: "ve-btn-group ve-flex-v-center ve-w-100",
					children: [
						btnAll,
						btnClear,
						btnNone,
						btnDefault,
					],
				}),
			],
		});
		this._getHeaderControls_addExtraStateBtns(opts, wrpStateBtnsOuter);

		const wrpSummary = veE({tag: "div", clazz: "ve-flex-vh-center ve-hidden"});

		const btnCombineBlue = veE({
			tag: "button",
			clazz: `ve-btn ve-btn-default ${opts.isMulti ? "ve-btn-xxs" : "ve-btn-xs"} ve-fltr__h-btn-logic--blue ve-fltr__h-btn-logic ve-w-100`,
			click: () => this._meta.combineBlue = Filter._getNextCombineMode(this._meta.combineBlue),
			title: `Blue match mode for this filter. "AND" requires all blues to match, "OR" requires at least one blue to match, "XOR" requires exactly one blue to match.`,
		});
		const hookCombineBlue = () => veE({ele: btnCombineBlue, txt: `${this._meta.combineBlue}`.toUpperCase()});
		this._addHook("meta", "combineBlue", hookCombineBlue);
		hookCombineBlue();

		const btnCombineRed = veE({
			tag: "button",
			clazz: `ve-btn ve-btn-default ${opts.isMulti ? "ve-btn-xxs" : "ve-btn-xs"} ve-fltr__h-btn-logic--red ve-fltr__h-btn-logic ve-w-100`,
			click: () => this._meta.combineRed = Filter._getNextCombineMode(this._meta.combineRed),
			title: `Red match mode for this filter. "AND" requires all reds to match, "OR" requires at least one red to match, "XOR" requires exactly one red to match.`,
		});
		const hookCombineRed = () => veE({ele: btnCombineRed, txt: `${this._meta.combineRed}`.toUpperCase()});
		this._addHook("meta", "combineRed", hookCombineRed);
		hookCombineRed();

		const btnShowHide = this._getBtnShowHide({isMulti: opts.isMulti});
		const hookShowHide = () => {
			veE({ele: btnShowHide}).vee.toggleClass("ve-active", this._uiMeta.isHidden);
			wrpStateBtnsOuter.vee.toggle(!this._uiMeta.isHidden);

			// Skip updating renders if results would be invisible
			if (!this._uiMeta.isHidden) {
				wrpSummary.vee.toggle(this._uiMeta.isHidden);
				return;
			}

			// render summary
			const cur = this.getValues()[this.header];

			const htmlSummary = [
				cur._totals.yes
					? `<span class="ve-fltr__summary_item ve-fltr__summary_item--include" title="${cur._totals.yes} hidden &quot;required&quot; tags">${cur._totals.yes}</span>`
					: null,
				cur._totals.yes && cur._totals.no
					? `<span class="ve-fltr__summary_item_spacer"></span>`
					: null,
				cur._totals.no
					? `<span class="ve-fltr__summary_item ve-fltr__summary_item--exclude" title="${cur._totals.no} hidden &quot;excluded&quot; tags">${cur._totals.no}</span>`
					: null,
			].filter(Boolean).join("");
			veE({ele: wrpSummary, html: htmlSummary}).vee.toggle(this._uiMeta.isHidden);
		};
		this._addHook("uiMeta", "isHidden", hookShowHide);
		this._addHookAll("state", hookShowHide);
		hookShowHide();

		return veE({
			tag: "div",
			clazz: `ve-flex-v-center ve-fltr__h-wrp-btns-outer`,
			children: [
				wrpSummary,
				wrpStateBtnsOuter,
				veE({tag: "span", clazz: `ve-btn-group ve-ml-2 ve-flex-v-center`, children: [btnCombineBlue, btnCombineRed]}),
				veE({
					tag: "div",
					clazz: "ve-btn-group ve-flex-v-center ve-ml-2",
					children: [
						btnShowHide,
						this._getBtnMenu({isMulti: opts.isMulti}),
					],
				}),
			],
		});
	}

	_getHeaderControls_addExtraStateBtns () {
		// To be optionally implemented by child classes
	}

	/**
	 * @param opts Options.
	 * @param opts.filterBox The FilterBox to which this filter is attached.
	 * @param opts.isFirst True if this is visually the first filter in the box.
	 * @param opts.wrpMini The form mini-view element.
	 * @param opts.isMulti The name of the MultiFilter this filter belongs to, if any.
	 */
	render (opts) {
		this._filterBox = opts.filterBox;
		this.__wrpMiniPills = opts.wrpMini ? veE({ele: opts.wrpMini}) : null;

		const wrpControls = this._getHeaderControls(opts);

		this.__wrpPills = veE({tag: "div", clazz: `ve-fltr__wrp-pills ${this._groupFn ? "ve-fltr__wrp-subs" : "ve-fltr__container-pills"}`});
		this._addHook("uiMeta", "isHidden", () => this.__wrpPills.vee.toggle(!this._uiMeta.isHidden))();

		if (this._nests) {
			const wrpNestHead = veE({tag: "div", clazz: "ve-fltr__wrp-pills--sub"}).vee.appendTo(this.__wrpPills);
			this.__wrpNestHeadInner = veE({tag: "div", clazz: "ve-flex ve-flex-wrap ve-fltr__container-pills"}).vee.appendTo(wrpNestHead);

			const wrpNestHeadSummary = veE({tag: "div", clazz: "ve-fltr__summary_nest"}).vee.appendTo(wrpNestHead);

			this._updateNestSummary = () => {
				const stats = {high: 0, low: 0};
				this._items.filter(it => this._state[it.item] && this._nestsHidden[it.nest]).forEach(it => {
					const key = this._state[it.item] === PILL_STATE__YES ? "high" : "low";
					stats[key]++;
				});

				wrpNestHeadSummary.vee.empty();

				if (stats.high) {
					veE({
						tag: "span",
						clazz: "ve-fltr__summary_item ve-fltr__summary_item--include",
						txt: stats.high,
						title: `${stats.high} hidden "required" tag${stats.high === 1 ? "" : "s"}`,
					}).vee.appendTo(wrpNestHeadSummary);
				}

				if (stats.high && stats.low) veE({tag: "span", clazz: "ve-fltr__summary_item_spacer"}).vee.appendTo(wrpNestHeadSummary);

				if (stats.low) {
					veE({
						tag: "span",
						clazz: "ve-fltr__summary_item ve-fltr__summary_item--exclude",
						txt: stats.low,
						title: `${stats.low} hidden "excluded" tag${stats.low === 1 ? "" : "s"}`,
					}).vee.appendTo(wrpNestHeadSummary);
				}
			};

			this._doRenderNests();
		}

		this._doRenderPills();

		const btnMobToggleControls = this._getBtnMobToggleControls(wrpControls);

		this.__wrpFilter = veT`<div>
			${opts.isFirst ? "" : `<div class="ve-fltr__dropdown-divider ${opts.isMulti ? "ve-fltr__dropdown-divider--indented" : ""} ve-mb-1"></div>`}
			<div class="ve-split ve-fltr__h ${this._minimalUi ? "ve-fltr__minimal-hide" : ""} ve-mb-1">
				<div class="ve-fltr__h-text ve-flex-h-center ve-mobile-sm__w-100">
					${opts.isMulti ? `<span class="ve-mr-2">\u2012</span>` : ""}
					${this._getRenderedHeader()}
					${btnMobToggleControls}
				</div>
				${wrpControls}
			</div>
			${this.__wrpPills}
		</div>`;

		this._doToggleDisplay();

		return this.__wrpFilter;
	}

	/**
	 * @param opts Options.
	 * @param opts.filterBox The FilterBox to which this filter is attached.
	 * @param opts.isFirst True if this is visually the first filter in the box.
	 * @param opts.wrpMini The form mini-view element.
	 * @param opts.isMulti The name of the MultiFilter this filter belongs to, if any.
	 */
	renderMinis (opts) {
		if (!opts.wrpMini) return;

		this._filterBox = opts.filterBox;
		this.__wrpMiniPills = veE({ele: opts.wrpMini});

		// Use a comment ("invisible node") as an anchor, to ensure per-filter pills are inserted in correct order w.r.t filters
		// TODO(Future) use this to enable per-filter sorting, e.g., allow "Source" filter to be sorted by "name"/"release date"
		this._miniPillAnchor ||= document.createComment(`Pill anchor -- ${this.header}`);
		if (this._miniPillAnchor.parentNode !== this.__wrpMiniPills) this.__wrpMiniPills.append(this._miniPillAnchor);

		this._doRenderMiniPills();
	}

	getValues ({nxtState = null} = {}) {
		const state = MiscUtil.copy(nxtState?.[this.header]?.state || this.__state);
		const meta = nxtState?.[this.header]?.meta || this.__meta;

		// remove state for any currently-absent filters
		Object.keys(state).filter(k => !this._items.some(it => `${it.item}` === k)).forEach(k => delete state[k]);
		const out = {...state};

		// add helper data
		out._isActive = Object.values(state).some(Boolean);
		out._totals = Object.fromEntries(PILL_STATES.map(pillState => [pillState, 0]));
		Object.values(state).forEach(v => {
			const totalKey = PILL_STATES[v] || PILL_STATES[PILL_STATE__IGNORE];
			out._totals[totalKey]++;
		});
		out._combineBlue = meta.combineBlue;
		out._combineRed = meta.combineRed;
		return {[this.header]: out};
	}

	_getNextState_base () {
		return {
			[this.header]: {
				...super._getNextState_base()[this.header],
				nestsHidden: MiscUtil.copyFast(this.__nestsHidden),
			},
		};
	}

	_mutNextState_reset ({nxtState, isResetAll = false}) {
		if (isResetAll) {
			this._mutNextState_resetBase({nxtState, isResetAll});
			this._mutNextState_resetNestsHidden({tgt: nxtState[this.header].nestsHidden});
		} else {
			// Always reset "AND/OR" states
			Object.assign(nxtState[this.header].meta, {combineBlue: Filter._DEFAULT_META.combineBlue, combineRed: Filter._DEFAULT_META.combineRed});
		}
		Object.keys(nxtState[this.header].state).forEach(k => delete nxtState[this.header].state[k]);

		// Ignore snapshot, as it is applied on top of the base "reset"
		this._items.forEach(item => nxtState[this.header].state[item.item] = this._getDefaultItemState(item.item, {isIgnoreSnapshot: true}));
	}

	_doRenderPills () {
		// The filter's UI may not be available if the filter modal has not been opened, but an update has been triggered.
		// If so, avoid rendering pills; if the filter is later opened, the `$render` call will render the pills as required.
		if (!this.__wrpPills) return;

		if (this._itemSortFn) this._items.sort(this._isSortByDisplayItems && this._displayFn ? (a, b) => this._itemSortFn(this._displayFn(a.item, a), this._displayFn(b.item, b)) : this._itemSortFn);

		this._items.forEach(it => {
			if (!it.rendered) {
				it.rendered = this._getPill(it);
				if (it.nest) {
					const hook = () => it.rendered.vee.toggle(!this._nestsHidden[it.nest]);
					this._addHook("nestsHidden", it.nest, hook);
					hook();
				}
			}

			if (this._groupFn) {
				const group = this._groupFn(it);
				this._doRenderPills_doRenderWrpGroup(group);
				this._pillGroupsMeta[group].wrpPills.append(it.rendered);
			} else it.rendered.vee.appendTo(this.__wrpPills);
		});
	}

	_doRenderPills_doRenderWrpGroup (group) {
		const existingMeta = this._pillGroupsMeta[group];
		if (existingMeta && !existingMeta.isAttached) {
			existingMeta.wrpDivider.vee.appendTo(this.__wrpPills);
			existingMeta.wrpPills.vee.appendTo(this.__wrpPills);
			existingMeta.isAttached = true;
		}
		if (existingMeta) return;

		this._pillGroupsMeta[group] = {
			wrpDivider: this._doRenderPills_doRenderWrpGroup_getDivider(group).vee.appendTo(this.__wrpPills),
			wrpPills: this._doRenderPills_doRenderWrpGroup_getWrpPillsSub(group).vee.appendTo(this.__wrpPills),
			isAttached: true,
		};

		Object.entries(this._pillGroupsMeta)
			.sort((a, b) => SortUtil.ascSortLower(a[0], b[0]))
			.forEach(([groupKey, groupMeta], i) => {
				groupMeta.wrpDivider.vee.appendTo(this.__wrpPills);
				groupMeta.wrpDivider.vee.toggle(!this._isGroupDividerHidden(groupKey, i));
				groupMeta.wrpPills.vee.appendTo(this.__wrpPills);
			});

		if (this._nests) {
			this._pillGroupsMeta[group].toggleDividerFromNestVisibility = () => {
