			.filter(nestMeta => nestMeta._btnNest)
			.forEach(nestMeta => nestMeta._btnNest.vee.detach());

		Object.values(this._pillGroupsMeta || {})
			.forEach(it => {
				it.wrpDivider.vee.detach();
				it.wrpPills.vee.detach();
				it.isAttached = false;
			});
	}
