					.forEach(k => nxtState[k] = PILL_STATE__IGNORE);
				this._proxyAssign("state", "_state", "__state", nxtState);
			},
		});

		const grpBtnsActive = veE({
			tag: "div",
			clazz: `ve-flex-v-center ve-btn-group`,
			children: [
				btnCancel,
				btnConfirm,
