	html.nt4 .cls__list .ve-lst__row--focused .ve-lst__row-inner *, html.nt4 .cls__list .list-multi-selected .ve-lst__row-inner * { color: #fff6e0 !important; }
	html.nt4 .cls__list .n4-merged .ve-lst__row-inner > .nt-name { font-size: 15px; }

	html.nt2 main.classes.ntc-on > .ntc { padding: 12px 14px 120px !important; }
