	html.nt4 .ntc-sec--sub > .ntc-sec__head { flex-basis: 100%; }
	html.nt4 .n4-pop { position: fixed; left: 8px; right: 8px; top: 56px; max-height: calc(100vh - 72px); }
	html.nt2 #pagecontent.cls__stats { font-size: 16px; }
}

/__ours/mobile.js:
/* 我们的 5etools —— 手机版的外壳部分（屏幕宽度 ≤ 760px 时起作用，电脑上什么都不做）。样式在 mobile.css。
 * 在 shell.html 的 <head> 里加载（要早于外壳自己的脚本，才能改默认的内存模式）。
 * 1 手机上默认「省内存」：不在后台预载别的页面（网页版里每预载一页都要下载几 MB 资料）。用户自己选过的不动。
 * 2 资料范围和版本开关从顶栏搬进「⋯」菜单（顶栏放不下），屏幕变宽时搬回去。
 * 3 顶栏的页面标签：当前页滚到看得见的位置；职业页的职业条：当前职业滚到看得见的位置。 */
(() => {
	"use strict";
	const MQ = window.matchMedia("(max-width: 760px)");
	try { if (MQ.matches && !localStorage.getItem("ours.memMode")) localStorage.setItem("ours.memMode", "save"); } catch (e) { /* storage blocked */ }

	const start = () => {
		const bar = document.getElementById("bar"), menu = document.getElementById("moremenu");
		const sw = document.getElementById("switch"), ed = document.getElementById("edsw");
		if (!bar || !menu || !sw || !ed) return;
		const home = document.createElement("span");   // where the switches live on a wide screen
		home.hidden = true;
		sw.before(home);
		const box = document.createElement("div");
		box.className = "mob-sw";
		box.innerHTML = `<div class="mob-sw__h">资料范围</div><div class="mob-sw__a"></div><div class="mob-sw__tip"></div>`
			+ `<div class="mob-sw__h">版本<small>只对职业、法术、专长生效</small></div><div class="mob-sw__b"></div><div class="mob-sep"></div>`;
		const tip = box.querySelector(".mob-sw__tip");
		const showTip = () => { tip.textContent = sw.querySelector(".seg.on")?.title || ""; };
		new MutationObserver(showTip).observe(sw, {attributes: true, subtree: true, attributeFilter: ["class"]});

		const place = () => {
			if (MQ.matches) {
				box.querySelector(".mob-sw__a").append(sw);
				box.querySelector(".mob-sw__b").append(ed);
				if (!box.isConnected) menu.prepend(box);
				showTip();
			} else if (box.isConnected) {
				home.after(sw, ed);
				box.remove();
			}
		};
		place();
		MQ.addEventListener?.("change", place);

		// keep the current page tab and the current class chip in view
		const tabs = document.getElementById("tabs");
		const intoView = (scroller, el) => {
			if (!scroller || !el) return;
			const a = scroller.getBoundingClientRect(), b = el.getBoundingClientRect();
			if (b.left < a.left + 8 || b.right > a.right - 24) scroller.scrollLeft += (b.left + b.width / 2) - (a.left + a.width / 2);
		};
		let lastTab = null;
		const chipDone = new WeakMap();
		setInterval(() => {   // a timer, not requestAnimationFrame: background frames get no animation frames
			if (!MQ.matches) return;
			const on = tabs?.querySelector(".tab.on");
			if (on && on !== lastTab) { lastTab = on; intoView(tabs, on); }
			const f = document.querySelector('#frames iframe[src*="classes.html"]');
			let doc = null;
			try { doc = f?.contentDocument; } catch (e) { return; }
			const list = doc?.querySelector("#list.cls__list"), cur = list?.querySelector(".list-multi-selected:not(.ve-hidden)");
			if (cur && chipDone.get(list) !== cur) { chipDone.set(list, cur); intoView(list, cur); }
		}, 400);
	};
	if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", start); else start();
})();

/__ours/notion.css:
/* 我们的 5etools —— Notion 风格界面（只在外壳里的「新界面」生效：html.nt）。
 * 颜色、字号、间距取自 Notion 网页版实际页面（notion.site）的计算样式；规则数据本身不做任何改动。
 * 网站自带的样式都放在 @layer vetools 里，这里不用 layer，所以选择器可以写得很简单。 */

html.nt {
	--nt-tex: #2c2c2b; --nt-tex2: #7d7a75; --nt-tex3: #a19e99; --nt-tex4: #bcbab6; --nt-texnav: #5f5e59;
	--nt-bg: #fff; --nt-surface: #fff; --nt-bg2: #f9f8f7; --nt-bg3: #f0efed; --nt-hover: rgba(42, 28, 0, .05); --nt-active: rgba(42, 28, 0, .07);
	--nt-line: #e6e5e3; --nt-line2: #f0efed; --nt-line3: #d4d3cf; --nt-cell: rgba(42, 28, 0, .07);
	--nt-ico: #8e8b86; --nt-blue: #2783de; --nt-focus: #2383e2; --nt-blue-bg: #e5f2fc; --nt-blue-bg2: #cee3f7; --nt-blue-tex: #264a72;
	--nt-sh-sm: 0 2px 4px 0 #0000000a, 0 0 0 1px #2a1c0012;
	--nt-sh-md: 0 8px 12px 0 #19191907, 0 2px 6px 0 #19191907, 0 0 0 1px #2a1c0012;
	--nt-sh-lg: 0 20px 24px 0 #1919190d, 0 5px 8px 0 #19191907, 0 0 0 1px #2a1c0012;
	--nt-sh-scr: 0 24px 48px 0 #1919193d, 0 4px 12px 0 #19191924, 0 0 0 1px #2a1c0012;
	--nt-font: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI Variable Display", "Segoe UI", Helvetica, "PingFang SC", "Microsoft YaHei", "Apple Color Emoji", Arial, sans-serif;
	/* Notion 标签色（背景 / 文字） */
	--nt-tag-gray: rgba(42, 28, 0, .07); --nt-tag-gray-t: #2c2c2b;
	--nt-tag-brown: rgba(127, 51, 0, .157); --nt-tag-brown-t: #584437;
	--nt-tag-blue: #cee3f7; --nt-tag-blue-t: #264a72;
	--nt-tag-green: rgba(0, 96, 38, .157); --nt-tag-green-t: #2a533c;
	--nt-tag-purple: rgba(92, 0, 163, .14); --nt-tag-purple-t: #553b69;
	--nt-tag-pink: #f4d8e4; --nt-tag-pink-t: #68354e;
	--nt-tag-red: rgba(206, 24, 0, .165); --nt-tag-red-t: #6d3531;
	--nt-tag-orange: #f3ddcb; --nt-tag-orange-t: #6a4222;
	--nt-tag-yellow: #f2e3b7; --nt-tag-yellow-t: #655121;
	/* Notion 文字色：用来区分子职特性、第三方特性等（原站用不同颜色区分，这里保留区分，只换成 Notion 的色值） */
	--nt-c-green: #448361; --nt-c-blue: #337ea9; --nt-c-purple: #9065b0; --nt-c-pink: #c14c8a; --nt-c-brown: #9f6b53; --nt-c-orange: #d9730d;
	background: var(--nt-bg); color-scheme: light;
}
html.nt body { background: var(--nt-bg) !important; color: var(--nt-tex); font-family: var(--nt-font); font-size: 14px; line-height: 1.5; -webkit-font-smoothing: auto; }
html.nt .overlay-noise { display: none; }
