/* ------------------------------------------------------------------ links: Notion 是正文色 + 浅下划线 */
html.nt a, html.nt a:visited { color: inherit; text-decoration: underline; text-decoration-color: rgba(42, 28, 0, .25); text-underline-offset: 2px; text-decoration-thickness: 1px; }
