html.nt .ve-lst__row-inner, html.nt .ve-lst__row-inner:hover { text-decoration: none; }

/* ------------------------------------------------------------------ the site's own header / menu: the shell has the sidebar */
html.nt.ours-in-shell header.page__header, html.nt.ours-in-shell .page__btn-toggle-nav { display: none !important; }
html.nt.ours-in-shell #navigation { position: fixed; top: 0; left: 0; width: 0; height: 0; margin: 0; padding: 0; border: 0; z-index: 2000; }
