/* ------------------------------------------------------------------ search: Notion's centred search window (Ctrl+K / 侧栏「搜索」 / F) */
html.nt.ours-in-shell .omni__wrp-input { position: fixed; left: -9999px; top: 0; width: 1px; opacity: 0; }
html.nt.nt-search::before { content: ""; position: fixed; inset: 0; z-index: 1999; background: rgba(15, 15, 15, .2); }
html.nt.nt-search .omni__wrp-input { left: 50%; top: max(9vh, 40px); transform: translateX(-50%); width: min(720px, calc(100vw - 48px)); opacity: 1; z-index: 2001;
	background: var(--nt-surface); border-radius: 12px; box-shadow: var(--nt-sh-scr); display: flex !important; align-items: center; height: 52px; padding: 0 12px 0 44px; margin: 0; }
html.nt.nt-search #navigation:has(.omni__wrp-output:not(.ve-hidden)) .omni__wrp-input { border-radius: 12px 12px 0 0; box-shadow: 0 24px 48px 0 #1919193d, 0 0 0 1px #2a1c0012; }
html.nt.nt-search .omni__wrp-input::before { content: ""; position: absolute; left: 16px; top: 16px; width: 20px; height: 20px; background: var(--nt-ico);
