/__ours/notion2.css:
/* 我们的 5etools —— Notion 风格 V2（职业页重排 + 列表面板精修）。只在 html.nt2 下生效，V1（notion.css）原样保留作对照。
 * 版式原则取自 Notion 页面实测：一栏正文（约 720–760px）、页头 = 40px 标题 + 属性、表格左对齐正文且可向右伸出、目录在右侧。 */

/* ================================================================== class page layout */
html.nt2 main.classes.ntc-on { display: grid !important; grid-template-columns: 232px minmax(0, 1fr); column-gap: 0; padding: 0 !important; align-items: start; }
html.nt2 main.classes.ntc-on > .ntc { grid-column: 2; grid-row: 1; min-width: 0; padding: 32px 48px 160px 48px; box-sizing: border-box; }
html.nt2 .ntc-hidden { display: none; }

/* the class list: a quiet secondary panel, separated by one hairline (no third column any more) */
html.nt2 main.classes.ntc-on #listcontainer { grid-column: 1; grid-row: 1; position: sticky; top: 0; height: 100vh; margin: 0; padding: 12px 10px 10px; box-sizing: border-box; display: flex; flex-direction: column;
	border-right: 1px solid var(--nt-line2); background: var(--nt-surface); width: auto; max-width: none; }
html.nt2 main.classes.ntc-on #listcontainer > .ve-night__shadow-big { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }
html.nt2 main.classes.ntc-on #list.cls__list { flex: 1 1 auto; max-height: none; min-height: 0; overflow-y: auto; margin: 0 -4px 0 0; padding-right: 4px; }
html.nt2 main.classes.ntc-on #listcontainer > .ve-my-3 { margin: 8px 0 0 !important; justify-content: flex-start; }
html.nt2 #listcontainer #filtertools { height: 26px; border-bottom: 0; margin: 2px 0 2px; }
html.nt2 #listcontainer #filtertools .sort { height: 26px !important; line-height: 26px !important; font-size: 12px; color: var(--nt-tex3); }
/* list rows: Notion sidebar/list items — no grid lines, rounded hover, selected = grey + medium */
html.nt2 .cls__list .ve-lst__row-inner { min-height: 28px; border-bottom: 0 !important; border-radius: 6px; padding: 0 4px 0 8px; }
html.nt2 .cls__list .ve-lst__row-inner > .nt-name { font-weight: 400; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
html.nt2 .cls__list .list-multi-selected > .ve-lst__row-inner { background: var(--nt-active) !important; }
html.nt2 .cls__list .list-multi-selected > .ve-lst__row-inner > .nt-name { font-weight: 600; }
html.nt2 .cls__list .ve-lst__row-inner .nt-tag { height: 18px; line-height: 18px; font-size: 11px; padding: 0 5px; }
html.nt2 #list.cls__list .ve-ours-cls-off + .ve-ours-cls-feat::before, html.nt2 #list.cls__list .ve-ours-cls-feat + .ve-ours-cls-rest::before, html.nt2 #list.cls__list .ve-ours-cls-off + .ve-ours-cls-rest::before {
	padding: 14px 8px 4px; border-bottom: 0; color: var(--nt-tex3); }

/* ---------------------------------------------------------------- page header: the focal point */
html.nt2 .ntc-head { max-width: 1016px; margin-bottom: 8px; }
html.nt2 .ntc-head__row { display: flex; align-items: flex-start; gap: 16px; }
html.nt2 .ntc-title { flex: 1; margin: 0; font: 700 40px/1.2 var(--nt-font); color: var(--nt-tex); letter-spacing: 0; }
html.nt2 .ntc-title__en { margin-left: 12px; font-weight: 400; color: var(--nt-tex3); font-size: 28px; }
html.nt2 .ntc-actions { padding-top: 10px; }
html.nt2 .ntc-actions .wrp-btn-readmode { margin: 0 !important; gap: 6px; }
html.nt2 .ntc-actions .ve-btn { height: 28px !important; line-height: 28px !important; padding: 0 10px !important; font-size: 14px !important; color: var(--nt-tex2); box-shadow: none !important; background: transparent !important; margin: 0 !important; }
html.nt2 .ntc-actions .ve-btn:hover { background: var(--nt-hover) !important; color: var(--nt-tex); }
/* properties: two columns of Notion property rows (label 104px grey, value), long ones span the width */
html.nt2 .ntc-props { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 32px; margin-top: 14px; padding-bottom: 14px; border-bottom: 1px solid var(--nt-line2); max-width: 1016px; }
html.nt2 .ntc-prop { display: grid; grid-template-columns: 104px minmax(0, 1fr); gap: 0 8px; align-items: start; min-height: 30px; padding: 4px 0; font-size: 14px; line-height: 22px; }
html.nt2 .ntc-prop--wide { grid-column: 1 / -1; }
html.nt2 .ntc-prop__k { color: var(--nt-tex2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
html.nt2 .ntc-prop__v { color: var(--nt-tex); min-width: 0; }
html.nt2 .ntc-prop__v > div, html.nt2 .ntc-prop__v > p { margin: 0; }
html.nt2 .ntc-prop__v b, html.nt2 .ntc-prop__v strong { font-weight: 400; color: var(--nt-tex2); }
html.nt2 .ntc-prop__v i { font-style: normal; color: var(--nt-tex2); }
html.nt2 .ntc-prop__v .ve-py-2 { display: none; }
html.nt2 .ntc-prop__v .nt-tag { margin-right: 6px; vertical-align: 1px; }
