/* ---------------------------------------------------------------- sections */
html.nt2 .ntc-sec { margin-top: 30px; max-width: 1016px; }
html.nt2 .ntc-sec__head { display: flex; align-items: center; gap: 10px; min-height: 32px; margin-bottom: 8px; }
html.nt2 .ntc-h { margin: 0; font: 600 20px/1.3 var(--nt-font); color: var(--nt-tex); letter-spacing: 0; }
html.nt2 .ntc-count { color: var(--nt-tex3); font-size: 14px; }

/* growth table: as wide as its columns (Notion tables are not stretched), level column as row header */
