html.nt2 .ve-cls-tbl > tbody > tr > td { height: 29px; padding: 0 12px; border-right: 1px solid var(--nt-cell); border-bottom: 1px solid var(--nt-cell); font-variant-numeric: tabular-nums; }
html.nt2 .ve-cls-tbl > tbody > tr > th { padding: 0 12px; }
html.nt2 .ve-cls-tbl > tbody > tr:has(> th.ve-cls-tbl__col-level) > th { height: 34px; font-size: 13px; background: var(--nt-bg2); }
html.nt2 .ve-cls-tbl > tbody > tr > td:first-child { color: var(--nt-tex2); text-align: right; }
html.nt2 .ve-cls-tbl a, html.nt2 .ve-cls-tbl a:visited { text-decoration: none; }
html.nt2 .ve-cls-tbl a:hover { text-decoration: underline; text-decoration-color: rgba(42, 28, 0, .45); }
html.nt2 .ve-cls-tbl > tbody > tr:has(> td):hover > td { background: rgba(35, 131, 226, .05); }
html.nt2 .ve-cls-tbl td:has(> a) { min-width: 220px; }

/* subclasses: grouped; compact Notion option tags (no borders), group label above each group */
html.nt2 .ntc-sec--sub .cls-tabs__wrp { display: block !important; padding: 0; margin: 0 !important; position: relative; }
html.nt2 .ntc-sec--sub .cls-tabs__wrp > .ve-flex-wrap { display: flex !important; flex-wrap: wrap; gap: 4px; margin: 0 !important; padding: 0; border: 0; width: 100%; }
html.nt2 .ntc-scg { flex: 0 0 100%; display: flex; align-items: baseline; gap: 6px; margin: 10px 0 2px; font-size: 12px; font-weight: 500; color: var(--nt-tex2); }
html.nt2 .ntc-scg:first-child, html.nt2 .ntc-scg[style*="order: 0"] { margin-top: 0; }
html.nt2 .ntc-scg__n { color: var(--nt-tex3); font-weight: 400; }
html.nt2 .ntc-scg--empty { display: none; }
html.nt2 .ntc-sec--sub .cls-tabs__wrp > .ve-flex-wrap > .ve-btn { height: 26px !important; line-height: 26px !important; padding: 0 8px !important; margin: 0 !important; font-size: 14px; border-radius: 4px !important;
	background: var(--nt-tag-gray) !important; box-shadow: none !important; color: var(--nt-tex) !important; transition: background .08s; }
html.nt2 .ntc-sec--sub .cls-tabs__wrp > .ve-flex-wrap > .ve-btn:hover { background: rgba(42, 28, 0, .12) !important; }
html.nt2 .ntc-sec--sub .cls-tabs__wrp > .ve-flex-wrap > .ve-btn > .ve-ml-1 { font-size: 12px; color: var(--nt-tex3); margin-left: 4px !important; }
html.nt2 .ntc-sec--sub .cls-tabs__wrp > .ve-flex-wrap > .ve-btn[class*="cls__btn-sc--active"] { font-weight: 500; }
html.nt2 .ntc-sec--sub .cls-tabs__wrp > .ve-flex-wrap > .ve-btn.cls__btn-sc--reprinted { background: transparent !important; box-shadow: inset 0 0 0 1px var(--nt-line) !important; }
html.nt2 .ntc-sec--sub .cls-tabs__wrp > :not(.ve-flex-wrap):not(.ve-btn-group:first-child) { position: absolute; right: 0; top: -40px; }
html.nt2 .ntc-sec--sub .cls-tabs__wrp i.ve-clickable, html.nt2 .ntc-sec--sub .cls-tabs__sc-not-shown { flex: 0 0 100%; margin-top: 8px; font-size: 12px; }

/* 特性 / 变体 / 简介: Notion view switch beside the section title */
html.nt2 .ntc-views { margin-left: 8px; }
html.nt2 .ntc-views > .ve-btn-group { display: flex !important; gap: 2px; margin: 0 !important; }
html.nt2 .ntc-views .ve-btn { height: 26px !important; line-height: 26px !important; padding: 0 8px !important; border-radius: 6px !important; box-shadow: none !important; background: transparent !important; color: var(--nt-tex3) !important; font-size: 14px; margin: 0 !important; }
html.nt2 .ntc-views .ve-btn:hover { background: var(--nt-hover) !important; color: var(--nt-tex2) !important; }
html.nt2 .ntc-views .ve-btn.cls__btn-cf--active, html.nt2 .ntc-views .ve-btn.ve-active { background: var(--nt-active) !important; color: var(--nt-tex) !important; font-weight: 500; }

/* ---------------------------------------------------------------- reading: one 760px column + table of contents on the right */
html.nt2 .ntc-read { display: grid; grid-template-columns: minmax(0, 760px) 200px; column-gap: 56px; align-items: start; }
html.nt2 .ntc-text { min-width: 0; }
html.nt2 .ntc-toc { position: sticky; top: 16px; max-height: calc(100vh - 32px); overflow-y: auto; scrollbar-width: none; }
html.nt2 .ntc-toc::-webkit-scrollbar { display: none; }
html.nt2 .ntc-toc .cls-nav { margin: 0; position: static; max-height: none; padding: 0; }
html.nt2 .ntc-toc .cls-nav__head { font-size: 12px; color: var(--nt-tex3); }
html.nt2 .ntc-toc .cls-nav__item { font-size: 13px; line-height: 18px; padding: 3px 8px; color: var(--nt-tex2); border-radius: 4px; }
html.nt2 .ntc-toc .cls-nav__item:hover { color: var(--nt-tex); background: var(--nt-hover); }
html.nt2 #pagecontent.cls__stats { font-size: 16px; }
html.nt2 #pagecontent .ve-rd__h--0 { font-size: 18px; line-height: 1.4; margin: 28px 0 4px; }
html.nt2 #pagecontent .ve-rd__h--1 { font-size: 16px; margin: 16px 0 2px; }
html.nt2 #pagecontent .ve-rd__h--2 { font-size: 16px; margin: 12px 0 2px; }
html.nt2 #pagecontent .ve-rd__b > p, html.nt2 #pagecontent .ve-rd__b > .ve-rd__p-list-item { margin: 0 0 6px; }
html.nt2 #pagecontent .ve-rd__title-link { color: var(--nt-tex4) !important; }
html.nt2 #pagecontent .ve-rd__h--0 .ve-rd__title-link, html.nt2 #pagecontent .ve-rd__h .ve-rd__h-toggle { opacity: 0; transition: opacity .1s; }
html.nt2 #pagecontent .ve-rd__h:hover .ve-rd__title-link, html.nt2 #pagecontent .ve-rd__h:hover .ve-rd__h-toggle { opacity: 1; }
/* subclass features: the site marks them; here a left rule in the subclass colour, so class vs subclass is visible while scrolling */
html.nt2 #pagecontent [class*="cls__feature-subclass"], html.nt2 #pagecontent [class*="cls__feature-variant-subclass"], html.nt2 #pagecontent [class*="cls__feature-brew-subclass"], html.nt2 #pagecontent [class*="cls__feature-ua-subclass"] {
	box-shadow: inset 3px 0 0 rgba(68, 131, 97, .35); padding-left: 16px !important; }
html.nt2 #pagecontent [class*="cls__feature-brew-subclass"] { box-shadow: inset 3px 0 0 rgba(144, 101, 176, .35); }
html.nt2 #pagecontent [class*="cls__feature-ua-subclass"] { box-shadow: inset 3px 0 0 rgba(217, 115, 13, .35); }
/* links in the text: quieter underline, still visible */
html.nt2 #pagecontent a, html.nt2 .ntc-props a { text-decoration-color: rgba(42, 28, 0, .2); }

@media screen and (max-width: 1400px) {
	html.nt2 .ntc-read { grid-template-columns: minmax(0, 1fr) 180px; column-gap: 36px; }
	html.nt2 main.classes.ntc-on > .ntc { padding-left: 36px; padding-right: 32px; }
}
@media screen and (max-width: 1180px) {
	html.nt2 .ntc-read { grid-template-columns: minmax(0, 1fr); }
	html.nt2 .ntc-toc { display: none; }
	html.nt2 .ntc-props { grid-template-columns: minmax(0, 1fr); }
}
/* the chosen subclass: Notion tag colour by kind of source (same meaning as the site's own colours) */
html.nt2 .ntc-sec--sub .cls-tabs__wrp > .ve-flex-wrap > .ve-btn.cls__btn-sc--active-fresh { background: var(--nt-tag-blue) !important; color: var(--nt-tag-blue-t) !important; }
html.nt2 .ntc-sec--sub .cls-tabs__wrp > .ve-flex-wrap > .ve-btn.cls__btn-sc--active-reprinted { background: rgba(42, 28, 0, .16) !important; color: var(--nt-tex) !important; }
html.nt2 .ntc-sec--sub .cls-tabs__wrp > .ve-flex-wrap > .ve-btn.cls__btn-sc--active-spicy { background: var(--nt-tag-green) !important; color: var(--nt-tag-green-t) !important; }
html.nt2 .ntc-sec--sub .cls-tabs__wrp > .ve-flex-wrap > .ve-btn.cls__btn-sc--active-stale { background: var(--nt-tag-yellow) !important; color: var(--nt-tag-yellow-t) !important; }
html.nt2 .ntc-sec--sub .cls-tabs__wrp > .ve-flex-wrap > .ve-btn.cls__btn-sc--active-brew { background: var(--nt-tag-purple) !important; color: var(--nt-tag-purple-t) !important; }
html.nt2 .ntc-sec--sub .cls-tabs__wrp > .ve-flex-wrap > .ve-btn.cls__btn-sc--active-rebrewed { background: var(--nt-tag-pink) !important; color: var(--nt-tag-pink-t) !important; }
html.nt2 .ntc-sec--sub .cls-tabs__wrp > .ve-flex-wrap > .ve-btn[class*="cls__btn-sc--active"] > .ve-ml-1 { color: inherit !important; opacity: .65; }
html.nt2 .ve-cls-tbl .ve-cls-tbl__col-level, html.nt2 .ve-cls-tbl .ve-cls-tbl__col-prof-bonus { width: auto; }
html.nt2 .ve-cls-tbl > tbody > tr > td.ve-cls-tbl__col-generic-center { min-width: 64px; }
/* only the outermost subclass block carries the rule */
html.nt2 #pagecontent [class*="cls__feature-subclass"] [class*="cls__feature-subclass"], html.nt2 #pagecontent [class*="cls__feature-brew-subclass"] [class*="cls__feature-brew-subclass"],
html.nt2 #pagecontent [class*="cls__feature-ua-subclass"] [class*="cls__feature-ua-subclass"], html.nt2 #pagecontent [class*="cls__feature-variant-subclass"] [class*="cls__feature-variant-subclass"] { box-shadow: none; padding-left: 0 !important; }
/* header keeps the properties you look up all the time; 起始装备 / 兼职 / 出处 sit right under the table, still open */
html.nt2 .ntc-sec--more { margin-top: 18px; }
html.nt2 .ntc-props--more { margin-top: 0; padding-bottom: 0; border-bottom: 0; grid-template-columns: minmax(0, 1fr); }
html.nt2 .ntc-sec--more:not(:has(.ntc-prop)) { display: none; }
html.nt2 .ntc-head .ntc-props { margin-top: 12px; padding-bottom: 12px; }
@media screen and (max-width: 1180px) { html.nt2 .ntc-head .ntc-props { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media screen and (max-width: 900px) { html.nt2 .ntc-head .ntc-props { grid-template-columns: minmax(0, 1fr); } }

/__ours/notion3.css:
/* 我们的 5etools —— V3 设计实验：暖色阅读配色。只在 html.nt3 下生效；页面结构沿用 V2（notion.css + notion2.css），这里只改颜色和导航带来的版面宽度。
 * 色彩来自原版 5etools 与规则书本身：羊皮纸底、标题红 #822000、数据块的金线、规则链接蓝，来源标记用每本书在原站的颜色。
 * 层级：顶栏（唯一的深色）→ 列表面板（旧纸）→ 阅读区（羊皮纸）→ 表格与弹层（最亮的纸面）。 */

/* 颜色及文字别名统一由 theme.css 定义；这里只保留基础投影和单元格边线。 */
html.nt3 {
	--nt-sh-sm: 0 1px 3px var(--bk-shadow-surface-soft), 0 0 0 1px var(--bk-shadow-outline-soft);
	--nt-sh-md: 0 8px 14px var(--bk-shadow-surface-medium), 0 2px 5px var(--bk-shadow-surface-faint), 0 0 0 1px var(--bk-shadow-outline-soft);
	--nt-sh-lg: 0 18px 28px var(--bk-shadow-surface-large), 0 4px 8px var(--bk-shadow-surface-soft), 0 0 0 1px var(--bk-shadow-outline-medium);
	--nt-sh-scr: 0 24px 48px var(--bk-shadow-search-large), 0 4px 12px var(--bk-shadow-search-soft), 0 0 0 1px var(--bk-shadow-search-outline);
}
html.nt3 ::selection { background: var(--bk-text-selection-bg); }
html.nt3 * { scrollbar-color: var(--bk-page-scroll-thumb) transparent; }
html.nt3 ::-webkit-scrollbar-thumb { background: var(--bk-page-scroll-thumb); }
html.nt3 ::-webkit-scrollbar-thumb:hover { background: var(--bk-page-scroll-thumb-hover); }
html.nt3 :focus-visible { outline-color: var(--v3-gold); }

/* ------------------------------------------------------------------ links: 规则链接是蓝色，不带下划线，悬停时出现 */
html.nt3 a, html.nt3 a:visited { color: var(--v3-link); text-decoration: none; }
html.nt3 a:hover { color: var(--bk-text-link-hover); text-decoration: underline; text-decoration-color: var(--bk-line-link-hover); text-underline-offset: 2px; }
html.nt3 #pagecontent a, html.nt3 .ntc-props a { text-decoration: none; }
html.nt3 #pagecontent a:hover, html.nt3 .ntc-props a:hover { text-decoration: underline; }
html.nt3 .help, html.nt3 .help-subtle { text-decoration-color: var(--bk-line-help-underline); }
html.nt3 .ve-roller, html.nt3 .render-roller { color: var(--v3-red) !important; background: var(--bk-btn-selected-wash); transition: background .1s; }
html.nt3 .ve-roller:hover, html.nt3 .render-roller:hover { background: var(--bk-btn-dice-hover-bg); }

/* ------------------------------------------------------------------ headings: 标题红；条目标题下有一条浅金线，方便扫读 */
html.nt3 .ve-rd__h { color: var(--v3-red); }
html.nt3 .ve-stats__h-name { color: var(--v3-red); }
html.nt3 .ve-rd__h--0 { border-bottom: 1px solid var(--bk-line-heading-soft); padding-bottom: 3px; margin-bottom: 6px; }
html.nt3 .ve-rd__b-inset .ve-rd__h { color: var(--v3-red); border-bottom: 0; }
html.nt3 .ve-rd__b-inset { background: var(--v3-panel); box-shadow: inset 3px 0 0 var(--v3-gold); border-radius: 0 8px 8px 0; }
html.nt3 .ve-rd__b-inset--readaloud { background: transparent; box-shadow: none; border-left-color: var(--v3-gold); }
html.nt3 .ve-rd__list-name { color: var(--v3-ink); }

/* ------------------------------------------------------------------ source marks: 每本书用它在原站的颜色（--src 由脚本写入）；没有专属颜色的按类别 */
html.nt3 .nt-tag { font-weight: 500; letter-spacing: .01em; }
html.nt3 .nt-tag[style*="--src"] { color: color-mix(in srgb, var(--src) 68%, var(--bk-tag-source-dark-mix)); background: color-mix(in srgb, var(--src) 17%, transparent); }
html.nt3 .omni__row-result [class*="ve-source__"] { font-weight: 500; }

/* ------------------------------------------------------------------ controls */
html.nt3 .ve-btn-default { box-shadow: inset 0 0 0 1px var(--v3-rule); transition: background .12s, box-shadow .12s; }
html.nt3 .ve-btn-default:hover, html.nt3 .ve-btn-default:focus { background: var(--bk-btn-default-hover-bg); box-shadow: inset 0 0 0 1px var(--bk-shadow-button-outline); }
html.nt3 .ve-btn-default.ve-active, html.nt3 .ve-btn-default:active { background: var(--v3-deep); box-shadow: inset 0 0 0 1px var(--bk-shadow-button-outline); }
html.nt3 .ve-form-control { box-shadow: inset 0 0 0 1px var(--v3-rule); }
html.nt3 .ve-lst__search { background: var(--v3-card) !important; box-shadow: inset 0 0 0 1px var(--v3-rule) !important; }
html.nt3 .ve-lst__search:focus { box-shadow: inset 0 0 0 1px var(--v3-link), 0 0 0 2px var(--bk-shadow-search-focus-ring) !important; }
html.nt3 #filter-search-group > .ve-btn { background: var(--v3-card); }
html.nt3 .ve-fltr__pill { box-shadow: inset 0 0 0 1px var(--v3-rule); }

/* ------------------------------------------------------------------ lists (every list page) */
html.nt3 #filtertools .sort { color: var(--v3-ink2); }
html.nt3 .ve-lst__row-inner { transition: background .08s; }
html.nt3 .ve-lst__row:hover > .ve-lst__row-inner { background: var(--bk-table-list-hover); }
html.nt3 .list-multi-selected > .ve-lst__row-inner { background: var(--v3-card) !important; box-shadow: inset 3px 0 0 var(--v3-red); }
html.nt3 .list-multi-selected > .ve-lst__row-inner > .ve-bold, html.nt3 .list-multi-selected > .ve-lst__row-inner > .nt-name { color: var(--v3-red); }

/* ------------------------------------------------------------------ tables in the text */
html.nt3 .ve-rd__table th, html.nt3 th.ve-rd__th { background: var(--v3-deep) !important; color: var(--bk-text-table-heading) !important; font-weight: 600; }
html.nt3 .ve-rd__table th, html.nt3 .ve-rd__table td { border-color: var(--v3-rule) !important; }
html.nt3 .ve-rd__table tbody tr:nth-child(even) > td { background: var(--bk-table-row-stripe); }
html.nt3 .ve-rd__table caption, html.nt3 .ve-rd__table-caption { color: var(--v3-red); }

/* ------------------------------------------------------------------ popovers, search window */
html.nt3 .ve-hwin > div:first-child { background: var(--v3-deep) !important; border-bottom-color: var(--v3-rule) !important; }
html.nt3.nt-search::before { background: var(--bk-page-modal-overlay); }
html.nt3 .ve-ui-modal__overlay { background: var(--bk-page-modal-overlay) !important; }
html.nt3 .omni__row-result:hover, html.nt3 .omni__row-result--selected, html.nt3 .omni__row-result:focus-within { background: var(--bk-btn-navigation-hover) !important; }

/* ================================================================== class page: V2's structure, wider now that the sidebar is gone */
html.nt3 main.classes.ntc-on { grid-template-columns: 256px minmax(0, 1fr); }
html.nt3 main.classes.ntc-on > .ntc { padding: 30px 44px 160px; }
html.nt3 .ntc-head, html.nt3 .ntc-sec { max-width: 1120px; margin-left: auto; margin-right: auto; }
html.nt3 .ntc-props { max-width: none; }
html.nt3 .ntc-read { grid-template-columns: minmax(0, 780px) 220px; justify-content: space-between; column-gap: 48px; }

/* the class list: 旧纸色面板，选中项是亮纸 + 红色书签 */
html.nt3 main.classes.ntc-on #listcontainer { background: var(--v3-panel); border-right: 1px solid var(--v3-rule); padding: 14px 12px 10px; }
html.nt3 .cls__list .ve-lst__row-inner { transition: background .08s; }
html.nt3 .cls__list .ve-lst__row:hover > .ve-lst__row-inner { background: var(--bk-btn-navigation-hover); }
html.nt3 .cls__list .list-multi-selected > .ve-lst__row-inner { background: var(--v3-card) !important; box-shadow: inset 3px 0 0 var(--v3-red), 0 1px 2px var(--bk-shadow-elevation-soft); }
html.nt3 #listcontainer #filtertools .sort { color: var(--v3-ink2); }
html.nt3 #list.cls__list .ve-ours-cls-off + .ve-ours-cls-feat::before, html.nt3 #list.cls__list .ve-ours-cls-feat + .ve-ours-cls-rest::before, html.nt3 #list.cls__list .ve-ours-cls-off + .ve-ours-cls-rest::before {
	color: var(--v3-ink2); border-top: 1px solid var(--v3-rule); margin-top: 8px; padding-top: 10px; }
html.nt3 #btngroup-manager .ve-btn-primary, html.nt3 #btngroup-manager .ve-btn-info { background: var(--v3-card); box-shadow: inset 0 0 0 1px var(--v3-rule); }

/* page header */
html.nt3 .ntc-title { color: var(--v3-red); letter-spacing: .01em; }
html.nt3 .ntc-title__en { color: var(--bk-text-class-english); }
html.nt3 .ntc-head .ntc-props { border-bottom: 2px solid var(--v3-gold); }
html.nt3 .ntc-props--more { border-bottom: 0; }
html.nt3 .ntc-prop__k { color: var(--v3-ink2); }
html.nt3 .ntc-actions .ve-btn { color: var(--v3-ink2); }
html.nt3 .ntc-actions .ve-btn:hover { color: var(--v3-red); }
/* 规则版本：和顶栏的版本开关同一种蓝；2014 用石色 */
html.nt3 .ntc-prop__v .nt-tag--24:not([style*="--src"]) { background: var(--bk-tag-off24-bg); color: var(--bk-tag-off24-ink); }
html.nt3 .ntc-prop__v .nt-tag--14:not([style*="--src"]) { background: var(--bk-tag-off14-bg); color: var(--bk-tag-off14-ink); }

/* section headings */
html.nt3 .ntc-h { color: var(--v3-red); }
html.nt3 .ntc-count { color: var(--v3-ink2); }

/* growth table: 最亮的纸面，上下金线（原站数据块的做法），隔行浅色，等级列加粗 */
html.nt3 .ntc-sec--table .ve-cls-tbl { background: var(--v3-card); border-top: 2px solid var(--v3-gold); border-bottom: 2px solid var(--v3-gold); }
html.nt3 .ve-cls-tbl > tbody > tr:has(> th.ve-cls-tbl__col-level) > th { background: var(--v3-deep); color: var(--bk-text-table-heading); font-weight: 600; border-right: 0; border-bottom: 1px solid var(--bk-line-class-table-heading); }
html.nt3 .ve-cls-tbl th[colspan]:not(.ve-cls-tbl__disp-name):not(.ve-tbl-border) { background: var(--v3-deep); color: var(--v3-red); font-weight: 600; padding-top: 6px; }
html.nt3 .ve-cls-tbl th[colspan]:empty { padding: 0 !important; height: 0; }
html.nt3 .ve-cls-tbl > tbody > tr > td { border-right: 0; border-bottom: 1px solid var(--bk-line-class-table-row); }
html.nt3 .ve-cls-tbl > tbody > tr:nth-child(even):has(> td) > td { background: var(--bk-table-class-row-stripe); }
