/__ours/notion4.css:
/* 我们的 5etools —— V4 设计实验：职业页重排。只在 html.nt4 下生效；外壳和配色沿用 V3（notion3.css），结构沿用 V2。
 * 四件事：列表每个职业一行；页头压成一行身份条；子职业只常驻本版官方的几个，其余进浏览面板；成长表并入所选子职的能力。
 * 原则：选择用的控件不占正文的位置；首屏留给成长表。 */

/* ================================================================== 1 class list: two tabs, one row per class */
html.nt4 .n4-ltabs { display: flex; gap: 2px; padding: 2px; margin: 10px 0 6px; background: var(--bk-btn-class-tabs-bg); border-radius: 7px; flex: none; }
html.nt4 .n4-ltabs button { flex: 1; height: 26px; padding: 0 6px; border: 0; border-radius: 5px; background: transparent; color: var(--v3-ink2); font: 13px var(--nt-font); cursor: pointer; white-space: nowrap; transition: background .1s, color .1s; }
html.nt4 .n4-ltabs button:hover { color: var(--v3-ink); }
html.nt4 .n4-ltabs button.on { background: var(--v3-card); color: var(--v3-red); font-weight: 600; box-shadow: 0 1px 2px var(--bk-shadow-tab-active); }
html.nt4 .n4-ltabs button > span { margin-left: 5px; font-weight: 400; font-size: 12px; color: var(--v3-ink2); font-variant-numeric: tabular-nums; }
html.nt4 #listcontainer #filtertools { display: none !important; }   /* the list has one order (规则书顺序); sorting buttons were noise */
html.nt4 #list .n4-merged .ve-lst__row-inner > span:last-child { display: none; }   /* both editions live behind this row: no book tag */
html.nt4 .cls__list .ve-lst__row-inner { min-height: 30px; }
html.nt4 .cls__list .n4-merged .ve-lst__row-inner > .nt-name { flex: 1 1 auto; max-width: none; width: auto; font-size: 15px; }
html.nt4 #list.n4-g-other .ve-ours-cls-off + .ve-ours-cls-feat::before, html.nt4 #list.n4-g-other .ve-ours-cls-off + .ve-ours-cls-rest::before { border-top: 0; margin-top: 0; padding-top: 4px; }
html.nt4 #list.n4-g-core:not(.n4-searching) .ve-lst__row::before { display: none !important; }

/* ================================================================== 2 identity strip */
html.nt4 main.classes.ntc-on > .ntc { padding-top: 18px; }
html.nt4 .ntc-head { margin-bottom: 0; padding-bottom: 10px; border-bottom: 2px solid var(--v3-gold); }
html.nt4 .ntc-head__row { align-items: center; flex-wrap: wrap; gap: 6px 14px; min-height: 36px; }
html.nt4 .ntc-title { flex: 0 0 auto; font-size: 24px; line-height: 32px; white-space: nowrap; }
html.nt4 .ntc-title__en { font-size: 15px; margin-left: 8px; font-weight: 400; }
html.nt4 .ntc-actions { padding-top: 0; margin-left: auto; }
html.nt4 .n4-ed { display: flex; align-items: center; gap: 6px; flex: none; }
html.nt4 .n4-edsw { display: inline-flex; padding: 2px; border-radius: 6px; background: var(--bk-btn-class-edition-track); }
html.nt4 .n4-edsw button { height: 22px; padding: 0 9px; border: 0; border-radius: 4px; background: transparent; color: var(--v3-ink2); font: 13px var(--nt-font); font-variant-numeric: tabular-nums; cursor: pointer; transition: background .1s, color .1s; }
html.nt4 .n4-edsw button:hover { color: var(--v3-ink); }
html.nt4 .n4-edsw button.on { background: var(--bk-tag-off24-bg); color: var(--bk-tag-off24-ink); font-weight: 600; cursor: default; }
html.nt4 .n4-edsw button[data-ed="14"].on { background: var(--bk-btn-edition-old-bg); color: var(--bk-btn-edition-old-ink); }
html.nt4 .n4-facts { display: flex; align-items: center; flex-wrap: wrap; gap: 2px 0; flex: 1 1 320px; min-width: 0; font-size: 14px; line-height: 24px; color: var(--v3-ink); }
html.nt4 .n4-fact { white-space: nowrap; padding: 0 12px; border-left: 1px solid var(--v3-rule); }
html.nt4 .n4-fact:first-child { padding-left: 0; border-left: 0; }
html.nt4 .n4-fact > i { font-style: normal; color: var(--v3-ink2); margin-right: 6px; font-size: 13px; }
html.nt4 .n4-more { height: 24px; margin-left: 4px; padding: 0 8px; border: 0; border-radius: 5px; background: transparent; color: var(--v3-link); font: 13px var(--nt-font); cursor: pointer; }
html.nt4 .n4-more:hover { background: var(--bk-table-class-row-hover); }
html.nt4 .ntc-head .ntc-props { display: none; margin-top: 10px; padding-bottom: 2px; border-bottom: 0; }
html.nt4 .ntc-head.n4-open .ntc-props { display: grid; }

/* ================================================================== 3 subclass row + browser */
html.nt4 .ntc-sec { margin-top: 22px; }
html.nt4 .ntc-sec--sub { position: relative; display: flex; align-items: flex-start; gap: 4px 12px; margin-top: 12px; }
