/* 预设下拉、全选、随机、重置、来源开关：收起（ours.js 加 ve-hidden）；面板里有搜索和“清除选择” */
html.nt4 .ntc-sec--sub .cls-tabs__wrp > .ve-flex-wrap { gap: 5px; align-items: center; }
html.nt4 .ntc-sec--sub .cls-tabs__wrp > .ve-flex-wrap > .ve-btn { display: inline-flex; align-items: center; height: 28px !important; line-height: 28px !important; padding: 0 10px !important; border-radius: 6px !important; }
html.nt4 .ntc-sec--sub .ve-btn.n4-off, html.nt4 .ntc-sec--sub .ntc-scg, html.nt4 .ntc-sec--sub .cls-tabs__sc-not-shown, html.nt4 .ntc-sec--sub .cls-tabs__wrp i.ve-clickable { display: none !important; }
html.nt4 .n4-browse { flex: none; display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 8px 0 11px; border: 0; border-radius: 6px; background: var(--v3-card); box-shadow: inset 0 0 0 1px var(--v3-rule); color: var(--v3-ink); font: 14px var(--nt-font); cursor: pointer; white-space: nowrap; transition: background .1s, box-shadow .1s; }
html.nt4 .n4-browse:hover, html.nt4 .n4-browse.on { box-shadow: inset 0 0 0 1px var(--v3-gold); background: var(--bk-btn-card-hover-bg); }
html.nt4 .n4-browse__n { color: var(--v3-ink2); font-variant-numeric: tabular-nums; }
html.nt4 .n4-browse.n4-none { display: none; }
html.nt4 .n4-caret { width: 7px; height: 7px; margin: -3px 3px 0 2px; border-right: 1.5px solid var(--v3-ink2); border-bottom: 1.5px solid var(--v3-ink2); transform: rotate(45deg); transition: transform .12s; }
html.nt4 .n4-browse.on .n4-caret { transform: rotate(-135deg); margin-top: 3px; }

html.nt4 .n4-pop { position: absolute; z-index: 60; left: 0; right: 0; top: calc(100% + 6px); max-height: min(66vh, 620px); display: flex; flex-direction: column; background: var(--v3-card); border-radius: 10px; box-shadow: var(--nt-sh-lg); animation: n4pop .12s ease-out; }
html.nt4 .n4-pop[hidden] { display: none; }
@keyframes n4pop { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) { html.nt4 .n4-pop { animation: none; } html.nt4 #pagecontent .n4-flash { animation: none; } }
html.nt4 .n4-pop__bar { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; padding: 10px 12px; border-bottom: 1px solid var(--v3-rule2); flex: none; }
html.nt4 .n4-pop__q { flex: 0 1 220px; min-width: 150px; height: 30px; padding: 0 10px; border: 0; border-radius: 6px; background: var(--v3-paper); box-shadow: inset 0 0 0 1px var(--v3-rule); color: var(--v3-ink); font: 14px var(--nt-font); outline: none; }
html.nt4 .n4-pop__q:focus { box-shadow: inset 0 0 0 2px var(--v3-gold); }
html.nt4 .n4-kinds { display: flex; flex-wrap: wrap; gap: 4px; flex: 1 1 auto; }
html.nt4 .n4-kinds button { height: 26px; padding: 0 9px; border: 0; border-radius: 13px; background: transparent; color: var(--v3-ink2); font: 13px var(--nt-font); cursor: pointer; white-space: nowrap; }
html.nt4 .n4-kinds button:hover { background: var(--bk-btn-hover-wash); color: var(--v3-ink); }
html.nt4 .n4-kinds button.on { background: var(--v3-deep); color: var(--v3-red); font-weight: 600; }
html.nt4 .n4-kinds button > span { margin-left: 5px; font-weight: 400; font-size: 12px; color: var(--v3-ink2); font-variant-numeric: tabular-nums; }
html.nt4 .n4-pop__btn { height: 26px; padding: 0 9px; border: 0; border-radius: 6px; background: transparent; color: var(--v3-ink2); font: 13px var(--nt-font); cursor: pointer; flex: none; }
html.nt4 .n4-pop__btn:hover { background: var(--bk-btn-navigation-hover); color: var(--v3-red); }
html.nt4 .n4-pop__list { flex: 1 1 auto; min-height: 0; overflow-y: auto; padding: 4px 12px 10px; }
html.nt4 .n4-g__h { display: flex; align-items: center; gap: 7px; margin: 12px 0 6px; font-size: 12px; font-weight: 600; color: var(--v3-ink2); }
html.nt4 .n4-g__h::before { content: ""; width: 8px; height: 8px; border-radius: 2px; background: var(--k, var(--v3-ink2)); }
html.nt4 .n4-g__h > span { font-weight: 400; color: var(--v3-ink2); }
html.nt4 [data-g="off24"] { --k: var(--v3-k-off24); } html.nt4 [data-g="off14"] { --k: var(--v3-k-off14); } html.nt4 [data-g="ours"] { --k: var(--v3-k-ours); }
html.nt4 [data-g="3p"] { --k: var(--v3-k-3p); } html.nt4 [data-g="ua"] { --k: var(--v3-k-ua); }
html.nt4 .n4-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 6px; }
html.nt4 .n4-card { position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "n tag" "t t"; gap: 1px 8px; align-items: center; min-height: 52px; padding: 7px 38px 7px 11px; border-radius: 7px; background: var(--v3-paper); box-shadow: inset 0 0 0 1px var(--v3-rule2); cursor: pointer; transition: background .08s, box-shadow .08s; }
html.nt4 .n4-card:hover { background: var(--bk-btn-card-hover-bg); box-shadow: inset 0 0 0 1px var(--v3-gold); }
html.nt4 .n4-card:focus-visible { outline: 2px solid var(--v3-gold); outline-offset: 1px; }
html.nt4 .n4-card.on { background: var(--bk-btn-card-hover-bg); box-shadow: inset 3px 0 0 var(--k), inset 0 0 0 1px var(--k); }
html.nt4 .n4-card__n { grid-area: n; font-size: 15px; font-weight: 600; color: var(--v3-ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
html.nt4 .n4-card.on .n4-card__n { color: var(--k); }
