/* 奇械师：2014 版子职业列在 2024 版下时，「2014」和来源两个标签并排 */
html.nt4 .n4-card > .n4-card__tags { grid-area: tag; display: flex; gap: 4px; justify-self: end; }
html.nt4 .n4-card__tags > .nt-tag { height: 18px; line-height: 18px; font-size: 11px; padding: 0 5px; }
html.nt4 .n4-card__t { grid-area: t; font-size: 13px; line-height: 18px; color: var(--v3-ink2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-height: 18px; }
html.nt4 .n4-card__add { position: absolute; right: 6px; top: 50%; width: 26px; height: 26px; margin-top: -13px; padding: 0; border: 0; border-radius: 6px; background: transparent; color: var(--v3-ink2); font: 16px/26px var(--nt-font); cursor: pointer; }
html.nt4 .n4-card__add:hover { background: var(--bk-btn-subclass-add-hover); color: var(--v3-red); }
html.nt4 .n4-pop__foot { flex: none; padding: 8px 14px 10px; border-top: 1px solid var(--v3-rule2); font-size: 12px; color: var(--v3-ink2); }
html.nt4 .n4-empty { padding: 28px 8px; color: var(--v3-ink2); font-size: 14px; text-align: center; }

/* ================================================================== 4 growth table with the chosen subclass's features */
html.nt4 .ntc-sec--table { margin-top: 14px; }
