	box-shadow: 0 1px 2px var(--bk-shadow-book-contact), 0 6px 14px var(--bk-shadow-book-raised), inset 3px 0 0 var(--bk-shadow-book-spine); transition: transform .14s, box-shadow .14s; }
html.nt4 .bk5-book:hover .bk5-cover { transform: translateY(-3px); box-shadow: 0 2px 4px var(--bk-shadow-book-hover), 0 12px 24px var(--bk-shadow-book-hover); }
html.nt4 .bk5-cover > img { display: block; width: 100%; height: 100%; object-fit: cover; }
html.nt4 .bk5-gen, html.nt4 .bk5-tochead__gen { box-sizing: border-box; width: 100%; height: 100%; display: flex; flex-direction: column; justify-content: space-between; padding: 14px 12px; color: var(--bk-text-book-cover);
	background: linear-gradient(160deg, var(--c, var(--bk-book-cover-fallback-bg)), color-mix(in srgb, var(--c, var(--bk-book-cover-fallback-bg)) 68%, var(--bk-book-cover-gradient-mix))); box-shadow: inset 6px 0 0 var(--bk-shadow-book-spine), inset 0 0 0 1px var(--bk-shadow-book-cover-frame); }
html.nt4 .bk5-gen__a { font-size: 11px; letter-spacing: .06em; opacity: .85; }
