/* ---- 读书页：目录 */
html.nt4.ours-bk[data-ours-page="book"] .view-col-wrapper, html.nt4.ours-bk[data-ours-page="adventure"] .view-col-wrapper { width: 100% !important; max-width: none !important; padding: 0 !important; margin: 0 !important; gap: 0; }
html.nt4.ours-bk #listcontainer.book-contents { max-width: 290px; min-width: 240px; margin: 0 !important; padding: 16px 12px 40px; background: var(--v3-panel); border-right: 1px solid var(--v3-rule); box-sizing: border-box;
	position: sticky; top: 0; align-self: flex-start; height: 100vh !important; max-height: 100vh !important; overflow-y: auto !important; }   /* 目录固定在左边，正文滚动时不跟着走 */
html.nt4 .bk5-tochead { display: grid; grid-template-columns: auto 38px minmax(0, 1fr); grid-template-rows: auto auto; column-gap: 8px; align-items: center; padding: 6px 4px 12px; margin-bottom: 8px; border-bottom: 1px solid var(--v3-rule); }
html.nt4 .bk5-tochead > .bk5-car { grid-row: 1 / 3; }
html.nt4 .bk5-tochead > .bk5-tochead__img, html.nt4 .bk5-tochead > .bk5-tochead__gen { grid-row: 1 / 3; grid-column: 2; }
html.nt4 .bk5-tochead__t { grid-column: 3; align-self: end; }
html.nt4 .bk5-tochead__s { grid-column: 3; align-self: start; }
html.nt4 .bk5-tochead__img, html.nt4 .bk5-tochead__gen { flex: none; width: 38px !important; height: 50px !important; padding: 0 !important; border-radius: 2px 4px 4px 2px; object-fit: cover; box-shadow: 0 2px 6px var(--bk-shadow-book-thumbnail); }
