html.nt4 .bk5-car::before { content: ""; width: 0; height: 0; border-left: 5px solid currentColor; border-top: 4px solid transparent; border-bottom: 4px solid transparent; transition: transform .12s; }
html.nt4 .bk5-car.open::before { transform: rotate(90deg); }
html.nt4 .bk5-car:hover { background: var(--bk-btn-selected-wash); color: var(--v3-ink); }
html.nt4.ours-bk .book-contents a { color: var(--v3-ink) !important; text-decoration: none !important; }
html.nt4.ours-bk .book-contents .bk5-cur { background: var(--v3-card); box-shadow: inset 2px 0 0 var(--v3-red); border-radius: 6px; }
html.nt4.ours-bk .book-contents .bk5-cur, html.nt4.ours-bk .book-contents .bk5-cur > a, html.nt4.ours-bk .book-contents .bk5-cur a:first-of-type { color: var(--v3-red) !important; font-weight: 600; }
html.nt4.ours-bk .book-contents .bk5-cur-sec { background: var(--bk-btn-navigation-hover); border-radius: 5px; }
html.nt4.ours-bk .book-contents .bk5-cur-sec, html.nt4.ours-bk .book-contents .bk5-cur-sec a { color: var(--v3-red) !important; font-weight: 600; }

/* ---- 读书页：正文 */
html.nt4.ours-bk .book-view { min-width: 0; margin: 0 !important; padding: 0 44px 80px; overflow: visible !important; }   /* 不自己滚：页面整体滚，面包屑才能 sticky 在顶部 */
html.nt4 .bk5-crumbs { position: sticky; top: 0; z-index: 5; display: flex; align-items: center; gap: 8px; box-sizing: border-box; width: 100%; max-width: 780px; flex: none; align-self: center; height: 44px; margin: 0 auto; background: var(--v3-paper);
	border-bottom: 1px solid var(--v3-rule2); font-size: 13px; color: var(--v3-ink2); white-space: nowrap; }
html.nt4 .bk5-crumbs__book { font-weight: 600; color: var(--v3-ink) !important; text-decoration: none !important; }
html.nt4 .bk5-crumbs__ch, html.nt4 .bk5-crumbs__sec { overflow: hidden; text-overflow: ellipsis; min-width: 0; }
html.nt4 .bk5-crumbs__sep { color: var(--v3-rule); }
html.nt4 .bk5-crumbs__sp { flex: 1 1 auto; }
html.nt4 .bk5-crumbs .ve-btn { height: 26px; border-radius: 6px !important; }
html.nt4 #pagecontent.bk5-doc { width: 100% !important; max-width: 780px; align-self: center; margin: 0 auto !important; border: 0 !important; background: transparent !important; box-shadow: none !important; }
html.nt4 #pagecontent.bk5-doc .ve-rd__b, html.nt4 #pagecontent.bk5-doc .ve-rd__b p, html.nt4 #pagecontent.bk5-doc .ve-rd__li { font-size: 16px; line-height: 1.9; }
html.nt4 #pagecontent.bk5-doc .ve-rd__b > p { margin: 0 0 14px; }
html.nt4 #pagecontent.bk5-doc .ve-rd__h--0 { font-size: 30px; line-height: 1.3; margin: 26px 0 16px; }
html.nt4 #pagecontent.bk5-doc .ve-rd__h--1 { font-size: 21px; margin: 30px 0 8px; }
html.nt4 #pagecontent.bk5-doc .ve-rd__b--inset, html.nt4 #pagecontent.bk5-doc .ve-rd__b-inset { border-radius: 10px; background: var(--bk-page-book-inset-bg) !important; border: 0 !important; box-shadow: inset 3px 0 0 var(--v3-gold) !important; padding: 16px 20px !important; font-size: 15px; line-height: 1.8; }
html.nt4 #pagecontent.bk5-doc img { max-width: 100%; height: auto; }
html.nt4 #pagecontent.bk5-doc td { padding-left: 0 !important; padding-right: 0 !important; }
html.nt4 .bk5-pn { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; box-sizing: border-box; width: 100%; max-width: 780px; flex: none; align-self: center; margin: 28px auto 40px; }
html.nt4 .bk5-pn a { display: block; padding: 12px 16px; border-radius: 10px; background: var(--v3-card); box-shadow: inset 0 0 0 1px var(--v3-rule); color: var(--v3-ink) !important; text-decoration: none !important; transition: box-shadow .12s, transform .12s; }
html.nt4 .bk5-pn a:hover { box-shadow: inset 0 0 0 1px var(--v3-gold), 0 6px 16px var(--bk-shadow-elevation-soft); transform: translateY(-1px); }
html.nt4 .bk5-pn small { display: block; font-size: 12px; color: var(--v3-ink2); }
html.nt4 .bk5-pn span { font-weight: 600; }
html.nt4 .bk5-pn__next { text-align: right; grid-column: 2; }

html.nt4.ours-bk .book-contents .ve-lst__row-inner { display: flex !important; align-items: center; }   /* 三角和条目标题同一行 */

/__ours/optioncard.css:
html:root .bk-opt-head {
  display: grid;
  grid-template: "art name source" auto "art info info" 1fr / auto minmax(0, 1fr) auto;
  gap: 8px 10px;
  align-items: start;
  container-type: inline-size;
}
html:root .bk-opt-name { grid-area: name; min-width: 0; }
html:root .bk-opt-name > * { min-width: 0; }
html:root .bk-opt .ve-stats__h-name { overflow-wrap: anywhere; }
html:root .bk-opt .stats__wrp-h-source { grid-area: source; }
html:root .bk-opt .bk-opt-head > :is(.bk-opt-cells, .bk-opt-meta) { grid-area: info; }
html:root .bk-opt-art {
  grid-area: art;
  align-self: start;
  position: relative;
  display: grid;
  place-items: center;
  box-sizing: border-box;
  width: 64px;
  height: 64px;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: 1.5px solid var(--bk-gold);
  border-radius: 6px;
  color: var(--bk-head);
  background: radial-gradient(circle at 50% 40%, color-mix(in srgb, var(--bk-gold) 18%, transparent), transparent 70%),
    radial-gradient(closest-side, var(--bk-glow), transparent);
}
html:root .bk-opt-portrait { width: 88px; height: 112px; }
html:root .bk-opt-art svg { width: 30px; height: 30px; border-radius: 50%; outline: 1px solid var(--bk-gold); outline-offset: 6px; }
html:root .bk-opt-art img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; visibility: hidden; }
html:root .bk-opt-art img.bk-opt-landscape { object-fit: cover; object-position: center; }
html:root .bk-opt-art[data-kind="image"] { cursor: zoom-in; }
html:root .bk-opt-art[data-kind="image"] img { visibility: visible; }
html:root .bk-opt-art[data-kind="image"] svg { visibility: hidden; }
html:root .bk-opt-art:focus-visible { outline: 2px solid var(--bk-gold); outline-offset: 2px; }
html:root .bk-opt-cells {
  display: grid;
  grid-template-columns: repeat(var(--bk-opt-columns), minmax(0, 1fr));
  overflow: hidden;
  gap: 1px;
  margin-bottom: 4px;
  border: 1px solid color-mix(in srgb, var(--bk-gold) 45%, var(--v3-rule));
  border-radius: 6px;
  background: color-mix(in srgb, var(--bk-gold) 28%, var(--v3-card));
}
html:root .bk-opt-cell {
  min-width: 0;
  padding: 2px 8px;
  background: var(--v3-card);
  color: var(--v3-ink);
  font-size: 14px;
  font-weight: 700;
  line-height: 1.35;
  overflow-wrap: anywhere;
  font-variant-numeric: tabular-nums;
}
html:root .bk-opt-wide { grid-column: 1 / -1; }
html:root .bk-opt-cell > .bk-opt-label { display: block; color: var(--v3-ink2); font-size: 11px; font-weight: 400; }
html:root .bk-opt-meta { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 5px; color: var(--v3-ink2); font-size: 13px; font-weight: 400; line-height: 1.4; }
html:root .bk-opt-meta > i { font-style: normal; }
html:root .bk-opt .bk-opt-tag { display: inline; border-radius: 999px; padding: 1px 6px; background: var(--v3-deep); color: var(--v3-ink2); font-size: 12px; font-weight: 700; }
html:root .bk-opt .bk-opt-foot { color: var(--v3-ink2); font-size: 12px; }
html:root .bk-opt-foot > .orn {
  position: relative;
  height: 1px;
  margin: 0 0 5px;
  background: linear-gradient(90deg, transparent, var(--bk-gold) 12%, var(--bk-gold) 88%, transparent);
}
html:root .bk-opt-foot > .orn::after {
  content: "";
  position: absolute;
  left: 50%;
  top: -3px;
  width: 6px;
  height: 6px;
  border: 1px solid var(--bk-gold);
  background: var(--v3-card);
  transform: rotate(45deg);
}
html:root .bk-opt .entry-title-inner:not(.tag) { font-family: var(--bk-heading-font); font-weight: 900; color: var(--bk-head); }
html:root .bk-opt .bk-opt-en { font: italic 400 13px Georgia, serif; color: var(--v3-ink2); }
html:root .bk-opt .ve-rd__table th { font-size: 11px; border-bottom: 1px solid var(--bk-gold); color: var(--v3-ink2); }
html:root .bk-opt .ve-rd__table > tbody > tr:nth-child(even) > td { background-color: var(--bk-row-stripe); }
html:root .bk-opt .ve-rd__table > tbody > tr > td:first-child { font-family: var(--bk-heading-font); font-weight: 900; font-variant-numeric: tabular-nums; }
html:root .bk-opt-list-icon,
html:root .bk-opt-list-icon svg,
html:root .bk-opt-filter svg { display: inline-block; flex: none; width: 14px; height: 14px; color: var(--bk-head); }
html:root .bk-opt-list-icon, html:root .bk-opt-filter svg { vertical-align: -2px; margin-inline-end: 4px; }
html:root .bk-opt-filter[aria-pressed="true"] svg { color: inherit; }
html.nt4.ours-l5 #pagecontent .ve-stats__th-name > .bk-opt-head { align-items: start; padding-bottom: 3px; }
html:root #stat-tabs:has(.stat-tab-gen) + #wrp-pagecontent #pagecontent .bk-opt-head { padding-top: 8px; }
html.nt3 .bk-opt .bk-opt-summary-only::before,
html.nt3 .bk-opt .bk-opt-summary-only::after { content: none; }
@layer vetools {
  html:root .bk-opt .ve-rd__table > tbody > tr > td:first-child,
  html:root .bk-opt .ve-rd__table > tbody > tr > td:first-child .ve-muted { color: var(--bk-head) !important; }
  html:root .ve-hwin .bk-opt-preview > tbody > tr > :is(th, td) { padding-inline: 12px !important; }
  html:root .ve-hwin:has(.bk-opt-preview) .ve-hoverborder { background-color: var(--v3-rule) !important; border-color: var(--bk-gold) !important; }
  html:root .bk-opt .bk-opt-foot { padding-top: 5px !important; }
}
@container (width < 560px) {
  html:root .bk-opt-cells { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
/* The disclosure is a sibling of the native link, with its own hit target. */
html.nt4.ours-l5[data-ours-page="races"] #listcontainer:has(.rf-list) #filtertools {
	display: flex !important;
	align-items: center;
	height: 24px;
}
html.nt4.ours-l5[data-ours-page="races"] #filtertools .sort {
	flex: 1;
	color: var(--v3-ink2);
}
html.nt4.ours-l5[data-ours-page="races"] #filtertools [aria-pressed="true"] {
	color: var(--bk-head);
	font-weight: 700;
}
.rf-list { display: flex; flex-direction: column; reading-flow: flex-visual; }
.rf-list > .ve-lst__row { position: relative; flex: none; }
html.nt4.ours-l5 #listcontainer .rf-list .ve-lst__row-inner { min-height: 38px; }
/* Every family row keeps the triangle slot, so names line up whether or not it has variants. */
html.nt4.ours-l5 #listcontainer .rf-list > .ve-lst__row:not(.rf-child) > a {
	padding-left: 32px !important;
}
html.nt4.ours-l5 #listcontainer .rf-list .rf-child > a {
	padding-left: 44px !important;
}
.rf-toggle {
	position: absolute;
	z-index: 1;
	inset: 0 auto 0 3px;
	margin: auto 0;
	width: 27px;
	height: 30px;
	display: grid;
	place-items: center;
	background: transparent;
	color: var(--v3-ink2);
	border: 0;
	border-radius: 3px;
	cursor: pointer;
}
.rf-toggle:hover, .rf-toggle:focus-visible { color: var(--bk-head); background: var(--v3-deep); }
.rf-toggle::before { content: ""; border: 4px solid transparent; border-right: 0; border-left: 6px solid currentColor; }
.rf-toggle[aria-expanded="true"]::before { transform: rotate(90deg); }
.rf-variant { margin-left: 6px; font-size: 12px; color: var(--v3-ink2); }
html.nt4.ours-l5 #listcontainer .rf-list .rf-current > a {
	background: var(--v3-card);
	box-shadow: inset 3px 0 0 var(--bk-head);
}

/__ours/ours.css:
/* 我们的 5etools —— 本地版外观 */
:root {
	--ours-T0: var(--bk-rating-legendary); --ours-T1: var(--bk-rating-epic); --ours-T2: var(--bk-rating-fine); --ours-T3: var(--bk-rating-good); --ours-T4: var(--bk-rating-common);

	 --ours-night: var(--bk-nav-legacy-gradient-start); --ours-plum: var(--bk-nav-legacy-gradient-end);
	--ours-shadow: 0 6px 22px var(--bk-shadow-legacy-panel);
}
.ve-night-mode {    --ours-shadow: 0 6px 22px var(--bk-shadow-legacy-night-panel); }
.ours-hide { display: none !important; }
.ours-muted { opacity: .65; font-size: .9em; font-weight: normal; }
.ours-c--T0 { color: var(--ours-T0); } .ours-c--T1 { color: var(--ours-T1); } .ours-c--T2 { color: var(--ours-T2); } .ours-c--T3 { color: var(--ours-T3); } .ours-c--T4 { color: var(--ours-T4); }
.ours-bg--T0 { background: linear-gradient(135deg, var(--bk-rating-legendary-gradient), var(--ours-T0)); } .ours-bg--T1 { background: linear-gradient(135deg, var(--bk-rating-epic-gradient), var(--ours-T1)); }
.ours-bg--T2 { background: linear-gradient(135deg, var(--bk-rating-fine-gradient), var(--ours-T2)); } .ours-bg--T3 { background: linear-gradient(135deg, var(--bk-rating-good-gradient), var(--ours-T3)); }
.ours-bg--T4 { background: linear-gradient(135deg, var(--bk-rating-common-gradient), var(--ours-T4)); }

/* ---------------------------------------------------------------- header polish */
.ours-local .page__header { background: linear-gradient(100deg, var(--bk-nav-legacy-header-start) 0%, var(--bk-nav-legacy-header-middle) 45%, var(--bk-nav-legacy-header-end) 100%); box-shadow: inset 0 -2px 0 var(--bk-shadow-header-gold-edge); }
.ours-local .page__title { text-shadow: 0 2px 8px var(--bk-shadow-text-strong); letter-spacing: .5px; }

/* ---------------------------------------------------------------- top bar */
.ours-bar { display: flex; align-items: center; gap: 12px; padding: 6px 12px !important; margin-top: 4px; margin-bottom: 6px;
	background: linear-gradient(90deg, var(--ours-night), var(--ours-plum)); color: var(--bk-text-legacy-bar); border-radius: 10px; box-shadow: var(--ours-shadow);
	border: 1px solid var(--bk-line-legacy-gold-frame); position: relative; z-index: 5; }
.ours-bar__brand { color: var(--bk-text-legacy-brand) !important; font-weight: 700; letter-spacing: 1px; white-space: nowrap; text-decoration: none !important; }
.ours-bar__sigil { display: inline-block; margin-right: 6px; color: var(--ours-gold); animation: ours-spin 12s linear infinite; }
@keyframes ours-spin { to { transform: rotate(360deg); } }
.ours-bar__switch { display: flex; background: var(--bk-nav-legacy-pressed-bg); border-radius: 999px; padding: 3px; gap: 2px; flex-wrap: wrap; }
.ours-seg { border: 0; background: transparent; color: var(--bk-text-legacy-control); padding: 4px 14px; border-radius: 999px; font-size: 13px; cursor: pointer; transition: all .15s; white-space: nowrap; }
.ours-seg:hover { background: var(--bk-nav-legacy-hover); }
.ours-seg--on { background: linear-gradient(135deg, var(--bk-btn-legacy-gold-gradient), var(--ours-gold)); color: var(--bk-btn-legacy-primary-ink); font-weight: 700; box-shadow: 0 0 10px var(--bk-shadow-legacy-button-glow); }
.ours-seg[data-mode=manual] { opacity: .7; font-size: 12px; }
.ours-bar:not(.ours-bar--list) .ours-bar__switch { opacity: .85; }
.ours-bar__spacer { flex: 1; }
.ours-bar__status { border: 1px solid var(--bk-line-legacy-control); background: var(--bk-btn-legacy-recessed-bg); color: var(--bk-text-legacy-control); border-radius: 999px; padding: 3px 12px; font-size: 12px; cursor: pointer; white-space: nowrap; }
.ours-dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: 6px; background: var(--bk-rating-unknown-marker); vertical-align: middle; }
.ours-dot--ok { background: var(--bk-nav-status-online-bg); box-shadow: 0 0 6px var(--bk-shadow-status-online-glow); } .ours-dot--off { background: var(--bk-nav-status-offline-bg); } .ours-dot--busy { background: var(--bk-nav-status-busy-bg); animation: ours-pulse 1s infinite; }
@keyframes ours-pulse { 50% { opacity: .3; } }
.ours-data-menu { position: absolute; z-index: 10000; width: 330px; padding: 10px; border-radius: 10px; background: var(--bk-page-legacy-menu-bg); border: 1px solid var(--bk-line-legacy-menu-frame); box-shadow: 0 8px 30px var(--bk-shadow-dialog-large); color: var(--bk-text-legacy-dialog); font-size: 13px; }
.ours-data-menu__info { opacity: .8; line-height: 1.6; margin: 2px 4px 8px; }
.ours-data-menu__path { word-break: break-all; font-size: 12px; color: var(--bk-text-legacy-gold-emphasis); }
.ours-data-menu__btn { display: block; width: 100%; text-align: left; margin-top: 6px; padding: 8px 10px; border-radius: 8px; border: 1px solid var(--bk-line-legacy-chip); background: var(--bk-btn-legacy-recessed-bg); color: inherit; cursor: pointer; }
.ours-data-menu__btn:hover { border-color: var(--bk-btn-legacy-gold-gradient); }
.ours-data-menu__btn b { display: block; font-size: 14px; color: var(--bk-text-legacy-gold-emphasis); }
.ours-data-menu__btn span { font-size: 12px; opacity: .75; }

/* ---------------------------------------------------------------- tier gems */
.ours-gem { display: inline-flex; align-items: center; justify-content: center; min-width: 22px; height: 16px; padding: 0 4px; margin-right: 5px; border-radius: 4px;
