			const prop = ent.__prop;
			const R = Renderer[prop];
			if (!R?.pGetFluff) return null;
			const fluff = await R.pGetFluff(ent);
			const img = fluff?.images?.[0];
			if (!img) return null;
			return Renderer.utils.getEntryMediaUrl(img, "href", "img");
		} catch (e) { return null; }
	}

