		const r = itemRating(ent) || {};
		const m = modal(`评价：${esc(ent.name)} <span class="ours-muted">${esc(Parser.sourceJsonToAbv(ent.source))}</span>`, `
			<div class="ours-form">
				<label>档位</label>${tierPicker(r.tier)}
