			add("挑战等级", pf._crFilter, [["0–4", "0", "4"], ["5–10", "5", "10"], ["11–16", "11", "16"], ["17+", "17", null]].map(([text, min, max]) => ({text, min: labels.indexOf(min), max: max == null ? pf._crFilter._state.max : labels.indexOf(max)})), {range: true, single: true});
