			clearTimeout(editionTimer); editionTimer = setTimeout(() => {
				if (!sorter) return;
				for (const list of lists) {
					const next = list.getSortedItems();
					if (next.length !== list.visibleItems.length || next.some((it, i) => it !== list.visibleItems[i])) list._doSort();
				}
