html:root .bk-spell .bk-spell-foot { display: grid; grid-template-columns: 100px minmax(0, 1fr); gap: 6px; }
html:root .bk-spell .bk-spell-foot > :first-child { font-size: 12px; font-weight: 700; color: var(--v3-ink2); }
html:root .bk-spell .bk-spell-foot-first { position: relative; margin-top: 8px; padding-top: 8px; }
html:root .bk-spell .bk-spell-foot-first::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 1px; background: linear-gradient(90deg, transparent, var(--bk-gold) 12%, var(--bk-gold) 88%, transparent); }
html:root .bk-spell .bk-spell-foot-first::after { content: ''; position: absolute; top: -3px; left: 50%; width: 6px; height: 6px; border: 1px solid var(--bk-gold); background: var(--v3-card); transform: rotate(45deg); }
html:root .bk-spell .bk-spell-source { font-size: 12px; color: var(--v3-ink2); }
html:root .bk-spell .entry-title-inner { font-family: var(--bk-heading-font); font-weight: 900; color: var(--bk-head); }
html:root .bk-spell .bk-spell-en { font: italic 400 13px Georgia, serif; color: var(--v3-ink2); }
html:root.ours-l5[data-ours-page="spells"] #listcontainer .list .bk-school { display: inline-flex; align-items: center; gap: 3px; width: 74px; color: var(--v3-ink2) !important; font-size: 12px; }
html:root .bk-school svg, html:root .bk-school-option svg { flex: none; width: 16px; height: 16px; color: var(--bk-head); }
html:root .bk-school-option { display: flex; align-items: center; gap: 5px; }
/* Keep every native preview row on the same inset, including prose and footer. */
@layer vetools {
  html:root .ve-hwin table.bk-spell.bk-spell-preview > tbody > tr > :is(th, td) { padding-inline: 12px !important; }
}
@container (width < 560px) {
  html:root .bk-spell .bk-spell-cells { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  html:root .bk-spell .bk-spell-cell:nth-child(3) { border-left: 0; }
  html:root .bk-spell .bk-spell-cell:nth-child(n+3) { border-top: 1px solid var(--v3-rule); }
}

/__ours/statblock.css:
/* 精装怪物卡：只作用于已经识别并移动了原生节点的卡片。 */
.bk-mon { container-type: inline-size; }
.bk-mon .bk-mon-row > th { font: 15px/1.65 var(--nt-font, sans-serif) !important; text-align: left; }
.bk-mon .bk-mon-row > th::before, .bk-mon .bk-mon-row > th::after { display: none; }
.bk-mon-head { position: relative; container-type: inline-size; display: grid; grid-template-columns: minmax(0,1fr); align-items: stretch !important; }
.bk-mon-head:has(.bk-mon-portrait) { grid-template-columns: minmax(0,1fr) 200px; column-gap: 12px; }
.bk-mon-main { min-width: 0; grid-column: 1; grid-row: 2; }
.bk-mon-meta { grid-column: 1 / -1; grid-row: 1; }
.bk-mon-meta { display: flex; gap: 8px; align-items: baseline; font-size: 12px; line-height: 1.4; color: var(--v3-ink2); }
.bk-mon-badge { border: 1px solid var(--v3-rule); border-radius: 12px; padding: 0 6px; color: var(--bk-head); }
.bk-mon-name .ve-stats__h-name { display: inline; font-family: var(--bk-heading-font); font-weight: 900; color: var(--bk-head); font-size: 26px; line-height: 1.2; }
.bk-mon-name .ve-stats__eh-name { display: inline; font: italic 14px Georgia, serif !important; color: var(--v3-ink2); margin-left: 8px !important; }
.bk-mon-name .ve-flex-col { display: block; }
.bk-mon-name .ve-split-v-end { display: block; }
.bk-mon-type { font-style: italic; color: var(--v3-ink2); line-height: 1.65; }
.bk-mon-vitals { display: grid; grid-template-columns: minmax(0,1fr) minmax(0,1fr) minmax(0,1.5fr); gap: 7px; margin: 3px 0; }
.bk-mon-vital { border-left: 2px solid var(--bk-gold); padding-left: 7px; min-width: 0; line-height: 1.4; }
.bk-mon-vital > small { display: block; color: var(--v3-ink2); font-size: 11px; }
.bk-mon-vital > small strong { font-weight: 400; }
.bk-mon-value { font-size: 13px; }
.bk-mon-speed-part { display: inline-block; white-space: nowrap; }
.bk-mon-number { font-family: var(--bk-heading-font); font-size: 24px; line-height: 1.1; font-weight: 900; color: var(--bk-num); font-variant-numeric: tabular-nums; }
.bk-mon-extra { display: inline; font-size: 12px; color: var(--v3-ink2); }
.bk-mon-abil { display: grid; grid-template-columns: repeat(6,minmax(0,1fr)); gap: 4px; margin: 4px 0; }
.bk-mon-ability { min-width: 0; text-align: center; border: 1px solid var(--v3-rule); border-radius: 4px; padding: 2px 0; background: var(--bk-row-stripe); line-height: 1.25; }
.bk-mon .bk-mon-ability { border-collapse: separate; border-spacing: 0; width: 100%; table-layout: fixed; }
.bk-mon .bk-mon-ability :is(td,th) { padding: 0 !important; border: 0; background: var(--bk-row-stripe) !important; text-align: center !important; }
.bk-mon .bk-mon-ability-label :is(td,th) { font: 11px/1.25 var(--nt-font,sans-serif) !important; color: var(--v3-ink2); }
.bk-mon .bk-mon-score > :is(td,th) { font: 15px/1.25 var(--nt-font,sans-serif) !important; }
.bk-mon-ability .bk-mon-number { font-size: 20px; }
.bk-mon-score .render-roller > .bk-mon-number { display: block; }
.bk-mon-score { font-variant-numeric: tabular-nums; }
.bk-mon-rolls { font-size: 11px; color: var(--v3-ink2); font-variant-numeric: tabular-nums; }
.bk-mon .bk-mon-rolls td { font-size: 11px; line-height: 1.3; }
.bk-mon .bk-mon-rolls [data-packed-dice] { font-size: 13px; font-weight: 700; }
.bk-mon-rolls div { display: inline; }
.bk-mon-kv { line-height: 1.65; }
.bk-mon-kv :is(strong,b) { color: var(--bk-head); }
.bk-mon-kv p { margin: 0 !important; }
.bk-mon-kv .ve-rd__compact-stat { margin-top: 0 !important; }
.bk-mon .sect { font-family: var(--bk-heading-font); font-weight: 900; color: var(--bk-head); border-bottom: 1px solid var(--bk-gold); letter-spacing: .1em; }
.bk-mon :is(.bk-mon-action,.ve-rd__list-item-name) { font-family: var(--bk-heading-font); font-weight: 900; color: var(--v3-ink); }
.bk-mon .bk-mon-action .en { font: italic 400 1em Georgia,serif; color: var(--v3-ink2); }
.bk-mon-portrait { position: relative; grid-column: 2; grid-row: 2; width: 200px; min-height: 0; margin: 0; display: grid; place-items: center; overflow: hidden; border: 1px solid var(--bk-gold); border-radius: 6px; background: radial-gradient(ellipse,var(--bk-portrait-glow),transparent 72%); box-sizing: border-box; }
.bk-mon-portrait img { width: 100%; height: 100%; min-height: 0; position: absolute; inset: 0; object-fit: cover; object-position: center 35%; }
.bk-mon-portrait[data-presentation="cutout"] img { object-fit: contain; object-position: center; }
.bk-mon-portrait[role="button"] { cursor: pointer; }
.bk-mon-portrait:focus-visible { outline: 2px solid var(--v3-link); outline-offset: -3px; }
.bk-mon-flower { position: absolute; color: var(--bk-gold); font-size: 72px; border: 1px solid var(--bk-gold); width: 110px; height: 110px; line-height: 105px; text-align: center; transform: rotate(45deg); }
.bk-mon-flower::before, .bk-mon-flower::after { content: ""; position: absolute; inset: 14px; border: 1px solid var(--bk-gold); }
.bk-mon-flower::after { inset: 30px; transform: rotate(45deg); }
@container (max-width: 639px) {
 .bk-mon-abil { grid-template-columns: repeat(3,minmax(0,1fr)); }
 .bk-mon-portrait { width: 200px; }
}
@media (max-width: 479px) {
 .bk-mon-head:has(.bk-mon-portrait) { grid-template-columns: minmax(0,1fr); }
 .bk-mon-portrait { grid-column: 1; grid-row: 3; height: 200px; justify-self: end; margin-top: 4px; }
}
.ve-hwin .bk-mon-preview { border-collapse: separate; border-spacing: 0; padding: 13px; }
@layer vetools {
 .bk-mon .bk-mon-row > th { padding-top: 8px !important; }
 .ve-hwin .bk-mon-preview .bk-mon-row > th { padding: 0 !important; }
 .ve-hwin .bk-mon-preview > tbody > tr > td { padding-left: 0 !important; padding-right: 0 !important; }
 .bk-mon .ve-source-marker { color: var(--v3-ink2) !important; }
 .bk-mon-name .ve-flex-col, .bk-mon-name .ve-split-v-end { display: block !important; }
 .bk-mon-ability small div { text-align: center !important; }
 .bk-mon .bk-mon-ability-label div { text-align: center !important; }
 .bk-mon .bk-mon-action, .bk-mon .bk-mon-action .en { color: var(--v3-ink) !important; }
 .bk-mon .bk-mon-action .en { color: var(--v3-ink2) !important; }
}

/__ours/theme.css:
/* 精装典籍主题变量：按用途分组；同一日夜色对只保留一个变量。 */
/* Quick-filter ink and paper switch together: colour crossfades dip below AA. */
html.nt3.ours-l5 .l5-chip { transition: border-color 120ms ease, box-shadow 120ms ease; }
@media (prefers-reduced-motion: reduce) { html.nt3.ours-l5 .l5-chip { transition: none; } }
:root { --bk-portrait-glow: color-mix(in srgb, var(--bk-gold) 22%, transparent); }
:root {
  --bk-img-base: var(--v3-deep);
  --bk-img-light: color-mix(in srgb, var(--bk-gold) 28%, transparent);
  --bk-img-line: color-mix(in srgb, var(--bk-gold) 29%, var(--bk-img-base));
}
:root { --bk-class-border: color-mix(in srgb, var(--v3-rule) 65%, var(--bk-gold)); --bk-class-mask: #000; }
:root[data-ours-theme="night"] { --bk-portrait-glow: var(--bk-glow); }
/* 怪物详情末尾也会露出遭遇构筑按钮，使用既有暖色按钮变量。 */
@layer vetools {
 html.nt3[data-ours-page="bestiary"] .ve-btn-success { color: var(--v3-paper) !important; background-color: var(--bk-head) !important; border-color: var(--bk-head) !important; }
}
/* 表格：第二行的暖色条纹，随规范底色切换。 */
:root { --bk-row-stripe: color-mix(in srgb, var(--v3-deep) 70%, var(--v3-card)); }
/* 按钮：夜间主按钮悬停，保持金色并稍微提亮。 */
:root[data-ours-theme="night"] { --bk-btn-primary-hover-bg: color-mix(in srgb, var(--bk-gold) 88%, var(--v3-ink)); }
/* 精装书架与纸面。布面封皮的实物色不随主题改变。 */
html.ours-bk {
  --bk-shelf-top: #c59b67; --bk-shelf-face: #a27146; --bk-shelf-edge: #74462d;
  --bk-shelf-shadow: #60391e45;
  --bk-cover-wine: #822d26; --bk-cover-blue: #244c70; --bk-cover-green: #315d49;
  --bk-cover-violet: #523666; --bk-cover-brown: #71503a;
  --bk-cover-ink: #fff6e6; --bk-cover-gold: #e0be80; --bk-cover-dark: #160d08;
  --bk-cover-spine: #170b0755; --bk-cover-shine: #fff6e64d;
  --bk-readaloud-bg: #fff4d9;
}
html.ours-bk[data-ours-theme="night"] {
  --bk-shelf-top: #795239; --bk-shelf-face: #503321; --bk-shelf-edge: #321e14;
  --bk-shelf-shadow: #0b0604a6;
  --bk-readaloud-bg: #3a2b20;
}
html.ours-bk[data-ours-theme="night"] #pagecontent.bk5-doc { --bk-page-book-inset-bg: #35261c; }
/* 页面底色、遮罩与书页：日间 */
:root {
  --bk-page-scroll-thumb: #d9c8a0;
  --bk-page-scroll-thumb-hover: #c4b081;
  --bk-page-modal-overlay: rgba(50, 25, 5, .28);
  --bk-page-tile-hover-bg: #fff6e2;
  --bk-page-feature-flash: rgba(201, 165, 90, .38);
  --bk-page-upcast-bg: rgba(130, 60, 0, .05);
  --bk-page-book-inset-bg: #f3e6cc;
  --bk-page-legacy-menu-bg: #241b14;
  --bk-page-legacy-input-bg: rgba(255, 255, 255, .6);
  --bk-page-legacy-dialog-overlay: rgba(15, 8, 20, .55);
  --bk-page-rating-gradient-start: #241a30;
  --bk-page-rating-gradient-end: #3a2346;
  --bk-page-rating-track-bg: rgba(127, 127, 127, .2);
  --bk-page-rating-comment-bg: rgba(217, 164, 65, .1);
  --bk-page-hall-hero-glow: rgba(255, 200, 120, .25);
  --bk-page-hall-hero-start: #1d1229;
  --bk-page-hall-hero-middle: #3d1f4a;
  --bk-page-hall-hero-end: #6b2f4d;
  --bk-page-hall-aura: rgba(246, 210, 122, .35);
  --bk-page-hall-book-count-bg: rgba(0, 0, 0, .28);
  --bk-page-hall-tile-glow: rgba(217, 164, 65, .25);
  --bk-page-class-group-heading-bg: rgba(217, 164, 65, .22);
  --bk-page-loading-overlay: rgba(10, 8, 6, .45);
  --bk-page-loading-card-bg: #1d1813;
}
/* 页面底色、遮罩与书页：夜间 */
:root[data-ours-theme="night"] {
  --bk-page-scroll-thumb: var(--v3-panel);
  --bk-page-scroll-thumb-hover: var(--v3-panel);
  --bk-page-modal-overlay: color-mix(in srgb, var(--bk-head) 28%, transparent);
  --bk-page-tile-hover-bg: var(--v3-card);
  --bk-page-feature-flash: color-mix(in srgb, var(--v3-ink) 38%, transparent);
  --bk-page-upcast-bg: color-mix(in srgb, var(--bk-head) 5%, transparent);
  --bk-page-book-inset-bg: var(--v3-card);
  --bk-page-legacy-menu-bg: var(--v3-deep);
  --bk-page-legacy-input-bg: color-mix(in srgb, var(--v3-ink) 60%, transparent);
  --bk-page-legacy-dialog-overlay: color-mix(in srgb, var(--bk-head) 55%, transparent);
  --bk-page-rating-gradient-start: var(--v3-deep);
  --bk-page-rating-gradient-end: var(--v3-deep);
  --bk-page-rating-track-bg: color-mix(in srgb, var(--bk-head) 20%, transparent);
  --bk-page-rating-comment-bg: color-mix(in srgb, var(--v3-ink) 10%, transparent);
  --bk-page-hall-hero-glow: color-mix(in srgb, var(--v3-ink) 25%, transparent);
  --bk-page-hall-hero-start: var(--v3-deep);
  --bk-page-hall-hero-middle: var(--v3-deep);
  --bk-page-hall-hero-end: var(--v3-deep);
  --bk-page-hall-aura: color-mix(in srgb, var(--v3-ink) 35%, transparent);
  --bk-page-hall-book-count-bg: color-mix(in srgb, var(--bk-head) 28%, transparent);
  --bk-page-hall-tile-glow: color-mix(in srgb, var(--v3-ink) 25%, transparent);
  --bk-page-class-group-heading-bg: color-mix(in srgb, var(--v3-ink) 22%, transparent);
  --bk-page-loading-overlay: color-mix(in srgb, var(--bk-head) 45%, transparent);
  --bk-page-loading-card-bg: var(--v3-deep);
}
/* 文字与强调：日间 */
:root {
  --bk-text-selection-bg: rgba(201, 165, 90, .4);
  --bk-text-link-hover: #1d4f7c;
  --bk-text-table-heading: #4b3a26;
  --bk-text-class-english: #b59a72;
  --bk-text-on-accent: #fff;
  --bk-text-title-source: #c2b497;
  --bk-text-on-heading-fill: #fff6e0;
  --bk-text-book-chip-count: #f3d7c7;
  --bk-text-book-cover: #fff6e6;
  --bk-text-legacy-bar: #f3e9d2;
  --bk-text-legacy-brand: #f6dfa4;
  --bk-text-legacy-control: #e8dcc0;
  --bk-text-legacy-dialog: #f1e3c4;
  --bk-text-legacy-gold-emphasis: #f6d27a;
  --bk-text-gem-empty: #555;
  --bk-text-rating-panel: #efe5cf;
  --bk-text-legacy-hall: #f6ecd6;
  --bk-text-hall-title: #fff3d0;
  --bk-text-hall-tile-icon: #7d4466;
  --bk-text-hall-tile-icon-night-fallback: #e5a8c8;
  --bk-text-class-group-heading: #8a5a1c;
  --bk-text-class-group-secondary: #888;
  --bk-text-edition-count: #4a90c8;
}
/* 文字与强调：夜间 */
:root[data-ours-theme="night"] {
  --bk-text-selection-bg: color-mix(in srgb, var(--v3-ink) 40%, transparent);
  --bk-text-link-hover: var(--v3-ink2);
  --bk-text-table-heading: var(--v3-ink2);
  --bk-text-class-english: var(--v3-ink2);
  --bk-text-on-accent: var(--v3-ink2);
  --bk-text-title-source: var(--v3-ink2);
  --bk-text-on-heading-fill: var(--v3-ink2);
  --bk-text-book-chip-count: var(--v3-ink2);
  --bk-text-book-cover: var(--v3-ink2);
  --bk-text-legacy-bar: var(--v3-ink2);
  --bk-text-legacy-brand: var(--v3-ink2);
  --bk-text-legacy-control: var(--v3-ink2);
  --bk-text-legacy-dialog: var(--v3-ink2);
  --bk-text-legacy-gold-emphasis: var(--v3-ink2);
  --bk-text-gem-empty: var(--v3-ink2);
  --bk-text-rating-panel: var(--v3-ink2);
  --bk-text-legacy-hall: var(--v3-ink2);
  --bk-text-hall-title: var(--v3-ink2);
  --bk-text-hall-tile-icon: var(--v3-ink2);
  --bk-text-hall-tile-icon-night-fallback: var(--v3-ink2);
  --bk-text-class-group-heading: var(--v3-ink2);
  --bk-text-class-group-secondary: var(--v3-ink2);
  --bk-text-edition-count: var(--v3-ink2);
}
/* 顶栏与状态：日间 */
:root {
  --bk-nav-legacy-gradient-start: #1b1626;
  --bk-nav-legacy-gradient-end: #4a2b55;
  --bk-nav-legacy-hover: rgba(255, 255, 255, .12);
  --bk-nav-legacy-header-start: #2b1836;
  --bk-nav-legacy-header-middle: #5a2f5f;
  --bk-nav-legacy-header-end: #7d4466;
  --bk-nav-legacy-pressed-bg: rgba(0, 0, 0, .35);
  --bk-nav-status-online-bg: #49d17a;
  --bk-nav-status-offline-bg: #e0a93b;
  --bk-nav-status-busy-bg: #59a6ff;
  --bk-nav-brand-ink: #fbe9c3;
  --bk-nav-hover: rgba(255, 236, 200, .1);
  --bk-nav-brand-mark: #e5bd62;
  --bk-nav-tab-hover: rgba(255, 236, 200, .12);
  --bk-nav-source-selected-bg: #e5bd62;
  --bk-nav-close-hover: rgba(255, 236, 200, .18);
  --bk-nav-control-bg: rgba(20, 4, 0, .34);
  --bk-nav-source-selected-ink: #3a1a08;
  --bk-nav-edition-selected-bg: #bcd6ee;
  --bk-nav-edition-selected-ink: #12324f;
  --bk-nav-menu-hover: rgba(255, 236, 200, .14);
  --bk-nav-status-ready-bg: #5d9a6c;
}
/* 顶栏与状态：夜间 */
:root[data-ours-theme="night"] {
