  --bk-nav-status-busy-bg: var(--v3-deep);
  --bk-nav-brand-ink: var(--v3-ink2);
  --bk-nav-hover: color-mix(in srgb, var(--v3-ink) 10%, transparent);
  --bk-nav-brand-mark: var(--v3-ink2);
  --bk-nav-tab-hover: color-mix(in srgb, var(--v3-ink) 12%, transparent);
  --bk-nav-source-selected-bg: var(--v3-panel);
  --bk-nav-close-hover: color-mix(in srgb, var(--v3-ink) 18%, transparent);
  --bk-nav-control-bg: color-mix(in srgb, var(--bk-head) 34%, transparent);
  --bk-nav-source-selected-ink: var(--v3-ink2);
  --bk-nav-edition-selected-bg: var(--v3-panel);
  --bk-nav-edition-selected-ink: var(--v3-ink2);
  --bk-nav-menu-hover: color-mix(in srgb, var(--v3-ink) 14%, transparent);
  --bk-nav-status-ready-bg: var(--v3-deep);
}
/* 来源标签：日间 */
:root {
  --bk-tag-off24-bg: #d6e5f2;
  --bk-tag-source-dark-mix: #1c1208;
  --bk-tag-off24-ink: #1f4f7d;
  --bk-tag-off14-bg: rgba(110, 86, 40, .14);
  --bk-tag-off14-ink: #5d5140;
}
