  --bk-tag-off14-bg: color-mix(in srgb, var(--bk-head) 14%, transparent);
  --bk-tag-off14-ink: var(--v3-ink2);
}
/* 表格与列表：日间 */
:root {
  --bk-table-list-hover: rgba(130, 32, 0, .055);
  --bk-table-row-stripe: rgba(201, 165, 90, .1);
  --bk-table-class-row-stripe: rgba(201, 165, 90, .11);
  --bk-table-class-row-hover: rgba(42, 106, 163, .1);
  --bk-table-list-paper-hover: rgba(255, 250, 240, .7);
