  html.nt3 .ve-sp__school--c { color: var(--bk-school-c) !important; }
  html.nt3 .ve-sp__school--d { color: var(--bk-school-d) !important; }
  html.nt3 .ve-sp__school--e { color: var(--bk-school-e) !important; }
