/* Task 13: shared rarity ink; 12% badge tints, independently checked on four papers. */
:root {
 --bk-rar-common: #605647; --bk-rar-uncommon: #23642e; --bk-rar-rare: #2453a0;
 --bk-rar-very: #71359f; --bk-rar-legendary: #87400e; --bk-rar-artifact: #922318;
 --bk-rar-common-bg: color-mix(in srgb, var(--bk-rar-common) 12%, transparent);
 --bk-rar-uncommon-bg: color-mix(in srgb, var(--bk-rar-uncommon) 12%, transparent);
 --bk-rar-rare-bg: color-mix(in srgb, var(--bk-rar-rare) 12%, transparent);
 --bk-rar-very-bg: color-mix(in srgb, var(--bk-rar-very) 12%, transparent);
 --bk-rar-legendary-bg: color-mix(in srgb, var(--bk-rar-legendary) 12%, transparent);
 --bk-rar-artifact-bg: color-mix(in srgb, var(--bk-rar-artifact) 12%, transparent);
 --bk-rarity-common: var(--bk-rar-common); --bk-rarity-uncommon: var(--bk-rar-uncommon);
 --bk-rarity-rare: var(--bk-rar-rare); --bk-rarity-very: var(--bk-rar-very);
 --bk-rarity-legendary: var(--bk-rar-legendary); --bk-rarity-artifact: var(--bk-rar-artifact);
}
